INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発生", "is_correct": true, "explanation": "炭素が新たに生じることを指し、文意に合います。"}, {"text": "契約", "is_correct": false, "explanation": "形は合うが、炭素をゼロ化する話に契約という意味は合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、炭素に卒業という意味は合わない。"}, {"text": "募集", "is_correct": false, "explanation": "形は合うが、炭素をゼロ化する文脈に募集の意味は合わない。"}], "explanations": {"発生": "炭素が新たに生じることを指し、文意に合います。", "契約": "形は合うが、炭素をゼロ化する話に契約という意味は合わない。", "卒業": "形は合うが、炭素に卒業という意味は合わない。", "募集": "形は合うが、炭素をゼロ化する文脈に募集の意味は合わない。"}, "sentence_index": 0, "correct_answer": "発生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母が私に誕生日プレゼントを発生してくれた。", "explanation": "「発生」は物を人に与える意味ではなく、自然に起こる意味なので誤用です。"}, {"text": "昨日、友だちと映画館で発生しました。", "explanation": "「発生」は人の行動ではなく現象が起こることを表すので誤用です。"}, {"text": "彼はいつも宿題を発生する。", "explanation": "宿題のような人がするものに「発生」は使えず、意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発生", "is_correct": true, "explanation": "何かが起こった原因を調べるので、文意に合います。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、調べる対象として散歩の原因という意味は合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "形は合うが、原因を調べる文脈に旅行は合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "形は合うが、原因を調べる文脈に掃除は合わない。"}], "explanations": {"発生": "何かが起こった原因を調べるので、文意に合います。", "散歩": "形は合うが、調べる対象として散歩の原因という意味は合わない。", "旅行": "形は合うが、原因を調べる文脈に旅行は合わない。", "掃除": "形は合うが、原因を調べる文脈に掃除は合わない。"}, "sentence_index": 6, "correct_answer": "発生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、六時に発生して学校へ行く。", "explanation": "「発生」は人が出発する意味ではなく、現象が起こる意味なので誤用です。"}, {"text": "新しい料理を発生して、家族に出した。", "explanation": "料理を作る意味で使っているが、「発生」は自然に起こることを表すので誤りです。"}, {"text": "彼女は財布を道に発生した。", "explanation": "「落とす」の意味で誤用している。「発生」は物に対する動作ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、町で事故を発生した。", "corrected_sentence": "昨日、町で事故が発生した。", "error_description": "「発生」は自動詞的に使うので、「事故を」ではなく「事故が」が正しいです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭で花が発生した。", "corrected_sentence": "庭で花が咲いた。", "error_description": "花には「発生」ではなく「咲く」を使うので、語の選択が誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「頻度は」で主題を示し、「場所によって大きく違う」と続けて述べる。"}, {"text": "を", "is_correct": false, "explanation": "「違う」は目的語を取らないので、「頻度を、場所によって大きく違う」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「頻度に、大きく違う」は不自然で、ここでは主題を示す「は」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「頻度へ」の形で、この文の「違う」とは結びつかない。"}], "correct_answer": "は", "explanations": {"は": "正解。「頻度は」で主題を示し、「場所によって大きく違う」と続けて述べる。", "を": "「違う」は目的語を取らないので、「頻度を、場所によって大きく違う」は成り立たない。", "に": "「頻度に、大きく違う」は不自然で、ここでは主題を示す「は」が必要。", "へ": "方向を示す「へ」は「頻度へ」の形で、この文の「違う」とは結びつかない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「頻度が減った」で、頻度を主語にして変化を述べる。"}, {"text": "で", "is_correct": false, "explanation": "「頻度で減った」は成り立たず、「で」は手段を示すので、減るものの主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「頻度と減った」は文が成り立たず、「と」は相手や引用を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「頻度から減った」とは言わず、減った頻度の主語は「が」で示す。"}], "correct_answer": "が", "explanations": {"が": "正解。「頻度が減った」で、頻度を主語にして変化を述べる。", "で": "「頻度で減った」は成り立たず、「で」は手段を示すので、減るものの主語にならない。", "と": "「頻度と減った」は文が成り立たず、「と」は相手や引用を示す。", "から": "起点の「から」は「頻度から減った」とは言わず、減った頻度の主語は「が」で示す。"}, "error_tags": {"で": "手段", "と": "相手・引用", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがどれくらいよく起こるかを表す数です。", "primary_collocate": null, "pronunciation": "ひんど", "ipa": "çindo", "syllable_count": 3, "sentences": [{"text": "この駅は電車が来る頻度が高いので、待たずに乗れます。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "この駅[えき]は電車[でんしゃ]が来[く]る頻度[ひんど]が高[たか]いので、待[ま]たずに乗[の]れます。", "sentence_source": "generated"}, {"text": "地震が起きる頻度は、場所によって大きく違います。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きる頻度[ひんど]は、場所[ばしょ]によって大[おお]きく違[ちが]います。", "sentence_source": "generated"}, {"text": "運動の頻度を、週に二回から三回に増やしました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "運動[うんどう]の頻度[ひんど]を、週[しゅう]に二回[にかい]から三回[さんかい]に増[ふ]やしました。", "sentence_source": "generated"}, {"text": "頻度が低い言葉は、辞書でも見つけにくいです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "頻度[ひんど]が低[ひく]い言葉[ことば]は、辞書[じしょ]でも見[み]つけにくいです。", "sentence_source": "generated"}, {"text": "掃除の頻度を決めて、カレンダーに書いておきます。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "掃除[そうじ]の頻度[ひんど]を決[き]めて、カレンダーに書[か]いておきます。", "sentence_source": "generated"}, {"text": "薬をのむ頻度は、医者に聞いて確かめてください。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "薬[くすり]をのむ頻度[ひんど]は、医者[いしゃ]に聞[き]いて確[たし]かめてください。", "sentence_source": "generated"}, {"text": "バスの頻度が少なく、一時間に一本しか来ません。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "バスの頻度[ひんど]が少[すく]なく、一時間[いちじかん]に一本[いっぽん]しか来[き]ません。", "sentence_source": "generated"}, {"text": "忘れ物をする頻度が減ったのは、メモを取り始めたからです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]をする頻度[ひんど]が減[へ]ったのは、メモを取[と]り始[はじ]めたからです。", "sentence_source": "generated"}, {"text": "事故が起こる頻度を調べて、グラフにまとめました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]こる頻度[ひんど]を調[しら]べて、グラフにまとめました。", "sentence_source": "generated"}, {"text": "友達に会う頻度は、年に一度くらいです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "友達[ともだち]に会[あ]う頻度[ひんど]は、年[とし]に一度[いちど]くらいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻度", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ある事がどのくらいよく起こるかを示す度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻度", "is_correct": true, "explanation": "正解。「来る頻度が高い」で、電車がどれくらいよく来るかを表す。"}, {"text": "料金", "is_correct": false, "explanation": "「電車が来る料金」は成り立たず、料金は来る回数の話にならないので文が通らない。"}, {"text": "評判", "is_correct": false, "explanation": "「電車が来る評判」は意味が通らず、電車の来る回数を述べる文の内容に合わない。"}, {"text": "音量", "is_correct": false, "explanation": "「電車が来る音量」は意味が成り立たず、来る回数や間隔の説明にならない。"}], "explanations": {"頻度": "正解。「来る頻度が高い」で、電車がどれくらいよく来るかを表す。", "料金": "「電車が来る料金」は成り立たず、料金は来る回数の話にならないので文が通らない。", "評判": "「電車が来る評判」は意味が通らず、電車の来る回数を述べる文の内容に合わない。", "音量": "「電車が来る音量」は意味が成り立たず、来る回数や間隔の説明にならない。"}, "sentence_index": 0, "correct_answer": "頻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は頻度がやさしく、誰にでも親切だ。", "explanation": "ここは〈性格〉の意味。「性格がやさしい」の語を頻度に入れ替えた文。頻度は起こる度合いを表すので、人の性格の言い方には合わない。"}, {"text": "このお酒は頻度が高く、少し飲んだだけでも酔いやすい。", "explanation": "ここは〈度数〉（酒のアルコールの強さ）の意味。頻度は「どれくらいよく起こるか」なので、酒の強さの表現には合わない。"}, {"text": "この箱は頻度が重くて、一人では持ち上げられない。", "explanation": "ここは〈重さ〉の意味。頻度は起こる回数の多さで、物の重さは表さないので「重い」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻度", "is_correct": true, "explanation": "正解。「頻度が少ない」で、バスが来る回数の少なさを表す。"}, {"text": "気温", "is_correct": false, "explanation": "「バスの気温が少ない」は成り立たず、気温はバスの運行の回数と関係しない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が少ない」は意味が通らず、バスの本数の話に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温が少ない」は文が成り立たず、バスの運行の話にならない。"}], "explanations": {"頻度": "正解。「頻度が少ない」で、バスが来る回数の少なさを表す。", "気温": "「バスの気温が少ない」は成り立たず、気温はバスの運行の回数と関係しない。", "天気": "「天気が少ない」は意味が通らず、バスの本数の話に合わない。", "体温": "「体温が少ない」は文が成り立たず、バスの運行の話にならない。"}, "sentence_index": 6, "correct_answer": "頻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子は頻度が高く、クラスでいちばん背が高い。", "explanation": "ここは〈身長〉の意味。「背が高い」の話なので身長を使う。頻度は起こる度合いで、人の背の高さには使わない。"}, {"text": "けがの頻度は軽く、すぐに治りそうだ。", "explanation": "ここは〈程度〉（けがの重さ）の意味。頻度は起こる回数の多さで、けがの重さは表さない。"}, {"text": "この料理は頻度が濃くて、味がしっかりしている。", "explanation": "ここは〈濃度〉の意味。頻度は起こる回数の多さなので、濃さの言い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は客が来る頻度を高いので、いつもにぎやかです。", "corrected_sentence": "この店は客が来る頻度が高いので、いつもにぎやかです。", "error_description": "「頻度」の後の助詞は「が」が正しい（誤り：を、正しい形：が）。「高い」の主語になるのは「が」で、「を」は動作の目的語に使うため、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達に会う頻度に、月に二回ほどです。", "corrected_sentence": "友達に会う頻度は、月に二回ほどです。", "error_description": "「頻度」の後は主題の「は」が正しい（誤り：に、正しい形：は）。「に」では文の主題にならず、「月に二回ほどです」と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「頻度を比べる」で、比べる対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「頻度へ比べました」は成り立たず、「へ」は方向を示す助詞。"}, {"text": "に", "is_correct": false, "explanation": "「頻度に表にして比べました」は不自然で、「に」は位置や相手を示すので比べる対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「頻度から比べました」は起点の意味になり、比べる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「頻度を比べる」で、比べる対象を示す。", "へ": "「頻度へ比べました」は成り立たず、「へ」は方向を示す助詞。", "に": "「頻度に表にして比べました」は不自然で、「に」は位置や相手を示すので比べる対象にならない。", "から": "「頻度から比べました」は起点の意味になり、比べる対象を示せない。"}, "error_tags": {"へ": "方向", "に": "位置・相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「頻度を聞く」で、聞く内容を示す。"}, {"text": "が", "is_correct": false, "explanation": "「頻度が聞きました」は成り立たず、「聞く」は対象に「を」を取る。"}, {"text": "と", "is_correct": false, "explanation": "「頻度と聞きました」は文が成り立たず、「と」は引用や相手を示す。"}, {"text": "の", "is_correct": false, "explanation": "「頻度の聞きました」は不自然で、「の」は名詞をつなぐ助詞なので「聞く」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「頻度を聞く」で、聞く内容を示す。", "が": "「頻度が聞きました」は成り立たず、「聞く」は対象に「を」を取る。", "と": "「頻度と聞きました」は文が成り立たず、「と」は引用や相手を示す。", "の": "「頻度の聞きました」は不自然で、「の」は名詞をつなぐ助詞なので「聞く」の対象にはならない。"}, "error_tags": {"が": "主格", "と": "引用・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が起こる回数や割合のこと。", "primary_collocate": null, "pronunciation": "ひんど", "ipa": "çindo", "syllable_count": 3, "sentences": [{"text": "雨が降る頻度は、六月がいちばん高いです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る頻度[ひんど]は、六月[ろくがつ]がいちばん高[たか]いです。", "sentence_source": "generated"}, {"text": "同じミスが起こる頻度を、表にして比べました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "同[おな]じミスが起[お]こる頻度[ひんど]を、表[ひょう]にして比[くら]べました。", "sentence_source": "generated"}, {"text": "彼女がこの店に来る頻度は、月に三回ほどです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "彼女[かのじょ]がこの店[みせ]に来[く]る頻度[ひんど]は、月[つき]に三回[さんかい]ほどです。", "sentence_source": "generated"}, {"text": "頻度の高い単語から覚えると、勉強が楽になります。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "頻度[ひんど]の高[たか]い単語[たんご]から覚[おぼ]えると、勉強[べんきょう]が楽[らく]になります。", "sentence_source": "generated"}, {"text": "停電が起きる頻度は、昔よりずっと減りました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "停電[ていでん]が起[お]きる頻度[ひんど]は、昔[むかし]よりずっと減[へ]りました。", "sentence_source": "generated"}, {"text": "洗濯の頻度は、家族の人数で変わります。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "洗濯[せんたく]の頻度[ひんど]は、家族[かぞく]の人数[にんずう]で変[か]わります。", "sentence_source": "generated"}, {"text": "ここは車が通る頻度が少ないので、とても静かです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "ここは車[くるま]が通[とお]る頻度[ひんど]が少[すく]ないので、とても静[しず]かです。", "sentence_source": "generated"}, {"text": "アンケートで、買い物に行く頻度を聞きました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "アンケートで、買[か]い物[もの]に行[い]く頻度[ひんど]を聞[き]きました。", "sentence_source": "generated"}, {"text": "故障の頻度が高いので、新しい機械に替えることにしました。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "故障[こしょう]の頻度[ひんど]が高[たか]いので、新[あたら]しい機械[きかい]に替[か]えることにしました。", "sentence_source": "generated"}, {"text": "歯医者に行く頻度は、半年に一回がよいそうです。", "target_word": "頻度", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]に行[い]く頻度[ひんど]は、半年[はんとし]に一回[いっかい]がよいそうです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻度", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ある事柄が起こる回数や、その割合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻度", "is_correct": true, "explanation": "正解。「降る頻度」で、雨がどれくらいよく降るかを表す。"}, {"text": "料金", "is_correct": false, "explanation": "「雨が降る料金」は成り立たず、料金は雨の降り方を表さない。"}, {"text": "評判", "is_correct": false, "explanation": "「雨が降る評判」は意味が通らず、文の「いちばん高い」とも合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「雨が降る天気」は意味が重なって不自然で、「六月がいちばん高い」と結びつかない。"}], "explanations": {"頻度": "正解。「降る頻度」で、雨がどれくらいよく降るかを表す。", "料金": "「雨が降る料金」は成り立たず、料金は雨の降り方を表さない。", "評判": "「雨が降る評判」は意味が通らず、文の「いちばん高い」とも合わない。", "天気": "「雨が降る天気」は意味が重なって不自然で、「六月がいちばん高い」と結びつかない。"}, "sentence_index": 0, "correct_answer": "頻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このマイクは頻度が高く、小さな声もよく拾う。", "explanation": "ここは〈感度〉（感じやすさ）の意味。頻度は「どれくらいよく起こるか」なので、機械の感じやすさには使わない。"}, {"text": "この作業は頻度がかかるので、毎日は無理だ。", "explanation": "ここは〈手間〉の意味。「手間がかかる」の語を頻度に入れた文。頻度は回数や割合で、時間や労力の多さは表さない。"}, {"text": "この車の頻度は時速八十キロだ。", "explanation": "ここは〈速さ〉の意味。頻度は起こる回数の割合で、車の速さは表さないので、時速で示す言い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻度", "is_correct": true, "explanation": "正解。「頻度が少ない」で、車がどれくらいよく通るかを表す。"}, {"text": "香り", "is_correct": false, "explanation": "「車が通る香りが少ない」は成り立たず、香りは車の通行と関係しない。"}, {"text": "体温", "is_correct": false, "explanation": "「車が通る体温」は成り立たず、体温は車の通行量と関係しない。"}, {"text": "気温", "is_correct": false, "explanation": "「車が通る気温」は意味が通らず、「とても静か」の理由にならない。"}], "explanations": {"頻度": "正解。「頻度が少ない」で、車がどれくらいよく通るかを表す。", "香り": "「車が通る香りが少ない」は成り立たず、香りは車の通行と関係しない。", "体温": "「車が通る体温」は成り立たず、体温は車の通行量と関係しない。", "気温": "「車が通る気温」は意味が通らず、「とても静か」の理由にならない。"}, "sentence_index": 6, "correct_answer": "頻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子犬は頻度が重くて、抱っこするとずっしりする。", "explanation": "ここは〈体重〉の意味。頻度は起こる度合いで、体の重さは表さないので「重い」とは言えない。"}, {"text": "この道の街灯は頻度が五メートルあいていて、夜は少し暗い。", "explanation": "ここは〈間隔〉の意味。頻度は「どれくらいよく起こるか」で、「あく」と言えず距離の話には合わない。"}, {"text": "この会議は頻度が長くて、みんなくたくたになった。", "explanation": "ここは〈時間〉の意味。頻度は回数や割合で、会議の長さ（時間の長さ）は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車で通う頻度で、月に五回ほどです。", "corrected_sentence": "電車で通う頻度は、月に五回ほどです。", "error_description": "「頻度」の後は主題の「は」が正しい（誤り：で、正しい形：は）。「で」は手段を示すので、ここでは文の主題にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36723, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ジムに通う頻度に、週に三回です。", "corrected_sentence": "ジムに通う頻度は、週に三回です。", "error_description": "「頻度」の後は主題の「は」が正しい（誤り：に、正しい形：は）。「に」では文の主題にならず、「週に三回です」と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
