INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36724, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "意味や違いがはっきりしていて、数字で比べたときに差があること。", "primary_collocate": null, "pronunciation": "ゆうい", "ipa": "jɯːi", "syllable_count": 3, "sentences": [{"text": "二つのクラスのテスト結果を比べると、平均点に有意な差が見られた。", "target_word": "有意", "complexity_tier": "T3", "furigana": "二[ふた]つのクラスのテスト結果[けっか]を比[くら]べると、平均点[へいきんてん]に有意[ゆうい]な差[さ]が見[み]られた。", "sentence_source": "generated"}, {"text": "新しい薬を飲んだグループは、飲まなかったグループより有意に血圧が下がった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]を飲[の]んだグループは、飲[の]まなかったグループより有意[ゆうい]に血圧[けつあつ]が下[さ]がった。", "sentence_source": "generated"}, {"text": "調査の結果、男女の間に有意な違いはないとわかった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]、男女[だんじょ]の間[あいだ]に有意[ゆうい]な違[ちが]いはないとわかった。", "sentence_source": "generated"}, {"text": "この実験では、温度によって成長に有意な差が出た。", "target_word": "有意", "complexity_tier": "T3", "furigana": "この実験[じっけん]では、温度[おんど]によって成長[せいちょう]に有意[ゆうい]な差[さ]が出[で]た。", "sentence_source": "generated"}, {"text": "売り上げは去年より有意に増えたと報告された。", "target_word": "有意", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは去年[きょねん]より有意[ゆうい]に増[ふ]えたと報告[ほうこく]された。", "sentence_source": "generated"}, {"text": "数字だけを見ると、AとBの間に有意な差があるとは言えない。", "target_word": "有意", "complexity_tier": "T3", "furigana": "数字[すうじ]だけを見[み]ると、AとBの間[あいだ]に有意[ゆうい]な差[さ]があるとは言[い]えない。", "sentence_source": "generated"}, {"text": "練習時間が長い生徒ほど、成績が有意に高かった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "練習[れんしゅう]時間[じかん]が長[なが]い生徒[せいと]ほど、成績[せいせき]が有意[ゆうい]に高[たか]かった。", "sentence_source": "generated"}, {"text": "両方の方法を比べたが、効果に有意な違いは確認できなかった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "両方[りょうほう]の方法[ほうほう]を比[くら]べたが、効果[こうか]に有意[ゆうい]な違[ちが]いは確認[かくにん]できなかった。", "sentence_source": "generated"}, {"text": "広告を出した後、来店客数が有意に増加した。", "target_word": "有意", "complexity_tier": "T3", "furigana": "広告[こうこく]を出[だ]した後[あと]、来店客数[らいてんきゃくすう]が有意[ゆうい]に増加[ぞうか]した。", "sentence_source": "generated"}, {"text": "測定したデータには、有意な差があると判断された。", "target_word": "有意", "complexity_tier": "T3", "furigana": "測定[そくてい]したデータには、有意[ゆうい]な差[さ]があると判断[はんだん]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有意だ", "label": "終止形"}, {"form": "有意な", "label": "連体形"}, {"form": "有意に", "label": "連用形"}, {"form": "有意である", "label": "断定形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "数字で比べて、はっきりした差や違いがあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "正解。「有意な差」で、統計的に意味のある差を表す。"}, {"text": "元気", "is_correct": false, "explanation": "「元気な差」は意味が通らず、平均点の比較の話に合わない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫な差」は意味が通らず、数字の比較には使えない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かな差」は意味が成り立たず、テスト結果の比較に合わない。"}], "explanations": {"有意": "正解。「有意な差」で、統計的に意味のある差を表す。", "元気": "「元気な差」は意味が通らず、平均点の比較の話に合わない。", "丈夫": "「丈夫な差」は意味が通らず、数字の比較には使えない。", "静か": "「静かな差」は意味が成り立たず、テスト結果の比較に合わない。"}, "sentence_index": 0, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この旅行は、私にとって有意な時間だった。", "explanation": "ここは〈有意義〉（価値がある）の意味。有意は統計的に差があることなので、時間の価値を言うときには使わない。"}, {"text": "彼はこの町で有意な画家として知られている。", "explanation": "ここは〈有名〉の意味。有意は統計的な差がある意味なので、人の知名度には使わない。"}, {"text": "この本は勉強にとって有意だ。", "explanation": "ここは〈有益〉（役に立つ）の意味。有意は統計的な差の意味で、役立つかどうかは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "正解。「有意に高い」で、統計的に差があるほど高かったことを表す。"}, {"text": "愉快", "is_correct": false, "explanation": "「愉快に高い」は意味が通らず、成績の高さを表さない。"}, {"text": "鮮明", "is_correct": false, "explanation": "「鮮明に高い」は成績の話に合わず、意味が通らない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やかに高い」は成績の高さの表現にならず、文の内容に合わない。"}], "explanations": {"有意": "正解。「有意に高い」で、統計的に差があるほど高かったことを表す。", "愉快": "「愉快に高い」は意味が通らず、成績の高さを表さない。", "鮮明": "「鮮明に高い」は成績の話に合わず、意味が通らない。", "穏やか": "「穏やかに高い」は成績の高さの表現にならず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このチームは後半、他校に対して有意に立っている。", "explanation": "ここは〈優位〉（有利な立場）の意味。有意は統計的な差があることなので、立場の強さには使わない。"}, {"text": "新人の彼は仕事がとても有意だ。", "explanation": "ここは〈有能〉（仕事ができる）の意味。有意は統計的な差を表すので、人の能力には使わない。"}, {"text": "この条件は、我々にとって有意だ。", "explanation": "ここは〈有利〉（都合がよい）の意味。有意は統計上の差なので、都合の良さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬の効果は、統計的に有意なと認められた。", "corrected_sentence": "この薬の効果は、統計的に有意だと認められた。", "error_description": "「有意」の後は「だ」で続ける（誤り：な、正しい形：だ）。「な」は名詞を修飾する形なので、「と認められた」には続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有意に", "is_correct": true, "explanation": "正解。「有意に下がった」で、統計的に差が認められるほど血圧が下がったことを副詞として表す。"}, {"text": "有意だ", "is_correct": false, "explanation": "「有意だ血圧が下がった」は「だ」が名詞の前に直接置けず、文が成り立たない。"}, {"text": "有意な", "is_correct": false, "explanation": "「有意な血圧」は名詞を修飾する形で、後ろの「下がった」を修飾できないので合わない。"}, {"text": "有意である", "is_correct": false, "explanation": "「有意である血圧が下がった」は断定の形が名詞を修飾できず、文が成り立たない。"}], "correct_form": "有意に", "base_form": "有意だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"有意に": "正解。「有意に下がった」で、統計的に差が認められるほど血圧が下がったことを副詞として表す。", "有意だ": "「有意だ血圧が下がった」は「だ」が名詞の前に直接置けず、文が成り立たない。", "有意な": "「有意な血圧」は名詞を修飾する形で、後ろの「下がった」を修飾できないので合わない。", "有意である": "「有意である血圧が下がった」は断定の形が名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬を飲んだ人は、熱が有意だ下がった。", "corrected_sentence": "この薬を飲んだ人は、熱が有意に下がった。", "error_description": "「有意」は副詞形の「に」で「下がった」を修飾する（誤り：だ、正しい形：に）。「有意だ」は「下がった」を修飾できず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有意な", "is_correct": true, "explanation": "正解。「有意な違い」で、統計的に意味のある違いを名詞の前で修飾する連体形。"}, {"text": "有意で", "is_correct": false, "explanation": "「有意で違い」は「で」で止まる接続の形で、名詞「違い」を修飾できず、文が成り立たない。"}, {"text": "有意なら", "is_correct": false, "explanation": "「有意なら違い」は仮定の形で、名詞「違い」を修飾できず、文が成り立たない。"}, {"text": "有意だろう", "is_correct": false, "explanation": "「有意だろう違い」は推量の形で文を言い切るもので、名詞「違い」を修飾できない。"}], "correct_form": "有意な", "base_form": "有意だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"有意な": "正解。「有意な違い」で、統計的に意味のある違いを名詞の前で修飾する連体形。", "有意で": "「有意で違い」は「で」で止まる接続の形で、名詞「違い」を修飾できず、文が成り立たない。", "有意なら": "「有意なら違い」は仮定の形で、名詞「違い」を修飾できず、文が成り立たない。", "有意だろう": "「有意だろう違い」は推量の形で文を言い切るもので、名詞「違い」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
