INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36725, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "統計的に意味のある差があること。偶然ではなく、ちゃんとした違いがあること。", "primary_collocate": null, "pronunciation": "ゆうい", "ipa": "jɯːi", "syllable_count": 3, "sentences": [{"text": "統計の検定で、この差は偶然ではなく有意だと確認された。", "target_word": "有意", "complexity_tier": "T3", "furigana": "統計[とうけい]の検定[けんてい]で、この差[さ]は偶然[ぐうぜん]ではなく有意[ゆうい]だと確認[かくにん]された。", "sentence_source": "generated"}, {"text": "有意な結果が出たので、論文に詳しく書いた。", "target_word": "有意", "complexity_tier": "T3", "furigana": "有意[ゆうい]な結果[けっか]が出[で]たので、論文[ろんぶん]に詳[くわ]しく書[か]いた。", "sentence_source": "generated"}, {"text": "サンプルが少なすぎて、有意な結果は得られなかった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "サンプルが少[すく]なすぎて、有意[ゆうい]な結果[けっか]は得[え]られなかった。", "sentence_source": "generated"}, {"text": "この二つのグループの差は、統計的に有意である。", "target_word": "有意", "complexity_tier": "T3", "furigana": "この二[ふた]つのグループの差[さ]は、統計的[とうけいてき]に有意[ゆうい]である。", "sentence_source": "generated"}, {"text": "検定をしたところ、薬の効果は有意だった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "検定[けんてい]をしたところ、薬[くすり]の効果[こうか]は有意[ゆうい]だった。", "sentence_source": "generated"}, {"text": "調査の数字は偶然の違いではなく、有意なものだと言える。", "target_word": "有意", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の数字[すうじ]は偶然[ぐうぜん]の違[ちが]いではなく、有意[ゆうい]なものだと言[い]える。", "sentence_source": "generated"}, {"text": "差が小さくても、データが多ければ有意になることがある。", "target_word": "有意", "complexity_tier": "T3", "furigana": "差[さ]が小[ちい]さくても、データが多[おお]ければ有意[ゆうい]になることがある。", "sentence_source": "generated"}, {"text": "先生は「この差が有意かどうか、まず検定しましょう」と言った。", "target_word": "有意", "complexity_tier": "T3", "furigana": "先生[せんせい]は「この差[さ]が有意[ゆうい]かどうか、まず検定[けんてい]しましょう」と言[い]った。", "sentence_source": "generated"}, {"text": "結果が有意でなかったので、仮説は支持されなかった。", "target_word": "有意", "complexity_tier": "T3", "furigana": "結果[けっか]が有意[ゆうい]でなかったので、仮説[かせつ]は支持[しじ]されなかった。", "sentence_source": "generated"}, {"text": "偶然ではなく有意に違うことを示すため、何度も実験を繰り返した。", "target_word": "有意", "complexity_tier": "T3", "furigana": "偶然[ぐうぜん]ではなく有意[ゆうい]に違[ちが]うことを示[しめ]すため、何度[なんど]も実験[じっけん]を繰[く]り返[かえ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有意だ", "label": "終止形"}, {"form": "有意な", "label": "連体形"}, {"form": "有意に", "label": "連用形"}, {"form": "有意である", "label": "断定形"}], "register": "書き言葉・学術的", "sense_fingerprint": "統計の検定で、偶然ではないと認められること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "正解。「有意だと確認された」で、偶然ではない統計的な差だと認められたことを表す。"}, {"text": "豊か", "is_correct": false, "explanation": "「偶然ではなく豊かだ」は意味が通らず、検定の結果の説明にならない。"}, {"text": "穏やか", "is_correct": false, "explanation": "「偶然ではなく穏やかだ」は検定の話に合わず、意味が成り立たない。"}, {"text": "愉快", "is_correct": false, "explanation": "「偶然ではなく愉快だ」は意味が通らず、統計の判断として不自然。"}], "explanations": {"有意": "正解。「有意だと確認された」で、偶然ではない統計的な差だと認められたことを表す。", "豊か": "「偶然ではなく豊かだ」は意味が通らず、検定の結果の説明にならない。", "穏やか": "「偶然ではなく穏やかだ」は検定の話に合わず、意味が成り立たない。", "愉快": "「偶然ではなく愉快だ」は意味が通らず、統計の判断として不自然。"}, "sentence_index": 0, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この講座は、学生にとって有意だった。", "explanation": "ここは〈有意義〉（価値がある）の意味。有意は統計で差が認められることなので、講座の価値には使わない。"}, {"text": "地元では、この二人の画家がとても有意だ。", "explanation": "ここは〈有名〉の意味。有意は統計的な差を表すので、人の知名度には使わない。"}, {"text": "その申し出は本当に有意だ。", "explanation": "ここは〈ありがたい〉の意味。有意は統計上の差なので、申し出への感謝の気持ちには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有意", "is_correct": true, "explanation": "正解。「有意になる」で、データが多いと統計的な差が認められることを表す。"}, {"text": "元気", "is_correct": false, "explanation": "「元気になる」は意味が通らず、データの数と結びつかない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫になる」は文の内容に合わず、統計の話にならない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かになる」は意味が通らず、データの量の話として不自然。"}], "explanations": {"有意": "正解。「有意になる」で、データが多いと統計的な差が認められることを表す。", "元気": "「元気になる」は意味が通らず、データの数と結びつかない。", "丈夫": "「丈夫になる」は文の内容に合わず、統計の話にならない。", "静か": "「静かになる」は意味が通らず、データの量の話として不自然。"}, "sentence_index": 6, "correct_answer": "有意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この試合は、後半に有意に進んだ。", "explanation": "ここは〈有利〉（都合よく進む）の意味。有意は統計的な差なので、試合の進み方には使わない。"}, {"text": "彼は会議の進行がとても有意で、みんなが頼りにしている。", "explanation": "ここは〈有能〉の意味。有意は統計的な差を表すので、人の能力の高さには使わない。"}, {"text": "この施設は一時間五百円で、有意だ。", "explanation": "ここは〈有料〉（お金がかかる）の意味。有意は統計的な差の意味で、料金の有無には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この差は統計的に有意にと言える。", "corrected_sentence": "この差は統計的に有意だと言える。", "error_description": "「有意」は「だ」で「と言える」に続く（誤り：に、正しい形：だ）。「に」は副詞形で、「と言える」の前には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有意な", "is_correct": true, "explanation": "正解。「有意な結果」で、統計的に差が認められた結果を名詞の前で修飾する連体形。"}, {"text": "有意だ", "is_correct": false, "explanation": "「有意だ結果」は「だ」が名詞の前に直接置けず、文が成り立たない。"}, {"text": "有意に", "is_correct": false, "explanation": "「有意に結果」は副詞形で、名詞「結果」を修飾できない。"}, {"text": "有意である", "is_correct": false, "explanation": "「有意である結果」は断定の形が名詞を修飾できず、文が成り立たない。"}], "correct_form": "有意な", "base_form": "有意だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"有意な": "正解。「有意な結果」で、統計的に差が認められた結果を名詞の前で修飾する連体形。", "有意だ": "「有意だ結果」は「だ」が名詞の前に直接置けず、文が成り立たない。", "有意に": "「有意に結果」は副詞形で、名詞「結果」を修飾できない。", "有意である": "「有意である結果」は断定の形が名詞を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験の結果、差は有意だ認められた。", "corrected_sentence": "実験の結果、差は有意に認められた。", "error_description": "「有意」は副詞形の「に」で「認められた」を修飾する（誤り：だ、正しい形：に）。「有意だ」は「認められた」に直接続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有意", "is_correct": true, "explanation": "正解。「有意かどうか」で、統計的に差があるかどうかを表す語幹の形。"}, {"text": "有意で", "is_correct": false, "explanation": "「有意でかどうか」は「で」の接続形が「かどうか」に直接続かず、文が成り立たない。"}, {"text": "有意なら", "is_correct": false, "explanation": "「有意ならかどうか」は仮定の形が「かどうか」の前に来ず、意味が通らない。"}, {"text": "有意だろう", "is_correct": false, "explanation": "「有意だろうかどうか」は推量の形が「かどうか」の前に来ず、文が成り立たない。"}], "correct_form": "有意", "base_form": "有意だ", "form_label": "語幹＋かどうか", "sentence_index": 7, "explanations": {"有意": "正解。「有意かどうか」で、統計的に差があるかどうかを表す語幹の形。", "有意で": "「有意でかどうか」は「で」の接続形が「かどうか」に直接続かず、文が成り立たない。", "有意なら": "「有意ならかどうか」は仮定の形が「かどうか」の前に来ず、意味が通らない。", "有意だろう": "「有意だろうかどうか」は推量の形が「かどうか」の前に来ず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
