INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを知ったり、わかったりすること。", "primary_collocate": null, "pronunciation": "にんち", "ipa": "ɲiɲt͡ɕi", "syllable_count": 3, "sentences": [{"text": "子どもは成長とともに、周りの世界を認知するようになる。", "target_word": "認知", "complexity_tier": "T3", "furigana": "子[こ]どもは成長[せいちょう]とともに、周[まわ]りの世界[せかい]を認知[にんち]するようになる。", "sentence_source": "generated"}, {"text": "新しい商品が広く認知されるまで、一年かかった。", "target_word": "認知", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]が広[ひろ]く認知[にんち]されるまで、一年[いちねん]かかった。", "sentence_source": "generated"}, {"text": "彼は部屋の空気の変化を素早く認知して、窓を開けた。", "target_word": "認知", "complexity_tier": "T3", "furigana": "彼[かれ]は部[へ]屋[や]の空[くう]気[き]の変[へん]化[か]を素[す]早[ばや]く認[にん]知[ち]して、窓[まど]を開[あ]けた。", "sentence_source": "generated"}, {"text": "この問題は、まだ社会に十分認知されていない。", "target_word": "認知", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、まだ社会[しゃかい]に十分[じゅうぶん]認知[にんち]されていない。", "sentence_source": "generated"}, {"text": "赤ちゃんは、数か月で母親の顔を認知できるようになる。", "target_word": "認知", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、数[すう]か月[げつ]で母親[ははおや]の顔[かお]を認知[にんち]できるようになる。", "sentence_source": "generated"}, {"text": "環境問題の認知が広がり、ごみを減らす人が増えた。", "target_word": "認知", "complexity_tier": "T3", "furigana": "環境[かんきょう]問題[もんだい]の認知[にんち]が広[ひろ]がり、ごみを減[へ]らす人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "暗い道では、遠くの人の姿を認知するのが難しい。", "target_word": "認知", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]では、遠[とお]くの人[ひと]の姿[すがた]を認知[にんち]するのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "この活動を認知してもらうために、ポスターを作った。", "target_word": "認知", "complexity_tier": "T3", "furigana": "この活動[かつどう]を認知[にんち]してもらうために、ポスターを作[つく]った。", "sentence_source": "generated"}, {"text": "犬は人間の言葉を、ある程度認知しているらしい。", "target_word": "認知", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]の言葉[ことば]を、ある程度[ていど]認知[にんち]しているらしい。", "sentence_source": "generated"}, {"text": "危険を認知した運転手は、急いで車を止めた。", "target_word": "認知", "complexity_tier": "T3", "furigana": "危険[きけん]を認知[にんち]した運転手[うんてんしゅ]は、急[いそ]いで車[くるま]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認知する", "label": "辞書形"}, {"form": "認知した", "label": "過去形"}, {"form": "認知して", "label": "て形"}, {"form": "認知される", "label": "受身形"}, {"form": "認知できる", "label": "可能形"}], "register": "やや硬い・書き言葉", "sense_fingerprint": "物事や存在を知り、それとわかること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認知", "is_correct": true, "explanation": "文中の『認知する』。周りの世界を知り、理解していくという意味に合う。"}, {"text": "延長", "is_correct": false, "explanation": "時間や距離を長く伸ばす意味で、世界を対象にする文には合わない。"}, {"text": "修繕", "is_correct": false, "explanation": "壊れた物を直す意味で、世界を対象にする文には合わない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりを終わらせる意味で、ここでは文が通らない。"}], "explanations": {"認知": "文中の『認知する』。周りの世界を知り、理解していくという意味に合う。", "延長": "時間や距離を長く伸ばす意味で、世界を対象にする文には合わない。", "修繕": "壊れた物を直す意味で、世界を対象にする文には合わない。", "解散": "集まりを終わらせる意味で、ここでは文が通らない。"}, "sentence_index": 0, "correct_answer": "認知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その俳優は台本の長いせりふを一晩で認知した。", "explanation": "ここは〈暗記〉（覚えて忘れないこと）の意味。認知は知ったりわかったりすることで、せりふを覚えて身につける意味では使わないので合わない。"}, {"text": "会社は彼の提案を認知して、すぐに予算をつけた。", "explanation": "ここは〈承認〉（正式に認めて許可する）の意味。認知は物事を知って認めることで、許可を与える意味では使わないので合わない。"}, {"text": "彼は生まれた子を、法律の手続きで自分の子として認知した。", "explanation": "ここは〈法律上の認知〉（父親が子を自分の子と認めること）の意味。物事を知る働きとは別の法律用語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認知", "is_correct": true, "explanation": "文中の『認知する』。遠くの人の姿を見分けて知るという意味に合う。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、人の姿を対象にする文には合わない。"}, {"text": "製造", "is_correct": false, "explanation": "物を作る意味で、姿を対象にはできないので文が通らない。"}, {"text": "消毒", "is_correct": false, "explanation": "菌を殺す意味で、人の姿には使わないので合わない。"}], "explanations": {"認知": "文中の『認知する』。遠くの人の姿を見分けて知るという意味に合う。", "配達": "品物を届ける意味で、人の姿を対象にする文には合わない。", "製造": "物を作る意味で、姿を対象にはできないので文が通らない。", "消毒": "菌を殺す意味で、人の姿には使わないので合わない。"}, "sentence_index": 6, "correct_answer": "認知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "『はい、認知しました』と彼は返事をした。", "explanation": "ここは〈承知〉（引き受けて了解する）の意味。認知は物事を知って認めることで、返事として了解する意味では使わないので合わない。"}, {"text": "学校は校則を認知して、髪を染めることを許した。", "explanation": "ここは〈容認〉（認めて受け入れること）の意味。認知は物事の存在を知って認めることで、規則を受け入れて許可する意味では使わないので合わない。"}, {"text": "祖父は認知が進み、家族の名前をよく忘れるようになった。", "explanation": "ここは〈認知症〉（脳の働きが衰える病気）の意味。知ることの働きとは別の病状を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その取り組みは、地域の人々を広く認知されるようになった。", "corrected_sentence": "その取り組みは、地域の人々に広く認知されるようになった。", "error_description": "『認知される』の動作主は『〜に』で示す。『人々を』は目的語の『を』なので誤り。正しくは『人々に認知される』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その祭りは、地元の人々に長く認知してきた。", "corrected_sentence": "その祭りは、地元の人々に長く認知されてきた。", "error_description": "主語『祭り』は認められる側なので受身『認知されてきた』が正しい。能動の『認知してきた』では、祭りが認知する側になってしまい誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『指標になる』の『に』。変化の結果を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "『指標をなる』は目的語を示すが、『なる』は目的語をとらないので誤り。"}, {"text": "が", "is_correct": false, "explanation": "『指標がなる』は主語を示す形だが、『なる』の文型として意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を表すので、変化を表す『なる』とは合わない。"}], "correct_answer": "に", "explanations": {"に": "『指標になる』の『に』。変化の結果を表し、文に合う。", "を": "『指標をなる』は目的語を示すが、『なる』は目的語をとらないので誤り。", "が": "『指標がなる』は主語を示す形だが、『なる』の文型として意味が通らない。", "で": "『で』は場所や手段を表すので、変化を表す『なる』とは合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『指標に』の『に』。それを基準にして測ることを表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "『点を指標を』と目的語が二つ重なるので誤り。"}, {"text": "の", "is_correct": false, "explanation": "『指標の』は修飾を表すが、後ろの『目的地までの距離を測った』とはつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "『指標へ』は方向を表すので、基準を示す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "『指標に』の『に』。それを基準にして測ることを表し、文に合う。", "を": "『点を指標を』と目的語が二つ重なるので誤り。", "の": "『指標の』は修飾を表すが、後ろの『目的地までの距離を測った』とはつながらない。", "へ": "『指標へ』は方向を表すので、基準を示す文脈には合わない。"}, "error_tags": {"を": "二重の目的語", "の": "修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを測るための目印。", "primary_collocate": null, "pronunciation": "しひょう", "ipa": "ɕihjoː", "syllable_count": 3, "sentences": [{"text": "雪の深さを測るために、庭に立てた棒を指標にした。", "target_word": "指標", "complexity_tier": "T3", "furigana": "雪[ゆき]の深[ふか]さを測[はか]るために、庭[にわ]に立[た]てた棒[ぼう]を指[し]標[ひょう]にした。", "sentence_source": "generated"}, {"text": "体重は、健康を測る一つの指標になる。", "target_word": "指標", "complexity_tier": "T3", "furigana": "体重[たいじゅう]は、健康[けんこう]を測[はか]る一[ひと]つの指標[しひょう]になる。", "sentence_source": "generated"}, {"text": "先生は、学力を測る指標として試験の点数を使っている。", "target_word": "指標", "complexity_tier": "T3", "furigana": "先生[せんせい]は、学力[がくりょく]を測[はか]る指標[しひょう]として試験[しけん]の点数[てんすう]を使[つか]っている。", "sentence_source": "generated"}, {"text": "川の水のきれいさを測る指標として、魚の種類を調べる。", "target_word": "指標", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]のきれいさを測[はか]る指標[しひょう]として、魚[さかな]の種類[しゅるい]を調[しら]べる。", "sentence_source": "generated"}, {"text": "新しい指標を使って、町の暮らしやすさを比べた。", "target_word": "指標", "complexity_tier": "T3", "furigana": "新[あたら]しい指標[しひょう]を使[つか]って、町[まち]の暮[く]らしやすさを比[くら]べた。", "sentence_source": "generated"}, {"text": "温度計の細かい線は、暑さを測るための指標だ。", "target_word": "指標", "complexity_tier": "T3", "furigana": "温度計[おんどけい]の細[こま]かい線[せん]は、暑[あつ]さを測[はか]るための指標[しひょう]だ。", "sentence_source": "generated"}, {"text": "売り上げは、会社の成長を測る大切な指標だ。", "target_word": "指標", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは、会社[かいしゃ]の成長[せいちょう]を測[はか]る大切[たいせつ]な指標[しひょう]だ。", "sentence_source": "generated"}, {"text": "地図の上の青い点を指標に、目的地までの距離を測った。", "target_word": "指標", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]の青[あお]い点[てん]を指標[しひょう]に、目的地[もくてきち]までの距離[きょり]を測[はか]った。", "sentence_source": "generated"}, {"text": "睡眠時間は、疲れ具合を測る指標の一つだ。", "target_word": "指標", "complexity_tier": "T3", "furigana": "睡眠[すいみん]時間[じかん]は、疲[つか]れ具合[ぐあい]を測[はか]る指標[しひょう]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "学校ごとの成績を比べるには、共通の指標が必要だ。", "target_word": "指標", "complexity_tier": "T3", "furigana": "学校[がっこう]ごとの成績[せいせき]を比[くら]べるには、共通[きょうつう]の指標[しひょう]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指標", "label": "基本形"}, {"form": "指標に", "label": "に格"}, {"form": "指標として", "label": "資格を表す形"}, {"form": "指標の", "label": "連体形"}], "register": "やや硬い・中立", "sense_fingerprint": "距離や程度を測るときに頼りにする目印", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指標", "is_correct": true, "explanation": "文中の『指標にした』。雪の深さを測るための目印として使う意味に合う。"}, {"text": "装飾", "is_correct": false, "explanation": "飾りとして付ける意味で、測るための目印という文脈には合わない。"}, {"text": "包装", "is_correct": false, "explanation": "物を包む意味で、棒を指標にするという文には合わない。"}, {"text": "陳列", "is_correct": false, "explanation": "商品などを並べて見せる意味で、ここでは文が通らない。"}], "explanations": {"指標": "文中の『指標にした』。雪の深さを測るための目印として使う意味に合う。", "装飾": "飾りとして付ける意味で、測るための目印という文脈には合わない。", "包装": "物を包む意味で、棒を指標にするという文には合わない。", "陳列": "商品などを並べて見せる意味で、ここでは文が通らない。"}, "sentence_index": 0, "correct_answer": "指標"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は班ごとに、掃除の指標を出した。", "explanation": "ここは〈指示〉（人に命じて動かすこと）の意味。指標は物事を測る目印で、命じる意味では使わないので合わない。"}, {"text": "先生が手を上げて、子どもたちに指標を送った。", "explanation": "ここは〈合図〉の意味。指標は測るための目印で、相手に知らせる動作の意味はないので合わない。"}, {"text": "理科の授業で、昆虫の指標を箱に集めた。", "explanation": "ここは〈標本〉（研究用に集めた見本）の意味。指標は測るための目印で、集めて保存する見本の意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指標", "is_correct": true, "explanation": "文中の『大切な指標だ』。会社の成長を測る目印の意味に合う。"}, {"text": "試練", "is_correct": false, "explanation": "困難な経験の意味で、会社の成長を測る文には合わない。"}, {"text": "衣装", "is_correct": false, "explanation": "身につける服装の意味で、ここでは文が通らない。"}, {"text": "悲劇", "is_correct": false, "explanation": "不幸な出来事の意味で、測る目印の文脈には合わない。"}], "explanations": {"指標": "文中の『大切な指標だ』。会社の成長を測る目印の意味に合う。", "試練": "困難な経験の意味で、会社の成長を測る文には合わない。", "衣装": "身につける服装の意味で、ここでは文が通らない。", "悲劇": "不幸な出来事の意味で、測る目印の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "指標"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交通安全の指標を募集した。", "explanation": "ここは〈標語〉（短い言葉で伝えるもの）の意味。指標は測るための目印で、言葉の意味はないので合わない。"}, {"text": "パーティーで、彼は指標を配った。", "explanation": "ここは〈名刺〉の意味。指標は測るための目印で、自分の名前や所属を書いて配る紙の意味はないので合わない。"}, {"text": "入学式で、校長の指標が長かった。", "explanation": "ここは〈挨拶〉（式での話）の意味。指標は測るための目印で、話や言葉のあいさつの意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この数字は、景気の良し悪しを測る指標を使われる。", "corrected_sentence": "この数字は、景気の良し悪しを測る指標として使われる。", "error_description": "『使われる』の前は資格を表す『指標として』が正しい。『指標を』は目的語を示すので、受身の文では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この数字は、体の状態を測る指標を一つだ。", "corrected_sentence": "この数字は、体の状態を測る指標の一つだ。", "error_description": "「指標」の後は「の一つだ」と続ける（誤り：を、正しい形：の）。「を」は目的語を示す格助詞で、名詞の後に「一つだ」を続けるこの文では使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
