INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『この指標が下がる』の『が』。指標を主語として示し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "『指標を下がる』は目的語を示すが、『下がる』は目的語をとらないので誤り。"}, {"text": "に", "is_correct": false, "explanation": "『指標に下がる』は方向や結果を示すが、この文では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示すので、『指標で下がる』は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『この指標が下がる』の『が』。指標を主語として示し、文に合う。", "を": "『指標を下がる』は目的語を示すが、『下がる』は目的語をとらないので誤り。", "に": "『指標に下がる』は方向や結果を示すが、この文では意味が通らない。", "で": "『で』は場所や手段を示すので、『指標で下がる』は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・結果", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や程度を判断するための手がかりとなるもの。", "primary_collocate": null, "pronunciation": "しひょう", "ipa": "ɕihjoː", "syllable_count": 3, "sentences": [{"text": "失業率は、景気の状態を判断する指標になる。", "target_word": "指標", "complexity_tier": "T3", "furigana": "失業率[しつぎょうりつ]は、景気[けいき]の状態[じょうたい]を判断[はんだん]する指標[しひょう]になる。", "sentence_source": "generated"}, {"text": "血液の数値は、体の調子を知るための大事な指標だ。", "target_word": "指標", "complexity_tier": "T3", "furigana": "血液[けつえき]の数値[すうち]は、体[からだ]の調子[ちょうし]を知[し]るための大事[だいじ]な指標[しひょう]だ。", "sentence_source": "generated"}, {"text": "物価の動きを、経済の指標として毎月確認している。", "target_word": "指標", "complexity_tier": "T3", "furigana": "物価[ぶっか]の動[うご]きを、経済[けいざい]の指標[しひょう]として毎月[まいつき]確認[かくにん]している。", "sentence_source": "generated"}, {"text": "お客さんの笑顔の数は、満足度を判断する指標だと考えられる。", "target_word": "指標", "complexity_tier": "T3", "furigana": "お客[きゃく]さんの笑顔[えがお]の数[かず]は、満足度[まんぞくど]を判断[はんだん]する指標[しひょう]だと考[かんが]えられる。", "sentence_source": "generated"}, {"text": "一つの指標だけで、会社の状態を決めてはいけない。", "target_word": "指標", "complexity_tier": "T3", "furigana": "一[ひと]つの指標[しひょう]だけで、会社[かいしゃ]の状態[じょうたい]を決[き]めてはいけない。", "sentence_source": "generated"}, {"text": "星の明るさは、その星までの距離を考える指標になる。", "target_word": "指標", "complexity_tier": "T3", "furigana": "星[ほし]の明[あか]るさは、その星[ほし]までの距離[きょり]を考[かんが]える指標[しひょう]になる。", "sentence_source": "generated"}, {"text": "土の色が、畑の栄養の程度を判断する指標になった。", "target_word": "指標", "complexity_tier": "T3", "furigana": "土[つち]の色[いろ]が、畑[はたけ]の栄養[えいよう]の程度[ていど]を判断[はんだん]する指標[しひょう]になった。", "sentence_source": "generated"}, {"text": "この指標が下がると、注意が必要だと言われている。", "target_word": "指標", "complexity_tier": "T3", "furigana": "この指標[しひょう]が下[さ]がると、注意[ちゅうい]が必要[ひつよう]だと言[い]われている。", "sentence_source": "generated"}, {"text": "新しい指標が発表され、国の豊かさが比べやすくなった。", "target_word": "指標", "complexity_tier": "T3", "furigana": "新[あたら]しい指標[しひょう]が発表[はっぴょう]され、国[くに]の豊[ゆた]かさが比[くら]べやすくなった。", "sentence_source": "generated"}, {"text": "医者は検査の数値を指標に、治療の方法を決めた。", "target_word": "指標", "complexity_tier": "T3", "furigana": "医者[いしゃ]は検査[けんさ]の数値[すうち]を指標[しひょう]に、治療[ちりょう]の方法[ほうほう]を決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指標", "label": "基本形"}, {"form": "指標に", "label": "に格"}, {"form": "指標として", "label": "資格を表す形"}, {"form": "指標の", "label": "連体修飾（の）"}], "register": "やや硬い・書き言葉", "sense_fingerprint": "状態や程度を判断するときの手がかりになる数値や事柄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指標", "is_correct": true, "explanation": "文中の『指標になる』。景気の状態を判断する手がかりの意味に合う。"}, {"text": "包装", "is_correct": false, "explanation": "物を包む意味で、状態を判断する文には合わない。"}, {"text": "陳列", "is_correct": false, "explanation": "並べて見せる意味で、判断する文脈には合わない。"}, {"text": "衣装", "is_correct": false, "explanation": "身につける服装の意味で、ここでは文が通らない。"}], "explanations": {"指標": "文中の『指標になる』。景気の状態を判断する手がかりの意味に合う。", "包装": "物を包む意味で、状態を判断する文には合わない。", "陳列": "並べて見せる意味で、判断する文脈には合わない。", "衣装": "身につける服装の意味で、ここでは文が通らない。"}, "sentence_index": 0, "correct_answer": "指標"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画を見終えて、みんなで指標を言い合った。", "explanation": "ここは〈感想〉（感じたことや考え）の意味。指標は状態を判断する手がかりで、感じたことを述べる意味では使わないので合わない。"}, {"text": "その店で、指標を払って帰った。", "explanation": "ここは〈代金〉の意味。指標は判断の手がかりで、お金として払う意味はないので合わない。"}, {"text": "先生の指標は、答案の誤りを正確に言い当てていた。", "explanation": "ここは〈指摘〉（誤りを示すこと）の意味。指標は状態を判断する手がかりで、誤りを示す発言の意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指標", "is_correct": true, "explanation": "文中の『指標になった』。畑の栄養の程度を判断する手がかりの意味に合う。"}, {"text": "悲劇", "is_correct": false, "explanation": "不幸な出来事の意味で、判断する文脈には合わない。"}, {"text": "欠陥", "is_correct": false, "explanation": "欠けている点の意味で、判断の手がかりという文脈には合わない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具の意味で、ここでは文が通らない。"}], "explanations": {"指標": "文中の『指標になった』。畑の栄養の程度を判断する手がかりの意味に合う。", "悲劇": "不幸な出来事の意味で、判断する文脈には合わない。", "欠陥": "欠けている点の意味で、判断の手がかりという文脈には合わない。", "寝具": "寝るための道具の意味で、ここでは文が通らない。"}, "sentence_index": 6, "correct_answer": "指標"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達に、長い指標を書いて送った。", "explanation": "ここは〈手紙〉の意味。指標は状態を判断する手がかりで、文章を書いて送るものではないので合わない。"}, {"text": "その歌手は、美しい指標を歌った。", "explanation": "ここは〈歌〉の意味。指標は判断の手がかりで、歌う対象にはならないので合わない。"}, {"text": "新しい指標を買って、毎日着て出かけた。", "explanation": "ここは〈服〉の意味。指標は判断の手がかりで、買って身につけるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "景気の動きを判断する指標を毎月使われている。", "corrected_sentence": "景気の動きを判断する指標が毎月使われている。", "error_description": "受身文で動作を受ける側は「が」で示す。「指標を使われている」は目的語の「を」が残っているので誤り。正しくは「指標が使われている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この数値は、体の状態を判断する指標をなる。", "corrected_sentence": "この数値は、体の状態を判断する指標になる。", "error_description": "『指標になる』の『に』は変化の結果を表す。『指標をなる』は、『なる』が目的語をとらないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「注目を浴びる」の目的語を示す形で、多くの人の関心を集めた意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「注目に浴びる」とは言わず、「に」は対象を示すが「浴びる」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「注目で浴びる」は手段を示すことになり、「注目を浴びる」の形にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「注目と浴びる」は並列を示すことになり、「浴びる」の目的語の関係が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「注目を浴びる」の目的語を示す形で、多くの人の関心を集めた意味になる。", "に": "「注目に浴びる」とは言わず、「に」は対象を示すが「浴びる」の目的語にはならない。", "で": "「注目で浴びる」は手段を示すことになり、「注目を浴びる」の形にならず不自然。", "と": "「注目と浴びる」は並列を示すことになり、「浴びる」の目的語の関係が成り立たない。"}, "error_tags": {}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無視", "is_correct": true, "explanation": "注目（関心を向ける）の反対で、関心を向けないことを表し、対義語として辞書に並ぶ。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、注目と反対の意味関係にない。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷雨は天気の現象で、注目と反対の意味関係にない。"}, {"text": "請求書", "is_correct": false, "explanation": "請求書は代金を求める書類で、注目と反対の意味関係にない。"}], "correct_answer": "無視", "explanations": {"無視": "注目（関心を向ける）の反対で、関心を向けないことを表し、対義語として辞書に並ぶ。", "地震": "地震は自然現象で、注目と反対の意味関係にない。", "雷雨": "雷雨は天気の現象で、注目と反対の意味関係にない。", "請求書": "請求書は代金を求める書類で、注目と反対の意味関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無視", "is_correct": true, "explanation": "注目（関心を向ける）の反対で、関心を向けないことを表し、対義語として辞書に並ぶ。"}, {"text": "雪崩", "is_correct": false, "explanation": "雪崩は自然現象で、注目と反対の意味関係にない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、注目と反対の意味関係にない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足は睡眠が足りない状態で、注目の対義語ではない。"}], "correct_answer": "無視", "explanations": {"無視": "注目（関心を向ける）の反対で、関心を向けないことを表し、対義語として辞書に並ぶ。", "雪崩": "雪崩は自然現象で、注目と反対の意味関係にない。", "停電": "停電は電気が止まることで、注目と反対の意味関係にない。", "寝不足": "寝不足は睡眠が足りない状態で、注目の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事を大事なことだと考えて、関心を強く向けること。", "primary_collocate": null, "pronunciation": "ちゅうもく", "ipa": "tɕɯːmokɯ", "syllable_count": 4, "sentences": [{"text": "新しい映画は、世界中から注目を集めています。", "target_word": "注目", "complexity_tier": "T3", "furigana": "新[あたら]しい映画[えいが]は、世界中[せかいじゅう]から注目[ちゅうもく]を集[あつ]めています。", "sentence_source": "generated"}, {"text": "彼の発明は、多くの人の注目を浴びました。", "target_word": "注目", "complexity_tier": "T3", "furigana": "彼[かれ]の発明[はつめい]は、多[おお]くの人[ひと]の注目[ちゅうもく]を浴[あ]びました。", "sentence_source": "generated"}, {"text": "先生は「ここに注目してください」と言いました。", "target_word": "注目", "complexity_tier": "T3", "furigana": "先生[せんせい]は「ここに注目[ちゅうもく]してください」と言[い]いました。", "sentence_source": "generated"}, {"text": "十五歳の選手が、大会で注目されています。", "target_word": "注目", "complexity_tier": "T3", "furigana": "十五歳[じゅうごさい]の選手[せんしゅ]が、大会[たいかい]で注目[ちゅうもく]されています。", "sentence_source": "generated"}, {"text": "この店は、安くておいしいと評判で、注目の的になっています。", "target_word": "注目", "complexity_tier": "T3", "furigana": "この店[みせ]は、安[やす]くておいしいと評判[ひょうばん]で、注目[ちゅうもく]の的[まと]になっています。", "sentence_source": "generated"}, {"text": "彼女の歌があまりにすばらしくて、会場中が注目した。", "target_word": "注目", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌[うた]があまりにすばらしくて、会場中[かいじょうじゅう]が注目[ちゅうもく]した。", "sentence_source": "generated"}, {"text": "今日のニュースで、いちばん注目したのは天気の話です。", "target_word": "注目", "complexity_tier": "T3", "furigana": "今日[きょう]のニュースで、いちばん注目[ちゅうもく]したのは天気[てんき]の話[はなし]です。", "sentence_source": "generated"}, {"text": "新製品は、発売前から注目されていました。", "target_word": "注目", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]は、発売前[はつばいまえ]から注目[ちゅうもく]されていました。", "sentence_source": "generated"}, {"text": "人の注目を集めたいなら、最初の一言が大事です。", "target_word": "注目", "complexity_tier": "T3", "furigana": "人[ひと]の注目[ちゅうもく]を集[あつ]めたいなら、最初[さいしょ]の一言[ひとこと]が大事[だいじ]です。", "sentence_source": "generated"}, {"text": "子どものころから、彼は絵の才能で注目されていた。", "target_word": "注目", "complexity_tier": "T3", "furigana": "子[こ]どものころから、彼[かれ]は絵[え]の才能[さいのう]で注目[ちゅうもく]されていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "注目", "label": "基本形"}, {"form": "注目する", "label": "動詞形（辞書形）"}, {"form": "注目した", "label": "過去形"}, {"form": "注目される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "大事だと思って関心を向けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注目", "is_correct": true, "explanation": "「世界中から注目を集める」の形で、人々の関心を表すので文が成り立つ。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は「世界中から集める」ものではなく、この空所に入らない。"}, {"text": "台風", "is_correct": false, "explanation": "台風は「世界中から集める」ものではなく、文として成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは「世界中から集める」ものではなく、この空所に入らない。"}], "explanations": {"注目": "「世界中から注目を集める」の形で、人々の関心を表すので文が成り立つ。", "寝坊": "寝坊は「世界中から集める」ものではなく、この空所に入らない。", "台風": "台風は「世界中から集める」ものではなく、文として成り立たない。", "夕焼け": "夕焼けは「世界中から集める」ものではなく、この空所に入らない。"}, "sentence_index": 0, "correct_answer": "注目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合に勝った選手は、注目の涙を流した。", "explanation": "ここは〈感激〉の意味。注目は関心を向けることで、感動の涙とは結びつかない。"}, {"text": "友人の結婚を、みんなで注目で祝った。", "explanation": "ここは〈祝う〉の意味。注目は関心を向けることで、祝うための手段としては使わない。"}, {"text": "勝利の場面で、会場は選手に大きな注目の花束を贈った。", "explanation": "ここは〈贈り物〉の意味。注目は関心を向けることで、花束のような物を贈る意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注目", "is_correct": true, "explanation": "「いちばん注目したのは天気の話」で、関心を向けた対象を表すので文が成り立つ。"}, {"text": "大雪", "is_correct": false, "explanation": "「いちばん大雪したのは」は意味をなさず、この空所に入らない。"}, {"text": "停電", "is_correct": false, "explanation": "「いちばん停電したのは」は意味をなさず、文として成り立たない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「いちばん寝不足したのは」は意味をなさず、この空所に入らない。"}], "explanations": {"注目": "「いちばん注目したのは天気の話」で、関心を向けた対象を表すので文が成り立つ。", "大雪": "「いちばん大雪したのは」は意味をなさず、この空所に入らない。", "停電": "「いちばん停電したのは」は意味をなさず、文として成り立たない。", "寝不足": "「いちばん寝不足したのは」は意味をなさず、この空所に入らない。"}, "sentence_index": 6, "correct_answer": "注目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族を失って、彼は注目に暮れていた。", "explanation": "ここは〈悲しみ〉の意味。「悲しみに暮れる」の「悲しみ」にあたり、注目では言えない。"}, {"text": "チームは毎年の注目を達成して、ついに優勝した。", "explanation": "ここは〈目標〉の意味。注目は関心を向けることで、達成すべき目的とは合わない。"}, {"text": "その失敗の注目を負って、社長は辞任した。", "explanation": "ここは〈責任〉の意味。注目は関心を向けることで、負うべきものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいゲームは、発売前から注目に集めています。", "corrected_sentence": "新しいゲームは、発売前から注目を集めています。", "error_description": "「集める」は「を」を取る。「注目に集める」は「に」が誤りで、「注目を集める」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日のニュースで、いちばん注目に集めたのは地震の話です。", "corrected_sentence": "今日のニュースで、いちばん注目を集めたのは地震の話です。", "error_description": "「集める」は「を」を取る。「注目に集めた」は「に」が誤りで、「注目を集めた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示し、「チンパンジーは人間に近い」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「人間に近い」は形容詞で目的語をとらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「チンパンジーで人間に近い」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「人間に近い」の主語にはならない。"}], "correct_answer": "は", "explanations": {"は": "主題を示し、「チンパンジーは人間に近い」と自然に続く。", "を": "目的語を示すが、「人間に近い」は形容詞で目的語をとらないので合わない。", "で": "場所や手段を示すが、「チンパンジーで人間に近い」は意味が通らない。", "へ": "方向を示すが、「人間に近い」の主語にはならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「チンパンジーが石で割る」となり、見た場面の動作主になる。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、「チンパンジーに石で」では主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、主語の位置には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「チンパンジーより石で割る」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「チンパンジーが石で割る」となり、見た場面の動作主になる。", "に": "相手や場所を示すが、「チンパンジーに石で」では主語にならない。", "から": "起点を示すが、主語の位置には合わない。", "より": "比較の基準を示すが、「チンパンジーより石で割る」は意味が通らない。"}, "error_tags": {"に": "相手・場所", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "チンパンジーは、人間にいちばん近い、おさるさんの一種です。", "primary_collocate": null, "pronunciation": "ちんぱんじー", "ipa": "tɕiɴpaɴdʑiː", "syllable_count": 6, "sentences": [{"text": "動物園で、チンパンジーがバナナを食べていた。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で、チンパンジーがバナナを食[た]べていた。", "sentence_source": "generated"}, {"text": "チンパンジーは人間に近いので、表情も似ている。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーは人間[にんげん]に近[ちか]いので、表情[ひょうじょう]も似[に]ている。", "sentence_source": "generated"}, {"text": "子どもたちはチンパンジーの前で手をふった。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "子[こ]どもたちはチンパンジーの前[まえ]で手[て]をふった。", "sentence_source": "generated"}, {"text": "チンパンジーは木の枝を道具のように使う。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーは木[き]の枝[えだ]を道具[どうぐ]のように使[つか]う。", "sentence_source": "generated"}, {"text": "母は、チンパンジーの赤ちゃんを見て笑った。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "母[はは]は、チンパンジーの赤[あか]ちゃんを見[み]て笑[わら]った。", "sentence_source": "generated"}, {"text": "あのチンパンジーは、飼育員さんの顔をよく覚えている。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "あのチンパンジーは、飼育員[しいくいん]さんの顔[かお]をよく覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "雨が降ると、チンパンジーは葉を傘にして座る。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、チンパンジーは葉[は]を傘[かさ]にして座[すわ]る。", "sentence_source": "generated"}, {"text": "チンパンジーが石でナッツを割るのを、みんなで見た。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーが石[いし]でナッツを割[わ]るのを、みんなで見[み]た。", "sentence_source": "generated"}, {"text": "チンパンジーは仲間と毛づくろいをして仲よくなる。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーは仲間[なかま]と毛[け]づくろいをして仲[なか]よくなる。", "sentence_source": "generated"}, {"text": "絵本のチンパンジーは、帽子をかぶって自転車に乗っていた。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "絵本[えほん]のチンパンジーは、帽子[ぼうし]をかぶって自転車[じてんしゃ]に乗[の]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チンパンジー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人間にいちばん近いサルの一種の動物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チンパンジー", "is_correct": true, "explanation": "動物園でバナナを食べる主語になれる動物で、ここに入るのはこの語だけ。"}, {"text": "檻", "is_correct": false, "explanation": "檻は動物を入れる設備で、バナナを食べる主語にはならない。"}, {"text": "入場券", "is_correct": false, "explanation": "入場券は人が買うもので、ものを食べることはない。"}, {"text": "売店", "is_correct": false, "explanation": "売店は店で、バナナを食べる主語にはならない。"}], "explanations": {"チンパンジー": "動物園でバナナを食べる主語になれる動物で、ここに入るのはこの語だけ。", "檻": "檻は動物を入れる設備で、バナナを食べる主語にはならない。", "入場券": "入場券は人が買うもので、ものを食べることはない。", "売店": "売店は店で、バナナを食べる主語にはならない。"}, "sentence_index": 0, "correct_answer": "チンパンジー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チンパンジーの背中には、大人の雄だけが持つ銀色の毛がある。", "explanation": "ここは〈ゴリラ〉の意味。大人の雄の背の銀色の毛（シルバーバック）はゴリラの特徴で、チンパンジーの語では別の種を指すことになる。"}, {"text": "チンパンジーは、ほとんど一生を木の上で過ごす。", "explanation": "ここは〈オランウータン〉の意味。ほとんど一生を木の上で過ごすのはオランウータンで、地上で多くの時間を過ごすチンパンジーには合わない。"}, {"text": "チンパンジーには、尻尾のある種類が多い。", "explanation": "ここは〈サル〉（分類全体）の意味。チンパンジーは一つの種類の名なので、「種類が多い」の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チンパンジー", "is_correct": true, "explanation": "葉を傘にして座る主語になれる生き物で、ここに入るのはこの語だけ。"}, {"text": "ベンチ", "is_correct": false, "explanation": "ベンチは人が座る物で、葉を傘にして座る主語にはならない。"}, {"text": "ランドセル", "is_correct": false, "explanation": "ランドセルは背負う物で、座ることはない。"}, {"text": "カーテン", "is_correct": false, "explanation": "カーテンは窓にかける布で、座る主語にならない。"}], "explanations": {"チンパンジー": "葉を傘にして座る主語になれる生き物で、ここに入るのはこの語だけ。", "ベンチ": "ベンチは人が座る物で、葉を傘にして座る主語にはならない。", "ランドセル": "ランドセルは背負う物で、座ることはない。", "カーテン": "カーテンは窓にかける布で、座る主語にならない。"}, "sentence_index": 6, "correct_answer": "チンパンジー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チンパンジーは、温泉に浸かってのんびり過ごすことで知られる。", "explanation": "ここは〈カピバラ〉の意味。温泉に浸かってのんびり過ごす姿で知られるのはカピバラで、チンパンジーの語では合わない。"}, {"text": "チンパンジーは、朝になると夫婦で二重唱をして縄張りを知らせる。", "explanation": "ここは〈テナガザル〉の意味。夫婦で二重唱をして縄張りを知らせるのはテナガザルの習性で、チンパンジーには合わない。"}, {"text": "チンパンジーは、ユーカリの葉をほとんど一日中食べて過ごす。", "explanation": "ここは〈コアラ〉の意味。ユーカリの葉を主に食べて一日の大半を過ごすのはコアラで、チンパンジーには当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "動物園の飼育員が、チンパンジーをエサを渡した。", "corrected_sentence": "動物園の飼育員が、チンパンジーにエサを渡した。", "error_description": "「渡す」の相手を示すのは「に」。「チンパンジーを」と「を」にすると、「エサを」と目的語が二つ並んで文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チンパンジーを、木の実をそっと割った。", "corrected_sentence": "チンパンジーが、木の実をそっと割った。", "error_description": "動作をする主語「チンパンジー」には「が」を付ける。「を」にすると「木の実を」と目的語が二つ並び、文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並べる相手を示し、「チンパンジーと人間の遺伝子は同じだ」と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「人間の遺伝子は同じだ」の前には入らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「チンパンジーで人間の遺伝子は同じだ」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「人間の遺伝子は同じだ」の主語にならない。"}], "correct_answer": "と", "explanations": {"と": "並べる相手を示し、「チンパンジーと人間の遺伝子は同じだ」と続く。", "を": "目的語を示すが、「人間の遺伝子は同じだ」の前には入らない。", "で": "場所や手段を示すが、「チンパンジーで人間の遺伝子は同じだ」は意味が通らない。", "へ": "方向を示すが、「人間の遺伝子は同じだ」の主語にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並べる相手を示し、「チンパンジーとボノボは似た大型のサルだ」と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「似た」は目的語をとらないので文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「チンパンジーからボノボは似た」は並列の形として合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「チンパンジーでボノボは似た」は意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "並べる相手を示し、「チンパンジーとボノボは似た大型のサルだ」と続く。", "を": "目的語を示すが、「似た」は目的語をとらないので文が成り立たない。", "から": "起点を示すが、「チンパンジーからボノボは似た」は並列の形として合わない。", "で": "手段や場所を示すが、「チンパンジーでボノボは似た」は意味が通らない。"}, "error_tags": {"を": "目的語", "から": "起点", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "チンパンジーは、アフリカに生息する大型のサルの一種で、人間と遺伝的に非常に近いことで知られています。", "primary_collocate": null, "pronunciation": "ちんぱんじー", "ipa": "tɕiɴpaɴdʑiː", "syllable_count": 6, "sentences": [{"text": "チンパンジーはアフリカの森に住み、人間と遺伝子が近い。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーはアフリカの森[もり]に住[す]み、人間[にんげん]と遺伝子[いでんし]が近[ちか]い。", "sentence_source": "generated"}, {"text": "研究によると、チンパンジーと人間の遺伝子はほとんど同じだ。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "研究[けんきゅう]によると、チンパンジーと人間[にんげん]の遺伝子[いでんし]はほとんど同[おな]じだ。", "sentence_source": "generated"}, {"text": "学者は、野生のチンパンジーを何十年も観察している。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "学者[がくしゃ]は、野生[やせい]のチンパンジーを何十年[なんじゅうねん]も観察[かんさつ]している。", "sentence_source": "generated"}, {"text": "チンパンジーは群れで暮らし、複雑な社会を作る。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーは群[む]れで暮[く]らし、複雑[ふくざつ]な社会[しゃかい]を作[つく]る。", "sentence_source": "generated"}, {"text": "森が減り、野生のチンパンジーの数も減っている。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "森[もり]が減[へ]り、野生[やせい]のチンパンジーの数[かず]も減[へ]っている。", "sentence_source": "generated"}, {"text": "実験で、チンパンジーは簡単な数字を覚えられると分かった。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "実験[じっけん]で、チンパンジーは簡単[かんたん]な数字[すうじ]を覚[おぼ]えられると分[わ]かった。", "sentence_source": "generated"}, {"text": "チンパンジーの病気は人間にうつることがあるので、研究者は注意している。", "target_word": "チンパンジー", "complexity_tier": "T4", "furigana": "チンパンジーの病気[びょうき]は人間[にんげん]にうつることがあるので、研究者[けんきゅうしゃ]は注意[ちゅうい]している。", "sentence_source": "generated"}, {"text": "チンパンジーとボノボは、よく似た大型のサルだ。", "target_word": "チンパンジー", "complexity_tier": "T3", "furigana": "チンパンジーとボノボは、よく似[に]た大型[おおがた]のサルだ。", "sentence_source": "generated"}, {"text": "保護団体は、チンパンジーの生息地を守る活動を続けている。", "target_word": "チンパンジー", "complexity_tier": "T4", "furigana": "保護団体[ほごだんたい]は、チンパンジーの生息地[せいそくち]を守[まも]る活動[かつどう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "この論文は、チンパンジーの道具使用の進化を扱っている。", "target_word": "チンパンジー", "complexity_tier": "T4", "furigana": "この論文[ろんぶん]は、チンパンジーの道具使用[どうぐしよう]の進化[しんか]を扱[あつか]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チンパンジー", "label": "基本形"}], "register": "formal", "sense_fingerprint": "アフリカに生息し、人間と遺伝的に非常に近い大型のサル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チンパンジー", "is_correct": true, "explanation": "アフリカの森に住み、人間と遺伝子が近い大型のサルで、ここに入るのはこの語だけ。"}, {"text": "細胞", "is_correct": false, "explanation": "細胞は生物の構成単位で、森に住む主語にはならない。"}, {"text": "化石", "is_correct": false, "explanation": "化石は過去の生物の跡で、森に住むことはない。"}, {"text": "海底", "is_correct": false, "explanation": "海底は場所で、森に住み遺伝子が近いという主語にはならない。"}], "explanations": {"チンパンジー": "アフリカの森に住み、人間と遺伝子が近い大型のサルで、ここに入るのはこの語だけ。", "細胞": "細胞は生物の構成単位で、森に住む主語にはならない。", "化石": "化石は過去の生物の跡で、森に住むことはない。", "海底": "海底は場所で、森に住み遺伝子が近いという主語にはならない。"}, "sentence_index": 0, "correct_answer": "チンパンジー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チンパンジーは、一頭の雄を中心に家族単位で暮らす。", "explanation": "ここは〈ゴリラ〉の意味。一頭の雄を中心にした家族単位の群れはゴリラの社会の特徴で、複数の雄と雌が混ざるチンパンジーの群れには合わない。"}, {"text": "チンパンジーは、雌が中心となって群れの争いをおさめることがある。", "explanation": "ここは〈ボノボ〉の意味。雌が中心になって争いをおさめる傾向で知られるのはボノボで、チンパンジーの語を当てると別の種の話になる。"}, {"text": "チンパンジーは、東南アジアの森でしか見られない。", "explanation": "ここは〈オランウータン〉の意味。東南アジアの森でしか見られないのはオランウータンで、アフリカに分布するチンパンジーには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チンパンジー", "is_correct": true, "explanation": "「〜の病気」が人間にうつると言える生き物で、ここに入るのはこの語。"}, {"text": "保険証", "is_correct": false, "explanation": "保険証は身分を示す証明書で、病気の主語にはならない。"}, {"text": "空港", "is_correct": false, "explanation": "空港は施設で、病気にかかることはない。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便局は施設で、病気の主語にはなれない。"}], "explanations": {"チンパンジー": "「〜の病気」が人間にうつると言える生き物で、ここに入るのはこの語。", "保険証": "保険証は身分を示す証明書で、病気の主語にはならない。", "空港": "空港は施設で、病気にかかることはない。", "郵便局": "郵便局は施設で、病気の主語にはなれない。"}, "sentence_index": 6, "correct_answer": "チンパンジー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チンパンジーは、音波で周りの様子を探る。", "explanation": "ここは〈イルカ〉の意味。音波で周囲を探ることで知られるのはイルカで、チンパンジーの語では別の動物を指すことになる。"}, {"text": "チンパンジーは、サバンナで大きな群れを作って暮らす。", "explanation": "ここは〈ヒヒ〉の意味。サバンナで大きな群れを作って暮らすのはヒヒで、森に住むチンパンジーには合わない。"}, {"text": "チンパンジーは、南極の海で群れになって魚を捕る。", "explanation": "ここは〈ペンギン〉の意味。南極の海で群れになって魚を捕るのはペンギンで、チンパンジーの語では意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、チンパンジーを行動を記録した。", "corrected_sentence": "研究者は、チンパンジーの行動を記録した。", "error_description": "「チンパンジーの行動」の「の」は所属を示す。「を」を二つ続けると目的語が二つ並び、文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チンパンジーを、よく群れで暮らしている。", "corrected_sentence": "チンパンジーは、よく群れで暮らしている。", "error_description": "「暮らす」は自動詞なので、主語には「は」を付ける。「を」にすると目的語をとることになり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「連れて」の目的語を示す。ペットの犬を連れて行くので正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。散歩に連れていくのは人なので、犬が主語では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す。連れて行く対象には「を」を使う。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。犬を連れる手段にはならない。"}], "correct_answer": "を", "explanations": {"を": "「連れて」の目的語を示す。ペットの犬を連れて行くので正解。", "が": "主語を示す。散歩に連れていくのは人なので、犬が主語では意味が通らない。", "に": "相手や場所を示す。連れて行く対象には「を」を使う。", "で": "手段や場所を示す。犬を連れる手段にはならない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。犬が急に走り出したので正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。走り出す動作は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す。走り出す動作の主体には使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。犬の動作の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。犬が急に走り出したので正解。", "を": "目的語を示す。走り出す動作は目的語を取らないので合わない。", "に": "相手や場所を示す。走り出す動作の主体には使えない。", "で": "手段や場所を示す。犬の動作の主語にはならない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ペットとしてよく飼われる、四本足の動物です。", "primary_collocate": null, "pronunciation": "いぬ", "ipa": "inɯ", "syllable_count": 2, "sentences": [{"text": "私の家では、白い犬を一匹飼っています。", "target_word": "犬", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]では、白[しろ]い犬[いぬ]を一匹[いっぴき]飼[か]っています。", "sentence_source": "generated"}, {"text": "毎朝、犬を連れて公園まで散歩に行きます。", "target_word": "犬", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、犬[いぬ]を連[つ]れて公園[こうえん]まで散歩[さんぽ]に行[い]きます。", "sentence_source": "generated"}, {"text": "知らない人が来ると、犬が大きな声で吠えました。", "target_word": "犬", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]が来[く]ると、犬[いぬ]が大[おお]きな声[こえ]で吠[ほ]えました。", "sentence_source": "generated"}, {"text": "雨の日は外に出られないので、犬は家の中でつまらなそうにしている。", "target_word": "犬", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]に出[で]られないので、犬[いぬ]は家[いえ]の中[なか]でつまらなそうにしている。", "sentence_source": "generated"}, {"text": "弟は犬が好きですが、猫はあまり好きではありません。", "target_word": "犬", "complexity_tier": "T3", "furigana": "弟[おとうと]は犬[いぬ]が好[す]きですが、猫[ねこ]はあまり好[す]きではありません。", "sentence_source": "generated"}, {"text": "公園で、小さい犬と大きい犬が一緒に遊んでいた。", "target_word": "犬", "complexity_tier": "T3", "furigana": "公園[こうえん]で、小[ちい]さい犬[いぬ]と大[おお]きい犬[いぬ]が一緒[いっしょ]に遊[あそ]んでいた。", "sentence_source": "generated"}, {"text": "犬にえさをやるのは、毎晩私の仕事です。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]にえさをやるのは、毎晩[まいばん]私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "散歩の途中、犬が急に走り出したので、手を離してしまった。", "target_word": "犬", "complexity_tier": "T3", "furigana": "散歩[さんぽ]の途中[とちゅう]、犬[いぬ]が急[きゅう]に走[はし]り出[だ]したので、手[て]を離[はな]してしまった。", "sentence_source": "generated"}, {"text": "この犬は名前を呼ぶと、すぐ走って来ます。", "target_word": "犬", "complexity_tier": "T3", "furigana": "この犬[いぬ]は名前[なまえ]を呼[よ]ぶと、すぐ走[はし]って来[き]ます。", "sentence_source": "generated"}, {"text": "犬が病気になったので、急いで動物病院へ連れて行きました。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]が病気[びょうき]になったので、急[いそ]いで動物病院[どうぶつびょういん]へ連[つ]れて行[い]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犬", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ペットとして飼う、散歩やえさの世話が必要な動物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犬", "is_correct": true, "explanation": "ペットとして飼われる一匹の動物を指す語。ここで正解。"}, {"text": "花", "is_correct": false, "explanation": "植物で、飼う対象にならず、一匹とも数えない。"}, {"text": "石", "is_correct": false, "explanation": "鉱物で、飼う対象にならない。"}, {"text": "紙", "is_correct": false, "explanation": "物で、一匹と数えて飼う対象にはならない。"}], "explanations": {"犬": "ペットとして飼われる一匹の動物を指す語。ここで正解。", "花": "植物で、飼う対象にならず、一匹とも数えない。", "石": "鉱物で、飼う対象にならない。", "紙": "物で、一匹と数えて飼う対象にはならない。"}, "sentence_index": 0, "correct_answer": "犬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は犬なで声で、上司にご機嫌を取ってきた。", "explanation": "ここは〈猫なで声〉（機嫌を取るように甘えた声）の言い方。犬なで声とは言わない。"}, {"text": "忙しくて、犬の手も借りたいくらいだ。", "explanation": "ここは〈猫の手も借りたい〉の慣用句。犬ではこの言い回しを使わない。"}, {"text": "あの話は、犬に化かされたようで信じられない。", "explanation": "ここは〈狐に化かされる〉の慣用句。犬ではこの言い回しを使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犬", "is_correct": true, "explanation": "えさを食べる生き物で、えさを与える対象になる。ここで正解。"}, {"text": "椅子", "is_correct": false, "explanation": "座る道具で、えさを与える対象にならない。"}, {"text": "本", "is_correct": false, "explanation": "読むもので、えさを与える対象にならない。"}, {"text": "車", "is_correct": false, "explanation": "乗り物で、えさを与える対象にならない。"}], "explanations": {"犬": "えさを食べる生き物で、えさを与える対象になる。ここで正解。", "椅子": "座る道具で、えさを与える対象にならない。", "本": "読むもので、えさを与える対象にならない。", "車": "乗り物で、えさを与える対象にならない。"}, "sentence_index": 6, "correct_answer": "犬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "何度言っても、犬の耳に念仏で聞いてもらえない。", "explanation": "ここは〈馬の耳に念仏〉の慣用句。犬ではこの言い回しを使わない。"}, {"text": "寒さで、腕に犬肌が立った。", "explanation": "ここは〈鳥肌が立つ〉の慣用句。犬肌とは言わない。"}, {"text": "名人でも、犬も木から落ちることがある。", "explanation": "ここは〈猿も木から落ちる〉のことわざ。犬ではこのことわざを使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は、毎朝、犬が公園に連れて行く。", "corrected_sentence": "父は、毎朝、犬を公園に連れて行く。", "error_description": "誤りは「犬が」。「連れて行く」は連れる対象を「を」で示すので、正しくは「犬を」。「犬が」だと犬が主語になり意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36734, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、三年前から犬が一匹飼っています。", "corrected_sentence": "祖母は、三年前から犬を一匹飼っています。", "error_description": "誤りは「犬が」。「飼う」は飼う対象を「を」で示すので、正しくは「犬を」。「犬が」だと犬が主語になり意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
