INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36735, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間と一緒に暮らすことが多い、哺乳類の動物。吠える声やしっぽを振る行動が特徴。", "primary_collocate": null, "pronunciation": "いぬ", "ipa": "inɯ", "syllable_count": 2, "sentences": [{"text": "犬は昔から人間と一緒に暮らしてきた動物です。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は昔[むかし]から人間[にんげん]と一緒[いっしょ]に暮[く]らしてきた動物[どうぶつ]です。", "sentence_source": "generated"}, {"text": "嬉しいとき、犬はしっぽを振って喜びを伝えます。", "target_word": "犬", "complexity_tier": "T3", "furigana": "嬉[うれ]しいとき、犬[いぬ]はしっぽを振[ふ]って喜[よろこ]びを伝[つた]えます。", "sentence_source": "generated"}, {"text": "夜中に犬の吠える声が聞こえて、目が覚めました。", "target_word": "犬", "complexity_tier": "T3", "furigana": "夜中[よなか]に犬[いぬ]の吠[ほ]える声[こえ]が聞[き]こえて、目[め]が覚[さ]めました。", "sentence_source": "generated"}, {"text": "犬は人間より耳がよく、小さな音でも聞き分けられる。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]より耳[みみ]がよく、小[ちい]さな音[おと]でも聞[き]き分[わ]けられる。", "sentence_source": "generated"}, {"text": "犬は哺乳類なので、生まれた子は母乳で育ちます。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は哺乳類[ほにゅうるい]なので、生[う]まれた子[こ]は母乳[ぼにゅう]で育[そだ]ちます。", "sentence_source": "generated"}, {"text": "隣の家の犬は、私を見るといつも吠える。", "target_word": "犬", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]の犬[いぬ]は、私[わたし]を見[み]るといつも吠[ほ]える。", "sentence_source": "generated"}, {"text": "犬は人の気持ちを読むのが上手だと言われています。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は人[ひと]の気持[きも]ちを読[よ]むのが上手[じょうず]だと言[い]われています。", "sentence_source": "generated"}, {"text": "犬は暑いと、舌を出して息をして体温を下げる。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は暑[あつ]いと、舌[した]を出[だ]して息[いき]をして体温[たいおん]を下[さ]げる。", "sentence_source": "generated"}, {"text": "警察では、鼻のよい犬が荷物の検査を手伝っています。", "target_word": "犬", "complexity_tier": "T3", "furigana": "警察[けいさつ]では、鼻[はな]のよい犬[いぬ]が荷物[にもつ]の検査[けんさ]を手伝[てつだ]っています。", "sentence_source": "generated"}, {"text": "犬は飼い主が帰ると、玄関まで走ってきて迎えます。", "target_word": "犬", "complexity_tier": "T3", "furigana": "犬[いぬ]は飼[か]い主[ぬし]が帰[かえ]ると、玄関[げんかん]まで走[はし]ってきて迎[むか]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "犬", "label": "基本形"}], "register": "中立", "sense_fingerprint": "吠える・しっぽを振るなど、習性が語られる哺乳類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "犬", "is_correct": true, "explanation": "人間と一緒に暮らしてきた哺乳類の動物を指す語。ここで正解。"}, {"text": "机", "is_correct": false, "explanation": "家具で、人間と一緒に暮らしてきた動物ではない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の部分で、動物ではないので暮らしの主語にならない。"}, {"text": "石", "is_correct": false, "explanation": "鉱物で、動物ではないので暮らしの主語にならない。"}], "explanations": {"犬": "人間と一緒に暮らしてきた哺乳類の動物を指す語。ここで正解。", "机": "家具で、人間と一緒に暮らしてきた動物ではない。", "窓": "建物の部分で、動物ではないので暮らしの主語にならない。", "石": "鉱物で、動物ではないので暮らしの主語にならない。"}, "sentence_index": 0, "correct_answer": "犬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は人前では犬をかぶって、おとなしく振る舞っている。", "explanation": "ここは〈猫をかぶる〉（本性を隠しておとなしく見せる）の慣用句。犬ではこの言い回しを使わない。"}, {"text": "怖い話を聞いて、背中に犬肌が立った。", "explanation": "ここは〈鳥肌が立つ〉の慣用句。犬肌とは言わない。"}, {"text": "彼は犬舌で、熱いお茶が飲めない。", "explanation": "ここは〈猫舌〉（熱いものが苦手な人）の言い方。犬舌とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犬", "is_correct": true, "explanation": "人の気持ちを読むと言われる動物を指す語。ここで正解。"}, {"text": "傘", "is_correct": false, "explanation": "雨具で、人の気持ちを読む主語にはならない。"}, {"text": "壁", "is_correct": false, "explanation": "建物の部分で、人の気持ちを読む主語にはならない。"}, {"text": "皿", "is_correct": false, "explanation": "食器で、人の気持ちを読む主語にはならない。"}], "explanations": {"犬": "人の気持ちを読むと言われる動物を指す語。ここで正解。", "傘": "雨具で、人の気持ちを読む主語にはならない。", "壁": "建物の部分で、人の気持ちを読む主語にはならない。", "皿": "食器で、人の気持ちを読む主語にはならない。"}, "sentence_index": 6, "correct_answer": "犬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晴れているのに雨が降るのは、犬の嫁入りだ。", "explanation": "ここは〈狐の嫁入り〉（晴れているのに降る雨）の言い方。犬ではこの言い回しを使わない。"}, {"text": "どんな名人も失敗する。犬も木から落ちるものだ。", "explanation": "ここは〈猿も木から落ちる〉のことわざ。犬ではこのことわざを使わない。"}, {"text": "犬の額ほどの小さな庭だが、花がきれいに咲いている。", "explanation": "ここは〈猫の額〉（とても狭いこと）の慣用句。犬の額とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犬を夜、家の外を見張っている。", "corrected_sentence": "犬が夜、家の外を見張っている。", "error_description": "誤りは「犬を」。「見張る」の主語は犬なので、正しくは「犬が」。「を」は目的語を示すため、主語には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生後間もない頃から、犬で人の声によく反応する。", "corrected_sentence": "生後間もない頃から、犬は人の声によく反応する。", "error_description": "誤りは「犬で」。「犬は」の「は」を「で」に変えると犬を手段にする意味になり、文が不自然になる。正しくは「犬は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「発達によって」の「に」。発達を原因として示し、後ろの「経済が成長した」へ続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「発達がよって」では原因を示す「によって」の形が崩れ、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「発達を」だと後ろに動詞がなく、原因を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「発達へよって」では原因の意味にならず、文が通じない。"}], "correct_answer": "に", "explanations": {"に": "「発達によって」の「に」。発達を原因として示し、後ろの「経済が成長した」へ続く。", "が": "主語を示す「が」。「発達がよって」では原因を示す「によって」の形が崩れ、文が成り立たない。", "を": "目的語を示す「を」。「発達を」だと後ろに動詞がなく、原因を表せない。", "へ": "方向を示す「へ」。「発達へよって」では原因の意味にならず、文が通じない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が育って、より良くなること。", "primary_collocate": null, "pronunciation": "はったつ", "ipa": "hattatsɯ", "syllable_count": 4, "sentences": [{"text": "交通が発達したおかげで、遠い町へも短い時間で行けるようになった。", "target_word": "発達", "complexity_tier": "T3", "furigana": "交通[こうつう]が発達[はったつ]したおかげで、遠[とお]い町[まち]へも短[みじか]い時間[じかん]で行[い]けるようになった。", "sentence_source": "generated"}, {"text": "この国は、鉄道の発達によって経済が大きく成長した。", "target_word": "発達", "complexity_tier": "T3", "furigana": "この国[くに]は、鉄道[てつどう]の発達[はったつ]によって経済[けいざい]が大[おお]きく成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "技術の発達で、私たちの生活はとても便利になりました。", "target_word": "発達", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の発達[はったつ]で、私[わたし]たちの生活[せいかつ]はとても便利[べんり]になりました。", "sentence_source": "generated"}, {"text": "医学が発達して、昔は治らなかった病気も治せるようになった。", "target_word": "発達", "complexity_tier": "T3", "furigana": "医学[いがく]が発達[はったつ]して、昔[むかし]は治[なお]らなかった病気[びょうき]も治[なお]せるようになった。", "sentence_source": "generated"}, {"text": "都市が発達するにつれて、人口も増えていきました。", "target_word": "発達", "complexity_tier": "T3", "furigana": "都市[とし]が発達[はったつ]するにつれて、人口[じんこう]も増[ふ]えていきました。", "sentence_source": "generated"}, {"text": "通信の発達により、世界中の人とすぐ話せる。", "target_word": "発達", "complexity_tier": "T3", "furigana": "通信[つうしん]の発達[はったつ]により、世界中[せかいじゅう]の人[ひと]とすぐ話[はな]せる。", "sentence_source": "generated"}, {"text": "農業が発達していなかった時代は、天候で食べ物の量が大きく変わった。", "target_word": "発達", "complexity_tier": "T3", "furigana": "農業[のうぎょう]が発達[はったつ]していなかった時代[じだい]は、天候[てんこう]で食[た]べ物[もの]の量[りょう]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "発達した道路網のおかげで、荷物が早く届く。", "target_word": "発達", "complexity_tier": "T3", "furigana": "発達[はったつ]した道路網[どうろもう]のおかげで、荷物[にもつ]が早[はや]く届[とど]く。", "sentence_source": "generated"}, {"text": "産業の発達は便利さをもたらしたが、同時に環境問題も生んだ。", "target_word": "発達", "complexity_tier": "T3", "furigana": "産業[さんぎょう]の発達[はったつ]は便利[べんり]さをもたらしたが、同時[どうじ]に環境[かんきょう]問題[もんだい]も生[う]んだ。", "sentence_source": "generated"}, {"text": "港町は貿易が発達し、昔から多くの商人が集まった。", "target_word": "発達", "complexity_tier": "T3", "furigana": "港町[みなとまち]は貿易[ぼうえき]が発達[はったつ]し、昔[むかし]から多[おお]くの商人[しょうにん]が集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発達", "label": "基本形"}, {"form": "発達する", "label": "動詞形"}, {"form": "発達した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "技術・交通・産業・都市などが進んで良くなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発達", "is_correct": true, "explanation": "「交通が発達した」で、交通が進んで良くなったという意味になり、後ろの「おかげで」の文脈に合う。"}, {"text": "停止", "is_correct": false, "explanation": "止まる意味。交通が止まったのでは、「おかげで短時間で行けるようになった」と続かない。"}, {"text": "故障", "is_correct": false, "explanation": "機械が壊れる意味。交通を主語にすると不自然で、良い結果の文脈に合わない。"}, {"text": "破壊", "is_correct": false, "explanation": "壊す意味。交通が破壊されたのでは「おかげで」の良い結果に続かない。"}], "explanations": {"発達": "「交通が発達した」で、交通が進んで良くなったという意味になり、後ろの「おかげで」の文脈に合う。", "停止": "止まる意味。交通が止まったのでは、「おかげで短時間で行けるようになった」と続かない。", "故障": "機械が壊れる意味。交通を主語にすると不自然で、良い結果の文脈に合わない。", "破壊": "壊す意味。交通が破壊されたのでは「おかげで」の良い結果に続かない。"}, "sentence_index": 0, "correct_answer": "発達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨夜、この町では大きな事故が発達した。", "explanation": "ここは〈発生〉の意味。事故は起きるもので、物事が育って良くなる〈発達〉とは意味が合わない。"}, {"text": "毎日練習したので、泳ぎがだいぶ発達した。", "explanation": "ここは〈上達〉の意味。練習で身につく技能には〈上達〉を使い、〈発達〉は物事の仕組みが育つことに使うので合わない。"}, {"text": "交渉が発達して、ようやく合意に至った。", "explanation": "ここは〈進展〉の意味。話し合いが前に進むことには〈進展〉を使い、〈発達〉は技術や社会の仕組みが育つことに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発達", "is_correct": true, "explanation": "「農業が発達していなかった」で、農業が進んでいなかったことを示し、文脈に合う。"}, {"text": "紛失", "is_correct": false, "explanation": "なくすこと。「農業が紛失していなかった」は意味が通らない。"}, {"text": "溶解", "is_correct": false, "explanation": "溶けて形がなくなること。農業の状態を表す語としては使えず、意味が通らない。"}, {"text": "消費", "is_correct": false, "explanation": "使い切る意味。「農業が消費していなかった」では時代の話として通じない。"}], "explanations": {"発達": "「農業が発達していなかった」で、農業が進んでいなかったことを示し、文脈に合う。", "紛失": "なくすこと。「農業が紛失していなかった」は意味が通らない。", "溶解": "溶けて形がなくなること。農業の状態を表す語としては使えず、意味が通らない。", "消費": "使い切る意味。「農業が消費していなかった」では時代の話として通じない。"}, "sentence_index": 6, "correct_answer": "発達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の売上が発達して、社員が増えた。", "explanation": "ここは〈成長〉の意味。売上や会社の規模が伸びることには〈成長〉を使い、〈発達〉は物事が育って良くなることに使うので合わない。"}, {"text": "新しい店が発達して、客が流れた。", "explanation": "ここは〈出現〉の意味。新しく現れることには〈出現〉を使い、〈発達〉は育って良くなることなので合わない。"}, {"text": "入場者が発達して、会場が混雑した。", "explanation": "ここは〈増加〉の意味。人数が増えることには〈増加〉を使い、〈発達〉は物事が育って良くなることに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交通の発達を、観光客が増えた。", "corrected_sentence": "交通の発達により、観光客が増えた。", "error_description": "「発達により」が正しい。「発達を」では後ろに動詞や理由を示す形がなく、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい交通網が発達させたことで、通勤が楽になった。", "corrected_sentence": "新しい交通網が発達したことで、通勤が楽になった。", "error_description": "「発達した」が正しい。「発達させた」は他動詞なので、「交通網が」を主語にすると合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「発達には」の「に」。発達を話題として示し、後ろの「大切です」へ続く。"}, {"text": "が", "is_correct": false, "explanation": "「発達が」では「には」の話題の形が崩れ、「大切です」の前提にならない。"}, {"text": "を", "is_correct": false, "explanation": "「発達を、家族との会話が大切」となり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「発達へは」では話題の流れが通じず、「大切です」の前提にならない。"}], "correct_answer": "に", "explanations": {"に": "「発達には」の「に」。発達を話題として示し、後ろの「大切です」へ続く。", "が": "「発達が」では「には」の話題の形が崩れ、「大切です」の前提にならない。", "を": "「発達を、家族との会話が大切」となり、文として成り立たない。", "へ": "「発達へは」では話題の流れが通じず、「大切です」の前提にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「発達の速さ」の「の」。発達と速さを結び、「速さは子どもによって違う」の主語になる。"}, {"text": "に", "is_correct": false, "explanation": "「発達に速さは」では続き方が不自然で、「違う」の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「発達で速さは」では手段の意味にならず、文がつながらない。"}, {"text": "から", "is_correct": false, "explanation": "「発達から速さは」では起点の意味が通らず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「発達の速さ」の「の」。発達と速さを結び、「速さは子どもによって違う」の主語になる。", "に": "「発達に速さは」では続き方が不自然で、「違う」の主語にならない。", "で": "「発達で速さは」では手段の意味にならず、文がつながらない。", "から": "「発達から速さは」では起点の意味が通らず、文が成り立たない。"}, "error_tags": {"に": "帰着・位置", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物の体や心、社会の仕組みなどが、時間をかけてより高度・複雑に変化すること。", "primary_collocate": null, "pronunciation": "はったつ", "ipa": "hattatsɯ", "syllable_count": 4, "sentences": [{"text": "赤ちゃんの体は、一年でとても発達します。", "target_word": "発達", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの体[からだ]は、一年[いちねん]でとても発達[はったつ]します。", "sentence_source": "generated"}, {"text": "子どもの言葉の発達には、家族との会話が大切です。", "target_word": "発達", "complexity_tier": "T3", "furigana": "子[こ]どもの言葉[ことば]の発達[はったつ]には、家族[かぞく]との会話[かいわ]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "運動を続けると、足の筋肉が発達する。", "target_word": "発達", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けると、足[あし]の筋肉[きんにく]が発達[はったつ]する。", "sentence_source": "generated"}, {"text": "犬は鼻が発達しているので、においを細かく嗅ぎ分けられる。", "target_word": "発達", "complexity_tier": "T3", "furigana": "犬[いぬ]は鼻[はな]が発達[はったつ]しているので、においを細[こま]かく嗅[か]ぎ分[わ]けられる。", "sentence_source": "generated"}, {"text": "人間の脳は、大人になるまで長い時間をかけて発達します。", "target_word": "発達", "complexity_tier": "T3", "furigana": "人間[にんげん]の脳[のう]は、大人[おとな]になるまで長[なが]い時間[じかん]をかけて発達[はったつ]します。", "sentence_source": "generated"}, {"text": "心の発達には、友達と遊ぶ経験が欠かせません。", "target_word": "発達", "complexity_tier": "T3", "furigana": "心[こころ]の発達[はったつ]には、友達[ともだち]と遊[あそ]ぶ経験[けいけん]が欠[か]かせません。", "sentence_source": "generated"}, {"text": "鳥の翼は、飛ぶために長い時間をかけて発達してきた。", "target_word": "発達", "complexity_tier": "T3", "furigana": "鳥[とり]の翼[つばさ]は、飛[と]ぶために長[なが]い時間[じかん]をかけて発達[はったつ]してきた。", "sentence_source": "generated"}, {"text": "発達の速さは子どもによって違うので、比べすぎないでください。", "target_word": "発達", "complexity_tier": "T3", "furigana": "発達[はったつ]の速[はや]さは子[こ]どもによって違[ちが]うので、比[くら]べすぎないでください。", "sentence_source": "generated"}, {"text": "社会の仕組みが発達すると、法律も複雑になっていく。", "target_word": "発達", "complexity_tier": "T3", "furigana": "社会[しゃかい]の仕組[しく]みが発達[はったつ]すると、法律[ほうりつ]も複雑[ふくざつ]になっていく。", "sentence_source": "generated"}, {"text": "ゾウは鼻が長く発達しており、手のように物をつかめる。", "target_word": "発達", "complexity_tier": "T3", "furigana": "ゾウは鼻[はな]が長[なが]く発達[はったつ]しており、手[て]のように物[もの]をつかめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発達", "label": "基本形"}, {"form": "発達する", "label": "動詞形"}, {"form": "発達した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "体・心・器官・社会の仕組みが時間をかけて高度になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発達", "is_correct": true, "explanation": "体が成長して高度になる意味で、「一年でとても発達します」に合う。"}, {"text": "停止", "is_correct": false, "explanation": "止まること。体が一年で止まるとは言わず、成長の文脈と合わない。"}, {"text": "故障", "is_correct": false, "explanation": "機械などが壊れること。人の体には使わない。"}, {"text": "混乱", "is_correct": false, "explanation": "頭や状況が乱れること。体の成長の話には合わない。"}], "explanations": {"発達": "体が成長して高度になる意味で、「一年でとても発達します」に合う。", "停止": "止まること。体が一年で止まるとは言わず、成長の文脈と合わない。", "故障": "機械などが壊れること。人の体には使わない。", "混乱": "頭や状況が乱れること。体の成長の話には合わない。"}, "sentence_index": 0, "correct_answer": "発達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の人口は、ここ数年で発達している。", "explanation": "ここは〈増加〉の意味。人数が増えることには〈増加〉を使い、〈発達〉は体や心、社会の仕組みが高度になることに使うので合わない。"}, {"text": "大学の学生数が発達して、教室が足りなくなった。", "explanation": "ここは〈増加〉の意味。人数が増えることには〈増加〉を使い、〈発達〉は体や心、社会の仕組みが高度になることに使うので合わない。"}, {"text": "毎日運転していたら、車の運転が発達した。", "explanation": "ここは〈上達〉の意味。練習で身につく技能には〈上達〉を使い、〈発達〉は体や心、社会の仕組みに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発達", "is_correct": true, "explanation": "時間をかけて高度になる意味で、翼が変わってきた流れに合う。"}, {"text": "破壊", "is_correct": false, "explanation": "壊す意味。翼が時間をかけて壊れてきた、では文脈と逆になる。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめること。「中断してきた」では少しずつ変化してきた流れが成り立たない。"}, {"text": "紛失", "is_correct": false, "explanation": "なくすこと。翼が失われてきたという話ではないので合わない。"}], "explanations": {"発達": "時間をかけて高度になる意味で、翼が変わってきた流れに合う。", "破壊": "壊す意味。翼が時間をかけて壊れてきた、では文脈と逆になる。", "中断": "途中でやめること。「中断してきた」では少しずつ変化してきた流れが成り立たない。", "紛失": "なくすこと。翼が失われてきたという話ではないので合わない。"}, "sentence_index": 6, "correct_answer": "発達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館の蔵書が発達して、利用者が増えた。", "explanation": "ここは〈充実〉の意味。中身が豊かに揃うことには〈充実〉を使い、〈発達〉は生物の体や心、社会の仕組みが時間をかけて変わることに使うので合わない。"}, {"text": "サービスの質が発達して、客が増えた。", "explanation": "ここは〈向上〉の意味。質が高まることには〈向上〉を使い、〈発達〉は生物の体や心、社会の仕組みが複雑になることに使うので合わない。"}, {"text": "新しい橋が発達して、交通が便利になった。", "explanation": "ここは〈完成〉の意味。作り上げられることには〈完成〉を使い、〈発達〉は生物や社会の仕組みが時間をかけて変わることに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日運動すると、心肺機能が発達させる。", "corrected_sentence": "毎日運動すると、心肺機能が発達する。", "error_description": "「発達する」が正しい。「発達させる」は他動詞で、「心肺機能が」と組むと文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36737, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "心の発達を、大人のやさしい関わりが欠かせない。", "corrected_sentence": "心の発達には、大人のやさしい関わりが欠かせない。", "error_description": "「発達には」が正しい。「欠かせない」は「には」の形と結びつくので、「発達を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
