INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36738, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と話したり、気持ちを伝えたりすること。", "primary_collocate": null, "pronunciation": "こみゅにけーしょん", "ipa": "komjɯnikeːɕoɴ", "syllable_count": 7, "sentences": [{"text": "友だちとコミュニケーションをとるのは楽しいです。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "友[とも]だちとコミュニケーションをとるのは楽[たの]しいです。", "sentence_source": "generated"}, {"text": "言葉が通じなくても、笑顔でコミュニケーションができます。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "言葉[ことば]が通[つう]じなくても、笑顔[えがお]でコミュニケーションができます。", "sentence_source": "generated"}, {"text": "家族とのコミュニケーションが足りないと、さびしくなります。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "家族[かぞく]とのコミュニケーションが足[た]りないと、さびしくなります。", "sentence_source": "generated"}, {"text": "コミュニケーションが苦手なので、人前で話すと緊張します。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "コミュニケーションが苦手[にがて]なので、人前[ひとまえ]で話[はな]すと緊張[きんちょう]します。", "sentence_source": "generated"}, {"text": "先生は生徒とのコミュニケーションを大切にしています。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]とのコミュニケーションを大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "電話やメールもコミュニケーションの一つです。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "電話[でんわ]やメールもコミュニケーションの一[ひと]つです。", "sentence_source": "generated"}, {"text": "コミュニケーションがうまくいかなくて、誤解が生まれました。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "コミュニケーションがうまくいかなくて、誤解[ごかい]が生[う]まれました。", "sentence_source": "generated"}, {"text": "外国人の友だちとは、英語でコミュニケーションをします。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の友[とも]だちとは、英語[えいご]でコミュニケーションをします。", "sentence_source": "generated"}, {"text": "毎朝あいさつをして、同僚とのコミュニケーションを深めます。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]あいさつをして、同僚[どうりょう]とのコミュニケーションを深[ふか]めます。", "sentence_source": "generated"}, {"text": "コミュニケーションの練習のために、クラブに入りました。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "コミュニケーションの練習[れんしゅう]のために、クラブに入[はい]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニケーション", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人と話して気持ちを伝え合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: さびしく (Zipf 2.32)']::text[], 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニケーション", "is_correct": true, "explanation": "「コミュニケーションをとる」で「意思を交わす」という意味になり、友だちと楽しく話す文に合う。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "「ネクタイをとる」は外すという意味で、友だちと楽しく行う動作としては意味が通らない。"}, {"text": "ビザ", "is_correct": false, "explanation": "「ビザをとる」は取得する意味で、友だちと一緒にする行動としては不自然。"}, {"text": "カーテン", "is_correct": false, "explanation": "「カーテンをとる」は外す意味で、友だちとの楽しい時間とは結びつかない。"}], "explanations": {"コミュニケーション": "「コミュニケーションをとる」で「意思を交わす」という意味になり、友だちと楽しく話す文に合う。", "ネクタイ": "「ネクタイをとる」は外すという意味で、友だちと楽しく行う動作としては意味が通らない。", "ビザ": "「ビザをとる」は取得する意味で、友だちと一緒にする行動としては不自然。", "カーテン": "「カーテンをとる」は外す意味で、友だちとの楽しい時間とは結びつかない。"}, "sentence_index": 0, "correct_answer": "コミュニケーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コミュニケーションのせいで、パソコンが動かなくなった。", "explanation": "ここは〈ウイルス〉の意味。人と伝え合う行為は機械を壊す原因にならないので、この文では使わない。"}, {"text": "会社のコミュニケーションに接続できず、メールが届かない。", "explanation": "ここは〈ネットワーク〉の意味。接続先は回線などのネットワークで、人の伝え合いは接続先にならない。"}, {"text": "新しいコミュニケーションを見て、料理を作った。", "explanation": "ここは〈レシピ〉の意味。見るのは料理の作り方で、伝え合う行為のコミュニケーションは見るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニケーション", "is_correct": true, "explanation": "「コミュニケーションがうまくいかない」は意思疎通が失敗したという意味で、誤解が生まれた文と合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気がうまくいかない」という言い方はなく、誤解とも関係しない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重がうまくいかない」は意味が通らず、誤解の原因にもならない。"}, {"text": "玄関", "is_correct": false, "explanation": "「玄関がうまくいかない」は意味が通らず、誤解が生まれる話とは結びつかない。"}], "explanations": {"コミュニケーション": "「コミュニケーションがうまくいかない」は意思疎通が失敗したという意味で、誤解が生まれた文と合う。", "天気": "「天気がうまくいかない」という言い方はなく、誤解とも関係しない。", "体重": "「体重がうまくいかない」は意味が通らず、誤解の原因にもならない。", "玄関": "「玄関がうまくいかない」は意味が通らず、誤解が生まれる話とは結びつかない。"}, "sentence_index": 6, "correct_answer": "コミュニケーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電波が弱くて、コミュニケーションが届かなかった。", "explanation": "ここは〈通信〉の意味。届くのは信号や情報で、人と伝え合うコミュニケーションは届くものではない。"}, {"text": "駅のコミュニケーションが混んでいて、約束に遅れた。", "explanation": "ここは〈交通〉の意味。混むのは道路や電車などの交通で、コミュニケーションは混むものではない。"}, {"text": "花粉が多くて、コミュニケーションでくしゃみが止まらない。", "explanation": "ここは〈アレルゲン〉の意味。くしゃみを起こすのは物質で、伝え合う行為のコミュニケーションは原因にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族とのコミュニケーションに大切にすると、安心します。", "corrected_sentence": "家族とのコミュニケーションを大切にすると、安心します。", "error_description": "「大切にする」の対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手の気持ちを知るには、コミュニケーションを欠かせません。", "corrected_sentence": "相手の気持ちを知るには、コミュニケーションが欠かせません。", "error_description": "「欠かせない」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「コミュニケーションの大切な手段」の「の」で、名詞どうしをつなぐ働きをする。"}, {"text": "を", "is_correct": false, "explanation": "「を」を置くと「コミュニケーションを大切な手段」となり、名詞をつなげられない。"}, {"text": "に", "is_correct": false, "explanation": "「に」を置くと「コミュニケーションに大切な手段」となり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」を置くと「コミュニケーションで大切な手段」となり、つながらない。"}], "correct_answer": "の", "explanations": {"の": "「コミュニケーションの大切な手段」の「の」で、名詞どうしをつなぐ働きをする。", "を": "「を」を置くと「コミュニケーションを大切な手段」となり、名詞をつなげられない。", "に": "「に」を置くと「コミュニケーションに大切な手段」となり、意味が通らない。", "で": "「で」を置くと「コミュニケーションで大切な手段」となり、つながらない。"}, "error_tags": {"を": "目的語", "に": "着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "情報や気持ちを、ことばやしぐさなどを使って相手に伝え、また相手のものを受け取ること。", "primary_collocate": null, "pronunciation": "こみゅにけーしょん", "ipa": "komjɯnikeːɕoɴ", "syllable_count": 7, "sentences": [{"text": "会議では、メンバー同士のコミュニケーションが大切です。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、メンバー同士[どうし]のコミュニケーションが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "しぐさもコミュニケーションの大切な手段です。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "しぐさもコミュニケーションの大切[たいせつ]な手段[しゅだん]です。", "sentence_source": "generated"}, {"text": "犬は鳴き声で仲間とコミュニケーションをとります。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "犬[いぬ]は鳴[な]き声[ごえ]で仲間[なかま]とコミュニケーションをとります。", "sentence_source": "generated"}, {"text": "彼は相手の話をよく聞くので、コミュニケーションが上手です。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の話[はなし]をよく聞[き]くので、コミュニケーションが上手[じょうず]です。", "sentence_source": "generated"}, {"text": "ネットでは顔が見えないため、コミュニケーションが難しいことがあります。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "ネットでは顔[かお]が見[み]えないため、コミュニケーションが難[むずか]しいことがあります。", "sentence_source": "generated"}, {"text": "この授業では、コミュニケーションの方法を学びます。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、コミュニケーションの方法[ほうほう]を学[まな]びます。", "sentence_source": "generated"}, {"text": "職場のコミュニケーションを良くするために、毎週話し合います。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "職場[しょくば]のコミュニケーションを良[よ]くするために、毎週[まいしゅう]話[はな]し合[あ]います。", "sentence_source": "generated"}, {"text": "コミュニケーションは、伝えるだけでなく受け取ることでもあります。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "コミュニケーションは、伝[つた]えるだけでなく受[う]け取[と]ることでもあります。", "sentence_source": "generated"}, {"text": "手話を使って、耳の聞こえない人とコミュニケーションをとりました。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "手話[しゅわ]を使[つか]って、耳[みみ]の聞[き]こえない人[ひと]とコミュニケーションをとりました。", "sentence_source": "generated"}, {"text": "言葉の違いで、コミュニケーションに時間がかかりました。", "target_word": "コミュニケーション", "complexity_tier": "T3", "furigana": "言葉[ことば]の違[ちが]いで、コミュニケーションに時間[じかん]がかかりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニケーション", "label": "基本形"}], "register": "中立", "sense_fingerprint": "言葉やしぐさで情報や気持ちを伝え合い受け取ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニケーション", "is_correct": true, "explanation": "「メンバー同士のコミュニケーションが大切」は、話し合いで伝え合う質が大事だという意味で文脈に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "「メンバー同士の玄関が大切」は意味が通らず、会議の話とは結びつかない。"}, {"text": "ゴミ", "is_correct": false, "explanation": "「メンバー同士のゴミが大切」とは言わず、会議の文脈に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「メンバー同士の冷蔵庫が大切」は意味が通らず、会議の話として成立しない。"}], "explanations": {"コミュニケーション": "「メンバー同士のコミュニケーションが大切」は、話し合いで伝え合う質が大事だという意味で文脈に合う。", "玄関": "「メンバー同士の玄関が大切」は意味が通らず、会議の話とは結びつかない。", "ゴミ": "「メンバー同士のゴミが大切」とは言わず、会議の文脈に合わない。", "冷蔵庫": "「メンバー同士の冷蔵庫が大切」は意味が通らず、会議の話として成立しない。"}, "sentence_index": 0, "correct_answer": "コミュニケーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花粉が多くて、コミュニケーションでくしゃみが止まらない。", "explanation": "ここは〈アレルゲン〉の意味。くしゃみを起こすのは物質で、伝え合う行為のコミュニケーションは原因にならない。"}, {"text": "会社のコミュニケーションに接続できず、メールが届かない。", "explanation": "ここは〈ネットワーク〉の意味。接続先は回線などのネットワークで、人の伝え合いは接続先にならない。"}, {"text": "コミュニケーションを入れて、車を走らせた。", "explanation": "ここは〈ガソリン〉の意味。入れるのは燃料で、伝え合う行為のコミュニケーションは車に入れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニケーション", "is_correct": true, "explanation": "「職場のコミュニケーションを良くする」は伝え合いの質を高めるという意味で、話し合いの文に合う。"}, {"text": "体重", "is_correct": false, "explanation": "「職場の体重を良くする」という言い方はなく、話し合いとも結びつかない。"}, {"text": "天井", "is_correct": false, "explanation": "「職場の天井を良くする」は意味が通らず、話し合いの目的にならない。"}, {"text": "財布", "is_correct": false, "explanation": "「職場の財布を良くする」は、毎週の話し合いで改善できる対象ではない。"}], "explanations": {"コミュニケーション": "「職場のコミュニケーションを良くする」は伝え合いの質を高めるという意味で、話し合いの文に合う。", "体重": "「職場の体重を良くする」という言い方はなく、話し合いとも結びつかない。", "天井": "「職場の天井を良くする」は意味が通らず、話し合いの目的にならない。", "財布": "「職場の財布を良くする」は、毎週の話し合いで改善できる対象ではない。"}, "sentence_index": 6, "correct_answer": "コミュニケーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電波が弱くて、コミュニケーションが届かなかった。", "explanation": "ここは〈通信〉の意味。届くのは信号や情報で、人と伝え合うコミュニケーションは届くものではない。"}, {"text": "駅のコミュニケーションが混んでいて、約束に遅れた。", "explanation": "ここは〈交通〉の意味。混むのは道路や電車などの交通で、コミュニケーションは混むものではない。"}, {"text": "川の水が汚れて、コミュニケーションで魚が死んだ。", "explanation": "ここは〈汚染物質〉の意味。水を汚すのは化学物質などで、伝え合う行為のコミュニケーションは原因にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初対面の人とも、コミュニケーションにとれます。", "corrected_sentence": "初対面の人とも、コミュニケーションがとれます。", "error_description": "「とれる」の主語は「が」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36739, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "通訳のおかげで、コミュニケーションをスムーズになりました。", "corrected_sentence": "通訳のおかげで、コミュニケーションがスムーズになりました。", "error_description": "「なる」の主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼の仮説」を話題にして、それが間違っていたと述べる主題の「は」。"}, {"text": "を", "is_correct": false, "explanation": "「仮説を間違っていた」では、間違うという述語の主体が示せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「仮説に間違っていた」では、間違うという述語の主体として合わない。"}, {"text": "で", "is_correct": false, "explanation": "「仮説で間違っていた」は手段の意味になり、主体を示すこの文には合わない。"}], "correct_answer": "は", "explanations": {"は": "「彼の仮説」を話題にして、それが間違っていたと述べる主題の「は」。", "を": "「仮説を間違っていた」では、間違うという述語の主体が示せず不自然。", "に": "「仮説に間違っていた」では、間違うという述語の主体として合わない。", "で": "「仮説で間違っていた」は手段の意味になり、主体を示すこの文には合わない。"}, "error_tags": {"を": "目的語の「を」は間違う主体を示せない", "に": "相手を示す「に」は主語の位置に合わない", "で": "手段の「で」は主体を示せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「仮説」を話題にして、それが本当だとわかったと述べる主題の「は」。"}, {"text": "と", "is_correct": false, "explanation": "「仮説と本当だ」では、本当だという述語の主体にならない。"}, {"text": "から", "is_correct": false, "explanation": "「仮説から本当だ」は起点の意味になり、本当だという述語とは合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「仮説へ本当だ」は方向の意味になり、この文の述語とは合わない。"}], "correct_answer": "は", "explanations": {"は": "「仮説」を話題にして、それが本当だとわかったと述べる主題の「は」。", "と": "「仮説と本当だ」では、本当だという述語の主体にならない。", "から": "「仮説から本当だ」は起点の意味になり、本当だという述語とは合わない。", "へ": "「仮説へ本当だ」は方向の意味になり、この文の述語とは合わない。"}, "error_tags": {"と": "並列・引用の「と」は主体にならない", "から": "起点の「から」は述語と合わない", "へ": "方向の「へ」は述語と合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まだ本当かどうかわからない、自分で考えた予想や考え。", "primary_collocate": null, "pronunciation": "かせつ", "ipa": "kasetsɯ", "syllable_count": 3, "sentences": [{"text": "実験の前に、結果についての仮説を立てた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "実験[じっけん]の前[まえ]に、結果[けっか]についての仮説[かせつ]を立[た]てた。", "sentence_source": "generated"}, {"text": "彼の仮説は、実際に調べてみると間違っていた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "彼[かれ]の仮説[かせつ]は、実際[じっさい]に調[しら]べてみると間違[まちが]っていた。", "sentence_source": "generated"}, {"text": "私は「猫は雨の日によく寝る」という仮説を考えた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "私[わたし]は「猫[ねこ]は雨[あめ]の日[ひ]によく寝[ね]る」という仮説[かせつ]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "まだ仮説なので、本当だと決めてはいけない。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "まだ仮説[かせつ]なので、本当[ほんとう]だと決[き]めてはいけない。", "sentence_source": "generated"}, {"text": "先生は生徒に、自分の仮説を発表させた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、自分[じぶん]の仮説[かせつ]を発表[はっぴょう]させた。", "sentence_source": "generated"}, {"text": "仮説が正しいかどうかは、調べないとわからない。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "仮説[かせつ]が正[ただ]しいかどうかは、調[しら]べないとわからない。", "sentence_source": "generated"}, {"text": "友達の仮説を聞いて、おもしろい考えだと思った。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "友達[ともだち]の仮説[かせつ]を聞[き]いて、おもしろい考[かんが]えだと思[おも]った。", "sentence_source": "generated"}, {"text": "証拠が見つかり、仮説は本当だとわかった。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "証拠[しょうこ]が見[み]つかり、仮説[かせつ]は本当[ほんとう]だとわかった。", "sentence_source": "generated"}, {"text": "雲が多い日は涼しいという仮説を、一週間かけて確かめた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "雲[くも]が多[おお]い日[ひ]は涼[すず]しいという仮説[かせつ]を、一週間[いっしゅうかん]かけて確[たし]かめた。", "sentence_source": "generated"}, {"text": "最初の仮説がだめでも、別の仮説を考えればいい。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "最初[さいしょ]の仮説[かせつ]がだめでも、別[べつ]の仮説[かせつ]を考[かんが]えればいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仮説", "label": "基本形"}], "register": "中立", "sense_fingerprint": "本当かどうかまだわからない、自分で考えた予想や話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仮説", "is_correct": true, "explanation": "「まだ本当かわからない考え」の意味で、「仮説を立てる」と言うのが自然。実験の前に立てるものとして合う。"}, {"text": "予算", "is_correct": false, "explanation": "予算は金額の見積もりなので、結果についての考えには合わない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は経験したあとに抱くものなので、実験の前に「立てる」対象ではない。"}, {"text": "報告", "is_correct": false, "explanation": "報告は結果をまとめて伝えることで、「立てる」対象にはならない。"}], "explanations": {"仮説": "「まだ本当かわからない考え」の意味で、「仮説を立てる」と言うのが自然。実験の前に立てるものとして合う。", "予算": "予算は金額の見積もりなので、結果についての考えには合わない。", "感想": "感想は経験したあとに抱くものなので、実験の前に「立てる」対象ではない。", "報告": "報告は結果をまとめて伝えることで、「立てる」対象にはならない。"}, "sentence_index": 0, "correct_answer": "仮説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この理論は多くの実験で確かめられ、今では仮説として教科書に載っている。", "explanation": "ここは確かめ済みで定まった考えという意味で使われている。仮説は本当かどうか未確認の段階の考えなので、確かめ済みの理論は定説と言うべきで、仮説とは言わない。"}, {"text": "彼が示した美しい計算は、この定理の仮説として、もう疑いようがない。", "explanation": "証明の意味で使われている。仮説は確かめる前の考えで、疑いのない証拠にはならないので、ここでは合わない。"}, {"text": "水が百度で沸騰することは、学校で習う仮説だ。", "explanation": "誰でも知っている常識は仮説ではない。仮説は未確認の考えという意味なので、常識には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仮説", "is_correct": true, "explanation": "「友達が立てた考え」を指す語で、聞いて面白いと感じる対象として自然。"}, {"text": "自信", "is_correct": false, "explanation": "「自信を聞く」とは言わない。自信は聞くものではなく持つものなので合わない。"}, {"text": "感情", "is_correct": false, "explanation": "「感情を聞く」は不自然で、話の内容として聞く対象にはならない。"}, {"text": "性格", "is_correct": false, "explanation": "「性格を聞く」は不自然で、「友達の性格」は聞いて考えの評価をする対象ではない。"}], "explanations": {"仮説": "「友達が立てた考え」を指す語で、聞いて面白いと感じる対象として自然。", "自信": "「自信を聞く」とは言わない。自信は聞くものではなく持つものなので合わない。", "感情": "「感情を聞く」は不自然で、話の内容として聞く対象にはならない。", "性格": "「性格を聞く」は不自然で、「友達の性格」は聞いて考えの評価をする対象ではない。"}, "sentence_index": 6, "correct_answer": "仮説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のあと、被災者たちは仮説の住宅で数か月暮らした。", "explanation": "「仮説」は考えの意味で、建物を指す「仮設」（仮に設けた施設）の意味ではない。ここは仮設住宅の意味なので合わない。"}, {"text": "川の橋の仮説工事が、今朝から始まった。", "explanation": "「架設」（橋などを架けること）の意味で使われている。仮説は考えのことなので、工事には合わない。"}, {"text": "地球が丸いことは、すでに観測で確かめられた仮説だ。", "explanation": "「事実」に近い意味で使われている。仮説は確かめていない考えという意味なので、確かめられた事実には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は結果について仮説を立ったので、実験を始めた。", "corrected_sentence": "研究者は結果について仮説を立てたので、実験を始めた。", "error_description": "「立つ」は自動詞で、目的語の「仮説を」と結びつかない。目的語をとる他動詞「立てる」の「立てた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その仮説は、データを集めてから、ようやく確かめた。", "corrected_sentence": "その仮説は、データを集めてから、ようやく確かめられた。", "error_description": "「仮説」が主語なので、「確かめる」は受身の「確かめられた」にする必要がある。能動の「確かめた」は主語と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支持する」の目的語を示す「を」。「仮説を支持していた」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「支持する」は目的語に「を」をとるので、「仮説に支持していた」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「仮説で支持していた」は手段の意味になり、目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「仮説から支持していた」は起点の意味になり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「支持する」の目的語を示す「を」。「仮説を支持していた」で正しい。", "に": "「支持する」は目的語に「を」をとるので、「仮説に支持していた」は不自然。", "で": "「仮説で支持していた」は手段の意味になり、目的語を示せない。", "から": "「仮説から支持していた」は起点の意味になり、目的語を示せない。"}, "error_tags": {"に": "目的語の「に」は「支持する」と合わない", "で": "手段の「で」は目的語を示せない", "から": "起点の「から」は目的語を示せない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼の仮説」を話題にして、それが大胆だと述べる主題の「は」。"}, {"text": "を", "is_correct": false, "explanation": "「仮説を大胆だ」では、大胆だという状態の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「仮説と大胆だ」では、大胆だという状態の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「仮説へ大胆だ」は方向の意味になり、この文の述語とは合わない。"}], "correct_answer": "は", "explanations": {"は": "「彼の仮説」を話題にして、それが大胆だと述べる主題の「は」。", "を": "「仮説を大胆だ」では、大胆だという状態の主語にならない。", "と": "「仮説と大胆だ」では、大胆だという状態の主語にならない。", "へ": "「仮説へ大胆だ」は方向の意味になり、この文の述語とは合わない。"}, "error_tags": {"を": "目的語の「を」は状態の主語にならない", "と": "並列・引用の「と」は主語にならない", "へ": "方向の「へ」は述語と合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある現象を説明するために、まだ証明されていない、もっともらしい考えや理論。", "primary_collocate": null, "pronunciation": "かせつ", "ipa": "kasetsɯ", "syllable_count": 3, "sentences": [{"text": "科学者は、その現象を説明する新しい仮説を発表した。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、その現象[げんしょう]を説明[せつめい]する新[あたら]しい仮説[かせつ]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "実験の結果は、彼女が立てた仮説を支持していた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "実験[じっけん]の結果[けっか]は、彼女[かのじょ]が立[た]てた仮説[かせつ]を支持[しじ]していた。", "sentence_source": "generated"}, {"text": "この仮説はまだ証明されておらず、多くの研究者が検証を続けている。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "この仮説[かせつ]はまだ証明[しょうめい]されておらず、多[おお]くの研究者[けんきゅうしゃ]が検証[けんしょう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "恐竜の絶滅については、隕石説をはじめ複数の仮説がある。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]の絶滅[ぜつめつ]については、隕石説[いんせきせつ]をはじめ複数[ふくすう]の仮説[かせつ]がある。", "sentence_source": "generated"}, {"text": "データが集まるにつれて、初めの仮説は修正を迫られた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "データが集[あつ]まるにつれて、初[はじ]めの仮説[かせつ]は修正[しゅうせい]を迫[せま]られた。", "sentence_source": "generated"}, {"text": "研究では、まず仮説を立て、次に実験で確かめる。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "研究[けんきゅう]では、まず仮説[かせつ]を立[た]て、次[つぎ]に実験[じっけん]で確[たし]かめる。", "sentence_source": "generated"}, {"text": "反対する証拠が出たため、その仮説は退けられた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "反対[はんたい]する証拠[しょうこ]が出[で]たため、その仮説[かせつ]は退[しりぞ]けられた。", "sentence_source": "generated"}, {"text": "彼の仮説は大胆だが、筋が通っているので注目された。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "彼[かれ]の仮説[かせつ]は大胆[だいたん]だが、筋[すじ]が通[とお]っているので注目[ちゅうもく]された。", "sentence_source": "generated"}, {"text": "宇宙の始まりに関する仮説は、観測技術の進歩で次々に検証されている。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の始[はじ]まりに関[かん]する仮説[かせつ]は、観測[かんそく]技術[ぎじゅつ]の進歩[しんぽ]で次々[つぎつぎ]に検証[けんしょう]されている。", "sentence_source": "generated"}, {"text": "論文には、仮説の根拠と検証方法が詳しく書かれていた。", "target_word": "仮説", "complexity_tier": "T3", "furigana": "論文[ろんぶん]には、仮説[かせつ]の根拠[こんきょ]と検証[けんしょう]方法[ほうほう]が詳[くわ]しく書[か]かれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仮説", "label": "基本形"}], "register": "中立", "sense_fingerprint": "科学・研究で、現象を説明するために立てる未証明の理論", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仮説", "is_correct": true, "explanation": "科学者が現象を説明するために発表する未証明の考えを指し、「発表した」と合う。"}, {"text": "印象", "is_correct": false, "explanation": "印象は受け取るもので、科学者が「発表する」対象にはならない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は表すものであり、現象の説明として「発表する」対象ではない。"}, {"text": "表情", "is_correct": false, "explanation": "表情は見せるものであり、学術的な内容を「発表する」対象ではない。"}], "explanations": {"仮説": "科学者が現象を説明するために発表する未証明の考えを指し、「発表した」と合う。", "印象": "印象は受け取るもので、科学者が「発表する」対象にはならない。", "感情": "感情は表すものであり、現象の説明として「発表する」対象ではない。", "表情": "表情は見せるものであり、学術的な内容を「発表する」対象ではない。"}, "sentence_index": 0, "correct_answer": "仮説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その法則は長い検証を経て、今ではすっかり仮説として疑う人はいない。", "explanation": "確かめ済みで定まった考えという意味で使われている。仮説は未確認の段階の考えなので、定説と言うべきで、ここでは合わない。"}, {"text": "月に水があることは、探査で確かめられた仮説だ。", "explanation": "「事実」に近い意味で使われている。仮説は確かめる前の考えという意味なので、確かめられた事実には使わない。"}, {"text": "地球が太陽の周りを回ることは、誰もが知る仮説だ。", "explanation": "誰もが知る常識は仮説ではない。仮説は未確認の考えという意味なので、常識には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仮説", "is_correct": true, "explanation": "証拠が出て退けられる、未確認の考えを指し、「その仮説は退けられた」と合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は退けられるものではなく、証拠との関係で論じる対象にもならない。"}, {"text": "感覚", "is_correct": false, "explanation": "感覚は退けられるものではなく、証拠に基づいて否定される対象ではない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は退けられるものではなく、証拠によって否定される対象にもならない。"}], "explanations": {"仮説": "証拠が出て退けられる、未確認の考えを指し、「その仮説は退けられた」と合う。", "季節": "季節は退けられるものではなく、証拠との関係で論じる対象にもならない。", "感覚": "感覚は退けられるものではなく、証拠に基づいて否定される対象ではない。", "天候": "天候は退けられるものではなく、証拠によって否定される対象にもならない。"}, "sentence_index": 6, "correct_answer": "仮説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震のあと、被災者は仮説の住宅で数か月暮らした。", "explanation": "「仮設」（仮に設けた建物）の意味で使われている。仮説は考えのことなので、住宅には使わない。"}, {"text": "町の川に、新しい橋の仮説工事が始まった。", "explanation": "「仮設」（仮に設けた施設）の意味で使われている。仮説は考えのことなので、工事用の施設には合わない。"}, {"text": "この村には、昔からの仮説が今も残っている。", "explanation": "ここは〈伝説〉（昔から語り伝えられた話）の意味で使われている。仮説は証明を待つ考えなので、語り継がれる昔話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究チームは、新しい仮説で発表した。", "corrected_sentence": "研究チームは、新しい仮説を発表した。", "error_description": "「発表する」の目的語は「仮説を」で示す。「仮説で」の「で」は誤りで、「仮説を」の「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の仮説に大胆だが、筋が通っており、検証の価値がある。", "corrected_sentence": "彼の仮説は大胆だが、筋が通っており、検証の価値がある。", "error_description": "「大胆だ」の主語を示すのは主題の「は」。「仮説に」の「に」は誤りで、「仮説は」の「は」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
