INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36742, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある運動や方針などを、人々に向けて新しく言い出し、勧めること。", "primary_collocate": null, "pronunciation": "ていしょう", "ipa": "teːɕoː", "syllable_count": 4, "sentences": [{"text": "市長は、町をきれいにするための新しい運動を提唱した。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "市長[しちょう]は、町[まち]をきれいにするための新[あたら]しい運動[うんどう]を提唱[ていしょう]した。", "sentence_source": "generated"}, {"text": "彼が提唱した考えに、多くの人が賛成した。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "彼[かれ]が提唱[ていしょう]した考[かんが]えに、多[おお]くの人[ひと]が賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "会議で、週休三日制を提唱する意見が出た。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、週休[しゅうきゅう]三日制[みっかせい]を提唱[ていしょう]する意見[いけん]が出[で]た。", "sentence_source": "generated"}, {"text": "先生は、毎朝の読書を提唱している。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "先生[せんせい]は、毎朝[まいあさ]の読書[どくしょ]を提唱[ていしょう]している。", "sentence_source": "generated"}, {"text": "その提唱は、みんなに受け入れられなかった。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "その提唱[ていしょう]は、みんなに受[う]け入[い]れられなかった。", "sentence_source": "generated"}, {"text": "環境を守ろうと提唱する声が、世界中で大きくなっている。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]ろうと提唱[ていしょう]する声[こえ]が、世界中[せかいじゅう]で大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "社長は、会社を変えるために早起きを提唱した。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、会社[かいしゃ]を変[か]えるために早起[はやお]きを提唱[ていしょう]した。", "sentence_source": "generated"}, {"text": "提唱された案について、全員で話し合った。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "提唱[ていしょう]された案[あん]について、全員[ぜんいん]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "若い議員が、学校給食の無料化を提唱して話題になった。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "若[わか]い議員[ぎいん]が、学校[がっこう]給食[きゅうしょく]の無料化[むりょうか]を提唱[ていしょう]して話題[わだい]になった。", "sentence_source": "generated"}, {"text": "彼女の提唱をきっかけに、町の掃除が始まった。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の提唱[ていしょう]をきっかけに、町[まち]の掃除[そうじ]が始[はじ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提唱", "label": "基本形"}, {"form": "提唱する", "label": "辞書形"}, {"form": "提唱した", "label": "過去形"}, {"form": "提唱される", "label": "受身形"}, {"form": "提唱して", "label": "て形"}], "register": "中立", "sense_fingerprint": "ある意見や考えをみんなに向けて言い出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提唱", "is_correct": true, "explanation": "運動や考えを人々に向けて言い出すという意味で、「運動を提唱した」と合う。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は楽器や曲を奏でることなので、運動には使わない。"}, {"text": "検査", "is_correct": false, "explanation": "検査は調べて確かめることなので、運動を対象に「した」と言うのは不自然。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることなので、運動には使わない。"}], "explanations": {"提唱": "運動や考えを人々に向けて言い出すという意味で、「運動を提唱した」と合う。", "演奏": "演奏は楽器や曲を奏でることなので、運動には使わない。", "検査": "検査は調べて確かめることなので、運動を対象に「した」と言うのは不自然。", "製造": "製造は物を作ることなので、運動には使わない。"}, "sentence_index": 0, "correct_answer": "提唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の前に、新しい資料を提唱した。", "explanation": "「提示」（見せて示すこと）の意味で使われている。提唱は意見や考えを人に向けて言い出すことで、資料には使わない。"}, {"text": "先生は、答案の誤りを提唱した。", "explanation": "「指摘」（誤りを言い表すこと）の意味で使われている。提唱は考えを言い出すことなので、誤りには使わない。"}, {"text": "彼は、自分の無実を強く提唱した。", "explanation": "「主張」（自分の考えを強く述べること）の意味で使われている。提唱は受け入れてもらうための考えを出すことで、無実には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提唱", "is_correct": true, "explanation": "会社を変えるために早起きを言い出すという意味で、「早起きを提唱した」と合う。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物や料理を頼むことなので、早起きには使わない。"}, {"text": "解剖", "is_correct": false, "explanation": "解剖は体を切り開いて調べることなので、早起きには使わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章の言語を変えることなので、早起きには使わない。"}], "explanations": {"提唱": "会社を変えるために早起きを言い出すという意味で、「早起きを提唱した」と合う。", "注文": "注文は品物や料理を頼むことなので、早起きには使わない。", "解剖": "解剖は体を切り開いて調べることなので、早起きには使わない。", "翻訳": "翻訳は文章の言語を変えることなので、早起きには使わない。"}, "sentence_index": 6, "correct_answer": "提唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、生徒にその本を提唱した。", "explanation": "「推薦」（すすめること）の意味で使われている。提唱は考えを言い出すことで、本をすすめる意味では使わない。"}, {"text": "会議で、昨日の売上を提唱した。", "explanation": "「報告」（結果を伝えること）の意味で使われている。提唱は考えを言い出すことなので、数字の報告には使わない。"}, {"text": "市民に危険を提唱した。", "explanation": "「警告」（注意を促すこと）の意味で使われている。提唱は考えを言い出すことなので、危険を知らせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市長は、町の清掃運動を提唱された。", "corrected_sentence": "市長は、町の清掃運動を提唱した。", "error_description": "主語の「市長は」は提唱する側なので、受身の「提唱された」ではなく能動の「提唱した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は、町の掃除に提唱した。", "corrected_sentence": "彼女は、町の掃除を提唱した。", "error_description": "「提唱する」の対象は「を」で示す。「町の掃除に」の「に」は誤りで、「町の掃除を」の「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
