INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36743, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の考えや説を人に示し、その正しさを認めてもらおうとすること", "primary_collocate": null, "pronunciation": "ていしょう", "ipa": "teːɕoː", "syllable_count": 4, "sentences": [{"text": "学者はその説を学会で提唱し、他の研究者に認めてもらおうとした。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "学者[がくしゃ]はその説[せつ]を学会[がっかい]で提唱[ていしょう]し、他[ほか]の研究者[けんきゅうしゃ]に認[みと]めてもらおうとした。", "sentence_source": "generated"}, {"text": "彼が提唱した理論は、発表当時は誰にも相手にされなかった。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "彼[かれ]が提唱[ていしょう]した理論[りろん]は、発表[はっぴょう]当時[とうじ]は誰[だれ]にも相手[あいて]にされなかった。", "sentence_source": "generated"}, {"text": "新しい教育方法を提唱するには、確かな根拠が必要だ。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "新[あたら]しい教育[きょういく]方法[ほうほう]を提唱[ていしょう]するには、確[たし]かな根拠[こんきょ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "アインシュタインは相対性理論を提唱した。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "アインシュタインは相対性[そうたいせい]理論[りろん]を提唱[ていしょう]した。", "sentence_source": "generated"}, {"text": "彼女は長年、食事と健康の関係についての新説を提唱してきた。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は長年[ながねん]、食事[しょくじ]と健康[けんこう]の関係[かんけい]についての新説[しんせつ]を提唱[ていしょう]してきた。", "sentence_source": "generated"}, {"text": "その提唱は、のちに多くの研究者に支持されるようになった。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "その提唱[ていしょう]は、のちに多[おお]くの研究者[けんきゅうしゃ]に支持[しじ]されるようになった。", "sentence_source": "generated"}, {"text": "環境保護の重要性を提唱する本が、世界中で読まれている。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "環境[かんきょう]保護[ほご]の重要性[じゅうようせい]を提唱[ていしょう]する本[ほん]が、世界中[せかいじゅう]で読[よ]まれている。", "sentence_source": "generated"}, {"text": "提唱された説が正しいかどうか、実験で確かめられた。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "提唱[ていしょう]された説[せつ]が正[ただ]しいかどうか、実験[じっけん]で確[たし]かめられた。", "sentence_source": "generated"}, {"text": "彼は独自の経済モデルを提唱し、政府に採用を求めた。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "彼[かれ]は独自[どくじ]の経済[けいざい]モデルを提唱[ていしょう]し、政府[せいふ]に採用[さいよう]を求[もと]めた。", "sentence_source": "generated"}, {"text": "提唱から五十年たって、ようやくその考えが正しいと認められた。", "target_word": "提唱", "complexity_tier": "T3", "furigana": "提唱[ていしょう]から五十年[ごじゅうねん]たって、ようやくその考[かんが]えが正[ただ]しいと認[みと]められた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提唱", "label": "基本形"}, {"form": "提唱する", "label": "辞書形"}, {"form": "提唱した", "label": "過去形"}, {"form": "提唱される", "label": "受身形"}, {"form": "提唱して", "label": "て形"}], "register": "中立", "sense_fingerprint": "自分の説や主張を公に示し、受け入れてもらおうと主張すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36743, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提唱", "is_correct": true, "explanation": "自分の説を学会の場で示すという意味で、「学会で提唱し」と合う。"}, {"text": "解剖", "is_correct": false, "explanation": "解剖は体などを切り開いて調べることなので、説には使わない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むことなので、説を示す場面には使わない。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は曲を奏でることなので、学会で説を示す場面には合わない。"}], "explanations": {"提唱": "自分の説を学会の場で示すという意味で、「学会で提唱し」と合う。", "解剖": "解剖は体などを切り開いて調べることなので、説には使わない。", "注文": "注文は品物を頼むことなので、説を示す場面には使わない。", "演奏": "演奏は曲を奏でることなので、学会で説を示す場面には合わない。"}, "sentence_index": 0, "correct_answer": "提唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その研究者は、新しいデータを提唱して論文にまとめた。", "explanation": "「発表」（結果を公に示すこと）の意味で使われている。提唱は考えを言い出すことで、データには使わない。"}, {"text": "二つの会社は、新製品の開発で提唱した。", "explanation": "「提携」（仕事で手を組むこと）の意味で使われている。提唱は考えを人に示すことで、会社同士の協力には使わない。"}, {"text": "卒業式では、全員で国歌を提唱した。", "explanation": "ここは〈斉唱〉（大勢で声をそろえて歌うこと）の意味で使われている。提唱は考えを人に示すことなので、歌を揃えて歌う場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36743, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提唱", "is_correct": true, "explanation": "環境保護の重要性を世に向けて言い出すという意味で、「提唱する本」と合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章の言語を変えることなので、重要性には使わない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることなので、重要性には使わない。"}, {"text": "検査", "is_correct": false, "explanation": "検査は調べて確かめることなので、重要性を対象に「する」とは言わない。"}], "explanations": {"提唱": "環境保護の重要性を世に向けて言い出すという意味で、「提唱する本」と合う。", "翻訳": "翻訳は文章の言語を変えることなので、重要性には使わない。", "製造": "製造は物を作ることなので、重要性には使わない。", "検査": "検査は調べて確かめることなので、重要性を対象に「する」とは言わない。"}, "sentence_index": 6, "correct_answer": "提唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、昔の失敗を提唱した。", "explanation": "「告白」（隠していたことを打ち明けること）の意味で使われている。提唱は考えを人に示すことで、失敗の打ち明けには使わない。"}, {"text": "その会社は、新商品を大々的に提唱した。", "explanation": "「宣伝」（広く知らせること）の意味で使われている。提唱は考えを言い出すことで、商品の宣伝には使わない。"}, {"text": "彼は法廷で、昨夜の出来事を提唱した。", "explanation": "「証言」（事実を述べること）の意味で使われている。提唱は考えを言い出すことで、出来事を述べる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36743, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学者は、自分の説を学会で提唱ようとして、準備を重ねた。", "corrected_sentence": "学者は、自分の説を学会で提唱しようとして、準備を重ねた。", "error_description": "「提唱する」の意向形は「提唱しよう」。「提唱よう」は活用の誤りで、「しよう」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36743, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その学者は、新しい方法を提唱と示した。", "corrected_sentence": "その学者は、新しい方法を提唱して示した。", "error_description": "「提唱」に続けて動作を並べるときは「提唱して」の形にする。「提唱と」の「と」は誤りで、「提唱して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
