INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36744, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "たった一つのこと。", "primary_collocate": null, "pronunciation": "たんいつ", "ipa": "taɴitsɯ", "syllable_count": 4, "sentences": [{"text": "この部品は単一の素材でできている。", "target_word": "単一", "complexity_tier": "T3", "furigana": "この部品[ぶひん]は単一[たんいつ]の素材[そざい]でできている。", "sentence_source": "generated"}, {"text": "実験では、単一の条件を変えて結果を比べた。", "target_word": "単一", "complexity_tier": "T3", "furigana": "実験(じっけん)では、単一(たんいつ)の条件(じょうけん)を変(か)えて結果(けっか)を比(くら)べた。", "sentence_source": "generated"}, {"text": "答えが単一ではない問題も、世の中にはたくさんある。", "target_word": "単一", "complexity_tier": "T4", "furigana": "答[こた]えが単一[たんいつ]ではない問題[もんだい]も、世[よ]の中[なか]にはたくさんある。", "sentence_source": "generated"}, {"text": "単一のボタンを押すだけで、機械が動く。", "target_word": "単一", "complexity_tier": "T3", "furigana": "単一[たんいつ]のボタンを押[お]すだけで、機械[きかい]が動[うご]く。", "sentence_source": "generated"}, {"text": "このアプリは単一の機能に絞ったので、使い方が分かりやすい。", "target_word": "単一", "complexity_tier": "T4", "furigana": "このアプリは単一[たんいつ]の機能[きのう]に絞[しぼ]ったので、使[つか]い方[かた]が分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "試験の評価が単一の点数で決まるのは不公平だ。", "target_word": "単一", "complexity_tier": "T3", "furigana": "試験(しけん)の評価(ひょうか)が単一(たんいつ)の点数(てんすう)で決(き)まるのは不公平(ふこうへい)だ。", "sentence_source": "generated"}, {"text": "単一の入口を持つ建物は、火事のとき逃げにくい。", "target_word": "単一", "complexity_tier": "T3", "furigana": "単一(たんいつ)の入口(いりぐち)を持(も)つ建物(たてもの)は、火事(かじ)のとき逃(に)げにくい。", "sentence_source": "generated"}, {"text": "彼女は単一の仕事に集中して、他の依頼は断った。", "target_word": "単一", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は単一[たんいつ]の仕事[しごと]に集中[しゅうちゅう]して、他[ほか]の依頼[いらい]は断[ことわ]った。", "sentence_source": "generated"}, {"text": "壁は単一の色で塗られていて、静かな印象だ。", "target_word": "単一", "complexity_tier": "T3", "furigana": "壁[かべ]は単一[たんいつ]の色[いろ]で塗[ぬ]られていて、静[しず]かな印象[いんしょう]だ。", "sentence_source": "generated"}, {"text": "このスープは単一の野菜で作るので、素材の味がよく分かる。", "target_word": "単一", "complexity_tier": "T3", "furigana": "このスープは単一(たんいつ)の野菜(やさい)で作(つく)るので、素材(そざい)の味(あじ)がよく分(わ)かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単一", "label": "語幹"}, {"form": "単一だ", "label": "終止形"}, {"form": "単一の", "label": "連体形"}, {"form": "単一で", "label": "連用形"}, {"form": "単一に", "label": "連用形"}], "register": "書き言葉", "sense_fingerprint": "数がたった一つであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは『たった一つ』の意味の単一。素材が一種類であることを表す。"}, {"text": "華麗", "is_correct": false, "explanation": "華麗は見た目の美しさを表す語で、素材の数を表す文脈に合わない。"}, {"text": "元気", "is_correct": false, "explanation": "元気は人の活力を表す語で、部品の素材を修飾しない。"}, {"text": "頑強", "is_correct": false, "explanation": "頑強は丈夫さを表す語で、素材の数を表す文脈に合わない。"}], "explanations": {"単一": "ここは『たった一つ』の意味の単一。素材が一種類であることを表す。", "華麗": "華麗は見た目の美しさを表す語で、素材の数を表す文脈に合わない。", "元気": "元気は人の活力を表す語で、部品の素材を修飾しない。", "頑強": "頑強は丈夫さを表す語で、素材の数を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "単一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この問題は単一だから、子どもでもすぐ解ける。", "explanation": "ここは〈単純〉の意味。単一は『数がたった一つ』で、『簡単』の意味はないので合わない。"}, {"text": "先生は生徒を単一に呼び、一人ずつ話を聞いた。", "explanation": "ここは〈個別〉の意味。単一は『数がたった一つ』で、『一人ずつ別々に』の意味はないので合わない。"}, {"text": "この部屋は単一で、窓が広くて明るい。", "explanation": "ここは〈広さ〉の意味。単一は『数がたった一つ』で、部屋の広さを表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは『たった一つ』の意味の単一。入口が一つしかない建物を表す。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は派手さを表す語で、入口の数を表す文脈に合わない。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快は楽しさを表す語で、入口を修飾する意味にならない。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は思い切りのよさを表す語で、入口の数を表す文脈に合わない。"}], "explanations": {"単一": "ここは『たった一つ』の意味の単一。入口が一つしかない建物を表す。", "豪華": "豪華は派手さを表す語で、入口の数を表す文脈に合わない。", "愉快": "愉快は楽しさを表す語で、入口を修飾する意味にならない。", "大胆": "大胆は思い切りのよさを表す語で、入口の数を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "単一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は単一で、家族と離れて暮らしている。", "explanation": "ここは〈単身〉の意味。単一は『数がたった一つ』で、『ひとり暮らし』の意味はないので合わない。"}, {"text": "この資料は、数量の単一をグラムに統一している。", "explanation": "ここは〈単位〉の意味。単一は『ただ一つ』で、『基準となる量』の意味はないので合わない。"}, {"text": "彼は単一で、遠くの町へ出かけた。", "explanation": "ここは〈単独〉の意味。単一は『数がたった一つ』で、『ひとりで』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカメラは単一をレンズで撮ると、写りが安定する。", "corrected_sentence": "このカメラは単一のレンズで撮ると、写りが安定する。", "error_description": "助詞の誤り：『単一』は名詞を修飾するときに『の』が必要で、『単一を』は誤り。正しくは『単一のレンズ』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは語幹の形。『の』が続いて『単一の条件』となる名詞修飾の形。"}, {"text": "単一だ", "is_correct": false, "explanation": "終止形で文を言い切る形。『条件を』の前には置けない。"}, {"text": "単一で", "is_correct": false, "explanation": "連用形（で）。動詞や文を続ける形で、名詞の前には使えない。"}, {"text": "単一に", "is_correct": false, "explanation": "連用形（に）。動詞を修飾する形で、名詞の前には置けない。"}], "correct_form": "単一", "base_form": "単一", "form_label": "語幹", "sentence_index": 1, "explanations": {"単一": "ここは語幹の形。『の』が続いて『単一の条件』となる名詞修飾の形。", "単一だ": "終止形で文を言い切る形。『条件を』の前には置けない。", "単一で": "連用形（で）。動詞や文を続ける形で、名詞の前には使えない。", "単一に": "連用形（に）。動詞を修飾する形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工具は単一だ部品で作られているので、道具箱が軽くなる。", "corrected_sentence": "この工具は単一の部品で作られているので、道具箱が軽くなる。", "error_description": "活用形の誤り：名詞『部品』を修飾するには『単一の』が必要なのに、『単一だ』を使った。正しくは『単一の部品』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは語幹の形。『の』が続いて『単一の仕事』となる名詞修飾の形。"}, {"text": "単一だった", "is_correct": false, "explanation": "過去の終止形で文を言い切る形。『仕事』の前には置けない。"}, {"text": "単一なら", "is_correct": false, "explanation": "仮定形（なら）。条件を述べる形で、名詞の前には置けない。"}, {"text": "単一ではなく", "is_correct": false, "explanation": "否定の連用中止形。文を区切る形で、『仕事』の前には置けない。"}], "correct_form": "単一", "base_form": "単一", "form_label": "語幹", "sentence_index": 7, "explanations": {"単一": "ここは語幹の形。『の』が続いて『単一の仕事』となる名詞修飾の形。", "単一だった": "過去の終止形で文を言い切る形。『仕事』の前には置けない。", "単一なら": "仮定形（なら）。条件を述べる形で、名詞の前には置けない。", "単一ではなく": "否定の連用中止形。文を区切る形で、『仕事』の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
