INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36745, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "一つのみで、他にないこと。", "primary_collocate": null, "pronunciation": "たんいつ", "ipa": "taɴitsɯ", "syllable_count": 4, "sentences": [{"text": "この店は単一の品種のワインだけを置いている。", "target_word": "単一", "complexity_tier": "T5", "furigana": "この店[みせ]は単一[たんいつ]の品種[ひんしゅ]のワインだけを置[お]いている。", "sentence_source": "generated"}, {"text": "この農園は、単一の品種で白ワインを造っている。", "target_word": "単一", "complexity_tier": "T3", "furigana": "この農園(のうえん)は、単一(たんいつ)の品種(ひんしゅ)で白(しろ)ワインを造(つく)っている。", "sentence_source": "generated"}, {"text": "単一の原因ではなく、いくつもの問題が重なって事故が起きた。", "target_word": "単一", "complexity_tier": "T4", "furigana": "単一[たんいつ]の原因[げんいん]ではなく、いくつもの問題[もんだい]が重[かさ]なって事故[じこ]が起[お]きた。", "sentence_source": "generated"}, {"text": "このコーヒーは単一の産地の豆で作られているので、味に個性がある。", "target_word": "単一", "complexity_tier": "T3", "furigana": "このコーヒーは単一(たんいつ)の産地(さんち)の豆(まめ)で作(つく)られているので、味(あじ)に個性(こせい)がある。", "sentence_source": "generated"}, {"text": "単一の会社に頼りすぎると、その会社が倒れたとき困る。", "target_word": "単一", "complexity_tier": "T4", "furigana": "単一[たんいつ]の会社[かいしゃ]に頼[たよ]りすぎると、その会社[かいしゃ]が倒[たお]れたとき困[こま]る。", "sentence_source": "generated"}, {"text": "国民の意見は単一ではなく、地域によってかなり違う。", "target_word": "単一", "complexity_tier": "T4", "furigana": "国民[こくみん]の意見[いけん]は単一[たんいつ]ではなく、地域[ちいき]によってかなり違[ちが]う。", "sentence_source": "generated"}, {"text": "彼の作品は単一のテーマで統一されている。", "target_word": "単一", "complexity_tier": "T4", "furigana": "彼[かれ]の作品[さくひん]は単一[たんいつ]のテーマで統一[とういつ]されている。", "sentence_source": "generated"}, {"text": "単一の方法で全員を教えるのは難しい。", "target_word": "単一", "complexity_tier": "T3", "furigana": "単一[たんいつ]の方法[ほうほう]で全員[ぜんいん]を教[おし]えるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "このグループは単一の目的のために作られた。", "target_word": "単一", "complexity_tier": "T3", "furigana": "このグループは単一[たんいつ]の目的[もくてき]のために作[つく]られた。", "sentence_source": "generated"}, {"text": "彼の論文は単一の理論で、社会全体を説明しようとしている。", "target_word": "単一", "complexity_tier": "T3", "furigana": "彼(かれ)の論文(ろんぶん)は単一(たんいつ)の理論(りろん)で、社会全体(しゃかいぜんたい)を説明(せつめい)しようとしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単一", "label": "語幹"}, {"form": "単一だ", "label": "終止形"}, {"form": "単一の", "label": "連体形"}, {"form": "単一で", "label": "連用形"}, {"form": "単一に", "label": "連用形"}], "register": "書き言葉", "sense_fingerprint": "ただ一つだけで、ほかのものが加わらない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38d5ee0e-efc1-410c-b164-1a2603d86ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは『ただ一つで他にない』の意味の単一。単一の品種は一種類の品種だけを使う意味になる。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は性格や雰囲気を表す語で、品種を修飾する意味にならない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫さを表す語で、品種の数を表す文脈に合わない。"}, {"text": "鮮明", "is_correct": false, "explanation": "鮮明は色や映像のはっきりさを表す語で、品種を修飾しない。"}], "explanations": {"単一": "ここは『ただ一つで他にない』の意味の単一。単一の品種は一種類の品種だけを使う意味になる。", "陽気": "陽気は性格や雰囲気を表す語で、品種を修飾する意味にならない。", "頑丈": "頑丈は丈夫さを表す語で、品種の数を表す文脈に合わない。", "鮮明": "鮮明は色や映像のはっきりさを表す語で、品種を修飾しない。"}, "sentence_index": 0, "correct_answer": "単一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この作業は単一なので、新人にも任せられる。", "explanation": "ここは〈単純〉の意味。単一は『ただ一つで他にないこと』で、『簡単』の意味はないので合わない。"}, {"text": "この靴は単一で、長い距離を歩いても疲れない。", "explanation": "ここは〈丈夫〉の意味。単一は『ただ一つで他にないこと』で、『丈夫さ』の意味はないので合わない。"}, {"text": "この店では、どの商品も単一に値下げされた。", "explanation": "ここは〈一律に〉の意味。単一は『ただ一つ』で、『全部同じように』の意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは『ただ一つで他にない』の意味の単一。テーマが一つに統一されている意味になる。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は派手さを表す語で、テーマの数を表す文脈に合わない。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快は楽しさを表す語で、テーマを修飾する意味にならない。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は思い切りのよさを表す語で、テーマの数を表す文脈に合わない。"}], "explanations": {"単一": "ここは『ただ一つで他にない』の意味の単一。テーマが一つに統一されている意味になる。", "豪華": "豪華は派手さを表す語で、テーマの数を表す文脈に合わない。", "愉快": "愉快は楽しさを表す語で、テーマを修飾する意味にならない。", "大胆": "大胆は思い切りのよさを表す語で、テーマの数を表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "単一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は単一に勉強を続けて、ついに試験に合格した。", "explanation": "ここは〈ひたすら〉の意味。単一は『ただ一つ』で、『一つのことに打ち込む』の意味はないので合わない。"}, {"text": "この資料は、距離の単一をメートルに統一している。", "explanation": "ここは〈単位〉の意味。単一は『ただ一つ』で、『基準となる量』の意味はないので合わない。"}, {"text": "彼は単一で、社会全体を説明しようとしている。", "explanation": "ここは〈単独〉の意味。単一は『ただ一つで他にないこと』で、『ひとりで』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は単一を目標に向かって、毎日努力を続けている。", "corrected_sentence": "彼は単一の目標に向かって、毎日努力を続けている。", "error_description": "助詞の誤り：『単一』は形状詞で、名詞を修飾するには『の』が必要。『単一を』は誤り。正しくは『単一の目標』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは語幹の形。『の』が続いて『単一の品種』となる名詞修飾の形。"}, {"text": "単一だ", "is_correct": false, "explanation": "終止形で文を言い切る形。『品種で』の前には置けない。"}, {"text": "単一で", "is_correct": false, "explanation": "連用形（で）。動詞や文を続ける形で、名詞の前には使えない。"}, {"text": "単一に", "is_correct": false, "explanation": "連用形（に）。動詞を修飾する形で、名詞の前には置けない。"}], "correct_form": "単一", "base_form": "単一", "form_label": "語幹", "sentence_index": 1, "explanations": {"単一": "ここは語幹の形。『の』が続いて『単一の品種』となる名詞修飾の形。", "単一だ": "終止形で文を言い切る形。『品種で』の前には置けない。", "単一で": "連用形（で）。動詞や文を続ける形で、名詞の前には使えない。", "単一に": "連用形（に）。動詞を修飾する形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36745, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は候補を単一だ絞って、選考を進めた。", "corrected_sentence": "彼女は候補を単一に絞って、選考を進めた。", "error_description": "活用形の誤り：『絞る』に続く連用形『単一に』が必要なのに、終止形『単一だ』を使った。正しくは『単一に絞って』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単一", "is_correct": true, "explanation": "ここは語幹の形。『の』が続いて『単一の方法』となる名詞修飾の形。"}, {"text": "単一だった", "is_correct": false, "explanation": "過去の終止形で文を言い切る形。『方法で』の前には置けない。"}, {"text": "単一なら", "is_correct": false, "explanation": "仮定形（なら）。条件を述べる形で、名詞の前には置けない。"}, {"text": "単一ではなく", "is_correct": false, "explanation": "否定の連用中止形。文を区切る形で、『方法で』に続けて名詞を修飾することはできない。"}], "correct_form": "単一", "base_form": "単一", "form_label": "語幹", "sentence_index": 7, "explanations": {"単一": "ここは語幹の形。『の』が続いて『単一の方法』となる名詞修飾の形。", "単一だった": "過去の終止形で文を言い切る形。『方法で』の前には置けない。", "単一なら": "仮定形（なら）。条件を述べる形で、名詞の前には置けない。", "単一ではなく": "否定の連用中止形。文を区切る形で、『方法で』に続けて名詞を修飾することはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4e9175b-b6ae-41f4-adb1-8f0333daa2bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36746, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "原因を主題として示し、「〜ことだ」で原因の内容を述べる文の形に合う。"}, {"text": "を", "is_correct": false, "explanation": "原因は「〜を」の目的語にはならず、「〜ことだ」と続けても文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や結果を示すが、ここは原因を主題として示す位置なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、原因は行き先にならないので文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "原因を主題として示し、「〜ことだ」で原因の内容を述べる文の形に合う。", "を": "原因は「〜を」の目的語にはならず、「〜ことだ」と続けても文が成り立たない。", "に": "「に」は対象や結果を示すが、ここは原因を主題として示す位置なので合わない。", "へ": "「へ」は方向を示すが、原因は行き先にならないので文が成立しない。"}, "error_tags": {"を": "目的語", "に": "対象", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "結果", "is_correct": true, "explanation": "原因によって生じたことを指し、「原因」と対になる語として辞典に載る。"}, {"text": "目的", "is_correct": false, "explanation": "目的は行動の狙いのことで、原因と対をなす語ではない。"}, {"text": "手段", "is_correct": false, "explanation": "手段は目的を果たす方法のことで、原因と対義の関係にない。"}, {"text": "基準", "is_correct": false, "explanation": "基準は判断のよりどころのことで、原因の対義語にはならない。"}], "correct_answer": "結果", "explanations": {"結果": "原因によって生じたことを指し、「原因」と対になる語として辞典に載る。", "目的": "目的は行動の狙いのことで、原因と対をなす語ではない。", "手段": "手段は目的を果たす方法のことで、原因と対義の関係にない。", "基準": "基準は判断のよりどころのことで、原因の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36746, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "結果", "is_correct": true, "explanation": "原因によって生じたことを指し、「原因」と対になる語として辞典に載る。"}, {"text": "規則", "is_correct": false, "explanation": "規則は決まりごとのことで、原因の対義語にはならない。"}, {"text": "資格", "is_correct": false, "explanation": "資格は認められた地位や条件のことで、原因と対義の関係にない。"}, {"text": "材料", "is_correct": false, "explanation": "材料は物を作るための素材で、原因と対をなす語ではない。"}], "correct_answer": "結果", "explanations": {"結果": "原因によって生じたことを指し、「原因」と対になる語として辞典に載る。", "規則": "規則は決まりごとのことで、原因の対義語にはならない。", "資格": "資格は認められた地位や条件のことで、原因と対義の関係にない。", "材料": "材料は物を作るための素材で、原因と対をなす語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36746, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こるもとになったこと。", "primary_collocate": null, "pronunciation": "げんいん", "ipa": "ɡeɴiɴ", "syllable_count": 4, "sentences": [{"text": "火事の原因は、古いストーブだった。", "target_word": "原因", "complexity_tier": "T3", "furigana": "火事[かじ]の原因[げんいん]は、古[ふる]いストーブだった。", "sentence_source": "generated"}, {"text": "遅刻の原因は、電車が止まったことだ。", "target_word": "原因", "complexity_tier": "T3", "furigana": "遅刻[ちこく]の原因[げんいん]は、電車[でんしゃ]が止[と]まったことだ。", "sentence_source": "generated"}, {"text": "風邪の原因がわからなくて、病院へ行った。", "target_word": "原因", "complexity_tier": "T3", "furigana": "風邪[かぜ]の原因[げんいん]がわからなくて、病院[びょういん]へ行[い]った。", "sentence_source": "generated"}, {"text": "失敗の原因を考えて、次はうまくやろうと思った。", "target_word": "原因", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の原因[げんいん]を考[かんが]えて、次[つぎ]はうまくやろうと思[おも]った。", "sentence_source": "generated"}, {"text": "頭が痛い原因は、昨日あまり寝なかったことだろう。", "target_word": "原因", "complexity_tier": "T3", "furigana": "頭[あたま]が痛[いた]い原因[げんいん]は、昨日[きのう]あまり寝[ね]なかったことだろう。", "sentence_source": "generated"}, {"text": "兄弟げんかの原因は、ほんの小さなことだった。", "target_word": "原因", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]げんかの原因[げんいん]は、ほんの小[ちい]さなことだった。", "sentence_source": "generated"}, {"text": "原因がわかれば、直し方も見つかる。", "target_word": "原因", "complexity_tier": "T3", "furigana": "原因[げんいん]がわかれば、直[なお]し方[かた]も見[み]つかる。", "sentence_source": "generated"}, {"text": "事故の原因について、警察が調べている。", "target_word": "原因", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]について、警察[けいさつ]が調[しら]べている。", "sentence_source": "generated"}, {"text": "水が出ない原因は、パイプが凍ったことだった。", "target_word": "原因", "complexity_tier": "T3", "furigana": "水[みず]が出[で]ない原因[げんいん]は、パイプが凍[こお]ったことだった。", "sentence_source": "generated"}, {"text": "原因は私にあるので、みんなに謝った。", "target_word": "原因", "complexity_tier": "T3", "furigana": "原因[げんいん]は私[わたし]にあるので、みんなに謝[あやま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原因", "label": "基本形"}], "register": "中立", "sense_fingerprint": "出来事や困った状態が起こるもとになったこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "「火事が起きるもとになったこと」の意味で、古いストーブがそのもとだと述べる文に合う。"}, {"text": "被害", "is_correct": false, "explanation": "被害は火事で生じた損害のことで、「火事の被害は古いストーブだった」は意味が通らない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は火事に伴う現象で、火事の出どころとして古いストーブを示す文には合わない。"}, {"text": "住所", "is_correct": false, "explanation": "住所は場所を示す語で、火事の性質を述べる文の主語にはならない。"}], "explanations": {"原因": "「火事が起きるもとになったこと」の意味で、古いストーブがそのもとだと述べる文に合う。", "被害": "被害は火事で生じた損害のことで、「火事の被害は古いストーブだった」は意味が通らない。", "煙": "煙は火事に伴う現象で、火事の出どころとして古いストーブを示す文には合わない。", "住所": "住所は場所を示す語で、火事の性質を述べる文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストの原因が返ってきた。", "explanation": "原因は出来事のもとを指す語で、返ってくる答案の点数には使えない。"}, {"text": "薬の原因がすぐに現れた。", "explanation": "原因は引き起こすもとを指す語で、薬がすぐに表す作用には使えない。"}, {"text": "原因が逃げた。", "explanation": "原因は人を指す語ではないので、逃げる人には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "「がわかれば」の主語になり、もとが判明すれば直し方も見つかるという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象の状態で、わかっても直し方が見つかるという文の主語にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分で、「直し方が見つかる」の文脈とは意味がつながらない。"}, {"text": "色", "is_correct": false, "explanation": "色は外観の性質で、直し方の手がかりを示す主語にはならない。"}], "explanations": {"原因": "「がわかれば」の主語になり、もとが判明すれば直し方も見つかるという文に合う。", "天気": "天気は気象の状態で、わかっても直し方が見つかるという文の主語にはならない。", "季節": "季節は一年の区分で、「直し方が見つかる」の文脈とは意味がつながらない。", "色": "色は外観の性質で、直し方の手がかりを示す主語にはならない。"}, "sentence_index": 6, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "実験の原因が達成された。", "explanation": "原因は達成されるねらいを表す語ではないので、この文では使えない。"}, {"text": "店の原因が広がった。", "explanation": "原因は世間に広がる評判を表す語ではないので、この文では使えない。"}, {"text": "彼との原因が解けた。", "explanation": "原因は解ける誤解を表す語ではないので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
