INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄や現象を引き起こすもととなる事柄。理由。", "primary_collocate": null, "pronunciation": "げんいん", "ipa": "ɡeɴiɴ", "syllable_count": 4, "sentences": [{"text": "専門家は、事故の原因を詳しく調べて報告書にまとめた。", "target_word": "原因", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、事故[じこ]の原因[げんいん]を詳[くわ]しく調[しら]べて報告書[ほうこくしょ]にまとめた。", "sentence_source": "generated"}, {"text": "地球温暖化の主な原因は、二酸化炭素の増加だと考えられている。", "target_word": "原因", "complexity_tier": "T3", "furigana": "地球[ちきゅう]温暖化[おんだんか]の主[おも]な原因[げんいん]は、二酸化炭素[にさんかたんそ]の増加[ぞうか]だと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "原因と結果を取り違えると、正しい判断ができない。", "target_word": "原因", "complexity_tier": "T3", "furigana": "原因[げんいん]と結果[けっか]を取[と]り違[ちが]えると、正[ただ]しい判断[はんだん]ができない。", "sentence_source": "generated"}, {"text": "売り上げが落ちた原因は、競合店の出店にあった。", "target_word": "原因", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが落[お]ちた原因[げんいん]は、競合店[きょうごうてん]の出店[しゅってん]にあった。", "sentence_source": "generated"}, {"text": "病気の原因が特定されたことで、新しい治療法が開発された。", "target_word": "原因", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]が特定[とくてい]されたことで、新[あたら]しい治療法[ちりょうほう]が開発[かいはつ]された。", "sentence_source": "generated"}, {"text": "停電の原因は、雷による送電線の故障だった。", "target_word": "原因", "complexity_tier": "T3", "furigana": "停電[ていでん]の原因[げんいん]は、雷[かみなり]による送電線[そうでんせん]の故障[こしょう]だった。", "sentence_source": "generated"}, {"text": "その問題の原因は、複数の要因が重なったことにある。", "target_word": "原因", "complexity_tier": "T3", "furigana": "その問題[もんだい]の原因[げんいん]は、複数[ふくすう]の要因[よういん]が重[かさ]なったことにある。", "sentence_source": "generated"}, {"text": "原因を取り除かない限り、同じ問題は何度も起きる。", "target_word": "原因", "complexity_tier": "T3", "furigana": "原因[げんいん]を取[と]り除[のぞ]かない限[かぎ]り、同[おな]じ問題[もんだい]は何度[なんど]も起[お]きる。", "sentence_source": "generated"}, {"text": "調査の結果、システム障害の原因はプログラムの誤りと判明した。", "target_word": "原因", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]、システム障害[しょうがい]の原因[げんいん]はプログラムの誤[あやま]りと判明[はんめい]した。", "sentence_source": "generated"}, {"text": "彼は自分の健康悪化の原因が、長年の不規則な生活にあると気づいた。", "target_word": "原因", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の健康[けんこう]悪化[あっか]の原因[げんいん]が、長年[ながねん]の不規則[ふきそく]な生活[せいかつ]にあると気[き]づいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原因", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ある結果や現象を引き起こす、もとになる事柄や理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 取り違える (Zipf 1.8)']::text[], '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "「詳しく調べて報告書にまとめた」の対象になり、事故のもとを調べるという文に合う。"}, {"text": "料金", "is_correct": false, "explanation": "料金は支払うお金のことで、事故を詳しく調べる対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象の状態で、事故を調べて報告書にまとめる対象とは合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、事故を調べる文の対象にはならない。"}], "explanations": {"原因": "「詳しく調べて報告書にまとめた」の対象になり、事故のもとを調べるという文に合う。", "料金": "料金は支払うお金のことで、事故を詳しく調べる対象にはならない。", "天気": "天気は気象の状態で、事故を調べて報告書にまとめる対象とは合わない。", "味": "味は食べ物の性質で、事故を調べる文の対象にはならない。"}, "sentence_index": 0, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい法律の原因が及んだ。", "explanation": "原因はもとになる事柄を指すので、ほかへ及ぶ作用の意味では使えない。"}, {"text": "先生の原因に従った。", "explanation": "原因は起こるもとを指すので、従うべき命令の意味では使えない。"}, {"text": "原因が届いた。", "explanation": "原因は届くものではないので、郵便で届くものの意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原因", "is_correct": true, "explanation": "「その問題の」の後に来て、複数の要因が重なったことにあると述べる文に合う。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は目に掛ける道具で、問題の要因を述べる文には合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は外観の性質で、「〜にある」と原因を説明する文には合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は人の生まれた日で、問題の要因を示す文脈には合わない。"}], "explanations": {"原因": "「その問題の」の後に来て、複数の要因が重なったことにあると述べる文に合う。", "眼鏡": "眼鏡は目に掛ける道具で、問題の要因を述べる文には合わない。", "色": "色は外観の性質で、「〜にある」と原因を説明する文には合わない。", "誕生日": "誕生日は人の生まれた日で、問題の要因を示す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "原因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この商品の原因は千円だ。", "explanation": "原因は引き起こすもとを指すので、仕入れにかかる費用の意味では使えない。"}, {"text": "この契約書の原因を大切に保管した。", "explanation": "原因は引き起こすもとを指すので、元の書類の意味では使えない。"}, {"text": "原因を精製して、ガソリンを作った。", "explanation": "原因は引き起こすもとを指すので、精製して燃料にする原油の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その事故の原因は、居眠り運転をある。", "corrected_sentence": "その事故の原因は、居眠り運転にある。", "error_description": "「ある」は所在を表して「〜にある」と続けるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の成績が落ちた原因を、睡眠不足にある。", "corrected_sentence": "彼の成績が落ちた原因は、睡眠不足にある。", "error_description": "「原因は〜にある」の「は」を「を」と誤っている。原因を主題として示すには「は」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「説明をお願い」の形で、お願いの対象となる説明を示す。"}, {"text": "が", "is_correct": false, "explanation": "「説明がお願い」は説明を求める対象を表せず、「が」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、説明を求める対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、お願いの対象を示す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「説明をお願い」の形で、お願いの対象となる説明を示す。", "が": "「説明がお願い」は説明を求める対象を表せず、「が」は合わない。", "で": "「で」は手段や場所を示すので、説明を求める対象にはならない。", "へ": "「へ」は方向を示すので、お願いの対象を示す位置には合わない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
