INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "よくわかるように話すこと。", "primary_collocate": null, "pronunciation": "せつめい", "ipa": "setsɯmeː", "syllable_count": 4, "sentences": [{"text": "先生は、むずかしい言葉の意味を、やさしく説明してくれました。", "target_word": "説明", "complexity_tier": "T3", "furigana": "先生[せんせい]は、むずかしい言葉[ことば]の意味[いみ]を、やさしく説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "道がわからなくて、駅の人に説明をお願いしました。", "target_word": "説明", "complexity_tier": "T3", "furigana": "道[みち]がわからなくて、駅[えき]の人[ひと]に説明[せつめい]をお願[ねが]いしました。", "sentence_source": "generated"}, {"text": "説明を聞いたので、使い方がよくわかりました。", "target_word": "説明", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いたので、使[つか]い方[かた]がよくわかりました。", "sentence_source": "generated"}, {"text": "兄はゲームのルールを、私に二十分も説明した。", "target_word": "説明", "complexity_tier": "T3", "furigana": "兄[あに]はゲームのルールを、私[わたし]に二十分[にじゅっぷん]も説明[せつめい]した。", "sentence_source": "generated"}, {"text": "説明が早すぎて、ぜんぜんわかりませんでした。", "target_word": "説明", "complexity_tier": "T3", "furigana": "説明[せつめい]が早[はや]すぎて、ぜんぜんわかりませんでした。", "sentence_source": "generated"}, {"text": "母に遅れた理由を説明すると、母は笑って許してくれた。", "target_word": "説明", "complexity_tier": "T3", "furigana": "母[はは]に遅[おく]れた理由[りゆう]を説明[せつめい]すると、母[はは]は笑[わら]って許[ゆる]してくれた。", "sentence_source": "generated"}, {"text": "この絵について、ひとことで説明できますか。", "target_word": "説明", "complexity_tier": "T3", "furigana": "この絵[え]について、ひとことで説明[せつめい]できますか。", "sentence_source": "generated"}, {"text": "店の人が、新しい機械の動かし方を説明している。", "target_word": "説明", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]が、新[あたら]しい機械[きかい]の動[うご]かし方[かた]を説明[せつめい]している。", "sentence_source": "generated"}, {"text": "説明がじょうずな先生の授業は、とても人気がある。", "target_word": "説明", "complexity_tier": "T3", "furigana": "説明[せつめい]がじょうずな先生[せんせい]の授業[じゅぎょう]は、とても人気[にんき]がある。", "sentence_source": "generated"}, {"text": "わからないところは、もう一度説明してください。", "target_word": "説明", "complexity_tier": "T3", "furigana": "わからないところは、もう一度[いちど]説明[せつめい]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説明", "label": "基本形"}], "register": "中立（話し言葉・書き言葉どちらでも使う）", "sense_fingerprint": "相手がわかるように、ことばでやさしく話して伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説明", "is_correct": true, "explanation": "「やさしく〜してくれました」で、難しい言葉の意味を分かりやすく話す動作に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学ぶための本で、「やさしく〜してくれました」の動作にはならない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、動作を表す語として成立しない。"}, {"text": "花束", "is_correct": false, "explanation": "花束は贈る物で、言葉の意味を伝える動作の語にはならない。"}], "explanations": {"説明": "「やさしく〜してくれました」で、難しい言葉の意味を分かりやすく話す動作に合う。", "教科書": "教科書は学ぶための本で、「やさしく〜してくれました」の動作にはならない。", "天井": "天井は部屋の上の面で、動作を表す語として成立しない。", "花束": "花束は贈る物で、言葉の意味を伝える動作の語にはならない。"}, "sentence_index": 0, "correct_answer": "説明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は説明を、二十分も撮った。", "explanation": "説明は撮影の対象になるものではないので、撮る対象としては使えない。"}, {"text": "兄は説明を、私に二十分も歌った。", "explanation": "説明は歌うものではないので、歌う対象としては使えない。"}, {"text": "兄は説明を、私に二十分もかけた。", "explanation": "説明は相手にかけるものではないので、かける対象としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説明", "is_correct": true, "explanation": "絵について一言で述べる動作を表し、「ひとことで〜できますか」に合う。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は目に掛ける道具で、「ひとことで〜できますか」の動作の語にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、「ひとことで〜できますか」の動作にはならない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車や入場に使う券で、「ひとことで〜できますか」の動作に合わない。"}], "explanations": {"説明": "絵について一言で述べる動作を表し、「ひとことで〜できますか」に合う。", "眼鏡": "眼鏡は目に掛ける道具で、「ひとことで〜できますか」の動作の語にはならない。", "窓": "窓は建物の開口部で、「ひとことで〜できますか」の動作にはならない。", "切符": "切符は乗車や入場に使う券で、「ひとことで〜できますか」の動作に合わない。"}, "sentence_index": 6, "correct_answer": "説明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "わからない機械は、もう一度説明を押してください。", "explanation": "説明は押せるものではないので、押す対象としては使えない。"}, {"text": "暑いので、説明を開けてください。", "explanation": "説明は開けるものではないので、開ける対象としては使えない。"}, {"text": "合図の時は、説明を鳴らしてください。", "explanation": "説明は鳴らせるものではないので、鳴らす対象としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、新しい機械の使い方を生徒に説明がした。", "corrected_sentence": "先生は、新しい機械の使い方を生徒に説明をした。", "error_description": "「説明をする」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36748, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "わからない点は、先生に説明さてもらった。", "corrected_sentence": "わからない点は、先生に説明してもらった。", "error_description": "「説明して」の形を「説明さて」と誤っている。「説明してもらった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
