INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36749, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の内容や理由などを、相手によくわかるように述べること。", "primary_collocate": null, "pronunciation": "せつめい", "ipa": "setsɯmeː", "syllable_count": 4, "sentences": [{"text": "会社は、値上げをする理由を客に説明した。", "target_word": "説明", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、値上[ねあ]げをする理由[りゆう]を客[きゃく]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "事故の原因について、担当者が丁寧に説明した。", "target_word": "説明", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]について、担当者[たんとうしゃ]が丁寧[ていねい]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "十分な説明がなかったので、みんなが不安になった。", "target_word": "説明", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]な説明[せつめい]がなかったので、みんなが不安[ふあん]になった。", "sentence_source": "generated"}, {"text": "医者は、手術の内容を家族に説明した。", "target_word": "説明", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、手術[しゅじゅつ]の内容[ないよう]を家族[かぞく]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "彼は計画を説明するために、資料を用意した。", "target_word": "説明", "complexity_tier": "T3", "furigana": "彼[かれ]は計画[けいかく]を説明[せつめい]するために、資料[しりょう]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "市長は、新しい制度の目的を市民に説明する予定だ。", "target_word": "説明", "complexity_tier": "T3", "furigana": "市長[しちょう]は、新[あたら]しい制度[せいど]の目的[もくてき]を市民[しみん]に説明[せつめい]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "説明を求められても、彼は何も答えなかった。", "target_word": "説明", "complexity_tier": "T3", "furigana": "説明[せつめい]を求[もと]められても、彼[かれ]は何[なに]も答[こた]えなかった。", "sentence_source": "generated"}, {"text": "結果がちがった理由を、グラフを使って説明します。", "target_word": "説明", "complexity_tier": "T3", "furigana": "結果[けっか]がちがった理由[りゆう]を、グラフを使[つか]って説明[せつめい]します。", "sentence_source": "generated"}, {"text": "その説明は筋が通っていて、だれも反対しなかった。", "target_word": "説明", "complexity_tier": "T3", "furigana": "その説明[せつめい]は筋[すじ]が通[とお]っていて、だれも反対[はんたい]しなかった。", "sentence_source": "generated"}, {"text": "契約の条件は、契約前に必ず説明しなければならない。", "target_word": "説明", "complexity_tier": "T3", "furigana": "契約[けいやく]の条件[じょうけん]は、契約前[けいやくまえ]に必[かなら]ず説明[せつめい]しなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説明", "label": "基本形"}], "register": "やや改まった書き言葉・公的な場面", "sense_fingerprint": "物事の内容・理由・原因を、相手が納得できるように筋道立てて述べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説明", "is_correct": true, "explanation": "「理由を客に〜した」で、値上げの理由を述べて伝える動作に合う。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は目に掛ける道具で、理由を客に伝える動作の語として合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、「客に〜した」の動作として成立しない。"}, {"text": "花束", "is_correct": false, "explanation": "花束は贈り物で、理由を客に伝える動作の語にはならない。"}], "explanations": {"説明": "「理由を客に〜した」で、値上げの理由を述べて伝える動作に合う。", "眼鏡": "眼鏡は目に掛ける道具で、理由を客に伝える動作の語として合わない。", "天井": "天井は部屋の上の面で、「客に〜した」の動作として成立しない。", "花束": "花束は贈り物で、理由を客に伝える動作の語にはならない。"}, "sentence_index": 0, "correct_answer": "説明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医者は、患者に説明を打った。", "explanation": "説明は打つものではないので、打つ対象としては使えない。"}, {"text": "医者は、説明を開けた。", "explanation": "説明は開けるものではないので、開ける対象としては使えない。"}, {"text": "医者は、指に説明をはめた。", "explanation": "説明は身につけるものではないので、はめる対象としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説明", "is_correct": true, "explanation": "「〜を求められても」の対象になり、説明を求められても答えなかったという文に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、「〜を求められても」の対象にはならない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、「〜を求められても」の対象にはならない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は燃えて出るもので、「求められても答えなかった」の対象にはならない。"}], "explanations": {"説明": "「〜を求められても」の対象になり、説明を求められても答えなかったという文に合う。", "窓": "窓は建物の開口部で、「〜を求められても」の対象にはならない。", "天井": "天井は部屋の上の面で、「〜を求められても」の対象にはならない。", "煙": "煙は燃えて出るもので、「求められても答えなかった」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "説明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食後に説明を飲まなければならない。", "explanation": "説明は飲めるものではないので、飲む対象としては使えない。"}, {"text": "車は説明を守らなければならない。", "explanation": "説明は守るものではないので、守る対象としては使えない。"}, {"text": "彼は難しい説明に合格した。", "explanation": "説明は合否を判定されるものではないので、合格の対象としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店は、値上げの理由を客に説明された。", "corrected_sentence": "店は、値上げの理由を客に説明した。", "error_description": "主語の「店」が説明する側なので、受身の「説明された」は誤り。能動の「説明した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "契約の内容は、契約前に必ず説明すなければならない。", "corrected_sentence": "契約の内容は、契約前に必ず説明しなければならない。", "error_description": "「説明しなければ」の「し」が「す」になっている。サ変動詞は「説明し」と続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「二つに切る」の「に」で、切った結果の状態（二つ）を表し、この文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。紙は切られる対象なので、ここでは合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「二つと切る」では結果の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「二つへ切る」とは言わないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「二つに切る」の「に」で、切った結果の状態（二つ）を表し、この文に合う。", "が": "「が」は主語を示す。紙は切られる対象なので、ここでは合わない。", "と": "「と」は並列や相手を示す。「二つと切る」では結果の意味にならない。", "へ": "「へ」は方向を示す。「二つへ切る」とは言わないので合わない。"}, "error_tags": {"が": "主格", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「はさみで切る」の「で」で、道具（手段）を表し、この文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「はさみを切る」ではそのはさみ自体を切る意味になり、文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「はさみに切る」は道具を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。道具には使わないので合わない。"}], "correct_answer": "で", "explanations": {"で": "「はさみで切る」の「で」で、道具（手段）を表し、この文に合う。", "を": "「はさみを切る」ではそのはさみ自体を切る意味になり、文脈に合わない。", "に": "「はさみに切る」は道具を示せず、不自然。", "へ": "「へ」は方向を示す。道具には使わないので合わない。"}, "error_tags": {"を": "目的語", "に": "位置・結果", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを切ることは、はさみやナイフでものを二つに分けることです。", "primary_collocate": null, "pronunciation": "きる", "ipa": "kiɾɯ", "syllable_count": 2, "sentences": [{"text": "母は包丁で玉ねぎを細かく切ります。", "target_word": "切ります", "complexity_tier": "T3", "furigana": "母[はは]は包丁[ほうちょう]で玉[たま]ねぎを細[こま]かく切[き]ります。", "sentence_source": "generated"}, {"text": "はさみで紙を二つに切ってください。", "target_word": "切って", "complexity_tier": "T3", "furigana": "はさみで紙[かみ]を二[ふた]つに切[き]ってください。", "sentence_source": "generated"}, {"text": "誕生日のケーキをナイフで八つに切った。", "target_word": "切った", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]のケーキをナイフで八[やっ]つに切[き]った。", "sentence_source": "generated"}, {"text": "かたいパンは、ナイフで薄く切ってから焼くと、かりっとする。", "target_word": "切って", "complexity_tier": "T3", "furigana": "かたいパンは、ナイフで薄[うす]く切[き]ってから焼[や]くと、かりっとする。", "sentence_source": "generated"}, {"text": "髪が長くなったので、美容院で切ってもらった。", "target_word": "切って", "complexity_tier": "T3", "furigana": "髪[かみ]が長[なが]くなったので、美容院[びよういん]で切[き]ってもらった。", "sentence_source": "generated"}, {"text": "父は庭の枝をはさみで切って、花びんに入れた。", "target_word": "切って", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]の枝[えだ]をはさみで切[き]って、花[か]びんに入[い]れた。", "sentence_source": "generated"}, {"text": "パンは薄く切ると、サンドイッチに使いやすい。", "target_word": "切る", "complexity_tier": "T3", "furigana": "パンは薄[うす]く切[き]ると、サンドイッチに使[つか]いやすい。", "sentence_source": "generated"}, {"text": "紙のひもをはさみで切ると、箱が開いた。", "target_word": "切る", "complexity_tier": "T3", "furigana": "紙[かみ]のひもをはさみで切[き]ると、箱[はこ]が開[あ]いた。", "sentence_source": "generated"}, {"text": "きゅうりは、うすく丸く切ってサラダに入れます。", "target_word": "切って", "complexity_tier": "T3", "furigana": "きゅうりは、うすく丸[まる]く切[き]ってサラダに入[い]れます。", "sentence_source": "generated"}, {"text": "長いリボンを半分に切って、二人で分けた。", "target_word": "切って", "complexity_tier": "T3", "furigana": "長[なが]いリボンを半分[はんぶん]に切[き]って、二人[ふたり]で分[わ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切る", "label": "辞書形"}, {"form": "切ります", "label": "丁寧形"}, {"form": "切って", "label": "て形"}, {"form": "切った", "label": "た形"}, {"form": "切らない", "label": "ない形"}, {"form": "切れば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "はさみや刃物で物を切り分ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 花びん (Zipf 1.51)','sentence 8 above tier T2: contains vocabulary far above tier T2: うすく (Zipf 2.37)']::text[], 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切ります", "is_correct": true, "explanation": "包丁で玉ねぎを細かく分ける動作を表し、この文の動詞として正しい。"}, {"text": "洗います", "is_correct": false, "explanation": "「洗う」は水で汚れを落とす動作で、玉ねぎを細かくする文には合わない。"}, {"text": "捨てます", "is_correct": false, "explanation": "「捨てる」は不要なものを処分する意味で、細かく分ける文脈に合わない。"}, {"text": "注ぎます", "is_correct": false, "explanation": "「注ぐ」は液体を流し入れる意味で、固形の玉ねぎを細かくする文には合わない。"}], "explanations": {"切ります": "包丁で玉ねぎを細かく分ける動作を表し、この文の動詞として正しい。", "洗います": "「洗う」は水で汚れを落とす動作で、玉ねぎを細かくする文には合わない。", "捨てます": "「捨てる」は不要なものを処分する意味で、細かく分ける文脈に合わない。", "注ぎます": "「注ぐ」は液体を流し入れる意味で、固形の玉ねぎを細かくする文には合わない。"}, "sentence_index": 0, "correct_answer": "切ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポスターを切って、壁から外した。", "explanation": "この文の動作は〈はがす〉にあたり、「切る」とは言わないので合わない。"}, {"text": "朝ごはんに卵を切って、フライパンに落とした。", "explanation": "卵の殻を割る動作で、「切る」とは言わないので合わない。"}, {"text": "鉛筆を切って、先を尖らせた。", "explanation": "鉛筆の先を削る動作で、「切る」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切る", "is_correct": true, "explanation": "薄く切り分ける動作を表し、「と」の前に入って文が成り立つ。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、パンを薄くする文脈には合わない。"}, {"text": "捨てる", "is_correct": false, "explanation": "「捨てる」は処分する意味で、パンを薄くする動作を表さない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "「注ぐ」は液体を流し入れる意味で、固形のパンには合わない。"}], "explanations": {"切る": "薄く切り分ける動作を表し、「と」の前に入って文が成り立つ。", "洗う": "「洗う」は汚れを落とす動作で、パンを薄くする文脈には合わない。", "捨てる": "「捨てる」は処分する意味で、パンを薄くする動作を表さない。", "注ぐ": "「注ぐ」は液体を流し入れる意味で、固形のパンには合わない。"}, "sentence_index": 6, "correct_answer": "切る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氷を切って、ジュースに入れた。", "explanation": "氷を砕く動作で、「切る」とは言わないので合わない。"}, {"text": "庭の土を切って、花の苗を植えた。", "explanation": "土を掘る動作で、「切る」とは言わないので合わない。"}, {"text": "洗ったタオルを切って、よく乾かした。", "explanation": "水分を出す絞る動作で、「切る」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パンをナイフで薄く切りてから焼いた。", "corrected_sentence": "パンをナイフで薄く切ってから焼いた。", "error_description": "五段動詞「切る」のて形は「切って」。「切りて」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "切って", "is_correct": true, "explanation": "て形。「切ってください」で依頼の文になるので、この文に合う。"}, {"text": "切った", "is_correct": false, "explanation": "た形（過去）。「切ったください」とは続かず、依頼の形にならない。"}, {"text": "切らない", "is_correct": false, "explanation": "ない形。「切らないください」は依頼の形として成り立たない。"}, {"text": "切ります", "is_correct": false, "explanation": "丁寧形。「切りますください」とは続けられず、依頼文にならない。"}], "correct_form": "切って", "base_form": "切る", "form_label": "て形", "sentence_index": 1, "explanations": {"切って": "て形。「切ってください」で依頼の文になるので、この文に合う。", "切った": "た形（過去）。「切ったください」とは続かず、依頼の形にならない。", "切らない": "ない形。「切らないください」は依頼の形として成り立たない。", "切ります": "丁寧形。「切りますください」とは続けられず、依頼文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36750, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "野菜をナイフに切ります。", "corrected_sentence": "野菜をナイフで切ります。", "error_description": "道具を表す「で」が必要。「に」では手段の意味にならず、不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "切る", "is_correct": true, "explanation": "辞書形。「切ると」と続けて条件を表し、「箱が開いた」につながるので、ここに合う。"}, {"text": "切れ", "is_correct": false, "explanation": "命令形。「切れと」では文がつながらず、ここでは合わない。"}, {"text": "切り", "is_correct": false, "explanation": "連用形。「切りと」と助詞「と」に続けられず、ここでは合わない。"}, {"text": "切らず", "is_correct": false, "explanation": "否定の連用形。「切らずと」とは続かず、ここでは合わない。"}], "correct_form": "切る", "base_form": "切る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"切る": "辞書形。「切ると」と続けて条件を表し、「箱が開いた」につながるので、ここに合う。", "切れ": "命令形。「切れと」では文がつながらず、ここでは合わない。", "切り": "連用形。「切りと」と助詞「と」に続けられず、ここでは合わない。", "切らず": "否定の連用形。「切らずと」とは続かず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
