INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "脳の内部の温度。脳の活動や体の状態によって変わります。", "primary_collocate": null, "pronunciation": "のうおん", "ipa": "noːoɴ", "syllable_count": 4, "sentences": [{"text": "頭を使って考えると、脳温がわずかに上がる。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "頭[あたま]を使[つか]って考[かんが]えると、脳温[のうおん]がわずかに上[あ]がる。", "sentence_source": "generated"}, {"text": "熱中症になると、体温だけでなく脳温も危険なほど高くなる。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "熱中症[ねっちゅうしょう]になると、体温[たいおん]だけでなく脳温[のうおん]も危険[きけん]なほど高[たか]くなる。", "sentence_source": "generated"}, {"text": "脳温は脳の活動によって、一日の中でも少しずつ変わる。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "脳温[のうおん]は脳[のう]の活動[かつどう]によって、一日[いちにち]の中[なか]でも少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "睡眠中は活動が落ちるので、脳温も下がりやすい。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "睡眠中[すいみんちゅう]は活動[かつどう]が落[お]ちるので、脳温[のうおん]も下[さ]がりやすい。", "sentence_source": "generated"}, {"text": "研究者は、運動中の脳温の変化を調べた。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、運動中[うんどうちゅう]の脳温[のうおん]の変化[へんか]を調[しら]べた。", "sentence_source": "generated"}, {"text": "事故で意識を失った患者の脳温を、病院で慎重に管理した。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "事故[じこ]で意識[いしき]を失[うしな]った患者[かんじゃ]の脳温[のうおん]を、病院[びょういん]で慎重[しんちょう]に管理[かんり]した。", "sentence_source": "generated"}, {"text": "脳温が高い状態が続くと、脳の働きが悪くなることがある。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "脳温[のうおん]が高[たか]い状態[じょうたい]が続[つづ]くと、脳[のう]の働[はたら]きが悪[わる]くなることがある。", "sentence_source": "generated"}, {"text": "この帽子は頭を冷やして、脳温の上昇を防ぐ。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "この帽子[ぼうし]は頭[あたま]を冷[ひ]やして、脳温[のうおん]の上昇[じょうしょう]を防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "サウナに入ると体温が上がり、それに合わせて脳温も上がる。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "サウナに入[はい]ると体温[たいおん]が上[あ]がり、それに合[あ]わせて脳温[のうおん]も上[あ]がる。", "sentence_source": "generated"}, {"text": "動物の脳温を測るには、小さなセンサーを頭の中に埋め込む必要がある。", "target_word": "脳温", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の脳温[のうおん]を測[はか]るには、小[ちい]さなセンサーを頭[あたま]の中[なか]に埋[う]め込[こ]む必要[ひつよう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脳温", "label": "基本形"}], "register": "technical", "sense_fingerprint": "脳の内部の温度。脳の活動や体の状態で変化する数値。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脳温", "is_correct": true, "explanation": "頭を使うと脳の温度がわずかに上がるという文に合う。"}, {"text": "脳細胞", "is_correct": false, "explanation": "脳を作る細胞の名前。「脳細胞がわずかに上がる」とは言わない。"}, {"text": "脳回", "is_correct": false, "explanation": "大脳表面の盛り上がりの名前。温度を表さないので合わない。"}, {"text": "脳幹", "is_correct": false, "explanation": "脳の部位の名前。温度として上がるとは言わないので文が成り立たない。"}], "explanations": {"脳温": "頭を使うと脳の温度がわずかに上がるという文に合う。", "脳細胞": "脳を作る細胞の名前。「脳細胞がわずかに上がる」とは言わない。", "脳回": "大脳表面の盛り上がりの名前。温度を表さないので合わない。", "脳幹": "脳の部位の名前。温度として上がるとは言わないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "脳温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は脳温が低いので、薄着では寒い。", "explanation": "ここは〈外気温〉の意味。外の空気の寒さを言う文で、脳の内部の温度である脳温とは合わない。"}, {"text": "湿気が多い日は、脳温が実際より高く感じる。", "explanation": "ここは〈体感温度〉の意味。皮膚で感じる暑さを指し、脳の内部の温度を表す脳温とは別物。"}, {"text": "冬の湖は脳温が低く、魚はあまり動かない。", "explanation": "ここは〈水温〉の意味。水の温度の話で、脳の中の温度ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脳温", "is_correct": true, "explanation": "脳の温度が高い状態が続くという文に合い、脳の働きの話とつながる。"}, {"text": "脳梁", "is_correct": false, "explanation": "左右の大脳をつなぐ部分の名前。「脳梁が高い状態」とは言わない。"}, {"text": "脳室", "is_correct": false, "explanation": "脳の中の空洞の名前。「脳室が高い状態」は意味が通らない。"}, {"text": "脳神経", "is_correct": false, "explanation": "脳から出る神経の総称。温度として高い状態になるとは言えない。"}], "explanations": {"脳温": "脳の温度が高い状態が続くという文に合い、脳の働きの話とつながる。", "脳梁": "左右の大脳をつなぐ部分の名前。「脳梁が高い状態」とは言わない。", "脳室": "脳の中の空洞の名前。「脳室が高い状態」は意味が通らない。", "脳神経": "脳から出る神経の総称。温度として高い状態になるとは言えない。"}, "sentence_index": 6, "correct_answer": "脳温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "脳温は脇の下に計器を挟んで測る。", "explanation": "ここは〈体温〉の意味。脇の下で測るのは体温で、脳の内部の温度である脳温は脇では測れない。"}, {"text": "運動のあと、脳温を指で数えたら一分間に百回だった。", "explanation": "ここは〈脈拍〉の意味。一分間に何回と数えるのは脈拍のことで、脳の内部の温度である脳温は数えない。"}, {"text": "彼は仕事への脳温が高く、毎日遅くまで残る。", "explanation": "ここは〈熱意〉の意味。仕事へのやる気の強さを表す語で、脳の温度を指す脳温は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱いお湯につかると、脳温が一時的に上げる。", "corrected_sentence": "熱いお湯につかると、脳温が一時的に上がる。", "error_description": "「上がる」が正しい。「上げる」は他動詞なので、「脳温が」を主語にすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると、脳温で少しずつ下がる。", "corrected_sentence": "夜になると、脳温が少しずつ下がる。", "error_description": "「脳温が」が正しい。「で」は手段や場所を示すので、「下がる」の主語としては合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「連帯の気持ち」と名詞を修飾する形。ここでは「連帯（の）気持ち」で文が成立する。"}, {"text": "が", "is_correct": false, "explanation": "「連帯が気持ちが強い」となり、主語が二つ並んで文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「連帯を気持ちが」では目的語を置く場所がなく、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「連帯に気持ち」では相手や到達点の意味になり、「気持ちが強い」につながらない。"}], "correct_answer": "の", "explanations": {"の": "「連帯の気持ち」と名詞を修飾する形。ここでは「連帯（の）気持ち」で文が成立する。", "が": "「連帯が気持ちが強い」となり、主語が二つ並んで文が成り立たない。", "を": "「連帯を気持ちが」では目的語を置く場所がなく、文が成り立たない。", "に": "「連帯に気持ち」では相手や到達点の意味になり、「気持ちが強い」につながらない。"}, "error_tags": {"が": "主語（〜が）", "を": "目的語（〜を）", "に": "相手・到達点（〜に）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「連帯を深める」で、深める対象（目的語）を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「連帯へ深める」は方向の意味になり、「深める」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「連帯の深める」は名詞修飾の形になり、「深める」の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「連帯より深める」は比較の意味になり、「深めるため」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「連帯を深める」で、深める対象（目的語）を示す。", "へ": "「連帯へ深める」は方向の意味になり、「深める」の目的語にならない。", "の": "「連帯の深める」は名詞修飾の形になり、「深める」の目的語にならない。", "より": "「連帯より深める」は比較の意味になり、「深めるため」の目的語にならない。"}, "error_tags": {"へ": "方向（〜へ）", "より": "比較（〜より）", "の": "連体修飾（〜の）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人が助け合うこと。", "primary_collocate": null, "pronunciation": "れんたい", "ipa": "ɾeɴtai", "syllable_count": 4, "sentences": [{"text": "地震のあと、町の人たちの連帯が復興を支えた。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、町[まち]の人[ひと]たちの連帯[れんたい]が復興[ふっこう]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "連帯の気持ちが強いクラスは、行事で力を出せる。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "連帯[れんたい]の気持[きも]ちが強[つよ]いクラスは、行事[ぎょうじ]で力[ちから]を出[だ]せる。", "sentence_source": "generated"}, {"text": "世界の人々が連帯して、困っている国を助けた。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "世界[せかい]の人々[ひとびと]が連帯[れんたい]して、困[こま]っている国[くに]を助[たす]けた。", "sentence_source": "generated"}, {"text": "私たちは、みんなの連帯を大切にしたい。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "私[わたし]たちは、みんなの連帯[れんたい]を大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "連帯がなければ、こんなに大きな仕事は終わらなかっただろう。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "連帯[れんたい]がなければ、こんなに大[おお]きな仕事[しごと]は終[お]わらなかっただろう。", "sentence_source": "generated"}, {"text": "災害の現場では、知らない人どうしの連帯が生まれた。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "災害[さいがい]の現場[げんば]では、知[し]らない人[ひと]どうしの連帯[れんたい]が生[う]まれた。", "sentence_source": "generated"}, {"text": "村の人々は連帯して、川のそうじを続けている。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "村[むら]の人々[ひとびと]は連帯[れんたい]して、川[かわ]のそうじを続[つづ]けている。", "sentence_source": "generated"}, {"text": "連帯を深めるため、毎年みんなで祭りを開く。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "連帯[れんたい]を深[ふか]めるため、毎年[まいとし]みんなで祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}, {"text": "仲間との連帯を感じて、彼女はもう一度がんばろうと思った。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "仲間[なかま]との連帯[れんたい]を感[かん]じて、彼女[かのじょ]はもう一度[いちど]がんばろうと思[おも]った。", "sentence_source": "generated"}, {"text": "国をこえた連帯の輪が、少しずつ広がっている。", "target_word": "連帯", "complexity_tier": "T3", "furigana": "国[くに]をこえた連帯[れんたい]の輪[わ]が、少[すこ]しずつ広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連帯する", "label": "基本形"}, {"form": "連帯して", "label": "て形"}, {"form": "連帯した", "label": "過去形"}, {"form": "連帯しない", "label": "否定形"}], "register": "中立（やや書き言葉）", "sense_fingerprint": "多くの人が気持ちをひとつにして、たがいに助け合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連帯", "is_correct": true, "explanation": "助け合う人々のつながりを表し、「町の人たちの〜が復興を支えた」の主語として合う。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まることを指す。町の人たちの停電が復興を支えたという文にはならない。"}, {"text": "騒音", "is_correct": false, "explanation": "うるさい音を指す。人々の騒音が復興を支えるという文は意味が通らない。"}, {"text": "設計", "is_correct": false, "explanation": "建物などの計画を指す。町の人たちの設計が復興を支えるという文にはならない。"}], "explanations": {"連帯": "助け合う人々のつながりを表し、「町の人たちの〜が復興を支えた」の主語として合う。", "停電": "電気が止まることを指す。町の人たちの停電が復興を支えたという文にはならない。", "騒音": "うるさい音を指す。人々の騒音が復興を支えるという文は意味が通らない。", "設計": "建物などの計画を指す。町の人たちの設計が復興を支えるという文にはならない。"}, "sentence_index": 0, "correct_answer": "連帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゲームで、ボタンを連帯して押した。", "explanation": "ここは〈連打〉の意味。同じ動作を速く何度も続けることで、人々が支え合う連帯とは違う。"}, {"text": "隣の家の人が、雪かきに連帯してくれた。", "explanation": "ここは〈協力〉の意味。連帯は多くの人が気持ちをひとつにして支え合うことで、一人の手伝いには使わない。"}, {"text": "宿題を連帯して三人で分けた。", "explanation": "ここは〈分担〉の意味。連帯は気持ちを寄せ合うことで、仕事や宿題を分ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連帯", "is_correct": true, "explanation": "助け合う村人の結びつきを表し、「川のそうじを続けている」と意味が合う。"}, {"text": "漏水", "is_correct": false, "explanation": "水が漏れることを指す。村の人々が〜して川のそうじを続けるという文には入らない。"}, {"text": "落雷", "is_correct": false, "explanation": "雷が落ちることを指す。村の人々の行動を表す「〜して」の部分に合わない。"}, {"text": "年表", "is_correct": false, "explanation": "年代順の記録を指す。村の人々が年表してそうじを続けるという文は意味が通らない。"}], "explanations": {"連帯": "助け合う村人の結びつきを表し、「川のそうじを続けている」と意味が合う。", "漏水": "水が漏れることを指す。村の人々が〜して川のそうじを続けるという文には入らない。", "落雷": "雷が落ちることを指す。村の人々の行動を表す「〜して」の部分に合わない。", "年表": "年代順の記録を指す。村の人々が年表してそうじを続けるという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "連帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ひとつの事故が連帯して、道路全体が止まった。", "explanation": "ここは〈連鎖〉の意味。連鎖は出来事が次々とつながることで、人々が立場をこえて支え合う連帯とは違う。"}, {"text": "今年は連帯を取って、家族で旅行した。", "explanation": "ここは〈連休〉の意味。続けて取れる休みのことで、人々が支え合う連帯とは違う。"}, {"text": "二つの車両を連帯して、一本の列車にした。", "explanation": "ここは〈連結〉の意味。車両などをつなぐことで、人々が支え合う連帯とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあと、村の人たちを連帯が復旧を支えた。", "corrected_sentence": "大雨のあと、村の人たちの連帯が復旧を支えた。", "error_description": "「村の人たちの連帯」と「の」でつなぐ。「を」にすると「人たちを」が目的語になり、「連帯が」との関係が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲間との連帯に保つため、毎週集まりを開いている。", "corrected_sentence": "仲間との連帯を保つため、毎週集まりを開いている。", "error_description": "「保つ」は「〜を保つ」と目的語に「を」をとる。「連帯に」とすると「保つ」の目的語が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「住民の連帯が行政を動かした」で、行政を動かした主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「連帯を行政を動かした」では目的語が二つになり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「連帯の行政を動かした」では連帯が行政を修飾する形になり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「連帯に行政を動かした」では連帯が相手や到達点となり、動かす主語が立たない。"}], "correct_answer": "が", "explanations": {"が": "「住民の連帯が行政を動かした」で、行政を動かした主語を示す。", "を": "「連帯を行政を動かした」では目的語が二つになり、文が成り立たない。", "の": "「連帯の行政を動かした」では連帯が行政を修飾する形になり、意味が通らない。", "に": "「連帯に行政を動かした」では連帯が相手や到達点となり、動かす主語が立たない。"}, "error_tags": {"を": "目的語（〜を）", "の": "連体修飾（〜の）", "に": "相手・到達点（〜に）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「連帯を呼びかける」で、呼びかける対象（目的語）を示す。"}, {"text": "から", "is_correct": false, "explanation": "「連帯から呼びかける」は起点の意味になり、文の目的が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「連帯の呼びかける」は名詞修飾の形になり、「呼びかける」の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「連帯より呼びかける」は比較の意味になり、この文では通らない。"}], "correct_answer": "を", "explanations": {"を": "「連帯を呼びかける」で、呼びかける対象（目的語）を示す。", "から": "「連帯から呼びかける」は起点の意味になり、文の目的が成立しない。", "の": "「連帯の呼びかける」は名詞修飾の形になり、「呼びかける」の目的語にならない。", "より": "「連帯より呼びかける」は比較の意味になり、この文では通らない。"}, "error_tags": {"から": "起点（〜から）", "より": "比較（〜より）", "の": "連体修飾（〜の）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "互いに助け合い、協力すること。特に、社会や集団の中で結束を強め、共に支え合うこと。", "primary_collocate": null, "pronunciation": "れんたい", "ipa": "ɾeɴtai", "syllable_count": 4, "sentences": [{"text": "労働者は連帯して、賃金の引き上げを求めた。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "労働者[ろうどうしゃ]は連帯[れんたい]して、賃金[ちんぎん]の引[ひ]き上[あ]げを求[もと]めた。", "sentence_source": "generated"}, {"text": "被害を受けた住民の連帯が、行政を動かした。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "被害[ひがい]を受[う]けた住民[じゅうみん]の連帯[れんたい]が、行政[ぎょうせい]を動[うご]かした。", "sentence_source": "generated"}, {"text": "市民の連帯を強めるために、地域の集会が開かれた。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "市民[しみん]の連帯[れんたい]を強[つよ]めるために、地域[ちいき]の集会[しゅうかい]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "国際社会の連帯なしに、この問題は解決できない。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "国際社会[こくさいしゃかい]の連帯[れんたい]なしに、この問題[もんだい]は解決[かいけつ]できない。", "sentence_source": "generated"}, {"text": "組合は、他の企業の労働者との連帯を表明した。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "組合[くみあい]は、他[ほか]の企業[きぎょう]の労働者[ろうどうしゃ]との連帯[れんたい]を表明[ひょうめい]した。", "sentence_source": "generated"}, {"text": "厳しい状況でも、人々の連帯は失われなかった。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "厳[きび]しい状況[じょうきょう]でも、人々[ひとびと]の連帯[れんたい]は失[うしな]われなかった。", "sentence_source": "generated"}, {"text": "彼女は、弱い立場の人々と連帯する道を選んだ。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は、弱[よわ]い立場[たちば]の人々[ひとびと]と連帯[れんたい]する道[みち]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "連帯を呼びかける声明が、各国の団体から出された。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "連帯[れんたい]を呼[よ]びかける声明[せいめい]が、各国[かっこく]の団体[だんたい]から出[だ]された。", "sentence_source": "generated"}, {"text": "社会の分断が進む中で、連帯の重要性が見直されている。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "社会[しゃかい]の分断[ぶんだん]が進[すす]む中[なか]で、連帯[れんたい]の重要性[じゅうようせい]が見直[みなお]されている。", "sentence_source": "generated"}, {"text": "学生たちは、被災地への連帯を示す募金活動を始めた。", "target_word": "連帯", "complexity_tier": "T4", "furigana": "学生[がくせい]たちは、被災地[ひさいち]への連帯[れんたい]を示[しめ]す募金活動[ぼきんかつどう]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連帯する", "label": "基本形"}, {"form": "連帯して", "label": "て形"}, {"form": "連帯した", "label": "過去形"}, {"form": "連帯しない", "label": "否定形"}], "register": "改まった書き言葉・社会問題や報道の文脈", "sense_fingerprint": "社会や集団の中で結束を強め、立場をこえて共に支え合い行動すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連帯", "is_correct": true, "explanation": "立場をこえて共に行動する意味で、労働者が賃金の引き上げを求める文に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことを指す。労働者が採掘して賃金を求める文には入らない。"}, {"text": "解雇", "is_correct": false, "explanation": "従業員を辞めさせることを指す。労働者が解雇して賃金を求めるという行動とは合わない。"}, {"text": "放牧", "is_correct": false, "explanation": "家畜を放して飼うことを指す。労働者が放牧して賃金を求める文には入らない。"}], "explanations": {"連帯": "立場をこえて共に行動する意味で、労働者が賃金の引き上げを求める文に合う。", "採掘": "地下の資源を掘り出すことを指す。労働者が採掘して賃金を求める文には入らない。", "解雇": "従業員を辞めさせることを指す。労働者が解雇して賃金を求めるという行動とは合わない。", "放牧": "家畜を放して飼うことを指す。労働者が放牧して賃金を求める文には入らない。"}, "sentence_index": 0, "correct_answer": "連帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警官は、銃を連帯して撃った。", "explanation": "ここは〈連発〉の意味。同じ動作を続けて行うことで、支え合う連帯とは違う。"}, {"text": "隣の人が引っ越しの荷物を運ぶのに連帯してくれた。", "explanation": "ここは〈協力〉の意味。連帯は集団が立場をこえて共に行動することで、一人の手伝いには使わない。"}, {"text": "作業を連帯して三人で分けた。", "explanation": "ここは〈分担〉の意味。連帯は共に支え合い行動することで、仕事を分ける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連帯", "is_correct": true, "explanation": "立場の異なる人々と支え合うことを表し、「弱い立場の人々と〜する道」に合う。"}, {"text": "施錠", "is_correct": false, "explanation": "戸や扉に鍵をかけることを指す。弱い立場の人々と施錠する道という文にはならない。"}, {"text": "濃縮", "is_correct": false, "explanation": "液体などを濃くすることを指す。人々と濃縮する道という意味にならない。"}, {"text": "謄写", "is_correct": false, "explanation": "文書を写し取ることを指す。人々と謄写する道という意味にならない。"}], "explanations": {"連帯": "立場の異なる人々と支え合うことを表し、「弱い立場の人々と〜する道」に合う。", "施錠": "戸や扉に鍵をかけることを指す。弱い立場の人々と施錠する道という文にはならない。", "濃縮": "液体などを濃くすることを指す。人々と濃縮する道という意味にならない。", "謄写": "文書を写し取ることを指す。人々と謄写する道という意味にならない。"}, "sentence_index": 6, "correct_answer": "連帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の被害が連帯して、周辺の道路まで広がった。", "explanation": "ここは〈連鎖〉の意味。被害が次々とつながって広がる意味で、人々が立場をこえて支え合う連帯とは違う。"}, {"text": "警察は町の出入りを連帯して監視している。", "explanation": "ここは〈監視〉の意味。見張る行為を表す語で、共に支え合う連帯の意味では使わない。"}, {"text": "彼は一人で連帯して、新しい家を建てた。", "explanation": "ここは〈単独〉の意味。ひとりで行う様子を表し、集団が支え合う連帯の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生たちは連帯しく、寮の改善を求めた。", "corrected_sentence": "学生たちは連帯して、寮の改善を求めた。", "error_description": "正しいて形は「連帯して」。「連帯しく」は活用の誤りで、「して」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他の地域との連帯に強めようと、会議を開いた。", "corrected_sentence": "他の地域との連帯を強めようと、会議を開いた。", "error_description": "「強める」は「〜を強める」と目的語に「を」をとる。「連帯に」とすると「強める」の目的語が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「成長を促進する」で、促進する対象を示す。"}, {"text": "の", "is_correct": false, "explanation": "「成長の促進する」となり、促進する対象の形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「成長に促進する」は相手や到達点を示し、促進の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「成長で促進する」は手段の意味になり、野菜の成長を促す文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「成長を促進する」で、促進する対象を示す。", "の": "「成長の促進する」となり、促進する対象の形にならない。", "に": "「成長に促進する」は相手や到達点を示し、促進の対象にならない。", "で": "「成長で促進する」は手段の意味になり、野菜の成長を促す文として不自然。"}, "error_tags": {"の": "連体修飾（〜の）", "に": "相手・到達点（〜に）", "で": "手段（〜で）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抑制", "is_correct": true, "explanation": "進みや働きを押さえる意味で、促進と反対の関係にある。"}, {"text": "維持", "is_correct": false, "explanation": "同じ状態を保つことを指す。進める・押さえるという対の関係にはない。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残しておくことを指す。促進の反対語ではない。"}, {"text": "継承", "is_correct": false, "explanation": "受け継ぐことを指す。促進と対になる語ではない。"}], "correct_answer": "抑制", "explanations": {"抑制": "進みや働きを押さえる意味で、促進と反対の関係にある。", "維持": "同じ状態を保つことを指す。進める・押さえるという対の関係にはない。", "保存": "そのまま残しておくことを指す。促進の反対語ではない。", "継承": "受け継ぐことを指す。促進と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「花が咲くのを促進する」で、促進する対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「咲くのへ促進する」は方向を示し、促進の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「咲くから促進する」は理由の意味になり、「咲くのを促進する」の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「咲くより促進する」は比較の意味になり、文が通らない。"}], "correct_answer": "を", "explanations": {"を": "「花が咲くのを促進する」で、促進する対象を示す。", "へ": "「咲くのへ促進する」は方向を示し、促進の対象にならない。", "から": "「咲くから促進する」は理由の意味になり、「咲くのを促進する」の対象を示せない。", "より": "「咲くより促進する」は比較の意味になり、文が通らない。"}, "error_tags": {"へ": "方向（〜へ）", "から": "起点・理由（〜から）", "より": "比較（〜より）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抑制", "is_correct": true, "explanation": "進みや働きを押さえる意味で、促進と反対の関係にある。"}, {"text": "製造", "is_correct": false, "explanation": "ものを作り出すことを指す。促進の対義語ではない。"}, {"text": "測定", "is_correct": false, "explanation": "数や量をはかることを指す。促進の対義語ではない。"}, {"text": "延長", "is_correct": false, "explanation": "長くすることを指す。進みを押さえる反対の関係にはない。"}], "correct_answer": "抑制", "explanations": {"抑制": "進みや働きを押さえる意味で、促進と反対の関係にある。", "製造": "ものを作り出すことを指す。促進の対義語ではない。", "測定": "数や量をはかることを指す。促進の対義語ではない。", "延長": "長くすることを指す。進みを押さえる反対の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを速く進めること。", "primary_collocate": null, "pronunciation": "そくしん", "ipa": "sokɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "工事の促進のために、働く人の数を増やした。", "target_word": "促進", "complexity_tier": "T3", "furigana": "工事[こうじ]の促進[そくしん]のために、働[はたら]く人[ひと]の数[かず]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "肥料は、野菜の成長を促進する。", "target_word": "促進", "complexity_tier": "T3", "furigana": "肥料[ひりょう]は、野菜[やさい]の成長[せいちょう]を促進[そくしん]する。", "sentence_source": "generated"}, {"text": "水をたくさん飲むと、体の血の流れが促進される。", "target_word": "促進", "complexity_tier": "T3", "furigana": "水[みず]をたくさん飲[の]むと、体[からだ]の血[ち]の流[なが]れが促進[そくしん]される。", "sentence_source": "generated"}, {"text": "運動は食べ物の消化を促進するといわれている。", "target_word": "促進", "complexity_tier": "T3", "furigana": "運動[うんどう]は食[た]べ物[もの]の消化[しょうか]を促進[そくしん]するといわれている。", "sentence_source": "generated"}, {"text": "作業を促進するため、新しい機械を入れた。", "target_word": "促進", "complexity_tier": "T3", "furigana": "作業[さぎょう]を促進[そくしん]するため、新[あたら]しい機械[きかい]を入[い]れた。", "sentence_source": "generated"}, {"text": "熱を加えると、化学の反応が促進される。", "target_word": "促進", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えると、化学[かがく]の反応[はんのう]が促進[そくしん]される。", "sentence_source": "generated"}, {"text": "計画を促進したいなら、もっと人手が必要だ。", "target_word": "促進", "complexity_tier": "T3", "furigana": "計画[けいかく]を促進[そくしん]したいなら、もっと人手[ひとで]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "日光は、花が咲くのを促進する。", "target_word": "促進", "complexity_tier": "T3", "furigana": "日光[にっこう]は、花[はな]が咲[さ]くのを促進[そくしん]する。", "sentence_source": "generated"}, {"text": "工場は、生産の促進をねらって夜も動いている。", "target_word": "促進", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、生産[せいさん]の促進[そくしん]をねらって夜[よる]も動[うご]いている。", "sentence_source": "generated"}, {"text": "薬を使って、傷が治るのを促進した。", "target_word": "促進", "complexity_tier": "T3", "furigana": "薬[くすり]を使[つか]って、傷[きず]が治[なお]るのを促進[そくしん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "促進する", "label": "基本形"}, {"form": "促進して", "label": "て形"}, {"form": "促進した", "label": "過去形"}, {"form": "促進される", "label": "受身形"}, {"form": "促進しない", "label": "否定形"}], "register": "中立（やや書き言葉）", "sense_fingerprint": "作業や成長、体の働きなどを、はやく進むようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促進", "is_correct": true, "explanation": "工事を早く進める意味で、「工事の〜のために」に入って文が成り立つ。"}, {"text": "冷却", "is_correct": false, "explanation": "冷やすことを指す。工事の冷却のために働く人を増やす文は通らない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替えることを指す。工事の換気のために人数を増やす文は意味が合わない。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物の働きで物質が変わることを指す。工事の発酵のために人数を増やす文は合わない。"}], "explanations": {"促進": "工事を早く進める意味で、「工事の〜のために」に入って文が成り立つ。", "冷却": "冷やすことを指す。工事の冷却のために働く人を増やす文は通らない。", "換気": "空気を入れ替えることを指す。工事の換気のために人数を増やす文は意味が合わない。", "発酵": "微生物の働きで物質が変わることを指す。工事の発酵のために人数を増やす文は合わない。"}, "sentence_index": 0, "correct_answer": "促進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バスは坂道で一気に促進した。", "explanation": "ここは〈加速〉の意味。加速は速度が増すことで、促進は物事の進みを促す意味なので、乗り物の速さには使わない。"}, {"text": "先生は生徒に、質問するよう促進した。", "explanation": "ここは〈促す〉の意味。促すは人に行動をうながすことで、促進は物事の進みに使い、人に対しては使わない。"}, {"text": "友人の悩みを促進した。", "explanation": "ここは〈解消〉の意味。悩みを取り除く意味で、促進は作業や成長などの進みを速める意味なので、悩みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促進", "is_correct": true, "explanation": "計画を進みやすくする意味で、「計画を〜したいなら」に合う。"}, {"text": "散布", "is_correct": false, "explanation": "まき散らすことを指す。計画を散布したいという文にはならない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分をなくすことを指す。計画を乾燥したいという文は意味が通らない。"}, {"text": "結露", "is_correct": false, "explanation": "水蒸気が冷えて水になることを指す。計画には使えない。"}], "explanations": {"促進": "計画を進みやすくする意味で、「計画を〜したいなら」に合う。", "散布": "まき散らすことを指す。計画を散布したいという文にはならない。", "乾燥": "水分をなくすことを指す。計画を乾燥したいという文は意味が通らない。", "結露": "水蒸気が冷えて水になることを指す。計画には使えない。"}, "sentence_index": 6, "correct_answer": "促進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "薬を使って、痛みを促進した。", "explanation": "ここは〈抑える〉の意味。抑えるは痛みを弱めることで、促進は物事を速く進める意味なので、痛みには使わない。"}, {"text": "作業時間を促進した。", "explanation": "ここは〈短縮〉の意味。短縮は時間を短くすることで、促進は作業の進みを速める意味で、時間そのものには使わない。"}, {"text": "客を出口へ促進した。", "explanation": "ここは〈誘導〉の意味。誘導は人を案内することで、促進は人ではなく物事の進みに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は、生産を促進のために、夜間の作業を増やした。", "corrected_sentence": "会社は、生産の促進のために、夜間の作業を増やした。", "error_description": "「生産の促進」と「の」でつなぐ。「を」を入れると「生産を」が促進の前に不自然に置かれ、名詞の並びが成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "温かいお風呂は、血の流れを促進で、疲れを取る。", "corrected_sentence": "温かいお風呂は、血の流れを促進して、疲れを取る。", "error_description": "「促進」は「〜する」の名詞なので、続けるには「して」が必要。「で」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
