INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36757, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の進行や発展を促し、進みやすくすること。", "primary_collocate": null, "pronunciation": "そくしん", "ipa": "sokɯɕiɴ", "syllable_count": 4, "sentences": [{"text": "政府は、観光の促進に力を入れている。", "target_word": "促進", "complexity_tier": "T4", "furigana": "政府[せいふ]は、観光[かんこう]の促進[そくしん]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "町は、地元の産業の発展を促進する政策を決めた。", "target_word": "促進", "complexity_tier": "T4", "furigana": "町[まち]は、地元[じもと]の産業[さんぎょう]の発展[はってん]を促進[そくしん]する政策[せいさく]を決[き]めた。", "sentence_source": "generated"}, {"text": "国際交流を促進するために、留学の制度を作った。", "target_word": "促進", "complexity_tier": "T4", "furigana": "国際交流[こくさいこうりゅう]を促進[そくしん]するために、留学[りゅうがく]の制度[せいど]を作[つく]った。", "sentence_source": "generated"}, {"text": "この法律は、再生可能エネルギーの利用を促進する。", "target_word": "促進", "complexity_tier": "T4", "furigana": "この法律[ほうりつ]は、再生可能[さいせいかのう]エネルギーの利用[りよう]を促進[そくしん]する。", "sentence_source": "generated"}, {"text": "読書の促進を目的に、図書館がイベントを開いた。", "target_word": "促進", "complexity_tier": "T4", "furigana": "読書[どくしょ]の促進[そくしん]を目的[もくてき]に、図書館[としょかん]がイベントを開[ひら]いた。", "sentence_source": "generated"}, {"text": "会社は、新しい商品の普及を促進するため、無料で配った。", "target_word": "促進", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、新[あたら]しい商品[しょうひん]の普及[ふきゅう]を促進[そくしん]するため、無料[むりょう]で配[くば]った。", "sentence_source": "generated"}, {"text": "研究者どうしの協力を促進する場として、会議が開かれた。", "target_word": "促進", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]どうしの協力[きょうりょく]を促進[そくしん]する場[ば]として、会議[かいぎ]が開[ひら]かれた。", "sentence_source": "generated"}, {"text": "健康づくりを促進する活動に、多くの市民が参加した。", "target_word": "促進", "complexity_tier": "T4", "furigana": "健康[けんこう]づくりを促進[そくしん]する活動[かつどう]に、多[おお]くの市民[しみん]が参加[さんか]した。", "sentence_source": "generated"}, {"text": "国は、働く女性の活躍を促進したいと考えている。", "target_word": "促進", "complexity_tier": "T4", "furigana": "国[くに]は、働[はたら]く女性[じょせい]の活躍[かつやく]を促進[そくしん]したいと考えている。", "sentence_source": "generated"}, {"text": "地域の活性化を促進するには、住民の協力が欠かせない。", "target_word": "促進", "complexity_tier": "T4", "furigana": "地域[ちいき]の活性化[かっせいか]を促進[そくしん]するには、住民[じゅうみん]の協力[きょうりょく]が欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "促進する", "label": "基本形"}, {"form": "促進して", "label": "て形"}, {"form": "促進した", "label": "過去形"}, {"form": "促進される", "label": "受身形"}, {"form": "促進しない", "label": "否定形"}], "register": "改まった書き言葉・政策や報道の文脈", "sense_fingerprint": "政策や活動などで、物事の発展や普及が進みやすいように働きかけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1539784a-cc1e-44b9-8a57-75ead9062576') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "促進", "is_correct": true, "explanation": "物事を進みやすくする意味で、「観光の〜に力を入れている」に合う。"}, {"text": "漏電", "is_correct": false, "explanation": "電気が漏れることを指す。観光の漏電に力を入れる文は通らない。"}, {"text": "調律", "is_correct": false, "explanation": "楽器の音を整えることを指す。観光の調律に力を入れる文には入らない。"}, {"text": "煙害", "is_correct": false, "explanation": "煙による被害を指す。観光の煙害に力を入れる文は意味が合わない。"}], "explanations": {"促進": "物事を進みやすくする意味で、「観光の〜に力を入れている」に合う。", "漏電": "電気が漏れることを指す。観光の漏電に力を入れる文は通らない。", "調律": "楽器の音を整えることを指す。観光の調律に力を入れる文には入らない。", "煙害": "煙による被害を指す。観光の煙害に力を入れる文は意味が合わない。"}, "sentence_index": 0, "correct_answer": "促進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この条例は、夜間の騒音を促進する。", "explanation": "ここは〈規制〉の意味。規制は取り締まって制限することで、促進は物事を進みやすくする意味。騒音には使わない。"}, {"text": "市は、補助金の期間を促進した。", "explanation": "ここは〈延長〉の意味。延長は期間を長くすることで、促進は進みを速める意味なので、期間には使わない。"}, {"text": "町は、ごみの量を促進する計画を立てた。", "explanation": "ここは〈削減〉の意味。削減は量を減らすことで、促進は進みを速める意味なので、量を減らす計画には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "促進", "is_correct": true, "explanation": "協力を進みやすくする意味で、「協力を〜する場」に入る。"}, {"text": "漏洩", "is_correct": false, "explanation": "秘密や情報がもれることを指す。協力を漏洩する場という文は意味が通らない。"}, {"text": "仮眠", "is_correct": false, "explanation": "短く眠ることを指す。協力を仮眠する場という文にはならない。"}, {"text": "点滅", "is_correct": false, "explanation": "点いたり消えたりすることを指す。協力を点滅する場という文は通らない。"}], "explanations": {"促進": "協力を進みやすくする意味で、「協力を〜する場」に入る。", "漏洩": "秘密や情報がもれることを指す。協力を漏洩する場という文は意味が通らない。", "仮眠": "短く眠ることを指す。協力を仮眠する場という文にはならない。", "点滅": "点いたり消えたりすることを指す。協力を点滅する場という文は通らない。"}, "sentence_index": 6, "correct_answer": "促進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校は、警備を促進した。", "explanation": "ここは〈強化〉の意味。強化は強くすることで、促進は物事を進みやすくする意味。警備を進める意味にはならない。"}, {"text": "市は、川の氾濫を促進するため、堤防を作った。", "explanation": "ここは〈防止〉の意味。防止は起きないようにすることで、促進は進みを速める意味なので、氾濫には使わない。"}, {"text": "係の人が書類を促進した。", "explanation": "ここは〈整理〉の意味。整理は物を順序よくまとめることで、促進は進みを速める意味で、書類には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、地域の医療の促進が力を入れている。", "corrected_sentence": "市は、地域の医療の促進に力を入れている。", "error_description": "「力を入れる」は「〜に力を入れる」の形をとる。「促進が」では促進が主語になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、子育ての環境の促進を努めている。", "corrected_sentence": "市は、子育ての環境の促進に努めている。", "error_description": "「努める」は「〜に努める」と対象に「に」をとる。「促進を努める」とすると「努める」の形が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42cb7c5c-d858-4b3f-876b-e0bb1d371cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「病院が複合した」: 複合の主語を示す「が」で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "複合は自動詞なので、目的語の「を」はとれない。"}, {"text": "に", "is_correct": false, "explanation": "「病院に複合した」は場所や相手の意味になり、文として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、ここでは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「病院が複合した」: 複合の主語を示す「が」で、文の意味に合う。", "を": "複合は自動詞なので、目的語の「を」はとれない。", "に": "「病院に複合した」は場所や相手の意味になり、文として合わない。", "へ": "方向を表す「へ」は、ここでは意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「香料が複合した」: 複合の主語を示す「が」で、文の意味に合う。"}, {"text": "より", "is_correct": false, "explanation": "「香料より複合した」は比較の意味になり、文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「香料から複合した」は出所の意味になり、主語を示す形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「香料で複合した」は手段の意味になり、香料を主語として示さない。"}], "correct_answer": "が", "explanations": {"が": "「香料が複合した」: 複合の主語を示す「が」で、文の意味に合う。", "より": "「香料より複合した」は比較の意味になり、文として成り立たない。", "から": "「香料から複合した」は出所の意味になり、主語を示す形として不自然。", "で": "「香料で複合した」は手段の意味になり、香料を主語として示さない。"}, "error_tags": {"より": "比較", "から": "起点・出所", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものが一緒になったようす。", "primary_collocate": null, "pronunciation": "ふくごう", "ipa": "ɸɯkɯɡoː", "syllable_count": 4, "sentences": [{"text": "二つの技術が複合した製品が、市場で注目を集めている。", "target_word": "複合した", "complexity_tier": "T3", "furigana": "二[ふた]つの技[ぎ]術[じゅつ]が複[ふく]合[ごう]した製[せい]品[ひん]が、市[し]場[じょう]で注[ちゅう]目[もく]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "この建物は、店と病院が複合した新しい施設だ。", "target_word": "複合", "complexity_tier": "T3", "furigana": "この建物[たてもの]は、店[みせ]と病院[びょういん]が複合[ふくごう]した新[あたら]しい施設[しせつ]だ。", "sentence_source": "generated"}, {"text": "複数の材料が複合して、強い板になる。", "target_word": "複合", "complexity_tier": "T3", "furigana": "複数[ふくすう]の材料[ざいりょう]が複合[ふくごう]して、強[つよ]い板[いた]になる。", "sentence_source": "generated"}, {"text": "静かな寺と古い町並みが複合した景観が、観光客に人気だ。", "target_word": "複合した", "complexity_tier": "T3", "furigana": "静[しず]かな寺[てら]と古[ふる]い町[まち]並[なみ]みが複[ふく]合[ごう]した景[けい]観[かん]が、観[かん]光[こう]客[きゃく]に人[にん]気[き]だ。", "sentence_source": "generated"}, {"text": "その料理は、甘さと辛さが複合した味で、人気がある。", "target_word": "複合", "complexity_tier": "T3", "furigana": "その料理[りょうり]は、甘[あま]さと辛[から]さが複合[ふくごう]した味[あじ]で、人気[にんき]がある。", "sentence_source": "generated"}, {"text": "二つの機能が複合した道具なので、一つで何でもできる。", "target_word": "複合", "complexity_tier": "T3", "furigana": "二[ふた]つの機能[きのう]が複合[ふくごう]した道具[どうぐ]なので、一[ひと]つで何[なん]でもできる。", "sentence_source": "generated"}, {"text": "音楽と映像が複合した表現が、新しい舞台芸術として評価された。", "target_word": "複合した", "complexity_tier": "T3", "furigana": "音[おん]楽[がく]と映[えい]像[ぞう]が複[ふく]合[ごう]した表[ひょう]現[げん]が、新[あたら]しい舞[ぶ]台[たい]芸[げい]術[じゅつ]として評[ひょう]価[か]された。", "sentence_source": "generated"}, {"text": "いくつかの香料が複合した香りは、一種類では出せない深みがある。", "target_word": "複合した", "complexity_tier": "T3", "furigana": "いくつかの香[こう]料[りょう]が複[ふく]合[ごう]した香[かお]りは、一[いっ]種[しゅ]類[るい]では出[だ]せない深[ふか]みがある。", "sentence_source": "generated"}, {"text": "この薬は、二つの成分が複合してはたらく。", "target_word": "複合", "complexity_tier": "T3", "furigana": "この薬[くすり]は、二[ふた]つの成分[せいぶん]が複合[ふくごう]してはたらく。", "sentence_source": "generated"}, {"text": "気持ちが複合して、うれしいのか悲しいのか自分でも分からない。", "target_word": "複合", "complexity_tier": "T3", "furigana": "気持[きも]ちが複合[ふくごう]して、うれしいのか悲[かな]しいのか自分[じぶん]でも分[わ]からない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "複合", "label": "基本形"}, {"form": "複合する", "label": "辞書形"}, {"form": "複合して", "label": "て形"}, {"form": "複合した", "label": "た形"}, {"form": "複合しない", "label": "否定形"}], "register": "中立（書き言葉寄り）", "sense_fingerprint": "別々のものが混ざり合い一つになっているようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "複合した", "is_correct": true, "explanation": "連体形で「製品」を修飾し、「二つの技術が一緒になった」という意味に合う。"}, {"text": "複合して", "is_correct": false, "explanation": "て形は名詞を修飾できず、「製品」に続けられない。"}, {"text": "複合し", "is_correct": false, "explanation": "連用形（語幹）は名詞の前に置けず、文が成り立たない。"}, {"text": "複合させて", "is_correct": false, "explanation": "使役のて形では「製品」を修飾できず、文の流れが途切れる。"}], "explanations": {"複合した": "連体形で「製品」を修飾し、「二つの技術が一緒になった」という意味に合う。", "複合して": "て形は名詞を修飾できず、「製品」に続けられない。", "複合し": "連用形（語幹）は名詞の前に置けず、文が成り立たない。", "複合させて": "使役のて形では「製品」を修飾できず、文の流れが途切れる。"}, "sentence_index": 0, "correct_answer": "複合した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暗号が複合して、メッセージが読めるようになった。", "explanation": "ここは〈復号〉（暗号を元の文章に戻す）の意味。〈複合〉はいくつかのものが一緒になる意味なので、暗号には使わない。"}, {"text": "二つの国が複合して、一つの国になった。", "explanation": "ここは〈併合〉（国や地域を一つにすること）の意味。国どうしを一つにする場合は併合を使い、複合は性質の違う要素が組み合わさったものに使う。"}, {"text": "砂糖だけが複合して、甘い液体ができた。", "explanation": "ここは〈混合〉の意味。一つの材料だけでは複合は使えず、液体を混ぜる場合は混合を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "複合した", "is_correct": true, "explanation": "連体形で「表現」を修飾し、「音楽と映像が一緒になった」という意味に合う。"}, {"text": "複合せず", "is_correct": false, "explanation": "ず形は名詞の前に置けず、「表現」につながらない。"}, {"text": "複合させ", "is_correct": false, "explanation": "使役の連用形（語幹）は名詞を修飾できず、文が成り立たない。"}, {"text": "複合しよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文の流れに合わない。"}], "explanations": {"複合した": "連体形で「表現」を修飾し、「音楽と映像が一緒になった」という意味に合う。", "複合せず": "ず形は名詞の前に置けず、「表現」につながらない。", "複合させ": "使役の連用形（語幹）は名詞を修飾できず、文が成り立たない。", "複合しよう": "意志形は名詞を修飾できず、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "複合した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームの仲間が複合して、強くまとまった。", "explanation": "ここは〈結束〉（人の気持ちや集団がまとまる）の意味。人の集まりにはこの意味で結束を使い、複合は性質の違うものが組み合わさる場合に使う。"}, {"text": "二つの町が複合して、一つの市になった。", "explanation": "ここは〈合併〉の意味。行政区域などを一つにまとめる場合は合併を使い、複合はそれぞれの要素が残った組み合わせに使う。"}, {"text": "一つの色が複合して、区別がつかなくなった。", "explanation": "ここは〈融合〉（溶け合って一つになる）の意味。一つだけの色には複合は使えず、溶け合う場合は融合を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの機能を複合した道具が、人気を集めている。", "corrected_sentence": "二つの機能が複合した道具が、人気を集めている。", "error_description": "「複合」は自動詞で「〜が複合する」の形をとる。「機能を」の「を」は使えず、「機能が複合した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音楽と映像が複合された表現が、新しい舞台で評価を受けた。", "corrected_sentence": "音楽と映像が複合した表現が、新しい舞台で評価を受けた。", "error_description": "「複合」は自動詞なので受身にできない。「複合された」ではなく「複合した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この問題は複合していて」: 話題を示す「は」で、ここでは複合の主語にあたる。"}, {"text": "を", "is_correct": false, "explanation": "複合は自動詞なので、目的語の「を」はとれない。"}, {"text": "に", "is_correct": false, "explanation": "「問題に複合していて」は対象の「に」が複合と結びつかず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、ここでは意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「この問題は複合していて」: 話題を示す「は」で、ここでは複合の主語にあたる。", "を": "複合は自動詞なので、目的語の「を」はとれない。", "に": "「問題に複合していて」は対象の「に」が複合と結びつかず不自然。", "へ": "方向を表す「へ」は、ここでは意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
