INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素が組み合わさっていること。単一ではないこと。", "primary_collocate": null, "pronunciation": "ふくごう", "ipa": "ɸɯkɯɡoː", "syllable_count": 4, "sentences": [{"text": "事故の原因は一つではなく、複合している。", "target_word": "複合", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]は一[ひと]つではなく、複合[ふくごう]している。", "sentence_source": "generated"}, {"text": "この問題は複合していて、簡単には解決できない。", "target_word": "複合", "complexity_tier": "T3", "furigana": "この問題[もんだい]は複合[ふくごう]していて、簡単[かんたん]には解決[かいけつ]できない。", "sentence_source": "generated"}, {"text": "売り上げが下がったのは、複合した要因があるからだ。", "target_word": "複合", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが下[さ]がったのは、複合[ふくごう]した要因[よういん]があるからだ。", "sentence_source": "generated"}, {"text": "彼の悩みは複合していて、一言では説明できない。", "target_word": "複合", "complexity_tier": "T3", "furigana": "彼[かれ]の悩[なや]みは複合[ふくごう]していて、一言[ひとこと]では説明[せつめい]できない。", "sentence_source": "generated"}, {"text": "単一の理由ではなく、いくつもの事情が複合している。", "target_word": "複合", "complexity_tier": "T3", "furigana": "単一[たんいつ]の理由[りゆう]ではなく、いくつもの事情[じじょう]が複合[ふくごう]している。", "sentence_source": "generated"}, {"text": "複合した症状が出ているので、いくつかの検査が必要だ。", "target_word": "複合", "complexity_tier": "T3", "furigana": "複合[ふくごう]した症状[しょうじょう]が出[で]ているので、いくつかの検査[けんさ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この事件は、複数の問題が複合して起きた。", "target_word": "複合", "complexity_tier": "T3", "furigana": "この事件[じけん]は、複数[ふくすう]の問題[もんだい]が複合[ふくごう]して起[お]きた。", "sentence_source": "generated"}, {"text": "複合している課題は、まず分けて考えるといい。", "target_word": "複合", "complexity_tier": "T3", "furigana": "複合[ふくごう]している課題[かだい]は、まず分[わ]けて考[かんが]えるといい。", "sentence_source": "generated"}, {"text": "複合した問題だったが、一つずつ整理して答えを出した。", "target_word": "複合", "complexity_tier": "T3", "furigana": "複合[ふくごう]した問題[もんだい]だったが、一[ひと]つずつ整理[せいり]して答[こた]えを出[だ]した。", "sentence_source": "generated"}, {"text": "この会社の失敗は、複合した理由によるものだ。", "target_word": "複合", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の失敗[しっぱい]は、複合[ふくごう]した理由[りゆう]によるものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "複合", "label": "基本形"}, {"form": "複合する", "label": "辞書形"}, {"form": "複合して", "label": "て形"}, {"form": "複合している", "label": "継続形"}, {"form": "複合した", "label": "た形"}], "register": "中立（書き言葉寄り）", "sense_fingerprint": "原因や問題が複数の要素から成り、単純ではないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "複合", "is_correct": true, "explanation": "「〜している」に続く名詞形で、原因が複数の要素から成る状態を表し、文の意味に合う。"}, {"text": "複合して", "is_correct": false, "explanation": "て形のままでは「している」に続けられず、文が成り立たない。"}, {"text": "複合し", "is_correct": false, "explanation": "連用形（語幹）では「している」に続かず、文が途中で切れる。"}, {"text": "複合させて", "is_correct": false, "explanation": "使役のて形では「〜させている」となり、原因の説明として意味が通らない。"}], "explanations": {"複合": "「〜している」に続く名詞形で、原因が複数の要素から成る状態を表し、文の意味に合う。", "複合して": "て形のままでは「している」に続けられず、文が成り立たない。", "複合し": "連用形（語幹）では「している」に続かず、文が途中で切れる。", "複合させて": "使役のて形では「〜させている」となり、原因の説明として意味が通らない。"}, "sentence_index": 0, "correct_answer": "複合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暗号が複合して、文章が読めるようになった。", "explanation": "ここは〈復号〉（暗号を元に戻す）の意味。〈複合〉は原因や問題が複数の要素から成ることには使わない。"}, {"text": "足の骨が複合して、三か月入院した。", "explanation": "ここは〈複合骨折〉（骨が皮膚を破って出る骨折）の意味。骨折の種類には複合骨折を使い、〈複合〉の『複数の要素が組み合わさる』意味では使わない。"}, {"text": "二つの会社が複合して、一つの会社になった。", "explanation": "ここは〈統合〉（組織を一つにまとめる）の意味。組織をまとめる場合は統合を使い、複合は要素が組み合わさったまま機能する場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "複合", "is_correct": true, "explanation": "「複合して起きた」の語幹。複数の問題が絡み合って起きたという意味に合う。"}, {"text": "複雑", "is_correct": false, "explanation": "「複雑して」は文法的に続かない。複雑は「複雑になって」の形が必要。"}, {"text": "複合した", "is_correct": false, "explanation": "た形では「複合した起きた」となり、「して」の位置に合わない。"}, {"text": "複合され", "is_correct": false, "explanation": "受身の形は自動詞の複合と合わず、「複合されて起きた」は成り立たない。"}], "explanations": {"複合": "「複合して起きた」の語幹。複数の問題が絡み合って起きたという意味に合う。", "複雑": "「複雑して」は文法的に続かない。複雑は「複雑になって」の形が必要。", "複合した": "た形では「複合した起きた」となり、「して」の位置に合わない。", "複合され": "受身の形は自動詞の複合と合わず、「複合されて起きた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "複合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社の失敗は、理由がひとつだけで、複合したものだ。", "explanation": "ここは〈単一〉（一つだけであること）の意味。理由が一つだけの場合は単一を使い、複合は複数の要素が組み合わさっている場合に使う。"}, {"text": "この会社の失敗は、同じ理由が複合して起きたものだ。", "explanation": "ここは〈重複〉（同じものが重なる）の意味。同じ理由が繰り返す場合は重複を使い、複合は性質の違う要素が組み合わさる場合に使う。"}, {"text": "この会社の失敗は、一つの部品が複合して壊れた理由によるものだ。", "explanation": "ここは〈結合〉（部品などをつなぐ）の意味。一つの部品には複合は使えず、つなぐ場合は結合を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この問題に複合していて、すぐには解けない。", "corrected_sentence": "この問題が複合していて、すぐには解けない。", "error_description": "「複合」は「〜が複合する」の形で使うので、「に」は不可。主語の「が」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事件の原因は、複合して理由によるものだ。", "corrected_sentence": "この事件の原因は、複合した理由によるものだ。", "error_description": "連体修飾では「複合して」ではなく「複合した」を使う。「理由」を修飾する形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「山々が重なり合って」: 重なり合う主体を示す主語の「が」。"}, {"text": "を", "is_correct": false, "explanation": "自動詞の重なり合うには目的語の「を」はとれない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、ここでは意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「山々より重なり合って」となり、意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「山々が重なり合って」: 重なり合う主体を示す主語の「が」。", "を": "自動詞の重なり合うには目的語の「を」はとれない。", "へ": "方向を表す「へ」は、ここでは意味が通らない。", "より": "比較の「より」は「山々より重なり合って」となり、意味が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「二人の影が重なり合って」: 重なり合う主体を示す主語の「が」。"}, {"text": "の", "is_correct": false, "explanation": "「二人の影の重なり合って」は、所有の「の」が動詞に続かず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「影から重なり合って」となり、出所の意味で意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「影で重なり合って」となり、影を主語として示さない。"}], "correct_answer": "が", "explanations": {"が": "「二人の影が重なり合って」: 重なり合う主体を示す主語の「が」。", "の": "「二人の影の重なり合って」は、所有の「の」が動詞に続かず不自然。", "から": "起点の「から」は「影から重なり合って」となり、出所の意味で意味が通らない。", "で": "手段の「で」は「影で重なり合って」となり、影を主語として示さない。"}, "error_tags": {"の": "所有", "から": "起点・出所", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、別のものの上にのるように、いっしょになる。", "primary_collocate": null, "pronunciation": "かさなりあう", "ipa": "kasanaɾiaɯ", "syllable_count": 6, "sentences": [{"text": "木の葉が重なり合って、地面に光が届かない。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "木[き]の葉[は]が重[かさ]なり合[あ]って、地面[じめん]に光[ひかり]が届[とど]かない。", "sentence_source": "generated"}, {"text": "山々が重なり合って見え、遠くの景色がぼんやりしている。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "山々[やまやま]が重[かさ]なり合[あ]って見[み]え、遠[とお]くの景色[けしき]がぼんやりしている。", "sentence_source": "generated"}, {"text": "二枚の紙が重なり合っていたので、一枚ずつはがした。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "二枚[にまい]の紙[かみ]が重[かさ]なり合[あ]っていたので、一枚[いちまい]ずつはがした。", "sentence_source": "generated"}, {"text": "屋根が重なり合う町並みは、上から見るときれいだ。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "屋根[やね]が重[かさ]なり合[あ]う町並[まちな]みは、上[うえ]から見[み]るときれいだ。", "sentence_source": "generated"}, {"text": "雲が重なり合って、空が急に暗くなった。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "雲[くも]が重[かさ]なり合[あ]って、空[そら]が急[きゅう]に暗[くら]くなった。", "sentence_source": "generated"}, {"text": "倒れた人々が重なり合って、なかなか起き上がれなかった。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "倒[たお]れた人々[ひとびと]が重[かさ]なり合[あ]って、なかなか起[お]き上[あ]がれなかった。", "sentence_source": "generated"}, {"text": "波が重なり合う場所では、水しぶきが高く上がる。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "波[なみ]が重[かさ]なり合[あ]う場所[ばしょ]では、水[みず]しぶきが高[たか]く上[あ]がる。", "sentence_source": "generated"}, {"text": "二人の影が重なり合って、一つに見えた。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "二人[ふたり]の影[かげ]が重[かさ]なり合[あ]って、一[ひと]つに見[み]えた。", "sentence_source": "generated"}, {"text": "皿が重なり合って置いてあり、下の皿が取り出せない。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "皿[さら]が重[かさ]なり合[あ]って置[お]いてあり、下[した]の皿[さら]が取[と]り出[だ]せない。", "sentence_source": "generated"}, {"text": "落ち葉が重なり合う道は、歩くとやわらかい。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "落[お]ち葉[ば]が重[かさ]なり合[あ]う道[みち]は、歩[ある]くとやわらかい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重なり合う", "label": "辞書形"}, {"form": "重なり合って", "label": "て形"}, {"form": "重なり合った", "label": "た形"}, {"form": "重なり合わない", "label": "否定形"}, {"form": "重なり合います", "label": "丁寧形"}], "register": "中立", "sense_fingerprint": "物が互いの上にのるように位置する物理的な重なり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重なり合って", "is_correct": true, "explanation": "て形で「重なり合って、地面に光が届かない」と原因を述べる文に合う。"}, {"text": "重なり合わない", "is_correct": false, "explanation": "否定では「重ならないので光が届かない」となり、原因と結果の関係が成り立たない。"}, {"text": "重なり合わせて", "is_correct": false, "explanation": "使役のて形では主語の「木の葉」と合わず、文が成り立たない。"}, {"text": "重なり合った", "is_correct": false, "explanation": "た形では「重なり合った、」で文が途中で切れ、因果関係が続かない。"}], "explanations": {"重なり合って": "て形で「重なり合って、地面に光が届かない」と原因を述べる文に合う。", "重なり合わない": "否定では「重ならないので光が届かない」となり、原因と結果の関係が成り立たない。", "重なり合わせて": "使役のて形では主語の「木の葉」と合わず、文が成り立たない。", "重なり合った": "た形では「重なり合った、」で文が途中で切れ、因果関係が続かない。"}, "sentence_index": 0, "correct_answer": "重なり合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの会社が重なり合って、一つの会社になった。", "explanation": "ここは〈合併〉の意味。会社を一つにまとめる場合は合併を使い、重なり合うは物が上にのる意味で使う。"}, {"text": "二人の説明が重なり合って、どちらが正しいか分からない。", "explanation": "ここは〈食い違う〉（意見が一致しない）の意味。意見が合わない場合は食い違うを使い、重なり合うは物が上にのる意味で使う。"}, {"text": "二つの党が重なり合って、新しい政党になった。", "explanation": "ここは〈合同〉（組織が一つになる）の意味。組織が一つになる場合は合同を使い、重なり合うは物が上にのる意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重なり合う", "is_correct": true, "explanation": "辞書形で「場所」を修飾し、波が重なる場所という意味に合う。"}, {"text": "重なり合わず", "is_correct": false, "explanation": "ず形は名詞の前に置けず、「場所」につながらない。"}, {"text": "重なり合い", "is_correct": false, "explanation": "連用形（語幹）は名詞を修飾できず、文が成り立たない。"}, {"text": "重なり合えば", "is_correct": false, "explanation": "条件形は名詞を修飾できず、「場所」に続けられない。"}], "explanations": {"重なり合う": "辞書形で「場所」を修飾し、波が重なる場所という意味に合う。", "重なり合わず": "ず形は名詞の前に置けず、「場所」につながらない。", "重なり合い": "連用形（語幹）は名詞を修飾できず、文が成り立たない。", "重なり合えば": "条件形は名詞を修飾できず、「場所」に続けられない。"}, "sentence_index": 6, "correct_answer": "重なり合う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人が重なり合って歩く道は、狭い。", "explanation": "ここは〈寄り添う〉（そばに寄り並ぶ）の意味。人が並んで歩く場合は寄り添うを使い、重なり合うは物が上にのる意味で使う。"}, {"text": "風が重なり合って、洗濯物がすぐ乾いた。", "explanation": "ここは〈吹き抜ける〉の意味。風が通る場合は吹き抜けるを使い、重なり合うは物が上にのる意味で使う。"}, {"text": "二つの店が重なり合って、にぎやかな通りができた。", "explanation": "ここは〈集まる〉（人や店が一か所に寄る）の意味。店が寄る場合は集まるを使い、重なり合うは物が上にのる意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "枝の先が重なり合いて、日陰がずっと続く。", "corrected_sentence": "枝の先が重なり合って、日陰がずっと続く。", "error_description": "「重なり合う」のて形は「重なり合って」。「重なり合いて」は誤った活用。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重なり合って", "is_correct": true, "explanation": "て形で、後の「見え」に続いて山々の見え方を述べる。"}, {"text": "重なり合った", "is_correct": false, "explanation": "た形では「重なり合った見え」となり、文の流れに合わない。"}, {"text": "重なり合わない", "is_correct": false, "explanation": "否定形では「重なり合わない見え」となり、景色のぼんやりさと結びつかない。"}, {"text": "重なり合います", "is_correct": false, "explanation": "丁寧形は「見え」に続けられず、接続が成り立たない。"}], "correct_form": "重なり合って", "base_form": "重なり合う", "form_label": "て形", "sentence_index": 1, "explanations": {"重なり合って": "て形で、後の「見え」に続いて山々の見え方を述べる。", "重なり合った": "た形では「重なり合った見え」となり、文の流れに合わない。", "重なり合わない": "否定形では「重なり合わない見え」となり、景色のぼんやりさと結びつかない。", "重なり合います": "丁寧形は「見え」に続けられず、接続が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36760, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "崖の下で波が重なり合わる時間は、とても短い。", "corrected_sentence": "崖の下で波が重なり合う時間は、とても短い。", "error_description": "「重なり合う」は辞書形で、「重なり合わる」は誤った活用。正しくは「重なり合う」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重なり合って", "is_correct": true, "explanation": "て形で、後の「一つに見えた」へ続き、見え方の理由を述べる。"}, {"text": "重なり合わせる", "is_correct": false, "explanation": "使役の辞書形では「影が重なり合わせる」となり、主語の影と合わない。"}, {"text": "重なり合え", "is_correct": false, "explanation": "命令・可能の形は文の途中で続かず、「一つに見えた」につながらない。"}, {"text": "重なり合おう", "is_correct": false, "explanation": "意志形では「影が重なり合おう」となり、過去の出来事の説明にならない。"}], "correct_form": "重なり合って", "base_form": "重なり合う", "form_label": "て形", "sentence_index": 7, "explanations": {"重なり合って": "て形で、後の「一つに見えた」へ続き、見え方の理由を述べる。", "重なり合わせる": "使役の辞書形では「影が重なり合わせる」となり、主語の影と合わない。", "重なり合え": "命令・可能の形は文の途中で続かず、「一つに見えた」につながらない。", "重なり合おう": "意志形では「影が重なり合おう」となり、過去の出来事の説明にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「担当範囲が重なり合って」: 重なり合う主体を示す主語の「が」。"}, {"text": "を", "is_correct": false, "explanation": "自動詞の重なり合うには目的語の「を」はとれない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、ここでは意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「担当範囲から重なり合って」となり、不自然で意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「担当範囲が重なり合って」: 重なり合う主体を示す主語の「が」。", "を": "自動詞の重なり合うには目的語の「を」はとれない。", "へ": "方向を表す「へ」は、ここでは意味が通らない。", "から": "起点の「から」は「担当範囲から重なり合って」となり、不自然で意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点・出所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「研究分野が重なり合う」: 重なり合う主体を示す主語の「が」。"}, {"text": "の", "is_correct": false, "explanation": "「研究分野の重なり合うので」は、名詞修飾の「の」が理由の文と噛み合わず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「研究分野に重なり合うので」は、対象の「に」が自動詞と合わず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「研究分野より重なり合うので」となり、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「研究分野が重なり合う」: 重なり合う主体を示す主語の「が」。", "の": "「研究分野の重なり合うので」は、名詞修飾の「の」が理由の文と噛み合わず不自然。", "に": "「研究分野に重なり合うので」は、対象の「に」が自動詞と合わず不自然。", "より": "比較の「より」は「研究分野より重なり合うので」となり、意味が通らない。"}, "error_tags": {"の": "所有・修飾", "に": "位置・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の物や事柄が、一部分または全体において、互いの上にのるように位置すること。また、複数の要素が同じ部分で一致すること。", "primary_collocate": null, "pronunciation": "かさなりあう", "ipa": "kasanaɾiaɯ", "syllable_count": 6, "sentences": [{"text": "二つの円が重なり合う部分が、共通点を表している。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "二[ふた]つの円[えん]が重[かさ]なり合[あ]う部分[ぶぶん]が、共通点[きょうつうてん]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "二人の担当範囲が重なり合っていて、同じ仕事を二回してしまった。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "二人[ふたり]の担当範囲[たんとうはんい]が重[かさ]なり合[あ]っていて、同[おな]じ仕事[しごと]を二回[にかい]してしまった。", "sentence_source": "generated"}, {"text": "二つの会議の時間が重なり合っているので、片方は欠席する。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "二[ふた]つの会議[かいぎ]の時間[じかん]が重[かさ]なり合[あ]っているので、片方[かたほう]は欠席[けっせき]する。", "sentence_source": "generated"}, {"text": "兄と私の好みは、重なり合う点が少ない。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の好[この]みは、重[かさ]なり合[あ]う点[てん]が少[すく]ない。", "sentence_source": "generated"}, {"text": "この二つの規則は内容が重なり合っているため、一つにまとめた。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "この二[ふた]つの規則[きそく]は内容[ないよう]が重[かさ]なり合[あ]っているため、一[ひと]つにまとめた。", "sentence_source": "generated"}, {"text": "二つの店の客層が重なり合っているので、競争が厳しい。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "二[ふた]つの店[みせ]の客層[きゃくそう]が重[かさ]なり合[あ]っているので、競争[きょうそう]が厳[きび]しい。", "sentence_source": "generated"}, {"text": "二つの業界の仕事内容が重なり合う分野で、新しい協力の形が生まれた。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "二[ふた]つの業[ぎょう]界[かい]の仕[し]事[ごと]内[ない]容[よう]が重[かさ]なり合[あ]う分[ぶん]野[や]で、新[あたら]しい協[きょう]力[りょく]の形[かたち]が生[う]まれた。", "sentence_source": "generated"}, {"text": "研究分野が重なり合うので、二人はよく意見を交換する。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "研究分野[けんきゅうぶんや]が重[かさ]なり合[あ]うので、二人[ふたり]はよく意見[いけん]を交換[こうかん]する。", "sentence_source": "generated"}, {"text": "二つの調査で重なり合う結果だけを、報告書に書いた。", "target_word": "重なり合う", "complexity_tier": "T3", "furigana": "二[ふた]つの調査[ちょうさ]で重[かさ]なり合[あ]う結果[けっか]だけを、報告書[ほうこくしょ]に書[か]いた。", "sentence_source": "generated"}, {"text": "授業の内容が重なり合っていて、同じ説明を二度聞いた。", "target_word": "重なり合って", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の内容[ないよう]が重[かさ]なり合[あ]っていて、同[おな]じ説明[せつめい]を二度[にど]聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重なり合う", "label": "辞書形"}, {"form": "重なり合って", "label": "て形"}, {"form": "重なり合っている", "label": "継続形"}, {"form": "重なり合った", "label": "た形"}, {"form": "重なり合わない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "範囲・内容・時間などが一部または全体で共通する部分を持つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重なり合う", "is_correct": true, "explanation": "辞書形で「部分」を修飾し、円が重なっている部分という意味に合う。"}, {"text": "重なり合って", "is_correct": false, "explanation": "て形は名詞を修飾できず、「部分」に続けられない。"}, {"text": "重なり合い", "is_correct": false, "explanation": "連用形（語幹）は名詞の前に置けず、文が成り立たない。"}, {"text": "重なり合わせて", "is_correct": false, "explanation": "使役のて形では「部分」を修飾できず、主語の「円」とも合わない。"}], "explanations": {"重なり合う": "辞書形で「部分」を修飾し、円が重なっている部分という意味に合う。", "重なり合って": "て形は名詞を修飾できず、「部分」に続けられない。", "重なり合い": "連用形（語幹）は名詞の前に置けず、文が成り立たない。", "重なり合わせて": "使役のて形では「部分」を修飾できず、主語の「円」とも合わない。"}, "sentence_index": 0, "correct_answer": "重なり合う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの意見が重なり合って、対立している。", "explanation": "ここは〈対立〉（反対の立場に立つ）の意味。意見が反対になる場合は対立を使い、重なり合うは共通の部分がある場合に使う。"}, {"text": "兄と私の好みは、上下に重なり合って並んでいる。", "explanation": "ここは物が上にのるように並ぶ意味。好みは物ではないので、一部共通する場合の重なり合うの用法とは合わない。"}, {"text": "二人の意見が、歌声のように重なり合って、ばらばらになった。", "explanation": "ここは〈分裂〉（ばらばらになる）の意味。意見が分かれる場合は分裂を使い、重なり合うは一致や共通部分がある場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重なり合う", "is_correct": true, "explanation": "辞書形で「分野」を修飾し、仕事内容が共通する分野という意味に合う。"}, {"text": "重なり合っても", "is_correct": false, "explanation": "「ても」は名詞を修飾できず、「分野」に続かない。"}, {"text": "重なり合え", "is_correct": false, "explanation": "命令・可能の形は名詞を修飾できず、文が成り立たない。"}, {"text": "重なり合おう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、文の流れに合わない。"}], "explanations": {"重なり合う": "辞書形で「分野」を修飾し、仕事内容が共通する分野という意味に合う。", "重なり合っても": "「ても」は名詞を修飾できず、「分野」に続かない。", "重なり合え": "命令・可能の形は名詞を修飾できず、文が成り立たない。", "重なり合おう": "意志形は名詞を修飾できず、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "重なり合う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業の内容が重なり合う方向に寄り添っていて、同じ説明を二度聞いた。", "explanation": "ここは〈寄り添う〉（そばに寄る）の意味。内容の共通部分を表す場合は重なり合うを使い、寄り添うは人や物がそばに寄る場合に使う。"}, {"text": "授業の内容が重なり合って交差していて、同じ説明を二度聞いた。", "explanation": "ここは〈交差する〉（線が交わる）の意味。内容の共通部分を表す場合は重なり合うを使い、交差は線や道が交わる場合に使う。"}, {"text": "ベッドの上で、毛布が重なり合う内容が二度も書かれていた。", "explanation": "ここは物が上にのるように重なる意味。内容の共通部分を表す重なり合うとは違い、物理的な重なりに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの会議の時間が重なり合わ時間帯は、避けるべきだ。", "corrected_sentence": "二つの会議の時間が重なり合う時間帯は、避けるべきだ。", "error_description": "「重なり合う」の活用を誤って「重なり合わ」にしている。連体形は「重なり合う」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "重なり合って", "is_correct": true, "explanation": "て形で、後に「いて」が続き、重なり合っている状態を表す。"}, {"text": "重なり合った", "is_correct": false, "explanation": "た形では「重なり合ったいて」となり、文として続かない。"}, {"text": "重なり合わず", "is_correct": false, "explanation": "ず形では「重なり合わずいて」となり、文として続かない。"}, {"text": "重なり合えば", "is_correct": false, "explanation": "条件形では「重なり合えばいて」となり、文が成り立たない。"}], "correct_form": "重なり合って", "base_form": "重なり合う", "form_label": "て形", "sentence_index": 1, "explanations": {"重なり合って": "て形で、後に「いて」が続き、重なり合っている状態を表す。", "重なり合った": "た形では「重なり合ったいて」となり、文として続かない。", "重なり合わず": "ず形では「重なり合わずいて」となり、文として続かない。", "重なり合えば": "条件形では「重なり合えばいて」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36761, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの研究分野を重なり合うので、二人はよく意見を交換する。", "corrected_sentence": "二つの研究分野が重なり合うので、二人はよく意見を交換する。", "error_description": "「重なり合う」は自動詞で「〜が重なり合う」の形をとる。「を」は使えず、主語は「が」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "重なり合う", "is_correct": true, "explanation": "辞書形で、後の「ので」に続き、理由を述べる。"}, {"text": "重なり合わせ", "is_correct": false, "explanation": "使役の語幹では「重なり合わせので」となり、文が成り立たない。"}, {"text": "重なり合え", "is_correct": false, "explanation": "命令・可能の形は「ので」に続けられない。"}, {"text": "重なり合おう", "is_correct": false, "explanation": "意志形では「研究分野が重なり合おうので」となり、意味が通らない。"}], "correct_form": "重なり合う", "base_form": "重なり合う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"重なり合う": "辞書形で、後の「ので」に続き、理由を述べる。", "重なり合わせ": "使役の語幹では「重なり合わせので」となり、文が成り立たない。", "重なり合え": "命令・可能の形は「ので」に続けられない。", "重なり合おう": "意志形では「研究分野が重なり合おうので」となり、意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少ない", "is_correct": true, "explanation": "「多い」の対義語。本の数がたくさんあることの反対を表し、正解。"}, {"text": "長い", "is_correct": false, "explanation": "長さの形容で、数量の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さの形容で、数量の対義語ではない。"}, {"text": "遠い", "is_correct": false, "explanation": "距離の形容で、数量の対義語ではない。"}], "correct_answer": "少ない", "explanations": {"少ない": "「多い」の対義語。本の数がたくさんあることの反対を表し、正解。", "長い": "長さの形容で、数量の対義語ではない。", "重い": "重さの形容で、数量の対義語ではない。", "遠い": "距離の形容で、数量の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少ない", "is_correct": true, "explanation": "「多い」の対義語。種類が多いことの反対を表し、正解。"}, {"text": "深い", "is_correct": false, "explanation": "深さの形容で、数量の対義語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さの形容で、数量の対義語ではない。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの形容で、数量の対義語ではない。"}], "correct_answer": "少ない", "explanations": {"少ない": "「多い」の対義語。種類が多いことの反対を表し、正解。", "深い": "深さの形容で、数量の対義語ではない。", "厚い": "厚さの形容で、数量の対義語ではない。", "暗い": "明るさの形容で、数量の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "数がたくさんあること。", "primary_collocate": null, "pronunciation": "おおい", "ipa": "oːi", "syllable_count": 3, "sentences": [{"text": "この町は公園が多いので、子どもが遊ぶ場所に困りません。", "target_word": "多い", "complexity_tier": "T3", "furigana": "この町[まち]は公園[こうえん]が多[おお]いので、子[こ]どもが遊[あそ]ぶ場所[ばしょ]に困[こま]りません。", "sentence_source": "generated"}, {"text": "私のクラスは男の子より女の子のほうが多いです。", "target_word": "多い", "complexity_tier": "T3", "furigana": "私[わたし]のクラスは男[おとこ]の子[こ]より女[おんな]の子[こ]のほうが多[おお]いです。", "sentence_source": "generated"}, {"text": "日曜日の駅は人が多くて、まっすぐ歩けませんでした。", "target_word": "多くて", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の駅[えき]は人[ひと]が多[おお]くて、まっすぐ歩[ある]けませんでした。", "sentence_source": "generated"}, {"text": "図書館には本が多いので、読みたい本がきっと見つかる。", "target_word": "多い", "complexity_tier": "T3", "furigana": "図書館[としょかん]には本[ほん]が多[おお]いので、読[よ]みたい本[ほん]がきっと見[み]つかる。", "sentence_source": "generated"}, {"text": "今年の夏は雨の日が多かったです。", "target_word": "多かった", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は雨[あめ]の日[ひ]が多[おお]かったです。", "sentence_source": "generated"}, {"text": "田中さんは友だちが多いので、いつもにぎやかだ。", "target_word": "多い", "complexity_tier": "T3", "furigana": "田中[たなか]さんは友[とも]だちが多[おお]いので、いつもにぎやかだ。", "sentence_source": "generated"}, {"text": "兄の部屋は本棚が多くて、歩く場所があまりありません。", "target_word": "多くて", "complexity_tier": "T3", "furigana": "兄[あに]の部屋[へや]は本棚[ほんだな]が多[おお]くて、歩[ある]く場所[ばしょ]があまりありません。", "sentence_source": "generated"}, {"text": "宿題が多い日は、夜おそくまで勉強します。", "target_word": "多い", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]い日[ひ]は、夜[よる]おそくまで勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "公園の池には魚が多く、子どもたちが毎日見に来る。", "target_word": "多く", "complexity_tier": "T3", "furigana": "公園[こうえん]の池[いけ]には魚[さかな]が多[おお]く、子[こ]どもたちが毎日[まいにち]見[み]に来[く]る。", "sentence_source": "generated"}, {"text": "この店は種類が多いので、選ぶのに時間がかかった。", "target_word": "多い", "complexity_tier": "T3", "furigana": "この店[みせ]は種類[しゅるい]が多[おお]いので、選[えら]ぶのに時間[じかん]がかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多い", "label": "辞書形"}, {"form": "多く", "label": "連用形"}, {"form": "多くて", "label": "て形"}, {"form": "多かった", "label": "過去形"}, {"form": "多くない", "label": "否定形"}, {"form": "多ければ", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "数や人・物がたくさんある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: おそく (Zipf 2.34)']::text[], 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多い", "is_correct": true, "explanation": "「公園が多い」で数がたくさんあるという意味になり、この文に合う。"}, {"text": "熱い", "is_correct": false, "explanation": "「熱い」は温度の形容で、公園の数を表せない。"}, {"text": "冷たい", "is_correct": false, "explanation": "「冷たい」は温度や感触の形容で、公園の数の文には合わない。"}, {"text": "重い", "is_correct": false, "explanation": "「重い」は重さの形容で、数がたくさんあることは表せない。"}], "explanations": {"多い": "「公園が多い」で数がたくさんあるという意味になり、この文に合う。", "熱い": "「熱い」は温度の形容で、公園の数を表せない。", "冷たい": "「冷たい」は温度や感触の形容で、公園の数の文には合わない。", "重い": "「重い」は重さの形容で、数がたくさんあることは表せない。"}, "sentence_index": 0, "correct_answer": "多い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は物価が多いので、生活費がかかる。", "explanation": "物価は数ではなく値段の水準を言うため、「多い」は使えない。"}, {"text": "この公園は面積が多いので、子どもが走り回れる。", "explanation": "面積は数ではなく広さを言うため、「多い」は使えない。"}, {"text": "この料理は味が多いので、塩を足した。", "explanation": "味の薄さは数えられないため、「多い」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多くて", "is_correct": true, "explanation": "て形。「本棚が多くて、歩く場所がない」という理由の文に入る。"}, {"text": "甘くて", "is_correct": false, "explanation": "味の形容で、本棚の状態を表さないので合わない。"}, {"text": "暖かくて", "is_correct": false, "explanation": "温度の形容で、本棚の数や量の文には合わない。"}, {"text": "辛くて", "is_correct": false, "explanation": "味の形容で、本棚の量を表せないので合わない。"}], "explanations": {"多くて": "て形。「本棚が多くて、歩く場所がない」という理由の文に入る。", "甘くて": "味の形容で、本棚の状態を表さないので合わない。", "暖かくて": "温度の形容で、本棚の数や量の文には合わない。", "辛くて": "味の形容で、本棚の量を表せないので合わない。"}, "sentence_index": 6, "correct_answer": "多くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子は身長が多いので、前の席に座ることにした。", "explanation": "身長は数ではなく高さを言うため、「多い」は使えない。"}, {"text": "父は体重が多いので、よく走る。", "explanation": "体重は数ではなく重さを言うため、「多い」は使えない。"}, {"text": "この子は目が多くて、かわいらしい。", "explanation": "目の大きさは数ではないため、「多い」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は客が多かく、店がとても忙しかった。", "corrected_sentence": "昨日は客が多く、店がとても忙しかった。", "error_description": "連用形は「多く」。「多かく」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多い", "is_correct": true, "explanation": "辞書形。「多いです」で文を終えられ、この文に合う。"}, {"text": "多く", "is_correct": false, "explanation": "連用形。「多くです」とは続けられず、述語にならない。"}, {"text": "多くて", "is_correct": false, "explanation": "て形。「多くてです」は成り立たず、文を終えられない。"}, {"text": "多ければ", "is_correct": false, "explanation": "仮定形。「多ければです」は成り立たず、述語にならない。"}], "correct_form": "多い", "base_form": "多い", "form_label": "辞書形", "sentence_index": 1, "explanations": {"多い": "辞書形。「多いです」で文を終えられ、この文に合う。", "多く": "連用形。「多くです」とは続けられず、述語にならない。", "多くて": "て形。「多くてです」は成り立たず、文を終えられない。", "多ければ": "仮定形。「多ければです」は成り立たず、述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は種類を多いので、初めての客には選びにくい。", "corrected_sentence": "この店は種類が多いので、初めての客には選びにくい。", "error_description": "「種類が多い」の主語は「が」。「を」は目的語の印で、形容詞「多い」の主語には使わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多い", "is_correct": true, "explanation": "連体形。「宿題が多い日」と名詞を修飾する形で、ここに合う。"}, {"text": "多かったら", "is_correct": false, "explanation": "過去の仮定形。「多かったら日は」と名詞を修飾できず、ここでは合わない。"}, {"text": "多かろう", "is_correct": false, "explanation": "推量形。「多かろう日は」と名詞を修飾できず、推量の文になってしまう。"}, {"text": "多けれ", "is_correct": false, "explanation": "文語の已然形。「多けれ日は」と名詞を修飾できず、ここでは合わない。"}], "correct_form": "多い", "base_form": "多い", "form_label": "連体形", "sentence_index": 7, "explanations": {"多い": "連体形。「宿題が多い日」と名詞を修飾する形で、ここに合う。", "多かったら": "過去の仮定形。「多かったら日は」と名詞を修飾できず、ここでは合わない。", "多かろう": "推量形。「多かろう日は」と名詞を修飾できず、推量の文になってしまう。", "多けれ": "文語の已然形。「多けれ日は」と名詞を修飾できず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
