INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少ない", "is_correct": true, "explanation": "「多い」の対義語。郵便物の量が普通より大きいことの反対を表し、正解。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さの形容で、量の対義語ではない。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの形容で、量の対義語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さの形容で、量の対義語ではない。"}], "correct_answer": "少ない", "explanations": {"少ない": "「多い」の対義語。郵便物の量が普通より大きいことの反対を表し、正解。", "厚い": "厚さの形容で、量の対義語ではない。", "暗い": "明るさの形容で、量の対義語ではない。", "深い": "深さの形容で、量の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "数量や程度が普通よりも大きいこと、たくさんあること。", "primary_collocate": null, "pronunciation": "おおい", "ipa": "oːi", "syllable_count": 3, "sentences": [{"text": "今年は雪が多いので、道路の除雪が追いつかない。", "target_word": "多い", "complexity_tier": "T3", "furigana": "今年[ことし]は雪[ゆき]が多[おお]いので、道路[どうろ]の除雪[じょせつ]が追[お]いつかない。", "sentence_source": "generated"}, {"text": "この地方は一年を通して雨が多く、洗濯物がなかなか乾かない。", "target_word": "多く", "complexity_tier": "T3", "furigana": "この地方[ちほう]は一年[いちねん]を通[とお]して雨[あめ]が多[おお]く、洗濯物[せんたくもの]がなかなか乾[かわ]かない。", "sentence_source": "generated"}, {"text": "彼は仕事の量が多いので、毎晩帰りがおそい。", "target_word": "多い", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]の量[りょう]が多[おお]いので、毎晩[まいばん]帰[かえ]りがおそい。", "sentence_source": "generated"}, {"text": "今日の客は昨日より多く、店員は休む時間もなかった。", "target_word": "多く", "complexity_tier": "T3", "furigana": "今日[きょう]の客[きゃく]は昨日[きのう]より多[おお]く、店員[てんいん]は休[やす]む時間[じかん]もなかった。", "sentence_source": "generated"}, {"text": "交通量が多い道なので、子どもだけで渡るのは危ない。", "target_word": "多い", "complexity_tier": "T3", "furigana": "交通量[こうつうりょう]が多[おお]い道[みち]なので、子[こ]どもだけで渡[わた]るのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "兄は私より食べる量が多いので、ご飯をたくさん作る。", "target_word": "多い", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]より食[た]べる量[りょう]が多[おお]いので、ご飯[はん]をたくさん作[つく]る。", "sentence_source": "generated"}, {"text": "地震の多い国では、家を丈夫に造る必要がある。", "target_word": "多い", "complexity_tier": "T3", "furigana": "地震[じしん]の多[おお]い国[くに]では、家[いえ]を丈夫[じょうぶ]に造[つく]る必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "今月は出費が多くて、貯金ができなかった。", "target_word": "多くて", "complexity_tier": "T3", "furigana": "今月[こんげつ]は出費[しゅっぴ]が多[おお]くて、貯金[ちょきん]ができなかった。", "sentence_source": "generated"}, {"text": "水分が多い果物は、冷やして食べるとおいしい。", "target_word": "多い", "complexity_tier": "T3", "furigana": "水分[すいぶん]が多[おお]い果物[くだもの]は、冷[ひ]やして食[た]べるとおいしい。", "sentence_source": "generated"}, {"text": "年末は郵便物の量が多く、配達が遅れることがある。", "target_word": "多く", "complexity_tier": "T3", "furigana": "年末[ねんまつ]は郵便物[ゆうびんぶつ]の量[りょう]が多[おお]く、配達[はいたつ]が遅[おく]れることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多い", "label": "辞書形"}, {"form": "多く", "label": "連用形"}, {"form": "多くて", "label": "て形"}, {"form": "多かった", "label": "過去形"}, {"form": "多くない", "label": "否定形"}, {"form": "多ければ", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "数量や程度が普通より大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多い", "is_correct": true, "explanation": "「雪が多い」で量が普通より大きいという意味になり、この文に合う。"}, {"text": "熱い", "is_correct": false, "explanation": "温度の形容で、雪の量を表せないので合わない。"}, {"text": "甘い", "is_correct": false, "explanation": "味の形容で、雪の量を表せないので合わない。"}, {"text": "苦い", "is_correct": false, "explanation": "味の形容で、雪の量を表せないので合わない。"}], "explanations": {"多い": "「雪が多い」で量が普通より大きいという意味になり、この文に合う。", "熱い": "温度の形容で、雪の量を表せないので合わない。", "甘い": "味の形容で、雪の量を表せないので合わない。", "苦い": "味の形容で、雪の量を表せないので合わない。"}, "sentence_index": 0, "correct_answer": "多い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は値段が多いので、学生はなかなか来ない。", "explanation": "ここは〈高い〉の意味。値段は量ではなく高さの話なので、〈多い〉は合わない。"}, {"text": "この体育館は面積が多くて、大会も開ける。", "explanation": "ここは〈広い〉の意味。面積は量ではなく広さの話なので、〈多い〉は合わない。"}, {"text": "弟は身長が多いので、前の席に座る。", "explanation": "ここは〈低い〉の意味。身長は量ではなく高さの話なので、〈多い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多い", "is_correct": true, "explanation": "連体形。「地震の多い国」と名詞を修飾し、この文に合う。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度や感触の形容で、地震の多さは表せないので合わない。"}, {"text": "酸っぱい", "is_correct": false, "explanation": "味の形容で、地震の多さは表せないので合わない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "硬さの形容で、地震の多さは表せないので合わない。"}], "explanations": {"多い": "連体形。「地震の多い国」と名詞を修飾し、この文に合う。", "冷たい": "温度や感触の形容で、地震の多さは表せないので合わない。", "酸っぱい": "味の形容で、地震の多さは表せないので合わない。", "柔らかい": "硬さの形容で、地震の多さは表せないので合わない。"}, "sentence_index": 6, "correct_answer": "多い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は声が多いので、遠くからでも分かる。", "explanation": "ここは〈大きい〉の意味。声の大きさは数ではないので、〈多い〉は合わない。"}, {"text": "この荷物は重さが多いので、一人で運べる。", "explanation": "ここは〈軽い〉の意味。重さは数ではなく重さの程度を言うので、〈多い〉は合わない。"}, {"text": "この道は幅が多いので、車がすれ違えない。", "explanation": "ここは〈狭い〉の意味。道の幅は数ではなく広さを言うので、〈多い〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の後、川の水量がかなり多いかった。", "corrected_sentence": "雨の後、川の水量がかなり多かった。", "error_description": "過去形は「多かった」。「多いかった」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "多く", "is_correct": true, "explanation": "連用形。「雨が多く、〜」と中止形で続け、「一年を通して」の傾向を述べるので、この文に合う。"}, {"text": "多きく", "is_correct": false, "explanation": "「多きく」は形容詞の誤った活用形。正しい連用形は「多く」。"}, {"text": "多いく", "is_correct": false, "explanation": "「多いく」は形容詞の誤った活用形。正しい連用形は「多く」。"}, {"text": "多かく", "is_correct": false, "explanation": "「多かく」は形容詞の誤った活用形。正しい連用形は「多く」。"}], "correct_form": "多く", "base_form": "多い", "form_label": "連用形", "sentence_index": 1, "explanations": {"多く": "連用形。「雨が多く、〜」と中止形で続け、「一年を通して」の傾向を述べるので、この文に合う。", "多きく": "「多きく」は形容詞の誤った活用形。正しい連用形は「多く」。", "多いく": "「多いく」は形容詞の誤った活用形。正しい連用形は「多く」。", "多かく": "「多かく」は形容詞の誤った活用形。正しい連用形は「多く」。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36763, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域は地震を多く、建物の補強が進んでいる。", "corrected_sentence": "この地域は地震が多く、建物の補強が進んでいる。", "error_description": "「地震が多い」の主語は「が」。「を」は目的語の印なので、形容詞「多い」の主語には使わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "多くて", "is_correct": true, "explanation": "て形。「出費が多くて、〜できなかった」と理由を続ける形で、この文に合う。"}, {"text": "多い", "is_correct": false, "explanation": "辞書形。理由を「て」で続けられず、「多い、貯金ができなかった」と文がつながらない。"}, {"text": "多いくて", "is_correct": false, "explanation": "「多いくて」は形容詞の誤った活用形。正しいて形は「多くて」。"}, {"text": "多かくて", "is_correct": false, "explanation": "「多かくて」は形容詞の誤った活用形。正しいて形は「多くて」。"}], "correct_form": "多くて", "base_form": "多い", "form_label": "て形", "sentence_index": 7, "explanations": {"多くて": "て形。「出費が多くて、〜できなかった」と理由を続ける形で、この文に合う。", "多い": "辞書形。理由を「て」で続けられず、「多い、貯金ができなかった」と文がつながらない。", "多いくて": "「多いくて」は形容詞の誤った活用形。正しいて形は「多くて」。", "多かくて": "「多かくて」は形容詞の誤った活用形。正しいて形は「多くて」。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
