INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「肝臓の疾患を指摘された」の「を」は、指摘される対象の「疾患」を示すので正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は人や相手を示すので、病名に付けると「指摘された」の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、指摘の対象には付かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は出どころを示すので、指摘の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「肝臓の疾患を指摘された」の「を」は、指摘される対象の「疾患」を示すので正しい。", "に": "「に」は人や相手を示すので、病名に付けると「指摘された」の文として不自然。", "へ": "「へ」は方向を示すので、指摘の対象には付かない。", "から": "「から」は出どころを示すので、指摘の対象を表せない。"}, "error_tags": {"に": "相手: 病名は指摘の相手にならず不自然", "へ": "direction: 指摘する相手や方向を示すが、疾患には向かない", "から": "source: 出どころを示すが、指摘の対象を表せない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体の一部に現れる病気のこと。", "primary_collocate": null, "pronunciation": "しっかん", "ipa": "ɕikkaɴ", "syllable_count": 4, "sentences": [{"text": "彼は心臓に疾患があり、定期的に病院へ行く。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "彼[かれ]は心臓[しんぞう]に疾患[しっかん]があり、定期的[ていきてき]に病院[びょういん]へ行[い]く。", "sentence_source": "generated"}, {"text": "目の疾患は、早く見つけるほど治しやすい。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "目[め]の疾患[しっかん]は、早[はや]く見[み]つけるほど治[なお]しやすい。", "sentence_source": "generated"}, {"text": "医者は、肺の疾患の可能性があると言った。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、肺[はい]の疾患[しっかん]の可能性[かのうせい]があると言[い]った。", "sentence_source": "generated"}, {"text": "祖父は長い間、腎臓の疾患に苦しんでいる。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "祖父[そふ]は長[なが]い間[あいだ]、腎臓[じんぞう]の疾患[しっかん]に苦[くる]しんでいる。", "sentence_source": "generated"}, {"text": "皮膚の疾患のため、強い薬は使えません。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "皮膚[ひふ]の疾患[しっかん]のため、強[つよ]い薬[くすり]は使[つか]えません。", "sentence_source": "generated"}, {"text": "検査で、胃の疾患が見つかりました。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "検査[けんさ]で、胃[い]の疾患[しっかん]が見[み]つかりました。", "sentence_source": "generated"}, {"text": "耳の疾患で、片方の耳がよく聞こえない。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "耳[みみ]の疾患[しっかん]で、片方[かたほう]の耳[みみ]がよく聞[き]こえない。", "sentence_source": "generated"}, {"text": "会社の健診で、肝臓の疾患を指摘された。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の健診[けんしん]で、肝臓[かんぞう]の疾患[しっかん]を指摘[してき]された。", "sentence_source": "generated"}, {"text": "疾患のある部分を、医者が丁寧に調べた。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "疾患[しっかん]のある部分[ぶぶん]を、医者[いしゃ]が丁寧[ていねい]に調[しら]べた。", "sentence_source": "generated"}, {"text": "歯ぐきの疾患は、放っておくと悪くなる。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "歯[は]ぐきの疾患[しっかん]は、放[ほう]っておくと悪[わる]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疾患", "label": "基本形"}, {"form": "疾患の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "心臓・目・皮膚など体の特定の部位に現れる病気。『〜に疾患がある』", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾患", "is_correct": true, "explanation": "心臓の病気を指す語で、「心臓に〜がある」という形に入る。"}, {"text": "薬剤", "is_correct": false, "explanation": "薬の意味で、「心臓に薬剤がある」とは言わないので合わない。"}, {"text": "栄養", "is_correct": false, "explanation": "体に取り入れるものを指し、心臓の場所に「栄養がある」とは続かない。"}, {"text": "呼吸", "is_correct": false, "explanation": "息を吸ったり吐いたりする動作で、「心臓に呼吸がある」は成り立たない。"}], "explanations": {"疾患": "心臓の病気を指す語で、「心臓に〜がある」という形に入る。", "薬剤": "薬の意味で、「心臓に薬剤がある」とは言わないので合わない。", "栄養": "体に取り入れるものを指し、心臓の場所に「栄養がある」とは続かない。", "呼吸": "息を吸ったり吐いたりする動作で、「心臓に呼吸がある」は成り立たない。"}, "sentence_index": 0, "correct_answer": "疾患"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強い雨で、川の堤防に疾患が見つかった。", "explanation": "ここは〈損傷〉の意味。堤防のいたみは損傷と言い、病気を指す疾患は使わない。"}, {"text": "新しく買った車の疾患を、販売店が無料で直してくれた。", "explanation": "ここは〈欠陥〉の意味。機械の不具合は欠陥と言い、体の病気を指す疾患は車には使わない。"}, {"text": "長く使った椅子の疾患が、少しずつ広がっている。", "explanation": "ここは〈傷み〉の意味。椅子の劣化は傷みと言い、病気を指す疾患は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疾患", "is_correct": true, "explanation": "耳の病気を指す語で、「耳の〜で、聞こえない」の原因として入る。"}, {"text": "包丁", "is_correct": false, "explanation": "台所で使う道具で、耳の状態の原因にはならない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさを表すだけで、耳が聞こえない原因にはならない。"}, {"text": "手袋", "is_correct": false, "explanation": "手にはめる物で、耳の状態を表す語としては合わない。"}], "explanations": {"疾患": "耳の病気を指す語で、「耳の〜で、聞こえない」の原因として入る。", "包丁": "台所で使う道具で、耳の状態の原因にはならない。", "音量": "音の大きさを表すだけで、耳が聞こえない原因にはならない。", "手袋": "手にはめる物で、耳の状態を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "疾患"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歯ぐきの疾患は、熱湯で煮ると死ぬ。", "explanation": "ここは〈細菌〉の意味。煮て死ぬのは細菌などの生き物で、病気そのものを指す疾患は死なない。"}, {"text": "隣家の疾患が止まらず、朝まで眠れなかった。", "explanation": "ここは〈騒音〉の意味。止まらず眠れないほどの騒ぎは騒音と言い、病名の疾患は使わない。"}, {"text": "胃は食べ物を消化する疾患だ。", "explanation": "ここは〈器官〉の意味。胃は消化をする体の器官で、病気を指す疾患とは別物だ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は肝臓の疾患を、定期的に検査を受けている。", "corrected_sentence": "父は肝臓の疾患で、定期的に検査を受けている。", "error_description": "「を」は疾患を目的語にできず、文が成り立たない。原因を表す「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は目の疾患な治療を受けている。", "corrected_sentence": "祖母は目の疾患の治療を受けている。", "error_description": "「疾患」に続く形は「の」。「な」は形容動詞につく語なので、名詞の疾患には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「疾患を持つ」で疾患を目的語にし、慢性的な病気を抱えているという文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「持つ」は人を主語にするので、疾患が主語では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「持つ」の対象を示さず、「疾患に持つ」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「持つ」の対象にはならず、「疾患で持つ」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「疾患を持つ」で疾患を目的語にし、慢性的な病気を抱えているという文が成り立つ。", "が": "「持つ」は人を主語にするので、疾患が主語では文が成り立たない。", "に": "「持つ」の対象を示さず、「疾患に持つ」では意味が通らない。", "で": "手段や場所を示すが、「持つ」の対象にはならず、「疾患で持つ」は成り立たない。"}, "error_tags": {"が": "subject: 「持つ」は人を主語にするので、疾患が主語では文が成り立たない", "に": "direction: 持つ対象を示さず、ここでは意味が合わない", "で": "means: 手段や場所を示すが、「持つ」の対象にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「疾患の種類」の形で疾患を修飾する名詞句になり、文の主題として成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は名詞どうしを結べず、「疾患に種類」は修飾関係にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、「疾患へ種類」では修飾関係にならない。"}, {"text": "から", "is_correct": false, "explanation": "出どころを示すが、名詞を続ける形にはならず「疾患から種類」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「疾患の種類」の形で疾患を修飾する名詞句になり、文の主題として成り立つ。", "に": "「に」は名詞どうしを結べず、「疾患に種類」は修飾関係にならない。", "へ": "方向を示すので、「疾患へ種類」では修飾関係にならない。", "から": "出どころを示すが、名詞を続ける形にはならず「疾患から種類」は成り立たない。"}, "error_tags": {"に": "direction: 名詞を結べず、疾患の種類を表せない", "へ": "direction: 方向を示すので、疾患の種類を表す形にならない", "から": "source: 出どころを示すが、名詞を続ける形にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "からだのしくみや器官に起こる、異常な状態や病気。", "primary_collocate": null, "pronunciation": "しっかん", "ipa": "ɕikkaɴ", "syllable_count": 4, "sentences": [{"text": "呼吸のしくみに疾患があると、息が苦しくなる。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "呼吸[こきゅう]のしくみに疾患[しっかん]があると、息[いき]が苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "慢性的な疾患を持つ人は、毎日薬を飲む。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "慢性的[まんせいてき]な疾患[しっかん]を持[も]つ人[ひと]は、毎日[まいにち]薬[くすり]を飲[の]む。", "sentence_source": "generated"}, {"text": "生まれつきの疾患で、体の機能がうまく働かない。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "生[う]まれつきの疾患[しっかん]で、体[からだ]の機能[きのう]がうまく働[はたら]かない。", "sentence_source": "generated"}, {"text": "この病院は、子どもの疾患を専門にしている。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、子[こ]どもの疾患[しっかん]を専門[せんもん]にしている。", "sentence_source": "generated"}, {"text": "脳の疾患は、発見が遅れると危険だ。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "脳[のう]の疾患[しっかん]は、発見[はっけん]が遅[おく]れると危険[きけん]だ。", "sentence_source": "generated"}, {"text": "医学部では、さまざまな疾患の原因を学ぶ。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "医学部[いがくぶ]では、さまざまな疾患[しっかん]の原因[げんいん]を学[まな]ぶ。", "sentence_source": "generated"}, {"text": "血液の疾患が疑われ、くわしい検査をした。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "血液[けつえき]の疾患[しっかん]が疑[うたが]われ、くわしい検査[けんさ]をした。", "sentence_source": "generated"}, {"text": "疾患の種類によって、治療の方法は変わる。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "疾患[しっかん]の種類[しゅるい]によって、治療[ちりょう]の方法[ほうほう]は変[か]わる。", "sentence_source": "generated"}, {"text": "ストレスが原因で起こる疾患も少なくない。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "ストレスが原因[げんいん]で起[お]こる疾患[しっかん]も少[すく]なくない。", "sentence_source": "generated"}, {"text": "彼女は神経の疾患と診断され、休職した。", "target_word": "疾患", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は神経[しんけい]の疾患[しっかん]と診断[しんだん]され、休職[きゅうしょく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疾患", "label": "基本形"}, {"form": "疾患の", "label": "連体形（の）"}], "register": "formal", "sense_fingerprint": "体のしくみ・器官の機能に生じた異常な状態や病気。医学的な病気の種類としての疾患", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾患", "is_correct": true, "explanation": "体のしくみの異常を表す語で、「呼吸のしくみに〜がある」に入る。"}, {"text": "包帯", "is_correct": false, "explanation": "傷を覆う布で、体のしくみの異常を表す語ではない。"}, {"text": "検診", "is_correct": false, "explanation": "健康を調べる検査で、しくみの中に「ある」とは言わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の水分量を表し、体のしくみの中にある状態ではない。"}], "explanations": {"疾患": "体のしくみの異常を表す語で、「呼吸のしくみに〜がある」に入る。", "包帯": "傷を覆う布で、体のしくみの異常を表す語ではない。", "検診": "健康を調べる検査で、しくみの中に「ある」とは言わない。", "湿度": "空気の水分量を表し、体のしくみの中にある状態ではない。"}, "sentence_index": 0, "correct_answer": "疾患"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の疾患は、夜になると一気に増える。", "explanation": "ここは〈客足〉の意味。店に来る人数は客足と言い、病名の疾患は使わない。"}, {"text": "彼女は将来への疾患で、夜も眠れない。", "explanation": "ここは〈不安〉の意味。将来を心配する気持ちは不安と言い、病気を指す疾患とは言わない。"}, {"text": "子どもの疾患が、夕方になって上がった。", "explanation": "ここは〈体温〉の意味。数値として上がったり下がったりするのは体温で、疾患は上がるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疾患", "is_correct": true, "explanation": "病気を表す語で、血液の異常として疑われる対象になる。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表し、血液の異常として疑われる語ではない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表すが、血液の状態として疑われる語ではない。"}, {"text": "嗅覚", "is_correct": false, "explanation": "においを感じる感覚で、血液の検査で疑われる対象にはならない。"}], "explanations": {"疾患": "病気を表す語で、血液の異常として疑われる対象になる。", "食欲": "食べたい気持ちを表し、血液の異常として疑われる語ではない。", "体重": "体の重さを表すが、血液の状態として疑われる語ではない。", "嗅覚": "においを感じる感覚で、血液の検査で疑われる対象にはならない。"}, "sentence_index": 6, "correct_answer": "疾患"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仕事が続いて、神経の疾患がたまってしまった。", "explanation": "ここは〈疲労〉の意味。たまっていくのは疲れで、病気の疾患はたまるものではない。"}, {"text": "この包丁の疾患が鈍くなり、よく切れない。", "explanation": "ここは〈切れ味〉の意味。刃の切れ味が落ちることは鈍くなると言い、病名の疾患は使わない。"}, {"text": "神経は全身に信号を送る疾患だ。", "explanation": "ここは〈器官〉の意味。神経は信号を伝える体の器官で、病気を指す疾患とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は脳の疾患を、しばらく入院した。", "corrected_sentence": "兄は脳の疾患で、しばらく入院した。", "error_description": "原因を表す「で」が正しい。「を」では疾患が入院の対象になってしまい、意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36765, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は耳の疾患に診断され、通院している。", "corrected_sentence": "妹は耳の疾患と診断され、通院している。", "error_description": "「診断される」には「と」が続く。「に」では病名が診断の相手のように読めてしまい、診断の内容を表す「と」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「診断で」は判断の根拠・手段を表し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「診断を、ただの疲れだった」では対象を示しても文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「診断が」の後に「は」は続かず、文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「診断へ」は方向を表すが、ここでは「ただの疲れだった」と結びつかない。"}], "correct_answer": "で", "explanations": {"で": "「診断で」は判断の根拠・手段を表し、ここに入る。", "を": "「診断を、ただの疲れだった」では対象を示しても文が成り立たない。", "が": "「診断が」の後に「は」は続かず、文が崩れる。", "へ": "「診断へ」は方向を表すが、ここでは「ただの疲れだった」と結びつかない。"}, "error_tags": {"で": "手段・根拠", "を": "対象", "が": "主語（主格）", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「診断が難しい」の主語を示し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「診断を難しい」は対象を示すが、形容詞「難しい」とは結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "「診断に難しい」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「診断で難しい」は手段を表し、形容詞の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「診断が難しい」の主語を示し、ここに入る。", "を": "「診断を難しい」は対象を示すが、形容詞「難しい」とは結びつかない。", "に": "「診断に難しい」は成り立たない。", "で": "「診断で難しい」は手段を表し、形容詞の主語にはならない。"}, "error_tags": {"が": "主語（主格）", "を": "対象", "に": "帰着点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気かどうかを調べること", "primary_collocate": null, "pronunciation": "しんだん", "ipa": "ɕindaɴ", "syllable_count": 4, "sentences": [{"text": "検査の結果、病気ではないと診断された。", "target_word": "診断", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]、病気[びょうき]ではないと診断[しんだん]された。", "sentence_source": "generated"}, {"text": "医者の診断では、ただの疲れだった。", "target_word": "診断", "complexity_tier": "T3", "furigana": "医者[いしゃ]の診断[しんだん]では、ただの疲[つか]れだった。", "sentence_source": "generated"}, {"text": "病気かどうか、早く診断してもらいたい。", "target_word": "診断", "complexity_tier": "T3", "furigana": "病気[びょうき]かどうか、早[はや]く診断[しんだん]してもらいたい。", "sentence_source": "generated"}, {"text": "熱が続くので、病院で診断を受けた。", "target_word": "診断", "complexity_tier": "T3", "furigana": "熱[ねつ]が続[つづ]くので、病院[びょういん]で診断[しんだん]を受[う]けた。", "sentence_source": "generated"}, {"text": "診断が出るまで、三日かかった。", "target_word": "診断", "complexity_tier": "T3", "furigana": "診断[しんだん]が出[で]るまで、三日[みっか]かかった。", "sentence_source": "generated"}, {"text": "若い医者が、短い時間で正しく診断した。", "target_word": "診断", "complexity_tier": "T3", "furigana": "若[わか]い医者[いしゃ]が、短[みじか]い時間[じかん]で正[ただ]しく診断[しんだん]した。", "sentence_source": "generated"}, {"text": "診断の結果を聞いて、家族は安心した。", "target_word": "診断", "complexity_tier": "T3", "furigana": "診断[しんだん]の結果[けっか]を聞[き]いて、家族[かぞく]は安心[あんしん]した。", "sentence_source": "generated"}, {"text": "子どもの病気は、診断が難しいことがある。", "target_word": "診断", "complexity_tier": "T3", "furigana": "子[こ]どもの病気[びょうき]は、診断[しんだん]が難[むずか]しいことがある。", "sentence_source": "generated"}, {"text": "診断を受けなかったら、病気に気づかなかっただろう。", "target_word": "診断", "complexity_tier": "T3", "furigana": "診断[しんだん]を受[う]けなかったら、病気[びょうき]に気[き]づかなかっただろう。", "sentence_source": "generated"}, {"text": "母は、軽い病気だと診断されて、すぐに家へ帰った。", "target_word": "診断", "complexity_tier": "T3", "furigana": "母[はは]は、軽[かる]い病気[びょうき]だと診断[しんだん]されて、すぐに家[いえ]へ帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "診断", "label": "基本形"}, {"form": "診断する", "label": "辞書形"}, {"form": "診断して", "label": "て形"}, {"form": "診断した", "label": "た形"}, {"form": "診断される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "医者が病気であるかどうかを調べて確かめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "診断", "is_correct": true, "explanation": "「病気ではないと〜された」は、検査の結果として病気かどうかを判定したことを表し、ここに合う。"}, {"text": "通院", "is_correct": false, "explanation": "病院へ通うことで、判定の意味にならない。「病気ではないと通院された」は成り立たない。"}, {"text": "退院", "is_correct": false, "explanation": "入院中の患者が病院を出ることで、病気かどうかの判定とは関係がない。"}, {"text": "注射", "is_correct": false, "explanation": "薬を体に入れる処置で、「病気ではないと注射された」では判定の内容にならない。"}], "explanations": {"診断": "「病気ではないと〜された」は、検査の結果として病気かどうかを判定したことを表し、ここに合う。", "通院": "病院へ通うことで、判定の意味にならない。「病気ではないと通院された」は成り立たない。", "退院": "入院中の患者が病院を出ることで、病気かどうかの判定とは関係がない。", "注射": "薬を体に入れる処置で、「病気ではないと注射された」では判定の内容にならない。"}, "sentence_index": 0, "correct_answer": "診断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "証拠を見て、彼が犯人だと診断した。", "explanation": "ここは〈判断〉の意味。診断は病気や症状を調べて判定することで、犯人を判定する場面には使わないので合わない。"}, {"text": "明日の天気を診断した。", "explanation": "ここは〈予測〉の意味。明日の天気は予測・予報で述べるもので、診断は現在の病気や症状の状態を判定する語なので合わない。"}, {"text": "散らかった机を、母が診断した。", "explanation": "ここは〈整理〉の意味。机を片付けることは整理で、診断は病気や症状の判定に使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "診断", "is_correct": true, "explanation": "「診断の結果」は病気の判定を指し、結果を聞いて家族が安心する文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は結果を生む行為ではなく、「散歩の結果を聞いて安心した」という文にはならない。"}, {"text": "休憩", "is_correct": false, "explanation": "休憩は結果を伝えられる性質のものではなく、「休憩の結果」は不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は結果として聞くものではなく、家族が安心する内容に結びつかない。"}], "explanations": {"診断": "「診断の結果」は病気の判定を指し、結果を聞いて家族が安心する文に合う。", "散歩": "散歩は結果を生む行為ではなく、「散歩の結果を聞いて安心した」という文にはならない。", "休憩": "休憩は結果を伝えられる性質のものではなく、「休憩の結果」は不自然。", "天気": "天気は結果として聞くものではなく、家族が安心する内容に結びつかない。"}, "sentence_index": 6, "correct_answer": "診断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ばらばらの証拠から、犯人の動機を診断した。", "explanation": "ここは〈推理〉の意味。犯人の動機は推理で導くもので、診断は病気や症状を判定する語なので合わない。"}, {"text": "難しい英語の手紙を、一文ずつ診断した。", "explanation": "ここは〈翻訳〉の意味。外国語の文を別の言語に置き換える行為で、診断は病気の判定に使う語なので合わない。"}, {"text": "新しい曲を診断した。", "explanation": "ここは〈作曲〉の意味。曲を作る行為は作曲で、診断は病気や症状を判定する語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医者の診断を、軽い風邪だと分かった。", "corrected_sentence": "医者の診断で、軽い風邪だと分かった。", "error_description": "「診断」に付く助詞が「を」になっている。正しくは「で」（根拠・手段）。診断を根拠にして分かったという意味なので「で」が必要で、「を」では対象にならず「分かった」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この病気は、診断を難しいと言われている。", "corrected_sentence": "この病気は、診断が難しいと言われている。", "error_description": "形容詞「難しい」の主語となる「診断」には「が」が必要。「を」は動作の対象を示すので、形容詞「難しい」とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
