INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36767, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気や症状の状態を調べて判断すること", "primary_collocate": null, "pronunciation": "しんだん", "ipa": "ɕindaɴ", "syllable_count": 4, "sentences": [{"text": "医者は、傷の状態を見て、骨折と診断した。", "target_word": "診断", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、傷[きず]の状態[じょうたい]を見[み]て、骨折[こっせつ]と診断[しんだん]した。", "sentence_source": "generated"}, {"text": "症状が重いと診断され、すぐ入院することになった。", "target_word": "診断", "complexity_tier": "T3", "furigana": "症状[しょうじょう]が重[おも]いと診断[しんだん]され、すぐ入院[にゅういん]することになった。", "sentence_source": "generated"}, {"text": "医者は、咳と熱から風邪だと診断した。", "target_word": "診断", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、咳[せき]と熱[ねつ]から風邪[かぜ]だと診断[しんだん]した。", "sentence_source": "generated"}, {"text": "医者の診断で、胃の調子が悪い原因は食べ過ぎだと分かった。", "target_word": "診断", "complexity_tier": "T3", "furigana": "医者[いしゃ]の診断[しんだん]で、胃[い]の調子[ちょうし]が悪[わる]い原因[げんいん]は食[た]べ過[す]ぎだと分[わ]かった。", "sentence_source": "generated"}, {"text": "症状をくわしく調べないと、正しい診断はできない。", "target_word": "診断", "complexity_tier": "T3", "furigana": "症状[しょうじょう]をくわしく調[しら]べないと、正[ただ]しい診断[しんだん]はできない。", "sentence_source": "generated"}, {"text": "診断によると、病気はまだ初期の段階だ。", "target_word": "診断", "complexity_tier": "T3", "furigana": "診断[しんだん]によると、病気[びょうき]はまだ初期[しょき]の段階[だんかい]だ。", "sentence_source": "generated"}, {"text": "彼は検査の数字を見て、糖尿病だと診断された。", "target_word": "診断", "complexity_tier": "T3", "furigana": "彼[かれ]は検査[けんさ]の数字[すうじ]を見[み]て、糖尿病[とうにょうびょう]だと診断[しんだん]された。", "sentence_source": "generated"}, {"text": "医者が症状を見て診断を下すまで、静かに待った。", "target_word": "診断", "complexity_tier": "T3", "furigana": "医者[いしゃ]が症状[しょうじょう]を見[み]て診断[しんだん]を下[くだ]すまで、静[しず]かに待[ま]った。", "sentence_source": "generated"}, {"text": "診断が正しかったので、薬がよく効いた。", "target_word": "診断", "complexity_tier": "T3", "furigana": "診断[しんだん]が正[ただ]しかったので、薬[くすり]がよく効[き]いた。", "sentence_source": "generated"}, {"text": "祖父は、早い診断のおかげで、大事にならずにすんだ。", "target_word": "診断", "complexity_tier": "T3", "furigana": "祖父[そふ]は、早[はや]い診断[しんだん]のおかげで、大事[おおごと]にならずにすんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "診断", "label": "基本形"}, {"form": "診断する", "label": "辞書形"}, {"form": "診断して", "label": "て形"}, {"form": "診断した", "label": "た形"}, {"form": "診断される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "症状や体の状態を調べて、病名や程度を判断すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "診断", "is_correct": true, "explanation": "「骨折と診断した」は傷の状態から病名を判定したことを表し、ここに合う。"}, {"text": "延期", "is_correct": false, "explanation": "日程を先送りする意味で、「骨折と延期した」という判定の文にはならない。"}, {"text": "退院", "is_correct": false, "explanation": "入院中の患者が病院を出ることで、骨折の判定を表す文にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "部屋などを片付ける行為で、「骨折と掃除した」は病名の判定の文にならない。"}], "explanations": {"診断": "「骨折と診断した」は傷の状態から病名を判定したことを表し、ここに合う。", "延期": "日程を先送りする意味で、「骨折と延期した」という判定の文にはならない。", "退院": "入院中の患者が病院を出ることで、骨折の判定を表す文にならない。", "掃除": "部屋などを片付ける行為で、「骨折と掃除した」は病名の判定の文にならない。"}, "sentence_index": 0, "correct_answer": "診断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の勝敗を、審判が診断した。", "explanation": "ここは〈判定〉の意味。試合の勝敗は判定で決めるもので、診断は病気や症状を判定する語なので合わない。"}, {"text": "明日の天気を、テレビが診断した。", "explanation": "ここは〈予報〉の意味。天気の見通しは予報で伝えるもので、診断は病気や症状の状態を判定する語なので合わない。"}, {"text": "会議の発言を、通訳が診断した。", "explanation": "ここは〈通訳〉の意味。発言を別の言語で伝える行為で、診断は病気の判定に使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "診断", "is_correct": true, "explanation": "「糖尿病だと〜された」は数字から病名を判定されたことを表し、ここに合う。"}, {"text": "宣伝", "is_correct": false, "explanation": "商品などを広める意味で、「糖尿病だと宣伝された」は成り立たない。"}, {"text": "取材", "is_correct": false, "explanation": "情報を集める行為で、病名の判定の形にはならない。"}, {"text": "注射", "is_correct": false, "explanation": "薬を体に入れる処置で、「糖尿病だと注射された」では病名の判定を表せない。"}], "explanations": {"診断": "「糖尿病だと〜された」は数字から病名を判定されたことを表し、ここに合う。", "宣伝": "商品などを広める意味で、「糖尿病だと宣伝された」は成り立たない。", "取材": "情報を集める行為で、病名の判定の形にはならない。", "注射": "薬を体に入れる処置で、「糖尿病だと注射された」では病名の判定を表せない。"}, "sentence_index": 6, "correct_answer": "診断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "答案を、先生が一つずつ診断した。", "explanation": "ここは〈採点〉の意味。答案に点数をつける行為は採点で、診断は病気や症状を判定する語なので合わない。"}, {"text": "新しいメロディーを診断した。", "explanation": "ここは〈作曲〉の意味。メロディーを作る行為は作曲で、診断は病気や症状の判定に使う語なので合わない。"}, {"text": "事件の動機を、刑事が診断した。", "explanation": "ここは〈推理〉の意味。事件の動機を推理で導く行為で、診断は病気や症状を判定する語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胃の調子が悪い原因は、医者の診断に分かった。", "corrected_sentence": "胃の調子が悪い原因は、医者の診断で分かった。", "error_description": "「分かった」の根拠・手段を示す助詞が「に」になっている。正しくは「で」。「に」は帰着点を表し、「診断によって分かった」の意味にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "症状が似ているので、医者の診断に受けた。", "corrected_sentence": "症状が似ているので、医者の診断を受けた。", "error_description": "「診断を受ける」の「を」が正しい。「に」では「受ける」の対象にならず、「診断に受けた」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「治療を受けた」の対象を示し、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「治療に受けた」は受ける対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「治療で受けた」は手段を示し、「受けた」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「治療へ受けた」は方向を表すが、「受ける」とは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "「治療を受けた」の対象を示し、ここに入る。", "に": "「治療に受けた」は受ける対象として成り立たない。", "で": "「治療で受けた」は手段を示し、「受けた」の対象にはならない。", "へ": "「治療へ受けた」は方向を表すが、「受ける」とは結びつかない。"}, "error_tags": {"に": "帰着点", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「治療を終えた」の対象を示し、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「治療に終えた」は対象を示せず、「終える」とは結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "「治療と終えて」は並列や相手を示すが、「終える」の対象にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「治療が終えて」は「終える」の対象を主語にできず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「治療を終えた」の対象を示し、ここに入る。", "に": "「治療に終えた」は対象を示せず、「終える」とは結びつかない。", "と": "「治療と終えて」は並列や相手を示すが、「終える」の対象にはならない。", "が": "「治療が終えて」は「終える」の対象を主語にできず、文が成り立たない。"}, "error_tags": {"に": "帰着点", "と": "相手・並列", "が": "主語（主格）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気やけがをよくするために、お医者さんがすることです。", "primary_collocate": null, "pronunciation": "ちりょう", "ipa": "tɕiɾʲoː", "syllable_count": 4, "sentences": [{"text": "医者はけがをした足の治療をすぐに始めた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "医者[いしゃ]はけがをした足[あし]の治療[ちりょう]をすぐに始[はじ]めた。", "sentence_source": "generated"}, {"text": "病院で歯の治療を受けたので、今日は少し口が痛い。", "target_word": "治療", "complexity_tier": "T3", "furigana": "病院[びょういん]で歯[は]の治療[ちりょう]を受[う]けたので、今日[きょう]は少[すこ]し口[くち]が痛[いた]い。", "sentence_source": "generated"}, {"text": "治療が終わるまで、毎週病院に通わなければならない。", "target_word": "治療", "complexity_tier": "T3", "furigana": "治療[ちりょう]が終[お]わるまで、毎週[まいしゅう]病院[びょういん]に通[かよ]わなければならない。", "sentence_source": "generated"}, {"text": "風邪の治療のために、母は私を病院へ連れて行った。", "target_word": "治療", "complexity_tier": "T3", "furigana": "風邪[かぜ]の治療[ちりょう]のために、母[はは]は私[わたし]を病院[びょういん]へ連[つ]れて行[い]った。", "sentence_source": "generated"}, {"text": "この病気は早く治療すれば、すぐによくなる。", "target_word": "治療", "complexity_tier": "T3", "furigana": "この病気[びょうき]は早[はや]く治療[ちりょう]すれば、すぐによくなる。", "sentence_source": "generated"}, {"text": "犬のけがの治療は、動物病院の先生がしてくれた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "犬[いぬ]のけがの治療[ちりょう]は、動物病院[どうぶつびょういん]の先生[せんせい]がしてくれた。", "sentence_source": "generated"}, {"text": "治療のあとで、医者は家で気をつけることを話した。", "target_word": "治療", "complexity_tier": "T3", "furigana": "治療[ちりょう]のあとで、医者[いしゃ]は家[いえ]で気[き]をつけることを話[はな]した。", "sentence_source": "generated"}, {"text": "彼は長い治療を終えて、やっと仕事に戻れた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "彼[かれ]は長[なが]い治療[ちりょう]を終[お]えて、やっと仕事[しごと]に戻[もど]れた。", "sentence_source": "generated"}, {"text": "治療の時間が長くて、待合室の子どもたちは疲れていた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "治療[ちりょう]の時間[じかん]が長[なが]くて、待合室[まちあいしつ]の子[こ]どもたちは疲[つか]れていた。", "sentence_source": "generated"}, {"text": "けがを治療してもらったので、先生にお礼を言った。", "target_word": "治療", "complexity_tier": "T3", "furigana": "けがを治療[ちりょう]してもらったので、先生[せんせい]にお礼[れい]を言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治療する", "label": "する動詞の辞書形"}, {"form": "治療した", "label": "過去形"}, {"form": "治療して", "label": "て形"}, {"form": "治療すれば", "label": "仮定形"}], "register": "neutral（普通体）", "sense_fingerprint": "病気やけがをよくするために医者が行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治療", "is_correct": true, "explanation": "「足の治療を始めた」はけがを治す医療行為を指し、ここに合う。"}, {"text": "予約", "is_correct": false, "explanation": "日時を取る行為で、けがを治す内容を表さず、「足の予約を始めた」は不自然。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを落とす行為で、けがを治す意味にならない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く運動の意味になり、けがの治療とは関係がない。"}], "explanations": {"治療": "「足の治療を始めた」はけがを治す医療行為を指し、ここに合う。", "予約": "日時を取る行為で、けがを治す内容を表さず、「足の予約を始めた」は不自然。", "掃除": "汚れを落とす行為で、けがを治す意味にならない。", "散歩": "歩く運動の意味になり、けがの治療とは関係がない。"}, "sentence_index": 0, "correct_answer": "治療"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "難しい英語の論文を、友人が治療した。", "explanation": "ここは〈翻訳〉の意味。外国語の文を別の言語に置き換えることは翻訳で、治療は病気やけがを治す語なので合わない。"}, {"text": "壊れた自転車を、店が治療した。", "explanation": "ここは〈修理〉の意味。機械や道具を直すことは修理で、治療は病気やけがを治す語なので合わない。"}, {"text": "汚れた部屋を、母が治療した。", "explanation": "ここは〈掃除〉の意味。部屋をきれいにすることは掃除で、治療は病気やけがに使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治療", "is_correct": true, "explanation": "「治療のあと」は治療後の注意を指し、医者が家での注意を話す文に合う。"}, {"text": "給料", "is_correct": false, "explanation": "給料の後に医者が家での注意を話す、という文の流れに合わない。"}, {"text": "選挙", "is_correct": false, "explanation": "選挙の後に医者が家での注意を話す文は成り立たない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行の後に医者が家での注意を話すのは不自然で、治療後の注意という意味にならない。"}], "explanations": {"治療": "「治療のあと」は治療後の注意を指し、医者が家での注意を話す文に合う。", "給料": "給料の後に医者が家での注意を話す、という文の流れに合わない。", "選挙": "選挙の後に医者が家での注意を話す文は成り立たない。", "旅行": "旅行の後に医者が家での注意を話すのは不自然で、治療後の注意という意味にならない。"}, "sentence_index": 6, "correct_answer": "治療"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に、車のエンジンを治療した。", "explanation": "ここは〈修理〉の意味。壊れた機械を直すのは修理で、治療は病気やけがを治す語なので合わない。"}, {"text": "新人を治療した。", "explanation": "ここは〈指導〉の意味。人に仕事を教えて導くのは指導で、治療は病気やけがを治す語なので合わない。"}, {"text": "ピアノを治療した。", "explanation": "ここは〈演奏〉の意味。楽器で音楽を奏でるのは演奏で、治療は病気やけがに使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この病気は、薬の治療を治った。", "corrected_sentence": "この病気は、薬の治療で治った。", "error_description": "「治る」は自動詞なので「を」は不要。治した手段を表す「で」にする。「治療を治った」は文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36768, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は長い治療に受けて、やっと仕事に戻れた。", "corrected_sentence": "彼は長い治療を受けて、やっと仕事に戻れた。", "error_description": "「治療を受ける」の「を」が正しい。「に」では「受ける」の対象にならず、結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「治療が必要だ」の主語を示し、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「必要だ」は主語に「が」を取るので、「治療を必要だ」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「治療で必要だ」は手段を表し、「必要だ」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「治療へ必要だ」は方向を表すが、「必要だ」とは結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「治療が必要だ」の主語を示し、ここに入る。", "を": "「必要だ」は主語に「が」を取るので、「治療を必要だ」は不自然。", "で": "「治療で必要だ」は手段を表し、「必要だ」の主語にはならない。", "へ": "「治療へ必要だ」は方向を表すが、「必要だ」とは結びつかない。"}, "error_tags": {"を": "対象", "で": "手段・根拠", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
