INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気やけがを治すために、薬を使ったり、手術をしたりすること。", "primary_collocate": null, "pronunciation": "ちりょう", "ipa": "tɕiɾʲoː", "syllable_count": 4, "sentences": [{"text": "医者は薬を使った治療で、彼の病気を少しずつよくしていった。", "target_word": "治療", "complexity_tier": "T3", "furigana": "医者[いしゃ]は薬[くすり]を使[つか]った治療[ちりょう]で、彼[かれ]の病気[びょうき]を少[すこ]しずつよくしていった。", "sentence_source": "generated"}, {"text": "手術による治療が必要だと言われて、父は入院を決めた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]による治療[ちりょう]が必要[ひつよう]だと言[い]われて、父[ちち]は入院[にゅういん]を決[き]めた。", "sentence_source": "generated"}, {"text": "この病気の治療には、毎日薬を飲み続けることが大切だ。", "target_word": "治療", "complexity_tier": "T3", "furigana": "この病気[びょうき]の治療[ちりょう]には、毎日[まいにち]薬[くすり]を飲[の]み続[つづ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "祖母は肩の痛みを治療するため、手術を受けた。", "target_word": "治療", "complexity_tier": "T3", "furigana": "祖母[そぼ]は肩[かた]の痛[いた]みを治療[ちりょう]するため、手術[しゅじゅつ]を受[う]けた。", "sentence_source": "generated"}, {"text": "新しい薬が見つかり、がんの治療は大きく進歩した。", "target_word": "治療", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]が見[み]つかり、がんの治療[ちりょう]は大[おお]きく進歩[しんぽ]した。", "sentence_source": "generated"}, {"text": "治療の方法には、薬を使う方法と手術をする方法がある。", "target_word": "治療", "complexity_tier": "T3", "furigana": "治療[ちりょう]の方法[ほうほう]には、薬[くすり]を使[つか]う方法[ほうほう]と手術[しゅじゅつ]をする方法[ほうほう]がある。", "sentence_source": "generated"}, {"text": "手術のあとの治療は、薬を飲むだけで、痛みはほとんどなかった。", "target_word": "治療", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]のあとの治療[ちりょう]は、薬[くすり]を飲[の]むだけで、痛[いた]みはほとんどなかった。", "sentence_source": "generated"}, {"text": "高い薬を使う治療なので、費用が心配だと姉は言った。", "target_word": "治療", "complexity_tier": "T3", "furigana": "高[たか]い薬[くすり]を使[つか]う治療[ちりょう]なので、費用[ひよう]が心配[しんぱい]だと姉[あね]は言[い]った。", "sentence_source": "generated"}, {"text": "医者は注射と薬で、娘の肺炎を治療した。", "target_word": "治療", "complexity_tier": "T3", "furigana": "医者[いしゃ]は注射[ちゅうしゃ]と薬[くすり]で、娘[むすめ]の肺炎[はいえん]を治療[ちりょう]した。", "sentence_source": "generated"}, {"text": "手術だけでなく、その後の薬による治療も大切だ。", "target_word": "治療", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]だけでなく、その後[ご]の薬[くすり]による治療[ちりょう]も大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "治療する", "label": "する動詞の辞書形"}, {"form": "治療した", "label": "過去形"}, {"form": "治療して", "label": "て形"}, {"form": "治療すれば", "label": "仮定形"}], "register": "neutral（普通体）", "sense_fingerprint": "薬や手術などの方法で病気やけがを治すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治療", "is_correct": true, "explanation": "「薬を使った治療」は病気を治す医療行為を指し、病気が少しずつよくなる文に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "薬を使った旅行では、病気をよくする意味にならない。"}, {"text": "練習", "is_correct": false, "explanation": "薬を使った練習では、病気の改善を表せない。"}, {"text": "講義", "is_correct": false, "explanation": "薬を使った講義は成り立たず、病気を治す内容にならない。"}], "explanations": {"治療": "「薬を使った治療」は病気を治す医療行為を指し、病気が少しずつよくなる文に合う。", "旅行": "薬を使った旅行では、病気をよくする意味にならない。", "練習": "薬を使った練習では、病気の改善を表せない。", "講義": "薬を使った講義は成り立たず、病気を治す内容にならない。"}, "sentence_index": 0, "correct_answer": "治療"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は新しい曲を治療して、コンサートで演奏した。", "explanation": "ここは〈作曲〉の意味。曲を作ることは作曲で、治療は病気やけがを治す語なので合わない。"}, {"text": "難しい英文の手紙を、友人が治療した。", "explanation": "ここは〈翻訳〉の意味。外国語の文を別の言語に置き換えることは翻訳で、治療は病気やけがに使う語なので合わない。"}, {"text": "テストの答案を、先生が治療した。", "explanation": "ここは〈採点〉の意味。答案に点数をつけることは採点で、治療は病気やけがを治す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治療", "is_correct": true, "explanation": "「手術のあとの治療」は術後の医療行為を指し、薬を飲むと痛みが少なかったという文に合う。"}, {"text": "通訳", "is_correct": false, "explanation": "手術のあとに通訳をするという意味になり、薬を飲む内容に合わない。"}, {"text": "採点", "is_correct": false, "explanation": "手術のあとの採点は成り立たず、薬を飲む内容に結びつかない。"}, {"text": "作曲", "is_correct": false, "explanation": "手術のあとの作曲は成り立たず、痛みの文脈とは結びつかない。"}], "explanations": {"治療": "「手術のあとの治療」は術後の医療行為を指し、薬を飲むと痛みが少なかったという文に合う。", "通訳": "手術のあとに通訳をするという意味になり、薬を飲む内容に合わない。", "採点": "手術のあとの採点は成り立たず、薬を飲む内容に結びつかない。", "作曲": "手術のあとの作曲は成り立たず、痛みの文脈とは結びつかない。"}, "sentence_index": 6, "correct_answer": "治療"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場では、古い機械を毎週治療している。", "explanation": "ここは〈整備〉の意味。機械を良い状態に保つことは整備で、治療は病気やけがに使う語なので合わない。"}, {"text": "母は、三人の子どもを一人で治療した。", "explanation": "ここは〈養育〉の意味。子どもを育てることは養育で、治療は病気やけがを治す語なので合わない。"}, {"text": "会議では、英語の発言を日本語に治療した。", "explanation": "ここは〈通訳〉の意味。発言を別の言語で伝えることは通訳で、治療は病気やけがに使う語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は薬の治療を快方に向かった。", "corrected_sentence": "父は薬の治療で快方に向かった。", "error_description": "「向かう」は自動詞で、「治療を」は対象を示すので不自然。手段を表す「で」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、長い治療が続けている。", "corrected_sentence": "父は、長い治療を続けている。", "error_description": "「続ける」は他動詞で、目的語に「を」を取る。「治療が続けている」は「続く」と「続ける」が混ざった誤りで、「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お茶を提供している」で、提供される物（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「お茶に提供している」は成り立たない。に は相手を示すが、ここは提供される物の位置。"}, {"text": "が", "is_correct": false, "explanation": "「お茶が提供している」は主語の形で、提供の目的語には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「お茶へ提供している」は方向の意味になり、目的語を示す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「お茶を提供している」で、提供される物（目的語）を示す。", "に": "「お茶に提供している」は成り立たない。に は相手を示すが、ここは提供される物の位置。", "が": "「お茶が提供している」は主語の形で、提供の目的語には合わない。", "へ": "「お茶へ提供している」は方向の意味になり、目的語を示す位置には合わない。"}, "error_tags": {"に": "相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「道具を提供した」で、提供される物（目的語）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「道具と提供した」は並列の意味になり、提供の目的語としては不自然。"}, {"text": "から", "is_correct": false, "explanation": "「道具から提供した」は起点を表し、提供の目的語には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「道具の提供した」は成り立たない。の は名詞同士をつなぐ助詞で、ここでは動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「道具を提供した」で、提供される物（目的語）を示す。", "と": "「道具と提供した」は並列の意味になり、提供の目的語としては不自然。", "から": "「道具から提供した」は起点を表し、提供の目的語には合わない。", "の": "「道具の提供した」は成り立たない。の は名詞同士をつなぐ助詞で、ここでは動詞の目的語にならない。"}, "error_tags": {"と": "並列", "から": "起点", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを人にあげること。", "primary_collocate": null, "pronunciation": "ていきょう", "ipa": "teikʲoː", "syllable_count": 4, "sentences": [{"text": "その会社は被災した人たちに食べ物を提供した。", "target_word": "提供", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は被災[ひさい]した人[ひと]たちに食[た]べ物[もの]を提供[ていきょう]した。", "sentence_source": "generated"}, {"text": "店は客に無料でお茶を提供している。", "target_word": "提供", "complexity_tier": "T3", "furigana": "店[みせ]は客[きゃく]に無料[むりょう]でお茶[ちゃ]を提供[ていきょう]している。", "sentence_source": "generated"}, {"text": "友人が提供してくれた部屋に、一週間泊まった。", "target_word": "提供", "complexity_tier": "T3", "furigana": "友人[ゆうじん]が提供[ていきょう]してくれた部屋[へや]に、一週間[いっしゅうかん]泊[と]まった。", "sentence_source": "generated"}, {"text": "地域の団体が、一人暮らしの高齢者に毎週食事を提供している。", "target_word": "提供", "complexity_tier": "T3", "furigana": "地域[ちいき]の団体[だんたい]が、一人[ひとり]暮[ぐ]らしの高齢者[こうれいしゃ]に毎週[まいしゅう]食事[しょくじ]を提供[ていきょう]している。", "sentence_source": "generated"}, {"text": "工場は地域の学校に古いパソコンを提供することにした。", "target_word": "提供", "complexity_tier": "T3", "furigana": "工場[こうじょう]は地域[ちいき]の学校[がっこう]に古[ふる]いパソコンを提供[ていきょう]することにした。", "sentence_source": "generated"}, {"text": "情報の提供に協力してくれた方に、お礼をした。", "target_word": "提供", "complexity_tier": "T3", "furigana": "情報[じょうほう]の提供[ていきょう]に協力[きょうりょく]してくれた方[かた]に、お礼[れい]をした。", "sentence_source": "generated"}, {"text": "住む家の提供を受けて、被災者はやっと安心した。", "target_word": "提供", "complexity_tier": "T3", "furigana": "住[す]む家[いえ]の提供[ていきょう]を受[う]けて、被災者[ひさいしゃ]はやっと安心[あんしん]した。", "sentence_source": "generated"}, {"text": "有名な選手が自分の道具を提供したので、大会は盛り上がった。", "target_word": "提供", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な選手[せんしゅ]が自分[じぶん]の道具[どうぐ]を提供[ていきょう]したので、大会[たいかい]は盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "市は旅行者に、無料で地図を提供している。", "target_word": "提供", "complexity_tier": "T3", "furigana": "市[し]は旅行者[りょこうしゃ]に、無料[むりょう]で地図[ちず]を提供[ていきょう]している。", "sentence_source": "generated"}, {"text": "彼は会場の提供を申し出て、みんなに感謝された。", "target_word": "提供", "complexity_tier": "T3", "furigana": "彼[かれ]は会場[かいじょう]の提供[ていきょう]を申[もう]し出[で]て、みんなに感謝[かんしゃ]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "提供する", "label": "する動詞の辞書形"}, {"form": "提供した", "label": "過去形"}, {"form": "提供して", "label": "て形"}, {"form": "提供される", "label": "受身形"}], "register": "neutral（普通体）", "sense_fingerprint": "物や場所や情報などを相手に差し出して使えるようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "「食べ物を提供した」は、物を相手に差し出すという意味に合う。"}, {"text": "参加", "is_correct": false, "explanation": "「食べ物を参加した」とは言わない。参加は会や行事に加わること。"}, {"text": "相談", "is_correct": false, "explanation": "「食べ物を相談した」は成り立たない。相談は話し合うことで、物を渡す文脈に合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「食べ物を出発した」は不自然。出発は場所を離れることで、物を目的語にとらない。"}], "explanations": {"提供": "「食べ物を提供した」は、物を相手に差し出すという意味に合う。", "参加": "「食べ物を参加した」とは言わない。参加は会や行事に加わること。", "相談": "「食べ物を相談した」は成り立たない。相談は話し合うことで、物を渡す文脈に合わない。", "出発": "「食べ物を出発した」は不自然。出発は場所を離れることで、物を目的語にとらない。"}, "sentence_index": 0, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は親切にしてくれた人に感謝を提供した。", "explanation": "〈表す〉は気持ちを言葉や態度で示すこと。提供は物や情報を相手に渡す語で、感謝という気持ちには使わない。"}, {"text": "学生は締め切りまでにレポートを提供した。", "explanation": "〈提出〉は決まった先へ書類などを出すこと。レポートの提出の文脈で提供を使うのは合わない。"}, {"text": "会社は社員に毎月交通費を提供している。", "explanation": "〈支給〉は決まった金銭などを与えること。交通費の支給の文脈で提供を使うのは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "「住む家の提供を受けて」で、住む家をあげてもらうという意味に合う。"}, {"text": "提出", "is_correct": false, "explanation": "「提出を受ける」は不自然。提出は自分から書類などを出すこと。"}, {"text": "返却", "is_correct": false, "explanation": "「返却を受ける」は不自然。返却は借りた物を返すことで、家の文脈に合わない。"}, {"text": "辞退", "is_correct": false, "explanation": "「辞退を受ける」は成り立たない。辞退は自分が断ることで、受け取る文脈に合わない。"}], "explanations": {"提供": "「住む家の提供を受けて」で、住む家をあげてもらうという意味に合う。", "提出": "「提出を受ける」は不自然。提出は自分から書類などを出すこと。", "返却": "「返却を受ける」は不自然。返却は借りた物を返すことで、家の文脈に合わない。", "辞退": "「辞退を受ける」は成り立たない。辞退は自分が断ることで、受け取る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店は注文の品を家まで提供した。", "explanation": "〈届ける〉は品物を相手のところまで運ぶこと。提供は相手に物を渡す意味で、品物を届ける場面には使わない。"}, {"text": "彼は店に代金を提供した。", "explanation": "〈支払う〉は代金を相手に渡す動作。提供は物や情報を差し出す意味で、代金の支払いには使わない。"}, {"text": "彼は会社の成長を大きく提供した。", "explanation": "〈貢献〉は役立つ働きをすること。提供は物や情報を相手に渡す語で、働きが役立つ意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は住民に無料で情報に提供している。", "corrected_sentence": "市は住民に無料で情報を提供している。", "error_description": "「提供する」は目的語に「を」をとる。「情報に」は誤りで、正しくは「情報を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は生徒に無料で食事で提供した。", "corrected_sentence": "学校は生徒に無料で食事を提供した。", "error_description": "「提供する」は目的語に「を」をとる。「食事で」は誤りで、正しくは「食事を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自然を秘めている」で、秘める対象（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「自然に秘めている」は成り立たない。に は場所や相手を示し、秘める対象の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「自然で秘めている」は不自然。で は手段や場所を示し、目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「自然と秘めている」は並列の意味になり、秘める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「自然を秘めている」で、秘める対象（目的語）を示す。", "に": "「自然に秘めている」は成り立たない。に は場所や相手を示し、秘める対象の位置には合わない。", "で": "「自然で秘めている」は不自然。で は手段や場所を示し、目的語にはならない。", "と": "「自然と秘めている」は並列の意味になり、秘める対象を示せない。"}, "error_tags": {"に": "場所", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「力を秘めている」で、秘める対象（目的語）を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「力へ秘めている」は方向の意味になり、秘める対象の位置には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「力から秘めている」は起点の意味になり、目的語としては不自然。"}, {"text": "より", "is_correct": false, "explanation": "「力より秘めている」は比較の意味になり、秘める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「力を秘めている」で、秘める対象（目的語）を示す。", "へ": "「力へ秘めている」は方向の意味になり、秘める対象の位置には合わない。", "から": "「力から秘めている」は起点の意味になり、目的語としては不自然。", "より": "「力より秘めている」は比較の意味になり、秘める対象を示せない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かくれたものを、外から見えないようにする。", "primary_collocate": null, "pronunciation": "ひめる", "ipa": "çimeɾɯ", "syllable_count": 3, "sentences": [{"text": "彼女は悲しい気持ちを胸に秘めて、笑顔で話していた。", "target_word": "秘めて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は悲[かな]しい気持[きも]ちを胸[むね]に秘[ひ]めて、笑顔[えがお]で話[はな]していた。", "sentence_source": "generated"}, {"text": "この小さな島は、美しい自然を秘めている。", "target_word": "秘めている", "complexity_tier": "T3", "furigana": "この小[ちい]さな島[しま]は、美[うつく]しい自然[しぜん]を秘[ひ]めている。", "sentence_source": "generated"}, {"text": "彼は大きな力を秘めているが、まだ自分では気づいていない。", "target_word": "秘めている", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな力[ちから]を秘[ひ]めているが、まだ自分[じぶん]では気[き]づいていない。", "sentence_source": "generated"}, {"text": "秘めた思いを伝えられず、卒業の日が来てしまった。", "target_word": "秘めた", "complexity_tier": "T3", "furigana": "秘[ひ]めた思[おも]いを伝[つた]えられず、卒業[そつぎょう]の日[ひ]が来[き]てしまった。", "sentence_source": "generated"}, {"text": "少年は夢を心に秘め、毎日遅くまで練習した。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "少年[しょうねん]は夢[ゆめ]を心[こころ]に秘[ひ]め、毎日[まいにち]遅[おそ]くまで練習[れんしゅう]した。", "sentence_source": "generated"}, {"text": "古い箱には、家族の歴史を秘めた手紙が入っていた。", "target_word": "秘めた", "complexity_tier": "T3", "furigana": "古[ふる]い箱[はこ]には、家族[かぞく]の歴史[れきし]を秘[ひ]めた手紙[てがみ]が入[はい]っていた。", "sentence_source": "generated"}, {"text": "彼は怒りを秘めたまま、何も言わずに部屋を出た。", "target_word": "秘めた", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[いか]りを秘[ひ]めたまま、何[なに]も言[い]わずに部屋[へや]を出[で]た。", "sentence_source": "generated"}, {"text": "この森は、まだ知られていない不思議な力を秘めていると言われる。", "target_word": "秘めている", "complexity_tier": "T3", "furigana": "この森[もり]は、まだ知[し]られていない不思議[ふしぎ]な力[ちから]を秘[ひ]めていると言[い]われる。", "sentence_source": "generated"}, {"text": "彼女は秘めていた才能を、舞台の上で見せた。", "target_word": "秘めていた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は秘[ひ]めていた才能[さいのう]を、舞台[ぶたい]の上[うえ]で見[み]せた。", "sentence_source": "generated"}, {"text": "誕生日の計画を胸に秘めておいたので、友達はとても驚いた。", "target_word": "秘めて", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]の計画[けいかく]を胸[むね]に秘[ひ]めておいたので、友達[ともだち]はとても驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "秘めて", "label": "て形"}, {"form": "秘めた", "label": "過去形・連体形"}, {"form": "秘めている", "label": "継続形"}, {"form": "秘めない", "label": "否定形"}], "register": "neutral（普通体）", "sense_fingerprint": "気持ちや力などを表に出さず、内に隠しておく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秘めて", "is_correct": true, "explanation": "「胸に秘めて」で、気持ちを表に出さず内に隠しておくという意味に合う。"}, {"text": "投げて", "is_correct": false, "explanation": "「胸に投げて」は成り立たない。投げるは物を放る動作で、気持ちには使わない。"}, {"text": "運んで", "is_correct": false, "explanation": "「胸に運んで」は不自然。運ぶは物の移動で、ここの文脈に合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "「胸に洗って」は成り立たない。洗うは汚れを落とす動作で、気持ちには使わない。"}], "explanations": {"秘めて": "「胸に秘めて」で、気持ちを表に出さず内に隠しておくという意味に合う。", "投げて": "「胸に投げて」は成り立たない。投げるは物を放る動作で、気持ちには使わない。", "運んで": "「胸に運んで」は不自然。運ぶは物の移動で、ここの文脈に合わない。", "洗って": "「胸に洗って」は成り立たない。洗うは汚れを落とす動作で、気持ちには使わない。"}, "sentence_index": 0, "correct_answer": "秘めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝ごはんを秘めた。", "explanation": "〈食べる〉は食べ物を口に入れること。秘めるは外から見えないように内に持つ意味で、食事の行為には使わない。"}, {"text": "彼は窓の鍵を秘めた。", "explanation": "〈閉める〉は戸や窓をふさぐこと。秘めるは外から見えないように内に持つ意味で、窓を閉める場面には使わない。"}, {"text": "彼女は電車の時刻を秘めた。", "explanation": "〈確認〉は調べて確かめること。秘めるは隠す意味で、時刻を確かめる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘めた", "is_correct": true, "explanation": "「怒りを秘めたまま」で、怒りを外に出さず内に隠しているという意味に合う。"}, {"text": "叩いた", "is_correct": false, "explanation": "「怒りを叩いた」は成り立たない。叩くは物を打つ動作で、気持ちには使わない。"}, {"text": "測った", "is_correct": false, "explanation": "「怒りを測った」は不自然。測るは量や大きさを調べることで、ここの文脈に合わない。"}, {"text": "拾った", "is_correct": false, "explanation": "「怒りを拾った」は成り立たない。拾うは落ちた物を取る動作で、気持ちには使わない。"}], "explanations": {"秘めた": "「怒りを秘めたまま」で、怒りを外に出さず内に隠しているという意味に合う。", "叩いた": "「怒りを叩いた」は成り立たない。叩くは物を打つ動作で、気持ちには使わない。", "測った": "「怒りを測った」は不自然。測るは量や大きさを調べることで、ここの文脈に合わない。", "拾った": "「怒りを拾った」は成り立たない。拾うは落ちた物を取る動作で、気持ちには使わない。"}, "sentence_index": 6, "correct_answer": "秘めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市は新しい橋を秘めた。", "explanation": "〈建設〉は建物や橋などを造ること。秘めるは内に隠す意味で、橋を造る場面には使わない。"}, {"text": "彼女は窓をうっかり秘めてしまった。", "explanation": "〈閉める〉は窓などをふさぐこと。秘めるは外から見えないように内に持つ意味で、窓を閉める動作にはならない。"}, {"text": "彼は子犬を友人に秘めた。", "explanation": "〈贈る〉は品物や動物を相手に渡して喜ばせること。秘めるは隠す意味で、人に渡す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この古い町は、豊かな歴史が秘めている。", "corrected_sentence": "この古い町は、豊かな歴史を秘めている。", "error_description": "「秘める」は目的語に「を」をとる。「歴史が」は誤りで、正しくは「歴史を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "秘めている", "is_correct": true, "explanation": "「美しい自然を秘めている」で、今もその自然を内に持つ状態を表す継続形。"}, {"text": "秘めて", "is_correct": false, "explanation": "て形のままでは文が終わらず、述語として成立しない。"}, {"text": "秘められている", "is_correct": false, "explanation": "受身にすると目的語の「を」は「が」に変わるため、「自然を」を保つこの文とは合わない。"}, {"text": "秘めたら", "is_correct": false, "explanation": "条件形は後ろに続く文が必要で、この文では文が終わらず成立しない。"}], "correct_form": "秘めている", "base_form": "秘める", "form_label": "継続形", "sentence_index": 1, "explanations": {"秘めている": "「美しい自然を秘めている」で、今もその自然を内に持つ状態を表す継続形。", "秘めて": "て形のままでは文が終わらず、述語として成立しない。", "秘められている": "受身にすると目的語の「を」は「が」に変わるため、「自然を」を保つこの文とは合わない。", "秘めたら": "条件形は後ろに続く文が必要で、この文では文が終わらず成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は希望を胸に秘めに、静かに笑った。", "corrected_sentence": "彼女は希望を胸に秘めて、静かに笑った。", "error_description": "「秘めて」（て形）が正しい。「秘めに」は活用形の誤りで、文として続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "秘めている", "is_correct": true, "explanation": "「力を秘めていると言われる」で、今もその力を内に持つ状態を表す継続形。"}, {"text": "秘めて", "is_correct": false, "explanation": "て形は「と言われる」に続かず、文が成立しない。"}, {"text": "秘めます", "is_correct": false, "explanation": "丁寧形は「言われる」の普通体の文と繋がらず、文の形が合わない。"}, {"text": "秘めよう", "is_correct": false, "explanation": "意志形は話し手の意向を表し、力の状態を述べる文には合わない。"}], "correct_form": "秘めている", "base_form": "秘める", "form_label": "継続形", "sentence_index": 7, "explanations": {"秘めている": "「力を秘めていると言われる」で、今もその力を内に持つ状態を表す継続形。", "秘めて": "て形は「と言われる」に続かず、文が成立しない。", "秘めます": "丁寧形は「言われる」の普通体の文と繋がらず、文の形が合わない。", "秘めよう": "意志形は話し手の意向を表し、力の状態を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「と」は「〜と一緒に」の相手を表す。母が一緒に買い物に行く相手なので合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。母は一緒に行く相手で、動かされる対象ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。母は相手を表す語なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。相手を表す文脈には合わない。"}], "correct_answer": "と", "explanations": {"と": "「と」は「〜と一緒に」の相手を表す。母が一緒に買い物に行く相手なので合う。", "を": "「を」は目的語を表す。母は一緒に行く相手で、動かされる対象ではないので合わない。", "で": "「で」は場所や手段を表す。母は相手を表す語なので合わない。", "へ": "「へ」は方向を表す。相手を表す文脈には合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「から」は起点を表す。母が電話をかけた相手なので、この文に合う。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すが、電話をかけた人を示す文脈には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「電話があった」の主語は電話そのものなので、母を主語にすると文の意味が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。電話があったという文では手段の意味が立たないので合わない。"}], "correct_answer": "から", "explanations": {"から": "「から」は起点を表す。母が電話をかけた相手なので、この文に合う。", "より": "「より」は比較や起点を表すが、電話をかけた人を示す文脈には合わない。", "が": "「が」は主語を表すが、「電話があった」の主語は電話そのものなので、母を主語にすると文の意味が崩れる。", "で": "「で」は場所や手段を表す。電話があったという文では手段の意味が立たないので合わない。"}, "error_tags": {"より": "比較・起点", "が": "主語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おかあさんのこと。", "primary_collocate": null, "pronunciation": "はは", "ipa": "haha", "syllable_count": 2, "sentences": [{"text": "母は毎朝、早く起きて朝ごはんを作ります。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、早[はや]く起[お]きて朝[あさ]ごはんを作[つく]ります。", "sentence_source": "generated"}, {"text": "私は母と一緒に買い物に行きました。", "target_word": "母", "complexity_tier": "T3", "furigana": "私[わたし]は母[はは]と一緒[いっしょ]に買[か]い物[もの]に行[い]きました。", "sentence_source": "generated"}, {"text": "母の作るカレーは、世界でいちばんおいしいです。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]の作[つく]るカレーは、世界[せかい]でいちばんおいしいです。", "sentence_source": "generated"}, {"text": "母に誕生日のプレゼントをあげました。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]に誕生日[たんじょうび]のプレゼントをあげました。", "sentence_source": "generated"}, {"text": "母は料理が上手なので、友だちもよく食べに来ます。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は料理[りょうり]が上手[じょうず]なので、友[とも]だちもよく食[た]べに来[き]ます。", "sentence_source": "generated"}, {"text": "風邪をひいたとき、母が薬を買ってきてくれました。", "target_word": "母", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたとき、母[はは]が薬[くすり]を買[か]ってきてくれました。", "sentence_source": "generated"}, {"text": "私の母は、毎週日曜日に公園を散歩します。", "target_word": "母", "complexity_tier": "T3", "furigana": "私[わたし]の母[はは]は、毎週[まいしゅう]日曜日[にちようび]に公園[こうえん]を散歩[さんぽ]します。", "sentence_source": "generated"}, {"text": "母から電話があって、来週帰ると伝えました。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]から電話[でんわ]があって、来週[らいしゅう]帰[かえ]ると伝[つた]えました。", "sentence_source": "generated"}, {"text": "母は優しいですが、宿題をしないと怒ります。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は優[やさ]しいですが、宿題[しゅくだい]をしないと怒[おこ]ります。", "sentence_source": "generated"}, {"text": "母に手紙を書いたら、すぐに返事が来ました。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]に手紙[てがみ]を書[か]いたら、すぐに返事[へんじ]が来[き]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "母", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分のおかあさん。他の人に話すときに使う言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "母", "is_correct": true, "explanation": "「母」は、朝ごはんを作る自分のおかあさんを指すので、この文に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は朝ごはんを作らないので、この文では合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は朝ごはんを作らないので、この文では合わない。"}, {"text": "机", "is_correct": false, "explanation": "机は朝ごはんを作らないので、この文では合わない。"}], "explanations": {"母": "「母」は、朝ごはんを作る自分のおかあさんを指すので、この文に合う。", "窓": "窓は朝ごはんを作らないので、この文では合わない。", "靴": "靴は朝ごはんを作らないので、この文では合わない。", "机": "机は朝ごはんを作らないので、この文では合わない。"}, "sentence_index": 0, "correct_answer": "母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "漁船は夕方、母に戻ってきた。", "explanation": "ここは〈母港〉（船が帰る港）の意味。「母」だけでは港は指せず、おかあさんの意味では船は戻れないので合わない。"}, {"text": "捕鯨船は捕った鯨を母に運び込んだ。", "explanation": "ここは〈母船〉（獲物を受け入れる大型船）の意味。「母」だけでは船は指せず、この文では合わない。"}, {"text": "彼は留学を終えて、母で働き始めた。", "explanation": "ここは〈母国〉の意味。「母」だけでは働く場所を指せず、「母で働く」は言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "母", "is_correct": true, "explanation": "「母」は毎週公園を散歩する自分のおかあさんを指すので、この文に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は公園を散歩しないので、この文では合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は公園を散歩しないので、この文では合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は公園を散歩しないので、この文では合わない。"}], "explanations": {"母": "「母」は毎週公園を散歩する自分のおかあさんを指すので、この文に合う。", "鍵": "鍵は公園を散歩しないので、この文では合わない。", "傘": "傘は公園を散歩しないので、この文では合わない。", "皿": "皿は公園を散歩しないので、この文では合わない。"}, "sentence_index": 6, "correct_answer": "母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この研究の母は、全国の十代だ。", "explanation": "ここは〈母集団〉（調べる対象全体）の意味。統計で使う語で、母親の意味の「母」では調査の対象は指せないので合わない。"}, {"text": "日本語の母は五つある。", "explanation": "ここは〈母音〉の意味。「母」だけでは音の種類は指せず、この文では合わない。"}, {"text": "その病院は、地元の大学病院を母にしている。", "explanation": "ここは〈母体〉（土台）の意味。「母」では組織の土台は言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちと母を一緒に映画を見ました。", "corrected_sentence": "友だちと母は一緒に映画を見ました。", "error_description": "誤りは「母を」（目的語の助詞）。正しくは「母は」（主題）。一緒に映画を見るのは母も含む人なので、主題の「は」が必要。「を」だと母が目的語になり、文の形が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は母にために手紙を書きました。", "corrected_sentence": "妹は母のために手紙を書きました。", "error_description": "誤りは「母に」（助詞の「の」が「に」になっている）。正しくは「母の」。「のために」で目的を表すので、「の」が必要。「にために」は助詞が重なり、文法的に不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は主題を表す。母について述べる文なので合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。母を目的語にすると、お弁当を作る人が分からなくなり文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。母を場所とすると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。母へお弁当を作る、では文の関係が合わない。"}], "correct_answer": "は", "explanations": {"は": "「は」は主題を表す。母について述べる文なので合う。", "を": "「を」は目的語を表す。母を目的語にすると、お弁当を作る人が分からなくなり文が崩れる。", "で": "「で」は場所や手段を表す。母を場所とすると文が成り立たない。", "へ": "「へ」は方向を表す。母へお弁当を作る、では文の関係が合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は相手や向かう先を表す。感謝を向ける相手が母なので合う。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。母から感謝を述べると、感謝の向きが逆になるので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。「感謝の言葉を」がすでに目的語なので、二つ目の「を」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。母を手段とすると、感謝を述べる文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「に」は相手や向かう先を表す。感謝を向ける相手が母なので合う。", "から": "「から」は起点を表す。母から感謝を述べると、感謝の向きが逆になるので合わない。", "を": "「を」は目的語を表す。「感謝の言葉を」がすでに目的語なので、二つ目の「を」は文が成り立たない。", "で": "「で」は場所や手段を表す。母を手段とすると、感謝を述べる文が成り立たない。"}, "error_tags": {"から": "起点", "を": "目的語（重複）", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の親である女性。家族の中で子どもを産み育てる人。", "primary_collocate": null, "pronunciation": "はは", "ipa": "haha", "syllable_count": 2, "sentences": [{"text": "母は一人で私と弟を育ててくれた。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は一人[ひとり]で私[わたし]と弟[おとうと]を育[そだ]ててくれた。", "sentence_source": "generated"}, {"text": "忙しい仕事の合間にも、母は毎日お弁当を作ってくれた。", "target_word": "母", "complexity_tier": "T3", "furigana": "忙[いそが]しい仕事[しごと]の合間[あいま]にも、母[はは]は毎日[まいにち]お弁当[べんとう]を作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "母が若いころ、この町で看護師として働いていたそうだ。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]が若[わか]いころ、この町[まち]で看護師[かんごし]として働[はたら]いていたそうだ。", "sentence_source": "generated"}, {"text": "子どもを産んで母になった友人は、前よりずっと強くなった。", "target_word": "母", "complexity_tier": "T3", "furigana": "子[こ]どもを産[う]んで母[はは]になった友人[ゆうじん]は、前[まえ]よりずっと強[つよ]くなった。", "sentence_source": "generated"}, {"text": "母は家族のために、いつも自分のことを後回しにした。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は家族[かぞく]のために、いつも自分[じぶん]のことを後回[あとまわ]しにした。", "sentence_source": "generated"}, {"text": "父は出張が多いので、家のことは母が決めている。", "target_word": "母", "complexity_tier": "T3", "furigana": "父[ちち]は出張[しゅっちょう]が多[おお]いので、家[いえ]のことは母[はは]が決[き]めている。", "sentence_source": "generated"}, {"text": "母の教えのおかげで、私は人に優しくできるようになった。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]の教[おし]えのおかげで、私[わたし]は人[ひと]に優[やさ]しくできるようになった。", "sentence_source": "generated"}, {"text": "結婚式で、新郎は育ててくれた母に感謝の言葉を述べた。", "target_word": "母", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、新郎[しんろう]は育[そだ]ててくれた母[はは]に感謝[かんしゃ]の言葉[ことば]を述[の]べた。", "sentence_source": "generated"}, {"text": "母は厳しかったが、私が困ったときは必ず助けてくれた。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]は厳[きび]しかったが、私[わたし]が困[こま]ったときは必[かなら]ず助[たす]けてくれた。", "sentence_source": "generated"}, {"text": "母と父は同じ大学の出身で、そこで出会ったそうだ。", "target_word": "母", "complexity_tier": "T3", "furigana": "母[はは]と父[ちち]は同[おな]じ大学[だいがく]の出身[しゅっしん]で、そこで出会[であ]ったそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "母", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分を産み育ててくれた親の女性。家族の中で子どもを育てる役割の人。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
