INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "母", "is_correct": true, "explanation": "「母」は、私に教えを残した自分のおかあさんを指すので、この文に合う。"}, {"text": "皿", "is_correct": false, "explanation": "皿は教えを与えないので、この文では合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は教えを与えないので、この文では合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は教えを与えないので、この文では合わない。"}], "explanations": {"母": "「母」は、私に教えを残した自分のおかあさんを指すので、この文に合う。", "皿": "皿は教えを与えないので、この文では合わない。", "鍵": "鍵は教えを与えないので、この文では合わない。", "傘": "傘は教えを与えないので、この文では合わない。"}, "sentence_index": 6, "correct_answer": "母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今回の調査の母は、全国の十代だ。", "explanation": "ここは〈母集団〉（調べる対象全体）の意味。統計で使う語で、母親の意味の「母」では調査の対象は指せないので合わない。"}, {"text": "日本語の母は五つある。", "explanation": "ここは〈母音〉の意味。「母」だけでは音の種類は指せず、この文では合わない。"}, {"text": "彼は留学を終えて、母で働き始めた。", "explanation": "ここは〈母国〉の意味。「母」だけでは働く場所を指せず、「母で働く」は言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は母を心配をかけないよう、毎日連絡をする。", "corrected_sentence": "兄は母に心配をかけないよう、毎日連絡をする。", "error_description": "誤りは「母を」（目的語の助詞）。正しくは「母に」（対象を示す助詞）。「心配をかける」は相手に対して使うので、「に」が必要。「を」だと母が目的語になり、文の形が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は毎朝、朝ごはんを作るて、私を起こす。", "corrected_sentence": "母は毎朝、朝ごはんを作って、私を起こす。", "error_description": "誤りは「作るて」（て形の誤り）。正しくは「作って」。「作る」のて形は「作って」で、「作るて」とは言わない。主語の母が作る動作なので、動詞の形を正しくする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べる」の目的語を示す（正解）。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「朝御飯が食べる」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すが、「朝御飯で食べる」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向や位置を示すが、ここでは「朝御飯に食べる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「食べる」の目的語を示す（正解）。", "が": "主語を示すが、「朝御飯が食べる」は文が成り立たない。", "で": "手段を示すが、「朝御飯で食べる」は不自然。", "に": "方向や位置を示すが、ここでは「朝御飯に食べる」は意味が通らない。"}, "error_tags": {"を": "「食べる」の目的語を示す（正解）", "が": "主語を示すが、「朝御飯が食べる」は文が成り立たない", "で": "手段を示すが、「朝御飯で食べる」は不自然", "に": "方向や位置を示すが、ここでは「朝御飯に食べる」は意味が通らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ホテルの朝御飯」の所属を示す（正解）。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「ホテルが朝御飯」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「ホテルを朝御飯」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「ホテルへ朝御飯」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「ホテルの朝御飯」の所属を示す（正解）。", "が": "主語を示すが、「ホテルが朝御飯」は文が成り立たない。", "を": "目的語を示すが、「ホテルを朝御飯」は不自然。", "へ": "方向を示すが、「ホテルへ朝御飯」は意味が通らない。"}, "error_tags": {"の": "「ホテルの朝御飯」の所属を示す（正解）", "が": "主語を示すが、「ホテルが朝御飯」は文が成り立たない", "を": "目的語を示すが、「ホテルを朝御飯」は不自然", "へ": "方向を示すが、「ホテルへ朝御飯」は意味が通らない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あさに たべる たべもの", "primary_collocate": null, "pronunciation": "あさごはん", "ipa": "asaɡohaɴ", "syllable_count": 5, "sentences": [{"text": "毎日、朝御飯を食べてから学校へ行く。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "毎日[まいにち]、朝御飯[あさごはん]を食[た]べてから学校[がっこう]へ行[い]く。", "sentence_source": "generated"}, {"text": "今朝は寝坊して、朝御飯を食べる時間がなかった。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "今朝[けさ]は寝坊[ねぼう]して、朝御飯[あさごはん]を食[た]べる時間[じかん]がなかった。", "sentence_source": "generated"}, {"text": "朝御飯にはいつもご飯と味噌汁を用意する。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]にはいつもご飯[はん]と味噌汁[みそしる]を用意[ようい]する。", "sentence_source": "generated"}, {"text": "母が作った朝御飯のにおいで目が覚めた。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "母[はは]が作[つく]った朝御飯[あさごはん]のにおいで目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "朝御飯を抜くと、午前中にお腹が空く。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]を抜[ぬ]くと、午前中[ごぜんちゅう]にお腹[なか]が空[す]く。", "sentence_source": "generated"}, {"text": "日曜日は、家族みんなで朝御飯を食べる。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は、家族[かぞく]みんなで朝御飯[あさごはん]を食[た]べる。", "sentence_source": "generated"}, {"text": "朝御飯の後、犬を連れて散歩に出かけた。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]の後[あと]、犬[いぬ]を連[つ]れて散歩[さんぽ]に出[で]かけた。", "sentence_source": "generated"}, {"text": "ホテルの朝御飯は、パンも果物も選べた。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "ホテルの朝御飯[あさごはん]は、パンも果物[くだもの]も選[えら]べた。", "sentence_source": "generated"}, {"text": "弟は朝御飯に毎日、納豆を食べている。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "弟[おとうと]は朝御飯[あさごはん]に毎日[まいにち]、納豆[なっとう]を食[た]べている。", "sentence_source": "generated"}, {"text": "朝御飯を作るために、六時に起きた。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]を作[つく]るために、六時[ろくじ]に起[お]きた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝御飯", "label": "基本形"}, {"form": "朝御飯を", "label": "を格"}, {"form": "朝御飯に", "label": "に格"}, {"form": "朝御飯の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "朝に食べる食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝御飯", "is_correct": true, "explanation": "「食べてから学校へ行く」の対象になる食べ物で、文の意味が通る。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は食べられないので、「を食べてから」と続かない。"}, {"text": "制服", "is_correct": false, "explanation": "制服は食べ物ではないので、この文では成り立たない。"}, {"text": "手帳", "is_correct": false, "explanation": "手帳は食べられないので、文の意味が通らない。"}], "explanations": {"朝御飯": "「食べてから学校へ行く」の対象になる食べ物で、文の意味が通る。", "教科書": "教科書は食べられないので、「を食べてから」と続かない。", "制服": "制服は食べ物ではないので、この文では成り立たない。", "手帳": "手帳は食べられないので、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "朝御飯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、玄関に朝御飯の束が届く。", "explanation": "ここは〈朝刊〉の意味。朝に配られる新聞は朝刊と言い、食べ物の朝御飯とは合わない。"}, {"text": "毎朝、校庭で朝御飯が行われる。", "explanation": "ここは〈朝礼〉の意味。学校で朝に行う集会は朝礼と言い、食事の朝御飯とは合わない。"}, {"text": "港の朝御飯は、新鮮な魚が並ぶことで有名だ。", "explanation": "ここは〈朝市〉の意味。朝に開かれる市場は朝市と言い、食事の朝御飯とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝御飯", "is_correct": true, "explanation": "食事の後に散歩に出かけるという流れに合う。"}, {"text": "切符", "is_correct": false, "explanation": "切符を食べた後に散歩に行くという流れは成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "電池の後に散歩に行くという文の流れは不自然。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋を身につけた後の散歩なら不自然で、文の流れに合わない。"}], "explanations": {"朝御飯": "食事の後に散歩に出かけるという流れに合う。", "切符": "切符を食べた後に散歩に行くという流れは成り立たない。", "電池": "電池の後に散歩に行くという文の流れは不自然。", "手袋": "手袋を身につけた後の散歩なら不自然で、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "朝御飯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝八時、家族で朝御飯を見るのが日課だ。", "explanation": "ここは〈朝ドラ〉の意味。テレビの朝の連続ドラマは朝ドラと言い、食べ物の朝御飯とは合わない。"}, {"text": "夏の庭で、朝御飯が一斉に咲いた。", "explanation": "ここは〈朝顔〉の意味。夏に咲く花は朝顔と言い、食べ物の朝御飯とは合わない。"}, {"text": "窓から朝御飯が差し込んだ。", "explanation": "ここは〈朝日〉の意味。窓から差し込む朝の光は朝日と言い、食べ物の朝御飯とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝御飯に食べてから、家を出た。", "corrected_sentence": "朝御飯を食べてから、家を出た。", "error_description": "「食べる」の対象は「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36778, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝御飯を食べいので、早く起きた。", "corrected_sentence": "朝御飯を食べたいので、早く起きた。", "error_description": "「食べたい」の「た」が抜けていて活用形が誤り。正しくは「食べたいので」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
