INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝御飯の時間」の所属を示す（正解）"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「朝御飯が時間」は成り立たない"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「朝御飯を時間」は意味が通らない"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「朝御飯で時間」は不自然"}], "correct_answer": "の", "explanations": {"の": "「朝御飯の時間」の所属を示す（正解）", "が": "主語を示すが、「朝御飯が時間」は成り立たない", "を": "目的語を示すが、「朝御飯を時間」は意味が通らない", "で": "手段や場所を示すが、「朝御飯で時間」は不自然"}, "error_tags": {"の": "「朝御飯の時間」の所属を示す（正解）", "が": "主語を示すが、「朝御飯が時間」は成り立たない", "を": "目的語を示すが、「朝御飯を時間」は意味が通らない", "で": "手段や場所を示すが、「朝御飯で時間」は不自然"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "朝に食べる食事。", "primary_collocate": null, "pronunciation": "あさごはん", "ipa": "asaɡohaɴ", "syllable_count": 5, "sentences": [{"text": "朝御飯は一日の始まりに大切な食事だ。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]は一日[いちにち]の始[はじ]まりに大切[たいせつ]な食事[しょくじ]だ。", "sentence_source": "generated"}, {"text": "父は新聞を読みながら、朝御飯を食べている。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "父[ちち]は新聞[しんぶん]を読[よ]みながら、朝御飯[あさごはん]を食[た]べている。", "sentence_source": "generated"}, {"text": "朝御飯にパンと卵を食べたので、昼まで元気だった。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]にパンと卵[たまご]を食[た]べたので、昼[ひる]まで元気[げんき]だった。", "sentence_source": "generated"}, {"text": "旅行の朝、窓から海を見ながら朝御飯をとった。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "旅行[りょこう]の朝[あさ]、窓[まど]から海[うみ]を見[み]ながら朝御飯[あさごはん]をとった。", "sentence_source": "generated"}, {"text": "朝御飯を食べない子どもが増えていると聞いた。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]を食[た]べない子[こ]どもが増[ふ]えていると聞[き]いた。", "sentence_source": "generated"}, {"text": "彼女は前の晩にサンドイッチを作って、それを朝御飯にする。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は前[まえ]の晩[ばん]にサンドイッチを作[つく]って、それを朝御飯[あさごはん]にする。", "sentence_source": "generated"}, {"text": "朝御飯が遅かったから、昼御飯はいらない。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]が遅[おそ]かったから、昼御飯[ひるごはん]はいらない。", "sentence_source": "generated"}, {"text": "朝御飯の時間になっても、兄は起きてこなかった。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]の時間[じかん]になっても、兄[あに]は起[お]きてこなかった。", "sentence_source": "generated"}, {"text": "キャンプでは、川の水でお茶をいれて朝御飯にした。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "キャンプでは、川[かわ]の水[みず]でお茶[ちゃ]をいれて朝御飯[あさごはん]にした。", "sentence_source": "generated"}, {"text": "朝御飯は、家族が話をする大切な時間だ。", "target_word": "朝御飯", "complexity_tier": "T3", "furigana": "朝御飯[あさごはん]は、家族[かぞく]が話[はなし]をする大切[たいせつ]な時間[じかん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝御飯", "label": "基本形"}, {"form": "朝御飯を", "label": "を格"}, {"form": "朝御飯は", "label": "は格"}, {"form": "朝御飯の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "朝にとる食事（一日の最初の食事）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朝御飯", "is_correct": true, "explanation": "一日の始まりにとる大切な食事として、文の主語に合う。"}, {"text": "手帳", "is_correct": false, "explanation": "手帳は食事ではないので、「大切な食事だ」と続かない。"}, {"text": "制服", "is_correct": false, "explanation": "制服は食事ではないので、文の意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は食事ではないので、この文には合わない。"}], "explanations": {"朝御飯": "一日の始まりにとる大切な食事として、文の主語に合う。", "手帳": "手帳は食事ではないので、「大切な食事だ」と続かない。", "制服": "制服は食事ではないので、文の意味が通らない。", "教科書": "教科書は食事ではないので、この文には合わない。"}, "sentence_index": 0, "correct_answer": "朝御飯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、郵便受けに朝御飯の束が入っている。", "explanation": "ここは〈朝刊〉の意味。朝に配られる新聞は朝刊と言い、食事の朝御飯とは合わない。"}, {"text": "毎朝八時、校庭で朝御飯の号令がかかる。", "explanation": "ここは〈朝礼〉の意味。学校で朝に行う集まりは朝礼と言い、食事の朝御飯とは合わない。"}, {"text": "母は毎朝、居間で朝御飯の続きを楽しみにしている。", "explanation": "ここは〈朝ドラ〉の意味。テレビの朝の連続ドラマは朝ドラと言い、食事の朝御飯とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朝御飯", "is_correct": true, "explanation": "「遅かった」の主語になり、朝の食事の遅れが昼食を要らなくする理由として自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「遅かった」とは言わず、文の理由として成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は「遅かった」とは言わず、文の意味が通らない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は「遅かった」とは言わず、この文の理由にならない。"}], "explanations": {"朝御飯": "「遅かった」の主語になり、朝の食事の遅れが昼食を要らなくする理由として自然。", "天気": "天気は「遅かった」とは言わず、文の理由として成り立たない。", "体重": "体重は「遅かった」とは言わず、文の意味が通らない。", "音楽": "音楽は「遅かった」とは言わず、この文の理由にならない。"}, "sentence_index": 6, "correct_answer": "朝御飯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎週土曜日、広場で朝御飯が開かれ、露店が並ぶ。", "explanation": "ここは〈朝市〉の意味。朝に開かれる市場は朝市と言い、食事の朝御飯とは合わない。"}, {"text": "庭の隅で、朝御飯が夏の花を開いた。", "explanation": "ここは〈朝顔〉の意味。夏に咲く花は朝顔と言い、食べ物の朝御飯とは合わない。"}, {"text": "東の空から朝御飯が昇った。", "explanation": "ここは〈朝日〉の意味。空に昇る太陽の光は朝日と言い、食べ物の朝御飯とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝御飯で食べながら、父は新聞を読んだ。", "corrected_sentence": "朝御飯を食べながら、父は新聞を読んだ。", "error_description": "「食べる」の対象は「を」で示す。「で」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝御飯を準備して、家族で飲んだ。", "corrected_sentence": "朝御飯を準備して、家族で食べた。", "error_description": "「朝御飯」は食べるものなので、動詞は「食べた」にする。「飲んだ」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は目的語を表す。ほうきで集める対象なので合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を表す。集める対象を示す位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表す。ほうきは手段で、集める対象を示さないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。集める対象は方向ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「を」は目的語を表す。ほうきで集める対象なので合う。", "に": "「に」は場所や相手を表す。集める対象を示す位置には合わない。", "で": "「で」は手段を表す。ほうきは手段で、集める対象を示さないので合わない。", "へ": "「へ」は方向を表す。集める対象は方向ではないので合わない。"}, "error_tags": {"に": "場所・相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語を表す。見えないのは塵なので合う。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表す。「塵と見えないほど」は成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「塵から見えない」は意味が通らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。「塵より見えない」は文の要素が合わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語を表す。見えないのは塵なので合う。", "と": "「と」は並列や相手を表す。「塵と見えないほど」は成り立たないので合わない。", "から": "「から」は起点を表す。「塵から見えない」は意味が通らないので合わない。", "より": "「より」は比較を表す。「塵より見えない」は文の要素が合わないので合わない。"}, "error_tags": {"と": "並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ちいさなごみのことです。", "primary_collocate": null, "pronunciation": "ごみ", "ipa": "ɡomi", "syllable_count": 2, "sentences": [{"text": "目に塵が入って、涙が出てきました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "目[め]に塵[ごみ]が入[はい]って、涙[なみだ]が出[で]てきました。", "sentence_source": "generated"}, {"text": "床に落ちた塵を、ほうきで集めました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "床[ゆか]に落[お]ちた塵[ごみ]を、ほうきで集[あつ]めました。", "sentence_source": "generated"}, {"text": "窓を開けると、風で塵が部屋に入ってきます。", "target_word": "塵", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、風[かぜ]で塵[ごみ]が部屋[へや]に入[はい]ってきます。", "sentence_source": "generated"}, {"text": "服についた塵を、手ではらいました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "服[ふく]についた塵[ごみ]を、手[て]ではらいました。", "sentence_source": "generated"}, {"text": "小さな塵でも、カメラに入ると写真が汚れます。", "target_word": "塵", "complexity_tier": "T3", "furigana": "小[ちい]さな塵[ごみ]でも、カメラに入[はい]ると写真[しゃしん]が汚[よご]れます。", "sentence_source": "generated"}, {"text": "掃除をしないと、机の上に塵がたまります。", "target_word": "塵", "complexity_tier": "T3", "furigana": "掃除[そうじ]をしないと、机[つくえ]の上[うえ]に塵[ごみ]がたまります。", "sentence_source": "generated"}, {"text": "弟は塵をちりとりに入れました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "弟[おとうと]は塵[ごみ]をちりとりに入[い]れました。", "sentence_source": "generated"}, {"text": "塵が見えないほど、きれいな部屋でした。", "target_word": "塵", "complexity_tier": "T3", "furigana": "塵[ごみ]が見[み]えないほど、きれいな部屋[へや]でした。", "sentence_source": "generated"}, {"text": "車の窓に塵がついて、白く汚れました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "車[くるま]の窓[まど]に塵[ごみ]がついて、白[しろ]く汚[よご]れました。", "sentence_source": "generated"}, {"text": "掃除機で、ソファの下の塵まで吸い取りました。", "target_word": "塵", "complexity_tier": "T3", "furigana": "掃除機[そうじき]で、ソファの下[した]の塵[ごみ]まで吸[す]い取[と]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "目や服や床などについた、とても小さなごみ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塵", "is_correct": true, "explanation": "「塵」は目に入る小さなごみを指すので、この文に合う。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は目に入る小さな物ではないので、この文では合わない。"}, {"text": "声", "is_correct": false, "explanation": "声は目に入る物ではないので、この文では合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は目に入る小さな物ではないので、この文では合わない。"}], "explanations": {"塵": "「塵」は目に入る小さなごみを指すので、この文に合う。", "椅子": "椅子は目に入る小さな物ではないので、この文では合わない。", "声": "声は目に入る物ではないので、この文では合わない。", "皿": "皿は目に入る小さな物ではないので、この文では合わない。"}, "sentence_index": 0, "correct_answer": "塵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は世俗の塵を嫌い、山奥の寺に入った。", "explanation": "ここは〈世俗の煩わしさ〉の意味。俗世の汚れを指す用法で、小さなごみの意味ではないので合わない。"}, {"text": "鼻をかむために塵を一枚取った。", "explanation": "ここは〈塵紙〉（ちりがみ）の意味。「塵」だけではティッシュは指せず、鼻をかむものは「ちりがみ」と言うので合わない。"}, {"text": "心の塵を払うため、毎朝座禅を組んだ。", "explanation": "ここは〈煩悩〉（心の汚れ）の意味。物理的なごみではないので、この義項では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塵", "is_correct": true, "explanation": "「塵」は床に落ちた小さなごみとして、ちりとりに入れる対象になるので、この文に合う。"}, {"text": "煙", "is_correct": false, "explanation": "煙はちりとりに入れられないので、この文では合わない。"}, {"text": "光", "is_correct": false, "explanation": "光はちりとりに入れられないので、この文では合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いはちりとりに入れられないので、この文では合わない。"}], "explanations": {"塵": "「塵」は床に落ちた小さなごみとして、ちりとりに入れる対象になるので、この文に合う。", "煙": "煙はちりとりに入れられないので、この文では合わない。", "光": "光はちりとりに入れられないので、この文では合わない。", "匂い": "匂いはちりとりに入れられないので、この文では合わない。"}, "sentence_index": 6, "correct_answer": "塵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題で、社内に塵が立った。", "explanation": "ここは〈埃〉の意味。「埃が立つ」（騒ぎになる）という慣用句は「塵」では言わないので合わない。"}, {"text": "俗世の塵から逃れたくて、彼は山あいの村に移った。", "explanation": "ここは〈俗世の煩わしさ〉の意味。小さなごみの意味ではないので、この義項では合わない。"}, {"text": "このパンは、小麦の塵を使って焼いた。", "explanation": "ここは〈粉〉の意味。小麦などの細かい粉は「粉」と言い、「塵」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の上に塵を積もっていた。", "corrected_sentence": "机の上に塵が積もっていた。", "error_description": "誤りは「塵を」（目的語）。正しくは「塵が」（主語）。「積もる」は物が自然に重なる動きなので、塵は主語として「が」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部屋の隅の塵ほど掃除した。", "corrected_sentence": "部屋の隅の塵まで掃除した。", "error_description": "誤りは「塵ほど」（程度の副助詞）。正しくは「塵まで」。「まで」は極端な対象まで及ぶことを表す。「ほど」は程度を表すので、「掃除した」と文の意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「が」は主語を表す。舞うのは塵なので合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や相手を表す。塵が主語の文では、場所を示す使い方として不自然なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。塵が方向へ舞う、とは言わないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表す。舞うという動詞は目的語を取らないので、この文では合わない。"}], "correct_answer": "が", "explanations": {"が": "「が」は主語を表す。舞うのは塵なので合う。", "に": "「に」は着点や相手を表す。塵が主語の文では、場所を示す使い方として不自然なので合わない。", "へ": "「へ」は方向を表す。塵が方向へ舞う、とは言わないので合わない。", "を": "「を」は目的語を表す。舞うという動詞は目的語を取らないので、この文では合わない。"}, "error_tags": {"に": "着点・相手", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「を」は目的語を表す。吸い込む対象なので合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着点や相手を表す。吸い込む対象としても作業の相手としても成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。吸い込む方向が逆になるので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表す。文の要素が合わないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「を」は目的語を表す。吸い込む対象なので合う。", "に": "「に」は着点や相手を表す。吸い込む対象としても作業の相手としても成り立たないので合わない。", "から": "「から」は起点を表す。吸い込む方向が逆になるので合わない。", "より": "「より」は比較を表す。文の要素が合わないので合わない。"}, "error_tags": {"に": "着点・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "細かいごみやほこりのこと。", "primary_collocate": null, "pronunciation": "ごみ", "ipa": "ɡomi", "syllable_count": 2, "sentences": [{"text": "古い本を開くと、細かい塵が舞い上がった。", "target_word": "塵", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]を開[ひら]くと、細[こま]かい塵[ごみ]が舞[ま]い上[あ]がった。", "sentence_source": "generated"}, {"text": "塵が舞って、部屋の中の空気が悪くなった。", "target_word": "塵", "complexity_tier": "T3", "furigana": "塵[ごみ]が舞[ま]って、部屋[へや]の中[なか]の空気[くうき]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "工事現場の近くは、風の強い日に塵が飛んでくる。", "target_word": "塵", "complexity_tier": "T3", "furigana": "工事現場[こうじげんば]の近[ちか]くは、風[かぜ]の強[つよ]い日[ひ]に塵[ごみ]が飛[と]んでくる。", "sentence_source": "generated"}, {"text": "机の上にうすく塵が積もっていたので、布でふいた。", "target_word": "塵", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]にうすく塵[ごみ]が積[つ]もっていたので、布[ぬの]でふいた。", "sentence_source": "generated"}, {"text": "塵が鼻に入って、くしゃみが止まらなくなった。", "target_word": "塵", "complexity_tier": "T3", "furigana": "塵[ごみ]が鼻[はな]に入[はい]って、くしゃみが止[と]まらなくなった。", "sentence_source": "generated"}, {"text": "掃除のとき、棚の奥の塵をブラシで落とした。", "target_word": "塵", "complexity_tier": "T3", "furigana": "掃除[そうじ]のとき、棚[たな]の奥[おく]の塵[ごみ]をブラシで落[お]とした。", "sentence_source": "generated"}, {"text": "長く使わなかった機械には、塵がたくさんついていた。", "target_word": "塵", "complexity_tier": "T3", "furigana": "長[なが]く使[つか]わなかった機械[きかい]には、塵[ごみ]がたくさんついていた。", "sentence_source": "generated"}, {"text": "塵を吸い込まないように、マスクをして作業した。", "target_word": "塵", "complexity_tier": "T3", "furigana": "塵[ごみ]を吸[す]い込[こ]まないように、マスクをして作業[さぎょう]した。", "sentence_source": "generated"}, {"text": "日光が差すと、空気中の塵がきらきらと光って見える。", "target_word": "塵", "complexity_tier": "T3", "furigana": "日光[にっこう]が差[さ]すと、空気中[くうきちゅう]の塵[ごみ]がきらきらと光[ひか]って見[み]える。", "sentence_source": "generated"}, {"text": "工場では、製品に塵がつかないよう、特別な服を着る。", "target_word": "塵", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、製品[せいひん]に塵[ごみ]がつかないよう、特別[とくべつ]な服[ふく]を着[き]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空気中を舞ったり物の上に積もったりする、細かいごみやほこり。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塵", "is_correct": true, "explanation": "「塵」は本を開いたときに舞い上がる細かいほこりを指すので、この文に合う。"}, {"text": "声", "is_correct": false, "explanation": "声は空気中を舞い上がらないので、この文では合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は舞い上がらないので、この文では合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は細かく舞い上がらないので、この文では合わない。"}], "explanations": {"塵": "「塵」は本を開いたときに舞い上がる細かいほこりを指すので、この文に合う。", "声": "声は空気中を舞い上がらないので、この文では合わない。", "雨": "雨は舞い上がらないので、この文では合わない。", "鍋": "鍋は細かく舞い上がらないので、この文では合わない。"}, "sentence_index": 0, "correct_answer": "塵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は世俗の塵から離れ、田舎で静かに暮らした。", "explanation": "ここは〈世俗の煩わしさ〉の意味。小さなごみの意味ではないので、この義項では合わない。"}, {"text": "鼻をかむために塵を一枚取った。", "explanation": "ここは〈塵紙〉（ちりがみ）の意味。「塵」だけではティッシュは指せず、鼻をかむものは「ちりがみ」と言うので合わない。"}, {"text": "この発表で、社内に塵が立った。", "explanation": "ここは〈埃〉の意味。「埃が立つ」（騒ぎになる）は「塵」では言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塵", "is_correct": true, "explanation": "「塵」は機械に積もって付くほこりを指すので、この文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は機械に付かないので、この文では合わない。"}, {"text": "笑い", "is_correct": false, "explanation": "笑いは機械に付かないので、この文では合わない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は機械に付かないので、この文では合わない。"}], "explanations": {"塵": "「塵」は機械に積もって付くほこりを指すので、この文に合う。", "歌": "歌は機械に付かないので、この文では合わない。", "笑い": "笑いは機械に付かないので、この文では合わない。", "夢": "夢は機械に付かないので、この文では合わない。"}, "sentence_index": 6, "correct_answer": "塵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "世俗の塵を捨てて、寺に入る決心をした。", "explanation": "ここは〈世俗の煩わしさ〉の意味。小さなごみの意味ではないので、この義項では合わない。"}, {"text": "お風呂で体の塵をこすり落とした。", "explanation": "ここは〈垢〉（あか）の意味。体の汚れは「塵」とは言わないので合わない。"}, {"text": "このケーキは、小麦の塵を混ぜて焼いた。", "explanation": "ここは〈粉〉の意味。小麦などの細かい粉は「粉」と言い、「塵」とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を閉めていないと、部屋に塵を入ってくる。", "corrected_sentence": "窓を閉めていないと、部屋に塵が入ってくる。", "error_description": "誤りは「塵を」（目的語）。正しくは「塵が」（主語）。「入ってくる」は自分から入る動きなので、塵は主語として「が」で示す。「を」は他動詞の文で使うので、この文に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36781, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "換気扇を回すと、塵が外へ出す。", "corrected_sentence": "換気扇を回すと、塵が外へ出ていく。", "error_description": "誤りは「出す」（他動詞）。正しくは「出ていく」（自動詞）。塵が主語で自ら外へ移動するので、「出ていく」で表す。「出す」だと人が何かを出す意味になり、文が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「子ねこ」は「生んだ」の対象なので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を表すが、「子ねこに生んだ」では意味が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すが、「子ねこで生んだ」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を表すが、「子ねこと生んだ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「子ねこ」は「生んだ」の対象なので「を」が入る。", "に": "相手や方向を表すが、「子ねこに生んだ」では意味が成り立たない。", "で": "場所や手段を表すが、「子ねこで生んだ」は合わない。", "と": "共同や相手を表すが、「子ねこと生んだ」は不自然。"}, "error_tags": {"に": "相手・方向", "で": "場所・手段", "と": "共同・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「卵」は「生みます」の対象なので「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「卵が生みます」は主語と動詞の関係が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「巣に」がすでに場所を表しているので重複して不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「卵より生みます」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「卵」は「生みます」の対象なので「を」が入る。", "が": "主語を示すが、「卵が生みます」は主語と動詞の関係が成立しない。", "へ": "方向を示すが、「巣に」がすでに場所を表しているので重複して不自然。", "より": "比較を示すが、「卵より生みます」では意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物が、子どもや卵をからだの外に出すこと。", "primary_collocate": null, "pronunciation": "うむ", "ipa": "ɯmɯ", "syllable_count": 2, "sentences": [{"text": "母は去年、元気な男の子を生みました。", "target_word": "生みました", "complexity_tier": "T3", "furigana": "母[はは]は去年[きょねん]、元気[げんき]な男[おとこ]の子[こ]を生[う]みました。", "sentence_source": "generated"}, {"text": "うちの猫が五ひきの子ねこを生んだ。", "target_word": "生んだ", "complexity_tier": "T3", "furigana": "うちの猫[ねこ]が五[ご]ひきの子[こ]ねこを生[う]んだ。", "sentence_source": "generated"}, {"text": "姉は来月、赤ちゃんを生む予定です。", "target_word": "生む", "complexity_tier": "T3", "furigana": "姉[あね]は来月[らいげつ]、赤[あか]ちゃんを生[う]む予定[よてい]です。", "sentence_source": "generated"}, {"text": "にわとりは毎日、卵を生みます。", "target_word": "生みます", "complexity_tier": "T3", "furigana": "にわとりは毎日[まいにち]、卵[たまご]を生[う]みます。", "sentence_source": "generated"}, {"text": "犬は一度に何びきも子を生むことがある。", "target_word": "生む", "complexity_tier": "T3", "furigana": "犬[いぬ]は一度[いちど]に何[なん]びきも子[こ]を生[う]むことがある。", "sentence_source": "generated"}, {"text": "この池でカエルが卵を生んでいる。", "target_word": "生んでいる", "complexity_tier": "T3", "furigana": "この池[いけ]でカエルが卵[たまご]を生[う]んでいる。", "sentence_source": "generated"}, {"text": "彼女は大きな病院で双子を生みました。", "target_word": "生みました", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大[おお]きな病院[びょういん]で双子[ふたご]を生[う]みました。", "sentence_source": "generated"}, {"text": "鳥は木の上の巣に卵を生みます。", "target_word": "生みます", "complexity_tier": "T3", "furigana": "鳥[とり]は木[き]の上[うえ]の巣[す]に卵[たまご]を生[う]みます。", "sentence_source": "generated"}, {"text": "子どもを生んでから、半年間仕事を休みました。", "target_word": "生んで", "complexity_tier": "T3", "furigana": "子[こ]どもを生[う]んでから、半年間[はんとしかん]仕事[しごと]を休[やす]みました。", "sentence_source": "generated"}, {"text": "ウミガメは夜の砂浜に上がって卵を生む。", "target_word": "生む", "complexity_tier": "T3", "furigana": "ウミガメは夜[よる]の砂浜[すなはま]に上[あ]がって卵[たまご]を生[う]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生む", "label": "辞書形"}, {"form": "生まない", "label": "否定形"}, {"form": "生みます", "label": "丁寧形"}, {"form": "生んで", "label": "て形"}, {"form": "生んだ", "label": "た形"}, {"form": "生めば", "label": "仮定形"}, {"form": "生もう", "label": "意志形"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "人や動物が子どもや卵をからだの外に出す、出産の意味の「生む」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生みました", "is_correct": true, "explanation": "過去の丁寧形で、「男の子を」の目的語と結びつき、「去年」の出産を自然に表す。"}, {"text": "生まれました", "is_correct": false, "explanation": "自動詞なので「男の子を」の「を」と合わない。「男の子が生まれました」の形になる。"}, {"text": "生もう", "is_correct": false, "explanation": "意志形で、すでに起きた「去年」の出来事とは続かない。"}, {"text": "生んで", "is_correct": false, "explanation": "て形なので、ここでは文が完結しない。"}], "explanations": {"生みました": "過去の丁寧形で、「男の子を」の目的語と結びつき、「去年」の出産を自然に表す。", "生まれました": "自動詞なので「男の子を」の「を」と合わない。「男の子が生まれました」の形になる。", "生もう": "意志形で、すでに起きた「去年」の出来事とは続かない。", "生んで": "て形なので、ここでは文が完結しない。"}, "sentence_index": 0, "correct_answer": "生みました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店主は毎晩、店の看板を生む。", "explanation": "ここは〈描く〉の意味。生むは出産や産卵の意味で、看板を描くことには使わない。"}, {"text": "母は毎晩、家族のために夕食を生む。", "explanation": "ここは「作る」の意味。生むは子や卵を体の外に出す意味で、料理には使わない。"}, {"text": "祖父は庭の盆栽を大切に生んでいる。", "explanation": "ここは「育てる」の意味。生むは出産の意味で、植物を育てることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生みました", "is_correct": true, "explanation": "過去の丁寧形で、「双子を」の目的語と結びつき、出産の出来事を表す。"}, {"text": "生めば", "is_correct": false, "explanation": "仮定形で、文が完結しない。"}, {"text": "生みながら", "is_correct": false, "explanation": "「ながら」の形なので、文末に置くと文が完結しない。"}, {"text": "生みそう", "is_correct": false, "explanation": "「〜そう」（様態）の形で、「〜そうだ」と続けないと文が完結しない。"}], "explanations": {"生みました": "過去の丁寧形で、「双子を」の目的語と結びつき、出産の出来事を表す。", "生めば": "仮定形で、文が完結しない。", "生みながら": "「ながら」の形なので、文末に置くと文が完結しない。", "生みそう": "「〜そう」（様態）の形で、「〜そうだ」と続けないと文が完結しない。"}, "sentence_index": 6, "correct_answer": "生みました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、ネクタイを生んでから出かける。", "explanation": "ここは〈締める〉の意味。生むは子や卵を出す意味で、ネクタイを締めることには使わない。"}, {"text": "ペンキ屋は毎日、白い壁を生んでいる。", "explanation": "ここは〈塗る〉の意味。生むは出産や産卵の意味で、壁を塗ることには使わない。"}, {"text": "父は毎朝、パンを生む。", "explanation": "ここは「焼く」の意味。生むは子や卵を出す意味で、パンには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は去年、元気な女の子を生まれました。", "corrected_sentence": "姉は去年、元気な女の子を生みました。", "error_description": "正しくは「生みました」（他動詞）。「生まれました」は自動詞なので「女の子を」と合わず、「女の子が生まれました」の形になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生んだ", "is_correct": true, "explanation": "た形（過去形）。「五ひきの子ねこを生んだ」という過去の出来事を表す。"}, {"text": "生もう", "is_correct": false, "explanation": "意志形で、すでに起きた出来事を述べる文と合わない。"}, {"text": "生めば", "is_correct": false, "explanation": "仮定形で、文を結ぶ主節がない。"}, {"text": "生んで", "is_correct": false, "explanation": "て形なので、ここでは文が完結しない。"}], "correct_form": "生んだ", "base_form": "生む", "form_label": "た形", "sentence_index": 1, "explanations": {"生んだ": "た形（過去形）。「五ひきの子ねこを生んだ」という過去の出来事を表す。", "生もう": "意志形で、すでに起きた出来事を述べる文と合わない。", "生めば": "仮定形で、文を結ぶ主節がない。", "生んで": "て形なので、ここでは文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アヒルは池のそばに卵が生みます。", "corrected_sentence": "アヒルは池のそばに卵を生みます。", "error_description": "正しくは「卵を生みます」。「卵」は「生みます」の目的語なので「を」が必要で、「が」では主語と動詞が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生みます", "is_correct": true, "explanation": "丁寧形。鳥が卵を産むという習慣的な事実を述べる。"}, {"text": "生みません", "is_correct": false, "explanation": "否定の丁寧形。鳥が卵を産むという習慣的な事実を否定してしまう。"}, {"text": "生まない", "is_correct": false, "explanation": "否定形で、習慣的な事実と反対の意味になる。"}, {"text": "生みなさい", "is_correct": false, "explanation": "命令形で、事実を述べる文と合わない。"}], "correct_form": "生みます", "base_form": "生む", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"生みます": "丁寧形。鳥が卵を産むという習慣的な事実を述べる。", "生みません": "否定の丁寧形。鳥が卵を産むという習慣的な事実を否定してしまう。", "生まない": "否定形で、習慣的な事実と反対の意味になる。", "生みなさい": "命令形で、事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「大きな争い」を生むので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を表すが、「争いに生む」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すが、「争いで生む」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表すが、「争いと生む」は意味をなさない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「大きな争い」を生むので「を」が入る。", "に": "相手や方向を表すが、「争いに生む」は成り立たない。", "で": "場所や手段を表すが、「争いで生む」は不自然。", "と": "共同や引用を表すが、「争いと生む」は意味をなさない。"}, "error_tags": {"に": "相手・方向", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「交流」を生むので「を」が入る。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表すが、「交流の生んでいる」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「交流へ生んでいる」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「交流より生んでいる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「交流」を生むので「を」が入る。", "の": "連体修飾を表すが、「交流の生んでいる」は文として成り立たない。", "へ": "方向を示すが、「交流へ生んでいる」は不自然。", "より": "比較を示すが、「交流より生んでいる」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生き物が、体の外に子どもや卵を出すこと。また、物事を新しく作り出すこと。", "primary_collocate": null, "pronunciation": "うむ", "ipa": "ɯmɯ", "syllable_count": 2, "sentences": [{"text": "この発明は大きな利益を生みました。", "target_word": "生みました", "complexity_tier": "T3", "furigana": "この発明[はつめい]は大[おお]きな利益[りえき]を生[う]みました。", "sentence_source": "generated"}, {"text": "小さな誤解が、大きな争いを生むことがある。", "target_word": "生む", "complexity_tier": "T3", "furigana": "小[ちい]さな誤解[ごかい]が、大[おお]きな争[あらそ]いを生[う]むことがある。", "sentence_source": "generated"}, {"text": "彼の努力が、すばらしい結果を生んだ。", "target_word": "生んだ", "complexity_tier": "T3", "furigana": "彼[かれ]の努力[どりょく]が、すばらしい結果[けっか]を生[う]んだ。", "sentence_source": "generated"}, {"text": "新しい商品を生むために、みんなで話し合います。", "target_word": "生む", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]を生[う]むために、みんなで話[はな]し合[あ]います。", "sentence_source": "generated"}, {"text": "犬が子を生んだので、家族が増えた。", "target_word": "生んだ", "complexity_tier": "T3", "furigana": "犬[いぬ]が子[こ]を生[う]んだので、家族[かぞく]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "兄の一言が、みんなの笑いを生んだ。", "target_word": "生んだ", "complexity_tier": "T3", "furigana": "兄[あに]の一言[ひとこと]が、みんなの笑[わら]いを生[う]んだ。", "sentence_source": "generated"}, {"text": "失敗は、新しい工夫を生むきっかけになる。", "target_word": "生む", "complexity_tier": "T3", "furigana": "失敗[しっぱい]は、新[あたら]しい工夫[くふう]を生[う]むきっかけになる。", "sentence_source": "generated"}, {"text": "この町の祭りは、多くの人の交流を生んでいる。", "target_word": "生んでいる", "complexity_tier": "T3", "furigana": "この町[まち]の祭[まつ]りは、多[おお]くの人[ひと]の交流[こうりゅう]を生[う]んでいる。", "sentence_source": "generated"}, {"text": "親ガメは砂の中に卵を生みます。", "target_word": "生みます", "complexity_tier": "T3", "furigana": "親[おや]ガメは砂[すな]の中[なか]に卵[たまご]を生[う]みます。", "sentence_source": "generated"}, {"text": "友だちの助言が、私に自信を生んでくれた。", "target_word": "生んで", "complexity_tier": "T3", "furigana": "友[とも]だちの助言[じょげん]が、私[わたし]に自信[じしん]を生[う]んでくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生む", "label": "辞書形"}, {"form": "生まない", "label": "否定形"}, {"form": "生みます", "label": "丁寧形"}, {"form": "生んで", "label": "て形"}, {"form": "生んだ", "label": "た形"}, {"form": "生めば", "label": "仮定形"}, {"form": "生もう", "label": "意志形"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "子や卵を出す意味に加えて、結果・利益・争いなどを新しく作り出す意味の「生む」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生みました", "is_correct": true, "explanation": "過去の丁寧形で、「利益を」の目的語と結びつき、結果が生じたことを表す。"}, {"text": "生まれました", "is_correct": false, "explanation": "自動詞なので「利益を」の「を」と合わない。「利益が生まれました」の形になる。"}, {"text": "生もう", "is_correct": false, "explanation": "意志形で、発明がもたらした結果を述べる文と合わない。"}, {"text": "生めば", "is_correct": false, "explanation": "仮定形で、文が完結しない。"}], "explanations": {"生みました": "過去の丁寧形で、「利益を」の目的語と結びつき、結果が生じたことを表す。", "生まれました": "自動詞なので「利益を」の「を」と合わない。「利益が生まれました」の形になる。", "生もう": "意志形で、発明がもたらした結果を述べる文と合わない。", "生めば": "仮定形で、文が完結しない。"}, "sentence_index": 0, "correct_answer": "生みました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は庭に小さな小屋を生んだ。", "explanation": "ここは「建てる」の意味。生むは結果や利益などを生み出す意味で、建物には使わない。"}, {"text": "彼女は毎日、日記を生んでいる。", "explanation": "ここは「書く」の意味。生むは結果や物事を生み出す意味で、文章には使わない。"}, {"text": "彼は毎朝、顔を生む。", "explanation": "ここは「洗う」の意味。生むは物事を生み出す意味で、体を洗うことには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生む", "is_correct": true, "explanation": "辞書形で、「きっかけ」を修飾する名詞句として自然に続く。"}, {"text": "生みます", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できないので、「きっかけ」とつながらない。"}, {"text": "生まれる", "is_correct": false, "explanation": "自動詞なので「工夫を」の「を」と合わない。"}, {"text": "生もう", "is_correct": false, "explanation": "意志形は名詞を修飾できないので、文が成り立たない。"}], "explanations": {"生む": "辞書形で、「きっかけ」を修飾する名詞句として自然に続く。", "生みます": "丁寧形は名詞を直接修飾できないので、「きっかけ」とつながらない。", "生まれる": "自動詞なので「工夫を」の「を」と合わない。", "生もう": "意志形は名詞を修飾できないので、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "生む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は朝早く起きて、ご飯を生んだ。", "explanation": "ここは「炊く」の意味。生むは子や卵を出す意味で、ご飯には使わない。"}, {"text": "父は週末、壁にポスターを生んだ。", "explanation": "ここは「貼る」の意味。生むは物事を生み出す意味で、貼ることには使わない。"}, {"text": "店は入り口に看板を生んだ。", "explanation": "ここは「立てる」の意味。生むは看板を立てることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この新製品は大きな売上を生まれました。", "corrected_sentence": "この新製品は大きな売上を生みました。", "error_description": "正しくは「生みました」（他動詞）。「生まれました」は自動詞なので「売上を」と合わず、「売上が生まれました」の形になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生む", "is_correct": true, "explanation": "辞書形。「ことがある」と続き、一般的な可能性を表す。"}, {"text": "生もう", "is_correct": false, "explanation": "意志形で、「ことがある」とは続かない。"}, {"text": "生みます", "is_correct": false, "explanation": "丁寧形で、「ことがある」と続かない。"}, {"text": "生めば", "is_correct": false, "explanation": "仮定形で、「ことがある」の文型と合わない。"}], "correct_form": "生む", "base_form": "生む", "form_label": "辞書形", "sentence_index": 1, "explanations": {"生む": "辞書形。「ことがある」と続き、一般的な可能性を表す。", "生もう": "意志形で、「ことがある」とは続かない。", "生みます": "丁寧形で、「ことがある」と続かない。", "生めば": "仮定形で、「ことがある」の文型と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36783, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会議は新しいアイデアが生みました。", "corrected_sentence": "この会議は新しいアイデアを生みました。", "error_description": "正しくは「アイデアを生みました」。「アイデア」は「生みました」の目的語なので「を」が必要で、「が」では主語と動詞が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生んでいる", "is_correct": true, "explanation": "「ている形」。祭りが交流を生み続けている状態を表し、文が続く。"}, {"text": "生めば", "is_correct": false, "explanation": "仮定形で、文を結ぶ主節がない。"}, {"text": "生んで", "is_correct": false, "explanation": "て形なので、ここでは文が終わらない。"}, {"text": "生みながら", "is_correct": false, "explanation": "「ながら」の形で、文を終えられず、「交流を生んでいる」という状態の述べ方と合わない。"}], "correct_form": "生んでいる", "base_form": "生む", "form_label": "ている形", "sentence_index": 7, "explanations": {"生んでいる": "「ている形」。祭りが交流を生み続けている状態を表し、文が続く。", "生めば": "仮定形で、文を結ぶ主節がない。", "生んで": "て形なので、ここでは文が終わらない。", "生みながら": "「ながら」の形で、文を終えられず、「交流を生んでいる」という状態の述べ方と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「屑」を手で払うので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を表すが、「屑に手で払った」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「屑が払った」は主語と動詞が合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同を表すが、「屑と払った」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「屑」を手で払うので「を」が入る。", "に": "相手や方向を表すが、「屑に手で払った」は意味が通らない。", "が": "主語を示すが、「屑が払った」は主語と動詞が合わない。", "と": "共同を表すが、「屑と払った」は意味が通らない。"}, "error_tags": {"に": "相手・方向", "が": "主語", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。細かい「屑」が出てくるので「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「出ます」は自動詞なので「屑を出ます」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すが、「屑で出ます」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「屑へ出ます」は不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。細かい「屑」が出てくるので「が」が入る。", "を": "目的語を示すが、「出ます」は自動詞なので「屑を出ます」は合わない。", "で": "場所や手段を表すが、「屑で出ます」は意味が通らない。", "へ": "方向を表すが、「屑へ出ます」は不自然。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いらない ものや、すてる もの、あまりの もの。", "primary_collocate": null, "pronunciation": "くず", "ipa": "kɯzɯ", "syllable_count": 2, "sentences": [{"text": "床に紙の屑が落ちています。", "target_word": "屑", "complexity_tier": "T3", "furigana": "床[ゆか]に紙[かみ]の屑[くず]が落[お]ちています。", "sentence_source": "generated"}, {"text": "机の上の消しゴムの屑を手で払った。", "target_word": "屑", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の消[け]しゴムの屑[くず]を手[て]で払[はら]った。", "sentence_source": "generated"}, {"text": "掃除をして、部屋の屑を集めました。", "target_word": "屑", "complexity_tier": "T3", "furigana": "掃除[そうじ]をして、部屋[へや]の屑[くず]を集[あつ]めました。", "sentence_source": "generated"}, {"text": "工事のあとに、木の屑が道に残っていた。", "target_word": "屑", "complexity_tier": "T3", "furigana": "工事[こうじ]のあとに、木[き]の屑[くず]が道[みち]に残[のこ]っていた。", "sentence_source": "generated"}, {"text": "パンの屑を鳥にあげました。", "target_word": "屑", "complexity_tier": "T3", "furigana": "パンの屑[くず]を鳥[とり]にあげました。", "sentence_source": "generated"}, {"text": "散髪のあと、床に落ちた屑をほうきで集めた。", "target_word": "屑", "complexity_tier": "T3", "furigana": "散髪[さんぱつ]のあと、床[ゆか]に落[お]ちた屑[くず]をほうきで集[あつ]めた。", "sentence_source": "generated"}, {"text": "屑を拾わないと、床が汚れてしまう。", "target_word": "屑", "complexity_tier": "T3", "furigana": "屑[くず]を拾[ひろ]わないと、床[ゆか]が汚[よご]れてしまう。", "sentence_source": "generated"}, {"text": "鉛筆を削ると、細かい屑が出ます。", "target_word": "屑", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]を削[けず]ると、細[こま]かい屑[くず]が出[で]ます。", "sentence_source": "generated"}, {"text": "机の下に食べ物の屑が散らばっていた。", "target_word": "屑", "complexity_tier": "T3", "furigana": "机[つくえ]の下[した]に食[た]べ物[もの]の屑[くず]が散[ち]らばっていた。", "sentence_source": "generated"}, {"text": "屑は、このごみ箱に入れてください。", "target_word": "屑", "complexity_tier": "T3", "furigana": "屑[くず]は、このごみ箱[ばこ]に入[い]れてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屑", "label": "基本形"}, {"form": "屑の", "label": "連体形（の）"}, {"form": "屑が", "label": "主語形（が）"}, {"form": "屑を", "label": "目的語形（を）"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "紙・パン・消しゴムなどから出る、いらなくなった細かいごみ・かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屑", "is_correct": true, "explanation": "紙くずの意味。床に落ちている細かいごみとして自然につながる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「紙の鉛筆」は意味が通らず、床に落ちているものとして合わない。"}, {"text": "水", "is_correct": false, "explanation": "「紙の水」は意味が通らず、床に落ちたものとして合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「紙の窓」は意味が通らず、床に落ちたものとして合わない。"}], "explanations": {"屑": "紙くずの意味。床に落ちている細かいごみとして自然につながる。", "鉛筆": "「紙の鉛筆」は意味が通らず、床に落ちているものとして合わない。", "水": "「紙の水」は意味が通らず、床に落ちたものとして合わない。", "窓": "「紙の窓」は意味が通らず、床に落ちたものとして合わない。"}, "sentence_index": 0, "correct_answer": "屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は授業で、生徒の屑を採点した。", "explanation": "ここは〈答案〉の意味。屑は答案のように採点の対象になるものではないので、この使い方はしない。"}, {"text": "宝石店の主人は、一日中、屑を丁寧に磨いている。", "explanation": "ここは〈宝物〉の意味。屑は価値のないごみなので、宝のように磨いて飾るものにはならない。"}, {"text": "庭の草花に、毎朝屑をたっぷり水やりする。", "explanation": "ここは〈苗〉の意味。屑は苗のように水をやって育てるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屑", "is_correct": true, "explanation": "小さなごみのことで、拾わないと床が汚れるという文脈に合う。"}, {"text": "壁", "is_correct": false, "explanation": "壁は拾うものではないので、「壁を拾わない」は文として成り立たない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は拾えないので、文脈に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は拾えないので、文脈に合わない。"}], "explanations": {"屑": "小さなごみのことで、拾わないと床が汚れるという文脈に合う。", "壁": "壁は拾うものではないので、「壁を拾わない」は文として成り立たない。", "空気": "空気は拾えないので、文脈に合わない。", "天井": "天井は拾えないので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先で、美しい景色の屑を撮った。", "explanation": "ここは「写真」の意味。屑は写して撮る対象にならないので、この使い方はしない。"}, {"text": "母は茶碗に温かい屑をよそった。", "explanation": "ここは「ご飯」の意味。屑は食べ物として盛るものではないので合わない。"}, {"text": "図書館で、屑を借りた。", "explanation": "ここは「本」の意味。屑は借りて読むものではないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机の下に紙の屑を落ちていた。", "corrected_sentence": "机の下に紙の屑が落ちていた。", "error_description": "正しくは「屑が落ちていた」。「落ちる」は自動詞なので、主語に「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36786, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業のあとに、床の屑に集めた。", "corrected_sentence": "作業のあとに、床の屑を集めた。", "error_description": "正しくは「屑を集めた」。「集める」は他動詞なので、集める対象に「を」を使う。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾。「鉄」が「屑」の素材であることを示すので「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「鉄が屑を集めて」は主語の関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「鉄を屑を」と目的語が二つになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示すが、「鉄に屑を集めて」は不自然。"}], "correct_answer": "の", "explanations": {"の": "連体修飾。「鉄」が「屑」の素材であることを示すので「の」が入る。", "が": "主語を示すが、「鉄が屑を集めて」は主語の関係が成り立たない。", "を": "目的語を示すが、「鉄を屑を」と目的語が二つになり不自然。", "に": "相手や方向を示すが、「鉄に屑を集めて」は不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "相手・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。「屑」について述べるので「は」が入る。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、「屑で運ばれます」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "共同を表すが、「屑と運ばれます」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「屑より運ばれます」は意味をなさない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。「屑」について述べるので「は」が入る。", "で": "手段や場所を表すが、「屑で運ばれます」は意味が通らない。", "と": "共同を表すが、「屑と運ばれます」は不自然。", "より": "比較を表すが、「屑より運ばれます」は意味をなさない。"}, "error_tags": {"で": "手段・場所", "と": "共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "材料を加工したあとに残る、切れ端や余りの部分。", "primary_collocate": null, "pronunciation": "くず", "ipa": "kɯzɯ", "syllable_count": 2, "sentences": [{"text": "布の屑でかわいい小物を作りました。", "target_word": "屑", "complexity_tier": "T3", "furigana": "布[ぬの]の屑[くず]でかわいい小物[こもの]を作[つく]りました。", "sentence_source": "generated"}, {"text": "工場では鉄の屑を集めて、もう一度使います。", "target_word": "屑", "complexity_tier": "T3", "furigana": "工場[こうじょう]では鉄[てつ]の屑[くず]を集[あつ]めて、もう一度[いちど]使[つか]います。", "sentence_source": "generated"}, {"text": "木工所には、木の屑がたくさん出る。", "target_word": "屑", "complexity_tier": "T3", "furigana": "木工所[もっこうじょ]には、木[き]の屑[くず]がたくさん出[で]る。", "sentence_source": "generated"}, {"text": "残った毛糸の屑で、小さな帽子を編みました。", "target_word": "屑", "complexity_tier": "T3", "furigana": "残[のこ]った毛糸[けいと]の屑[くず]で、小[ちい]さな帽子[ぼうし]を編[あ]みました。", "sentence_source": "generated"}, {"text": "切った野菜の屑でスープをとる。", "target_word": "屑", "complexity_tier": "T3", "furigana": "切[き]った野菜[やさい]の屑[くず]でスープをとる。", "sentence_source": "generated"}, {"text": "材料の屑が出ないように、きれいに切ります。", "target_word": "屑", "complexity_tier": "T3", "furigana": "材料[ざいりょう]の屑[くず]が出[で]ないように、きれいに切[き]ります。", "sentence_source": "generated"}, {"text": "革の屑を使って、財布を作る人もいる。", "target_word": "屑", "complexity_tier": "T3", "furigana": "革[かわ]の屑[くず]を使[つか]って、財布[さいふ]を作[つく]る人[ひと]もいる。", "sentence_source": "generated"}, {"text": "金属の屑は、リサイクル工場へ運ばれます。", "target_word": "屑", "complexity_tier": "T3", "furigana": "金属[きんぞく]の屑[くず]は、リサイクル工場[こうじょう]へ運[はこ]ばれます。", "sentence_source": "generated"}, {"text": "ケーキを切ったあとの屑を、子どもたちに分けた。", "target_word": "屑", "complexity_tier": "T3", "furigana": "ケーキを切[き]ったあとの屑[くず]を、子[こ]どもたちに分[わ]けた。", "sentence_source": "generated"}, {"text": "紙の屑を集めて、手作りのノートを作った。", "target_word": "屑", "complexity_tier": "T3", "furigana": "紙[かみ]の屑[くず]を集[あつ]めて、手作[てづく]りのノートを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屑", "label": "基本形"}, {"form": "屑の", "label": "連体形（の）"}, {"form": "屑が", "label": "主語形（が）"}, {"form": "屑を", "label": "目的語形（を）"}], "register": "中立（標準的な話し言葉・書き言葉）", "sense_fingerprint": "布・木・金属などの材料を使ったあとに残る切れ端や余り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屑", "is_correct": true, "explanation": "布の切れ端のことで、小物の材料として自然に使われる。"}, {"text": "布", "is_correct": false, "explanation": "「布の布」は意味が重なり不自然。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は材料にならないので、小物を作る文脈に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は材料にならないので、小物を作る文脈に合わない。"}], "explanations": {"屑": "布の切れ端のことで、小物の材料として自然に使われる。", "布": "「布の布」は意味が重なり不自然。", "太陽": "太陽は材料にならないので、小物を作る文脈に合わない。", "雨": "雨は材料にならないので、小物を作る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毎朝、屑を壺に活ける。", "explanation": "ここは〈花〉の意味。屑は花のように壺に活けるものではないので、この使い方はしない。"}, {"text": "母は屑でパンを焼いた。", "explanation": "ここは「小麦粉」の意味。屑はパンの材料にはならないので、この使い方はしない。"}, {"text": "姉は屑を、来週の試験で先生に出した。", "explanation": "ここは〈答案〉の意味。屑は答案のように先生に提出するものではないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屑", "is_correct": true, "explanation": "革の切れ端のことで、財布を作る材料として使われる。"}, {"text": "光", "is_correct": false, "explanation": "光は材料として使えないので、文脈に合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は材料として使えないので、文脈に合わない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は材料として使えないので、文脈に合わない。"}], "explanations": {"屑": "革の切れ端のことで、財布を作る材料として使われる。", "光": "光は材料として使えないので、文脈に合わない。", "音": "音は材料として使えないので、文脈に合わない。", "空気": "空気は材料として使えないので、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉が渇いたので、コップの屑を飲んだ。", "explanation": "ここは「水」の意味。屑は飲むものではないので、この使い方はしない。"}, {"text": "子どもたちは、みんなで楽しい屑を歌った。", "explanation": "ここは〈曲〉の意味。屑は楽しい曲のように歌うものではないので合わない。"}, {"text": "歯ブラシで、屑を磨いた。", "explanation": "ここは〈靴〉の意味。屑は靴のように磨いてきれいにするものではないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "残った布の屑が、クッションを作った。", "corrected_sentence": "残った布の屑で、クッションを作った。", "error_description": "正しくは「屑で」。材料を表すには「で」を使う。「が」は主語を示すので、「屑が作った」は意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場で出た金属の屑を、すべて回収される。", "corrected_sentence": "工場で出た金属の屑は、すべて回収される。", "error_description": "正しくは「屑は」。「回収される」は受け身なので、対象は主語として「は」や「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所属を表す「の」。「蜜柑の皮」と続けて、蜜柑のものだと示す。"}, {"text": "に", "is_correct": false, "explanation": "相手・方向の「に」。「蜜柑に皮をむく」では意味が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「をむく」と二つ重なり、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「蜜柑へ皮をむく」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "所属を表す「の」。「蜜柑の皮」と続けて、蜜柑のものだと示す。", "に": "相手・方向の「に」。「蜜柑に皮をむく」では意味が成り立たない。", "を": "目的語の「を」。「をむく」と二つ重なり、不自然になる。", "へ": "方向の「へ」。「蜜柑へ皮をむく」では意味が通らない。"}, "error_tags": {"に": "相手・方向", "を": "目的語の重複", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す「を」。「蜜柑を食べる」と目的語として続く。"}, {"text": "に", "is_correct": false, "explanation": "相手・方向の「に」。「蜜柑に食べる」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「蜜柑へ食べる」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "所属の「の」。「蜜柑の食べる」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す「を」。「蜜柑を食べる」と目的語として続く。", "に": "相手・方向の「に」。「蜜柑に食べる」では成り立たない。", "へ": "方向の「へ」。「蜜柑へ食べる」では意味が通らない。", "の": "所属の「の」。「蜜柑の食べる」では文が成り立たない。"}, "error_tags": {"に": "相手・方向", "へ": "方向", "の": "所属"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "だいだいいろの くだもの。かわを むいて たべる。", "primary_collocate": null, "pronunciation": "みかん", "ipa": "mikaɴ", "syllable_count": 3, "sentences": [{"text": "冬は、こたつで蜜柑を食べるのが楽しみです。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "冬[ふゆ]は、こたつで蜜柑[みかん]を食[た]べるのが楽[たの]しみです。", "sentence_source": "generated"}, {"text": "蜜柑の皮をむくと、いい匂いがした。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]の皮[かわ]をむくと、いい匂[にお]いがした。", "sentence_source": "generated"}, {"text": "祖母が、箱いっぱいの蜜柑を送ってくれた。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "祖母[そぼ]が、箱[はこ]いっぱいの蜜柑[みかん]を送[おく]ってくれた。", "sentence_source": "generated"}, {"text": "この蜜柑は甘いので、子どもたちに人気がある。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "この蜜柑[みかん]は甘[あま]いので、子[こ]どもたちに人気[にんき]がある。", "sentence_source": "generated"}, {"text": "朝ごはんに、パンと蜜柑を食べた。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんに、パンと蜜柑[みかん]を食[た]べた。", "sentence_source": "generated"}, {"text": "机の上のかごに、蜜柑が三つ入っている。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]のかごに、蜜柑[みかん]が三[みっ]つ入[はい]っている。", "sentence_source": "generated"}, {"text": "蜜柑は皮が薄いので、手で簡単にむける。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]は皮[かわ]が薄[うす]いので、手[て]で簡単[かんたん]にむける。", "sentence_source": "generated"}, {"text": "八百屋で、安い蜜柑を一袋買った。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "八百屋[やおや]で、安[やす]い蜜柑[みかん]を一袋[ひとふくろ]買[か]った。", "sentence_source": "generated"}, {"text": "蜜柑の房を一つずつ分けて、弟にあげた。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]の房[ふさ]を一[ひと]つずつ分[わ]けて、弟[おとうと]にあげた。", "sentence_source": "generated"}, {"text": "風邪をひいた日、母が蜜柑を持ってきてくれた。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいた日[ひ]、母[はは]が蜜柑[みかん]を持[も]ってきてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜柑", "label": "基本形"}, {"form": "蜜柑を", "label": "目的語形"}, {"form": "蜜柑が", "label": "主語形"}, {"form": "蜜柑の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "皮をむいて食べる、橙色の身近な果物としての「蜜柑」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜柑", "is_correct": true, "explanation": "食べられる果物の名前。「こたつで〜を食べる」に合う。"}, {"text": "石", "is_correct": false, "explanation": "石は食べられないので、「石を食べる」は成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は食べ物ではないので、食べるものとして合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は食べられない物で、ここには入らない。"}], "explanations": {"蜜柑": "食べられる果物の名前。「こたつで〜を食べる」に合う。", "石": "石は食べられないので、「石を食べる」は成り立たない。", "鉛筆": "鉛筆は食べ物ではないので、食べるものとして合わない。", "座布団": "座布団は食べられない物で、ここには入らない。"}, "sentence_index": 0, "correct_answer": "蜜柑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花から蜜柑を集めて、ハチが巣に運ぶ。", "explanation": "ここは〈蜜〉の話。ハチが花から集めるのは蜜で、果物の蜜柑ではないので合わない。"}, {"text": "梅干しを作るために、蜜柑を塩で漬けた。", "explanation": "ここは〈梅〉の話。梅干しは梅を塩で漬けたものなので、蜜柑では作らない。"}, {"text": "この蜜柑は、渋抜きをして甘くした。", "explanation": "ここは〈柿〉の話。渋抜きは渋柿の処理で、蜜柑には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜柑", "is_correct": true, "explanation": "食べられる果物の名前。皮が薄くむけるという説明に合う。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は皮を持たず、むいて食べるものではないので合わない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は皮を持たず、むいて食べるものではないので合わない。"}, {"text": "段ボール", "is_correct": false, "explanation": "段ボールは食べ物ではなく、皮がむけるという説明に合わない。"}], "explanations": {"蜜柑": "食べられる果物の名前。皮が薄くむけるという説明に合う。", "鉄": "鉄は皮を持たず、むいて食べるものではないので合わない。", "氷": "氷は皮を持たず、むいて食べるものではないので合わない。", "段ボール": "段ボールは食べ物ではなく、皮がむけるという説明に合わない。"}, "sentence_index": 6, "correct_answer": "蜜柑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜柑は、まず鬼皮をむいてから渋皮をむく。", "explanation": "ここは〈栗〉の話。鬼皮と渋皮は栗の皮なので、蜜柑には使わない。"}, {"text": "のどが痛い夜は、温かい蜜柑を湯に溶かして飲む。", "explanation": "ここは〈蜂蜜〉の話。湯に溶かして飲むのは蜂蜜で、蜜柑をその使い方では言わない。"}, {"text": "蜜柑のひげをとって、ゆでる。", "explanation": "ここは〈とうもろこし〉の話。ひげは実の先についたとうもろこしの特徴で、蜜柑にはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬は、こたつで蜜柑が食べて過ごします。", "corrected_sentence": "冬は、こたつで蜜柑を食べて過ごします。", "error_description": "助詞の誤り。「食べる」の目的語は「を」で示す。「蜜柑が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36788, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父が、蜜柑が一箱送ってくれた。", "corrected_sentence": "祖父が、蜜柑を一箱送ってくれた。", "error_description": "助詞の誤り。「送る」の目的語である「蜜柑」は「を」で示す。「蜜柑が」だと蜜柑が送ってくれたことになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "蜜柑を主題にして「冬が旬」と述べる文になり、正しい。"}, {"text": "を", "is_correct": false, "explanation": "蜜柑を目的語にすると後ろの「冬が旬で」と続かず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表す「で」は、主題を示す位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、ここでは文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "蜜柑を主題にして「冬が旬」と述べる文になり、正しい。", "を": "蜜柑を目的語にすると後ろの「冬が旬で」と続かず、不自然。", "で": "場所や手段を表す「で」は、主題を示す位置に合わない。", "へ": "方向を表す「へ」は、ここでは文として成り立たない。"}, "error_tags": {"は": "主題", "を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "蜜柑と木が連体修飾でつながり、「蜜柑の木」として正しい。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、蜜柑と木の関係を表せず、「蜜柑から木には」は非文。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、木の位置を表す文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所の「で」は、蜜柑と木の関係を表せず合わない。"}], "correct_answer": "の", "explanations": {"の": "蜜柑と木が連体修飾でつながり、「蜜柑の木」として正しい。", "から": "起点の「から」は、蜜柑と木の関係を表せず、「蜜柑から木には」は非文。", "を": "目的語の「を」は、木の位置を表す文に合わない。", "で": "場所の「で」は、蜜柑と木の関係を表せず合わない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ミカン科の常緑低木、またはその果実。冬に実る橙色の果物で、皮をむいて食べる。", "primary_collocate": null, "pronunciation": "みかん", "ipa": "mikaɴ", "syllable_count": 3, "sentences": [{"text": "庭の蜜柑の木に、橙色の実がたくさんなっている。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "庭[にわ]の蜜柑[みかん]の木[き]に、橙色[だいだいいろ]の実[み]がたくさんなっている。", "sentence_source": "generated"}, {"text": "蜜柑は冬が旬で、十二月ごろにいちばんおいしくなる。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]は冬[ふゆ]が旬[しゅん]で、十二月[じゅうにがつ]ごろにいちばんおいしくなる。", "sentence_source": "generated"}, {"text": "愛媛は、蜜柑の産地として有名だ。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "愛媛[えひめ]は、蜜柑[みかん]の産地[さんち]として有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "蜜柑の畑では、秋の終わりから収穫が始まる。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]の畑[はたけ]では、秋[あき]の終[お]わりから収穫[しゅうかく]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "蜜柑の実は、緑から橙色に変わる。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]の実[み]は、緑[みどり]から橙色[だいだいいろ]に変[か]わる。", "sentence_source": "generated"}, {"text": "蜜柑は常緑の木なので、冬でも葉が落ちない。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]は常緑[じょうりょく]の木[き]なので、冬[ふゆ]でも葉[は]が落[お]ちない。", "sentence_source": "generated"}, {"text": "山の斜面に蜜柑の畑が広がっている。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]に蜜柑[みかん]の畑[はたけ]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "蜜柑の木には、初夏に白くて小さな花が咲く。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "蜜柑[みかん]の木には、初夏に白くて小さな花が咲く。", "sentence_source": "generated"}, {"text": "収穫した蜜柑を、大きな箱に詰めて出荷する。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "収穫[しゅうかく]した蜜柑[みかん]を、大[おお]きな箱[はこ]に詰[つ]めて出荷[しゅっか]する。", "sentence_source": "generated"}, {"text": "寒い地方では蜜柑は育ちにくいので、暖かい海沿いで作られる。", "target_word": "蜜柑", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]では蜜柑[みかん]は育[そだ]ちにくいので、暖[あたた]かい海沿[うみぞ]いで作[つく]られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜜柑", "label": "基本形"}, {"form": "蜜柑を", "label": "目的語形"}, {"form": "蜜柑が", "label": "主語形"}, {"form": "蜜柑の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "木・栽培・産地・旬など植物としての面も含む「蜜柑」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜柑", "is_correct": true, "explanation": "庭の木に橙色の実がなる文脈で、「蜜柑の木」が自然に続く。"}, {"text": "池", "is_correct": false, "explanation": "「庭の池の木」とは言わず、実がなる文脈にも合わない。"}, {"text": "石", "is_correct": false, "explanation": "石に木が付くという組み合わせは成り立たず、実がなる文と合わない。"}, {"text": "物置", "is_correct": false, "explanation": "物置の木とは言わず、橙色の実がなる文脈に合わない。"}], "explanations": {"蜜柑": "庭の木に橙色の実がなる文脈で、「蜜柑の木」が自然に続く。", "池": "「庭の池の木」とは言わず、実がなる文脈にも合わない。", "石": "石に木が付くという組み合わせは成り立たず、実がなる文と合わない。", "物置": "物置の木とは言わず、橙色の実がなる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "蜜柑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜柑を塩と糠で漬けて、沢庵のように冬の食卓に出した。", "explanation": "ここは〈大根〉の用法。沢庵は大根を漬けたものなので、蜜柑を沢庵に仕立てるとは言わないので合わない。"}, {"text": "朝、パンに蜜柑を塗って食べた。", "explanation": "ここは〈蜂蜜〉の用法。蜜柑は果物を丸ごと指すもので、パンに塗るものではないので合わない。"}, {"text": "蜜柑を塩で漬け込んで、冬まで保存する。", "explanation": "ここは〈梅〉の用法。梅を塩で漬けて梅干しにするのは梅の扱いで、蜜柑を塩漬けにして冬まで保存する習慣はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜柑", "is_correct": true, "explanation": "山の斜面に広がる畑の作物として、「蜜柑の畑」が自然に続く。"}, {"text": "岩", "is_correct": false, "explanation": "「岩の畑」とは言えず、作物が広がる文脈に合わない。"}, {"text": "煙", "is_correct": false, "explanation": "煙が畑を作るという組み合わせは成り立たず、広がる文脈に合わない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧の畑」とは言わず、斜面に広がる畑の文脈に合わない。"}], "explanations": {"蜜柑": "山の斜面に広がる畑の作物として、「蜜柑の畑」が自然に続く。", "岩": "「岩の畑」とは言えず、作物が広がる文脈に合わない。", "煙": "煙が畑を作るという組み合わせは成り立たず、広がる文脈に合わない。", "霧": "「霧の畑」とは言わず、斜面に広がる畑の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "蜜柑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜柑は牛乳を固めて作る食べ物で、冷蔵庫で保存する。", "explanation": "ここは〈チーズ〉の製法。牛乳を固めて作るのはチーズで、蜜柑は果物なのでこの説明は合わない。"}, {"text": "蜜柑を石膏で固めて、切り分けて食べた。", "explanation": "ここは〈豆腐〉の製法。石膏などで固めて切り分けるのは豆腐で、蜜柑をこの方法で作るとは言わないので合わない。"}, {"text": "壁の蜜柑が、十二時を指していた。", "explanation": "ここは〈時計〉の用法。時刻を指すのは時計で、果物の蜜柑は時刻を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎年、冬になると蜜柑に収穫して、友達に送る。", "corrected_sentence": "毎年、冬になると蜜柑を収穫して、友達に送る。", "error_description": "「収穫する」は他動詞なので、目的語の蜜柑には「を」を使う。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36789, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜柑へ苗木を、祖父は毎年庭に植える。", "corrected_sentence": "蜜柑の苗木を、祖父は毎年庭に植える。", "error_description": "「蜜柑の苗木」は「蜜柑の」で苗木の種類を表す。「蜜柑へ」は方向を表すので、名詞を修飾する「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「いる」の存在場所を示す「に」で、「川に魚がいる」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、存在の「いる」の文には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、いる場所を表す形にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「川より魚がいる」は文意が通らない。"}], "correct_answer": "に", "explanations": {"に": "「いる」の存在場所を示す「に」で、「川に魚がいる」の形になる。", "を": "「を」は目的語を示すので、存在の「いる」の文には入らない。", "へ": "「へ」は方向を示し、いる場所を表す形にはならない。", "より": "「より」は比較を示すので、「川より魚がいる」は文意が通らない。"}, "error_tags": {"で": "動作の場所", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「川の水」で、川に属する水であることを示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所を示すので、川に属する水という所属の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「川を水が」は目的語の形になり、後ろの主語「水が」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「川へ水が」は方向を示し、川に属する水という意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「川の水」で、川に属する水であることを示す。", "に": "「に」は場所を示すので、川に属する水という所属の意味にならない。", "を": "「川を水が」は目的語の形になり、後ろの主語「水が」と合わない。", "へ": "「川へ水が」は方向を示し、川に属する水という意味にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みずが ながれて いる ところ。", "primary_collocate": null, "pronunciation": "かわ", "ipa": "kaɰa", "syllable_count": 2, "sentences": [{"text": "川の水はとても冷たくて、足を入れると気持ちがいいです。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]はとても冷[つめ]たくて、足[あし]を入[い]れると気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "川には魚がたくさんいるので、父と釣りに行きました。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]には魚[さかな]がたくさんいるので、父[ちち]と釣[つ]りに行[い]きました。", "sentence_source": "generated"}, {"text": "雨がたくさん降ったから、川の水が増えました。", "target_word": "川", "complexity_tier": "T3", "furigana": "雨[あめ]がたくさん降[ふ]ったから、川[かわ]の水[みず]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "川に橋がかかっていて、歩いて向こうへ渡れます。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]に橋[はし]がかかっていて、歩[ある]いて向[む]こうへ渡[わた]れます。", "sentence_source": "generated"}, {"text": "夏になると、子どもたちは川で泳いで遊びます。", "target_word": "川", "complexity_tier": "T3", "furigana": "夏[なつ]になると、子[こ]どもたちは川[かわ]で泳[およ]いで遊[あそ]びます。", "sentence_source": "generated"}, {"text": "川の水は山から海のほうへ流れていきます。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は山[やま]から海[うみ]のほうへ流[なが]れていきます。", "sentence_source": "generated"}, {"text": "私の家の近くには、きれいな川があります。", "target_word": "川", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]の近[ちか]くには、きれいな川[かわ]があります。", "sentence_source": "generated"}, {"text": "川の水が汚れていたので、魚は一匹もいませんでした。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が汚[よご]れていたので、魚[さかな]は一匹[いっぴき]もいませんでした。", "sentence_source": "generated"}, {"text": "川のそばを歩くと、涼しい風が吹いていました。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]のそばを歩[ある]くと、涼[すず]しい風[かぜ]が吹[ふ]いていました。", "sentence_source": "generated"}, {"text": "昨日は川で石を拾って、家に持って帰りました。", "target_word": "川", "complexity_tier": "T3", "furigana": "昨日[きのう]は川[かわ]で石[いし]を拾[ひろ]って、家[いえ]に持[も]って帰[かえ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "川", "label": "基本形"}], "register": "標準（丁寧）", "sense_fingerprint": "水が流れている場所、川（やさしい説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "川", "is_correct": true, "explanation": "「川の水」は流れのある水場を指し、足を入れて涼めるという文脈に合う。"}, {"text": "空", "is_correct": false, "explanation": "「空の水」は成り立たず、足を入れて涼める水場を指さない。"}, {"text": "石", "is_correct": false, "explanation": "「石の水」は意味が通らず、水が流れる場所を表さない。"}, {"text": "風", "is_correct": false, "explanation": "「風の水」は不自然で、冷たい水のある場所を表す語にならない。"}], "explanations": {"川": "「川の水」は流れのある水場を指し、足を入れて涼めるという文脈に合う。", "空": "「空の水」は成り立たず、足を入れて涼める水場を指さない。", "石": "「石の水」は意味が通らず、水が流れる場所を表さない。", "風": "「風の水」は不自然で、冷たい水のある場所を表す語にならない。"}, "sentence_index": 0, "correct_answer": "川"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園の川では、ボートがのんびり浮かび、鯉が水面に顔を出している。", "explanation": "ここは〈池〉の意味。水がとどまって動かないところは池を指し、流れる川とは違う。"}, {"text": "この川は周りを山に囲まれ、水がほとんど動かず、空を静かに映している。", "explanation": "ここは〈湖〉の意味。川は流れている水を指すので、動かない水の様子には合わない。"}, {"text": "この川は高い崖から一気に落ちて、白いしぶきを上げている。", "explanation": "ここは〈滝〉の意味。川は地形に沿って流れ下るもので、崖から垂直に落ちる様子は滝を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "川", "is_correct": true, "explanation": "近くにある清らかな水場を指し、「きれいな川があります」と自然に続く。"}, {"text": "泥", "is_correct": false, "explanation": "「きれいな泥」は汚れを連想させ、清らかな場所の意味に合わない。"}, {"text": "ほこり", "is_correct": false, "explanation": "「きれいなほこり」は矛盾し、清潔な風景を表す語として合わない。"}, {"text": "排気ガス", "is_correct": false, "explanation": "「きれいな排気ガス」は矛盾し、近くにあって心地よい場所を表す語にならない。"}], "explanations": {"川": "近くにある清らかな水場を指し、「きれいな川があります」と自然に続く。", "泥": "「きれいな泥」は汚れを連想させ、清らかな場所の意味に合わない。", "ほこり": "「きれいなほこり」は矛盾し、清潔な風景を表す語として合わない。", "排気ガス": "「きれいな排気ガス」は矛盾し、近くにあって心地よい場所を表す語にならない。"}, "sentence_index": 6, "correct_answer": "川"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バスルームの川から、熱いお湯が勢いよく出てきた。", "explanation": "ここは〈シャワー〉の意味。体にお湯をかける設備を指し、自然に流れる川とは違う。"}, {"text": "台所の川から冷たい水を汲んで、コップに注いだ。", "explanation": "ここは〈水道〉の意味。蛇口から出る水を指し、自然に流れる川とは違う。"}, {"text": "朝の山道に、白い川がふわりとたちこめて、景色が見えなかった。", "explanation": "ここは〈霧〉の意味。川は地面を流れる水なので、空気中にたちこめるものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の上の川を、夏になると魚が集まります。", "corrected_sentence": "山の上の川に、夏になると魚が集まります。", "error_description": "「集まる」は場所を「に」で示すので、「川を」は誤り。「を」は他動詞の目的語を示す助詞で、自動詞の「集まる」には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36790, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の湧き水が集まって、この谷には細い川が一枚流れている。", "corrected_sentence": "山の湧き水が集まって、この谷には細い川が一本流れている。", "error_description": "川は細長く流れるものなので助数詞は「本」が正しい。「枚」は平らなものを数える助数詞で、川には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
