INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「川の水」で、川に属する水であることを示す。"}, {"text": "へ", "is_correct": false, "explanation": "「川へ水は」は方向を示し、川に属する水という意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「川を水は」は目的語の形になり、主題の「水は」と並ばず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「川より水は」は比較の形になり、川に属する水の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「川の水」で、川に属する水であることを示す。", "へ": "「川へ水は」は方向を示し、川に属する水という意味にならない。", "を": "「川を水は」は目的語の形になり、主題の「水は」と並ばず不自然。", "より": "「川より水は」は比較の形になり、川に属する水の意味にならない。"}, "error_tags": {"へ": "方向", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地上に降った雨水などが集まって、低い方へ流れていく水の流れ。", "primary_collocate": null, "pronunciation": "かわ", "ipa": "kaɰa", "syllable_count": 2, "sentences": [{"text": "山に降った雨が集まって、大きな川になる。", "target_word": "川", "complexity_tier": "T3", "furigana": "山[やま]に降[ふ]った雨[あめ]が集[あつ]まって、大[おお]きな川[かわ]になる。", "sentence_source": "generated"}, {"text": "台風のあと、川の水が急に増えて危険だった。", "target_word": "川", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、川[かわ]の水[みず]が急[きゅう]に増[ふ]えて危険[きけん]だった。", "sentence_source": "generated"}, {"text": "この川は北の山から流れ出て、町の真ん中を通っている。", "target_word": "川", "complexity_tier": "T3", "furigana": "この川[かわ]は北[きた]の山[やま]から流[なが]れ出[で]て、町[まち]の真[ま]ん中[なか]を通[とお]っている。", "sentence_source": "generated"}, {"text": "川の流れが速いので、子どもが入ってはいけない。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れが速[はや]いので、子[こ]どもが入[はい]ってはいけない。", "sentence_source": "generated"}, {"text": "川が海に出るところには、広い砂浜が広がっている。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]が海[うみ]に出[で]るところには、広[ひろ]い砂浜[すなはま]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "昔の人は、川の水を飲み水や畑に使っていた。", "target_word": "川", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、川[かわ]の水[みず]を飲[の]み水[みず]や畑[はたけ]に使[つか]っていた。", "sentence_source": "generated"}, {"text": "大雨で川があふれ、道路が水につかった。", "target_word": "川", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で川[かわ]があふれ、道路[どうろ]が水[みず]につかった。", "sentence_source": "generated"}, {"text": "川の水は上から下へ流れるので、船で上るのは大変だ。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は上[うえ]から下[した]へ流[なが]れるので、船[ふね]で上[のぼ]るのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "春になると、雪がとけて川の水が多くなる。", "target_word": "川", "complexity_tier": "T3", "furigana": "春[はる]になると、雪[ゆき]がとけて川[かわ]の水[みず]が多[おお]くなる。", "sentence_source": "generated"}, {"text": "川に沿って歩いていくと、小さな橋が見えてきた。", "target_word": "川", "complexity_tier": "T3", "furigana": "川[かわ]に沿[そ]って歩[ある]いていくと、小[ちい]さな橋[はし]が見[み]えてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "川", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "雨水が集まり低い方へ流れる水の流れ、河川", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "川", "is_correct": true, "explanation": "雨水が集まって大きくなった流れを指し、「大きな川になる」と自然に続く。"}, {"text": "空", "is_correct": false, "explanation": "「大きな空になる」は意味が通らず、雨水が集まって流れる先にならない。"}, {"text": "石", "is_correct": false, "explanation": "「大きな石になる」は雨水が集まった結果として成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "「大きな花になる」は雨水の流れとは無関係で、結果として不自然。"}], "explanations": {"川": "雨水が集まって大きくなった流れを指し、「大きな川になる」と自然に続く。", "空": "「大きな空になる」は意味が通らず、雨水が集まって流れる先にならない。", "石": "「大きな石になる」は雨水が集まった結果として成り立たない。", "花": "「大きな花になる」は雨水の流れとは無関係で、結果として不自然。"}, "sentence_index": 0, "correct_answer": "川"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裏庭の川では、金魚が静かに泳ぎ、睡蓮の葉が水面を覆っている。", "explanation": "ここは〈池〉の意味。ためた水で動かないものは池を指し、低い方へ流れていく川には合わない。"}, {"text": "山の奥の川は、雨水が集まって広く静かにたまり、水はほとんど流れていない。", "explanation": "ここは〈湖〉の意味。この語は低い方へ流れていく水を指すので、流れのない水には合わない。"}, {"text": "がけの上の川は、雨水が一気に真下へ落ち、白く砕けて飛び散る。", "explanation": "ここは〈滝〉の意味。川は低い方へ流れ下るもので、崖から真下に落ちる様子は滝を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "川", "is_correct": true, "explanation": "増えた流れが溢れるという意味で、「大雨で川があふれ」と自然に続く。"}, {"text": "窓", "is_correct": false, "explanation": "「窓があふれ」は意味が通らず、水があふれる対象にならない。"}, {"text": "箱", "is_correct": false, "explanation": "「箱があふれ」は不自然で、水があふれる対象として成り立たない。"}, {"text": "畑", "is_correct": false, "explanation": "「畑があふれ」は不自然で、水があふれる場所として合わない。"}], "explanations": {"川": "増えた流れが溢れるという意味で、「大雨で川があふれ」と自然に続く。", "窓": "「窓があふれ」は意味が通らず、水があふれる対象にならない。", "箱": "「箱があふれ」は不自然で、水があふれる対象として成り立たない。", "畑": "「畑があふれ」は不自然で、水があふれる場所として合わない。"}, "sentence_index": 6, "correct_answer": "川"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の朝、川に白い芽が次々と出て、みんな畑を耕す。", "explanation": "ここは〈畑〉の意味。作物を育てる土地を指し、低い方へ流れていく水の川とは違う。"}, {"text": "台所の川の栓をひねって、冷たい水を汲んだ。", "explanation": "ここは〈水道〉の意味。栓や蛇口から出る水を指し、自然に流れる川とは違う。"}, {"text": "朝の山道に、白い川がふわりとたちこめて、遠くの景色が見えなかった。", "explanation": "ここは〈霧〉の意味。川は地面を流れる水なので、空気中にたちこめるものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谷あいの雨水が集まって、低いほうへ流す川になっていく。", "corrected_sentence": "谷あいの雨水が集まって、低いほうへ流れる川になっていく。", "error_description": "「川」を修飾するのは自動詞「流れる」。「流す」は他動詞で、水が自ら流れる川の意味にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36791, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな沢が集まって、やがて大きな川がなっていく。", "corrected_sentence": "小さな沢が集まって、やがて大きな川になっていく。", "error_description": "「〜になる」の「に」は変化の結果を示す。「が」では変化の先を示せないので、ここは「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「木の下に埋める」で、埋める場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「木の下が埋めて」は主語が二つになり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「木の下と埋めて」は並列になり、埋める場所の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「木の下より埋めて」は比較になり、文意が通らない。"}], "correct_answer": "に", "explanations": {"に": "「木の下に埋める」で、埋める場所を示す。", "が": "「木の下が埋めて」は主語が二つになり、不自然。", "と": "「木の下と埋めて」は並列になり、埋める場所の意味にならない。", "より": "「木の下より埋めて」は比較になり、文意が通らない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地面に埋める」で、埋める場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「地面を」が「ごみを」と並んで目的語が重なり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「地面が埋める」は主語になり、「ごみを」と並んで埋める場所の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「地面から埋める」は起点を示し、ごみを埋める場所の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「地面に埋める」で、埋める場所を示す。", "を": "「地面を」が「ごみを」と並んで目的語が重なり、文が成り立たない。", "が": "「地面が埋める」は主語になり、「ごみを」と並んで埋める場所の意味にならない。", "から": "「地面から埋める」は起点を示し、ごみを埋める場所の意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをあなにいれて、そのうえをとちでかくすことです。", "primary_collocate": null, "pronunciation": "うめる", "ipa": "ɯmeɾɯ", "syllable_count": 3, "sentences": [{"text": "犬は大切な骨を庭の土に埋めました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "犬[いぬ]は大切[たいせつ]な骨[ほね]を庭[にわ]の土[つち]に埋[う]めました。", "sentence_source": "generated"}, {"text": "宝物の箱を木の下に埋めて、地図を書きました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "宝物[たからもの]の箱[はこ]を木[き]の下[した]に埋[う]めて、地図[ちず]を書[か]きました。", "sentence_source": "generated"}, {"text": "子どもたちは砂浜で、友だちの足を砂に埋めて遊びました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "子[こ]どもたちは砂浜[すなはま]で、友[とも]だちの足[あし]を砂[すな]に埋[う]めて遊[あそ]びました。", "sentence_source": "generated"}, {"text": "死んだ小鳥を、公園の隅に埋めました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "死[し]んだ小鳥[ことり]を、公園[こうえん]の隅[すみ]に埋[う]めました。", "sentence_source": "generated"}, {"text": "春に花が咲くように、秋に球根を土に埋めます。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "春[はる]に花[はな]が咲[さ]くように、秋[あき]に球根[きゅうこん]を土[つち]に埋[う]めます。", "sentence_source": "generated"}, {"text": "掘った穴に種を入れて、土をかけて埋めました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "掘[ほ]った穴[あな]に種[たね]を入[い]れて、土[つち]をかけて埋[う]めました。", "sentence_source": "generated"}, {"text": "だれにも見つからないように、お金を山の中に埋めた男の話を読みました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "だれにも見[み]つからないように、お金[かね]を山[やま]の中[なか]に埋[う]めた男[おとこ]の話[はなし]を読[よ]みました。", "sentence_source": "generated"}, {"text": "ごみを地面に埋めると、土が汚れてしまいます。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "ごみを地面[じめん]に埋[う]めると、土[つち]が汚[よご]れてしまいます。", "sentence_source": "generated"}, {"text": "私は手紙を缶に入れて、校庭に埋めました。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "私[わたし]は手紙[てがみ]を缶[かん]に入[い]れて、校庭[こうてい]に埋[う]めました。", "sentence_source": "generated"}, {"text": "祖父は畑に大根を埋めて、冬の間も保存します。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "祖父[そふ]は畑[はたけ]に大根[だいこん]を埋[う]めて、冬[ふゆ]の間[あいだ]も保存[ほぞん]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "埋めます", "label": "丁寧形"}, {"form": "埋めた", "label": "た形"}, {"form": "埋めて", "label": "て形"}, {"form": "埋めない", "label": "ない形"}, {"form": "埋めれば", "label": "ば形"}, {"form": "埋めよう", "label": "意向形"}], "register": "標準（丁寧）", "sense_fingerprint": "物を穴に入れて上に土をかけ隠す、埋める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めました」で、物を土の中に入れて覆い隠す意味になる。"}, {"text": "食べ", "is_correct": false, "explanation": "「庭の土に食べました」は不自然で、食べる先は口になる。"}, {"text": "洗い", "is_correct": false, "explanation": "「庭の土に洗いました」は意味が通らず、土に物を隠す行為にならない。"}, {"text": "燃や", "is_correct": false, "explanation": "「庭の土に燃やしました」は不自然で、土の中に隠す行為を表さない。"}], "explanations": {"埋め": "「埋めました」で、物を土の中に入れて覆い隠す意味になる。", "食べ": "「庭の土に食べました」は不自然で、食べる先は口になる。", "洗い": "「庭の土に洗いました」は意味が通らず、土に物を隠す行為にならない。", "燃や": "「庭の土に燃やしました」は不自然で、土の中に隠す行為を表さない。"}, "sentence_index": 0, "correct_answer": "埋め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "死んだ小鳥を、公園の隅に植えました。", "explanation": "ここは〈植える〉の意味。草木を地面に据える動作で、小鳥を土で覆う意味にはならない。"}, {"text": "死んだ小鳥を、公園の隅に掘りました。", "explanation": "ここは〈掘る〉の意味。穴をあける動作で、物を入れて土で覆う意味ではない。"}, {"text": "空いた時間を、読書で詰めました。", "explanation": "ここは〈詰める〉の意味。物を隙間へ押し込む動作で、時間を満たす〈埋める〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めた」で、お金を土の中に隠す意味になる。"}, {"text": "眺め", "is_correct": false, "explanation": "「眺めた」は見る動作で、お金を山の中に隠す意味にならない。"}, {"text": "磨い", "is_correct": false, "explanation": "「磨いた」は磨く動作で、隠す意味にならない。"}, {"text": "干し", "is_correct": false, "explanation": "「干した」は乾かす動作で、山の中に隠す意味にならない。"}], "explanations": {"埋め": "「埋めた」で、お金を土の中に隠す意味になる。", "眺め": "「眺めた」は見る動作で、お金を山の中に隠す意味にならない。", "磨い": "「磨いた」は磨く動作で、隠す意味にならない。", "干し": "「干した」は乾かす動作で、山の中に隠す意味にならない。"}, "sentence_index": 6, "correct_answer": "埋め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は畑に大根を捨てて、冬の間も保存します。", "explanation": "ここは〈捨てる〉の意味。手放す行為は保存と矛盾し、土で覆う〈埋める〉の意味にはならない。"}, {"text": "祖父は畑に大根を磨いて、冬の間も保存します。", "explanation": "ここは〈磨く〉の意味。表面をみがく動作で、土をかぶせる〈埋める〉とは違う。"}, {"text": "祖父は畑に大根を縫って、冬の間も保存します。", "explanation": "ここは〈縫う〉の意味。布や革を糸で綴る動作で、土で覆う〈埋める〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い缶を庭の隅に埋もれて、ふたをした。", "corrected_sentence": "古い缶を庭の隅に埋めて、ふたをした。", "error_description": "「埋める」は他動詞で「〜を埋める」の形をとる。「埋もれる」は自動詞なので、「缶を埋もれて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めて」の連用形で、後ろに「て」が続く形として正しい。"}, {"text": "埋めた", "is_correct": false, "explanation": "過去形なので、「て」で続けて動作を並べる文の形に合わない。"}, {"text": "埋めない", "is_correct": false, "explanation": "否定形なので、実際に行った肯定の動作を述べる文に合わない。"}, {"text": "埋めよう", "is_correct": false, "explanation": "意向形なので、実際に行った動作を述べる文の形に合わない。"}], "correct_form": "埋め", "base_form": "埋める", "form_label": "連用形", "sentence_index": 1, "explanations": {"埋め": "「埋めて」の連用形で、後ろに「て」が続く形として正しい。", "埋めた": "過去形なので、「て」で続けて動作を並べる文の形に合わない。", "埋めない": "否定形なので、実際に行った肯定の動作を述べる文に合わない。", "埋めよう": "意向形なので、実際に行った動作を述べる文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36792, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日、古い手紙を庭の隅に埋めました。", "corrected_sentence": "明日、古い手紙を庭の隅に埋めます。", "error_description": "「明日」は未来を示すので、非過去の「埋めます」が正しい。「埋めました」は過去形で、未来の予定と矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めると」の連用形で、後ろの「と」に続く形として正しい。"}, {"text": "埋めます", "is_correct": false, "explanation": "丁寧形の「ます」は語幹の後に「る」を続けられず、「埋めますると」となって成り立たない。"}, {"text": "埋めて", "is_correct": false, "explanation": "「て」形なので、「と」の条件節に続かない。"}, {"text": "埋めれば", "is_correct": false, "explanation": "仮定形なので、続く「と」と重なり、文が成り立たない。"}], "correct_form": "埋め", "base_form": "埋める", "form_label": "連用形", "sentence_index": 7, "explanations": {"埋め": "「埋めると」の連用形で、後ろの「と」に続く形として正しい。", "埋めます": "丁寧形の「ます」は語幹の後に「る」を続けられず、「埋めますると」となって成り立たない。", "埋めて": "「て」形なので、「と」の条件節に続かない。", "埋めれば": "仮定形なので、続く「と」と重なり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「池を埋める」で、埋める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「池が埋めて」は池を主語にしてしまい、埋める対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「池と埋めて」は並列になり、埋める対象の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「池より埋めて」は比較になり、文意が通らない。"}], "correct_answer": "を", "explanations": {"を": "「池を埋める」で、埋める対象を示す。", "が": "「池が埋めて」は池を主語にしてしまい、埋める対象を示せない。", "と": "「池と埋めて」は並列になり、埋める対象の意味にならない。", "より": "「池より埋めて」は比較になり、文意が通らない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「土で埋める」の「で」は、埋めるための材料を示す。"}, {"text": "を", "is_correct": false, "explanation": "「土を埋める」は土を埋める対象にする形になり、材料の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「土へ埋める」は方向を示し、材料の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「土から埋める」は起点を示し、材料の意味にならない。"}], "correct_answer": "で", "explanations": {"で": "「土で埋める」の「で」は、埋めるための材料を示す。", "を": "「土を埋める」は土を埋める対象にする形になり、材料の意味にならない。", "へ": "「土へ埋める」は方向を示し、材料の意味にならない。", "から": "「土から埋める」は起点を示し、材料の意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "土や砂の中に物を入れて、表面を土などでおおうこと。また、穴などに物を入れて、中に満たすこと。", "primary_collocate": null, "pronunciation": "うめる", "ipa": "ɯmeɾɯ", "syllable_count": 3, "sentences": [{"text": "工事の人が、道路にできた穴を土で埋めた。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、道路[どうろ]にできた穴[あな]を土[つち]で埋[う]めた。", "sentence_source": "generated"}, {"text": "古い池を埋めて、その上に駐車場を作る。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "古[ふる]い池[いけ]を埋[う]めて、その上[うえ]に駐車場[ちゅうしゃじょう]を作[つく]る。", "sentence_source": "generated"}, {"text": "父は庭に穴を掘り、枯れ葉を入れて土で埋めた。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "父[ちち]は庭[にわ]に穴[あな]を掘[ほ]り、枯[か]れ葉[は]を入[い]れて土[つち]で埋[う]めた。", "sentence_source": "generated"}, {"text": "地震でできた溝を、砂利で埋める作業が続いている。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "地震[じしん]でできた溝[みぞ]を、砂利[じゃり]で埋[う]める作業[さぎょう]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "犬が掘った穴を、私はスコップで埋めた。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "犬[いぬ]が掘[ほ]った穴[あな]を、私[わたし]はスコップで埋[う]めた。", "sentence_source": "generated"}, {"text": "昔の人は、使わなくなった井戸を石と土で埋めた。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、使[つか]わなくなった井戸[いど]を石[いし]と土[つち]で埋[う]めた。", "sentence_source": "generated"}, {"text": "海を埋めて作った土地に、新しい工場が建った。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "海[うみ]を埋[う]めて作[つく]った土地[とち]に、新[あたら]しい工場[こうじょう]が建[た]った。", "sentence_source": "generated"}, {"text": "じゃがいもを植えるときは、穴に種芋を入れて土で埋める。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "じゃがいもを植[う]えるときは、穴[あな]に種芋[たねいも]を入[い]れて土[つち]で埋[う]める。", "sentence_source": "generated"}, {"text": "波が運んだ砂が、港の入り口を埋めてしまった。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "波[なみ]が運[はこ]んだ砂[すな]が、港[みなと]の入[い]り口[ぐち]を埋[う]めてしまった。", "sentence_source": "generated"}, {"text": "木を植えたあと、根のまわりの穴を土で埋めて、水をやった。", "target_word": "埋め", "complexity_tier": "T3", "furigana": "木[き]を植[う]えたあと、根[ね]のまわりの穴[あな]を土[つち]で埋[う]めて、水[みず]をやった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "埋めます", "label": "丁寧形"}, {"form": "埋めた", "label": "た形"}, {"form": "埋めて", "label": "て形"}, {"form": "埋めない", "label": "ない形"}, {"form": "埋めれば", "label": "ば形"}, {"form": "埋めよう", "label": "意向形"}], "register": "標準（常体）", "sense_fingerprint": "土や砂で覆い隠す、また穴やくぼみを物で満たしてふさぐ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 種芋 (Zipf 1.92)']::text[], '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めた」で、穴を土でふさぐ意味になる。"}, {"text": "焼い", "is_correct": false, "explanation": "「穴を土で焼いた」は不自然で、ふさぐ行為にならない。"}, {"text": "数え", "is_correct": false, "explanation": "「穴を土で数えた」は意味が通らず、ふさぐ動作にならない。"}, {"text": "眺め", "is_correct": false, "explanation": "「穴を土で眺めた」は意味が通らず、ふさぐ動作にならない。"}], "explanations": {"埋め": "「埋めた」で、穴を土でふさぐ意味になる。", "焼い": "「穴を土で焼いた」は不自然で、ふさぐ行為にならない。", "数え": "「穴を土で数えた」は意味が通らず、ふさぐ動作にならない。", "眺め": "「穴を土で眺めた」は意味が通らず、ふさぐ動作にならない。"}, "sentence_index": 0, "correct_answer": "埋め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末の予定を仕事で沈めてしまい、休む時間がなかった。", "explanation": "ここは〈沈める〉の意味。水などの底へ物を落とす動作で、予定を満たす〈埋める〉とは違う。"}, {"text": "地震でできた溝を、砂利で敷く作業が続いている。", "explanation": "ここは〈敷く〉の意味。平らに広げて下に置く動作で、溝をふさぐ〈埋める〉とは違う。"}, {"text": "地震でできた溝を、砂利で焼く作業が続いている。", "explanation": "ここは〈焼く〉の意味。熱を加えて変える動作で、溝を物で満たす〈埋める〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「海を埋めて」で、海に土を入れて陸地にする意味になる。"}, {"text": "運ん", "is_correct": false, "explanation": "「海を運んで」は意味が通らず、埋め立ての意味にならない。"}, {"text": "食べ", "is_correct": false, "explanation": "「海を食べて作った土地」は意味が通らず、埋め立ての意味にならない。"}, {"text": "織っ", "is_correct": false, "explanation": "「海を織って」は意味が通らず、埋め立ての意味にならない。"}], "explanations": {"埋め": "「海を埋めて」で、海に土を入れて陸地にする意味になる。", "運ん": "「海を運んで」は意味が通らず、埋め立ての意味にならない。", "食べ": "「海を食べて作った土地」は意味が通らず、埋め立ての意味にならない。", "織っ": "「海を織って」は意味が通らず、埋め立ての意味にならない。"}, "sentence_index": 6, "correct_answer": "埋め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木を植えたあと、根のまわりの穴を土で植えて、水をやった。", "explanation": "ここは〈植える〉の意味。草木を地面に据える動作で、穴を土でふさぐ意味ではない。"}, {"text": "木を植えたあと、根のまわりの穴を土で盛って、水をやった。", "explanation": "ここは〈盛る〉の意味。土を高く積む動作で、穴をふさぐ意味にはならない。"}, {"text": "木を植えたあと、根のまわりの穴を土で洗って、水をやった。", "explanation": "ここは〈洗う〉の意味。汚れを落とす動作で、穴を土でふさぐ意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い井戸を、石と土で埋まることにした。", "corrected_sentence": "古い井戸を、石と土で埋めることにした。", "error_description": "「埋める」は他動詞で目的語「井戸を」をとる。「埋まる」は自動詞なので、「井戸を埋まる」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋めて」の連用形で、後ろに「て」が続く形として正しい。"}, {"text": "埋めた", "is_correct": false, "explanation": "過去形なので、「て」で続けて動作を並べる文の形に合わない。"}, {"text": "埋めない", "is_correct": false, "explanation": "否定形なので、実際に行う肯定の動作の文に合わない。"}, {"text": "埋めよう", "is_correct": false, "explanation": "意向形なので、決まった動作の順序を述べる文に合わない。"}], "correct_form": "埋め", "base_form": "埋める", "form_label": "連用形", "sentence_index": 1, "explanations": {"埋め": "「埋めて」の連用形で、後ろに「て」が続く形として正しい。", "埋めた": "過去形なので、「て」で続けて動作を並べる文の形に合わない。", "埋めない": "否定形なので、実際に行う肯定の動作の文に合わない。", "埋めよう": "意向形なので、決まった動作の順序を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36793, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、古い水路を砂利で埋めました。", "corrected_sentence": "来週、古い水路を砂利で埋めます。", "error_description": "「来週」は未来を示すので、非過去の「埋めます」が正しい。「埋めました」は過去形で、未来の予定と矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "埋め", "is_correct": true, "explanation": "「埋める」の語幹に当たる連用形で、土で覆う動作を表す形として正しい。"}, {"text": "埋めます", "is_correct": false, "explanation": "丁寧形なので、「る」で終わる辞書形の位置に入らない。"}, {"text": "埋めて", "is_correct": false, "explanation": "「て」形なので、「る」で終わる文の形に合わない。"}, {"text": "埋めれば", "is_correct": false, "explanation": "仮定形なので、「る」で終わる文の形に続かない。"}], "correct_form": "埋め", "base_form": "埋める", "form_label": "連用形", "sentence_index": 7, "explanations": {"埋め": "「埋める」の語幹に当たる連用形で、土で覆う動作を表す形として正しい。", "埋めます": "丁寧形なので、「る」で終わる辞書形の位置に入らない。", "埋めて": "「て」形なので、「る」で終わる文の形に合わない。", "埋めれば": "仮定形なので、「る」で終わる文の形に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
