INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36794, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "しばらくは、ちょっとの時間がたつことです。", "primary_collocate": null, "pronunciation": "しばらく", "ipa": "ɕibaɾakɯ", "syllable_count": 4, "sentences": [{"text": "暫く待ってください。すぐに先生が来ます。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く待[ま]ってください。すぐに先生[せんせい]が来[き]ます。", "sentence_source": "generated"}, {"text": "疲れたので、暫く休みました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "疲[つか]れたので、暫[しばら]く休[やす]みました。", "sentence_source": "generated"}, {"text": "雨がひどいので、暫く外に出ないでください。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "雨[あめ]がひどいので、暫[しばら]く外[そと]に出[で]ないでください。", "sentence_source": "generated"}, {"text": "暫く考えてから、私は「はい」と答えました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く考[かんが]えてから、私[わたし]は「はい」と答[こた]えました。", "sentence_source": "generated"}, {"text": "電車が止まったので、駅で暫く待ちました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったので、駅[えき]で暫[しばら]く待[ま]ちました。", "sentence_source": "generated"}, {"text": "暫くすると、雨はやんで空が明るくなりました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]くすると、雨[あめ]はやんで空[そら]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "母は暫く黙っていましたが、やがて笑い出しました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "母[はは]は暫[しばら]く黙[だま]っていましたが、やがて笑[わら]い出[だ]しました。", "sentence_source": "generated"}, {"text": "暫く歩くと、小さな店が見えてきました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く歩[ある]くと、小[ちい]さな店[みせ]が見[み]えてきました。", "sentence_source": "generated"}, {"text": "熱いお茶なので、暫く置いてから飲みます。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]なので、暫[しばら]く置[お]いてから飲[の]みます。", "sentence_source": "generated"}, {"text": "暫くして、友だちから返事が来ました。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]くして、友[とも]だちから返事[へんじ]が来[き]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暫く", "label": "基本形"}], "register": "標準（丁寧）", "sense_fingerprint": "少しの間、ちょっとの時間（やさしい説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36794, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暫く", "is_correct": true, "explanation": "「少しの間」を表し、「待ってください」の前に入って、少し待つよう指示する文として自然に成り立つ。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は後ろに否定の表現を伴う副詞なので、肯定の「待ってください」とは続かない。"}, {"text": "たびたび", "is_correct": false, "explanation": "何度も繰り返す意味で、一度待つよう指示する文には合わない。"}, {"text": "とても", "is_correct": false, "explanation": "程度を強める副詞で、「待つ」という動作を修飾しないため文が成り立たない。"}], "explanations": {"暫く": "「少しの間」を表し、「待ってください」の前に入って、少し待つよう指示する文として自然に成り立つ。", "決して": "「決して」は後ろに否定の表現を伴う副詞なので、肯定の「待ってください」とは続かない。", "たびたび": "何度も繰り返す意味で、一度待つよう指示する文には合わない。", "とても": "程度を強める副詞で、「待つ」という動作を修飾しないため文が成り立たない。"}, "sentence_index": 0, "correct_answer": "暫く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い交渉の末、暫く合意が成立した。", "explanation": "〈暫く〉は少しの時間を表すので、長い交渉の末に一度だけ成立する結果には合わない。"}, {"text": "祖父は暫く、三十年この店を守ってきた。", "explanation": "〈暫く〉は短い時間を表すので、三十年という長い期間の話には合わない。"}, {"text": "彼は暫く、一生この町で暮らした。", "explanation": "〈暫く〉は短い時間を表すので、一生という長い期間の話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36794, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暫く", "is_correct": true, "explanation": "「しばらく黙っていた」で、やがて笑い出すまでの時間を表し、文の流れに合う。"}, {"text": "滅多に", "is_correct": false, "explanation": "「滅多に」は否定の文で使う副詞で、肯定の「黙っていました」には合わない。"}, {"text": "大いに", "is_correct": false, "explanation": "程度の大きさを表すが、「黙る」という状態を修飾しないので文が成り立たない。"}, {"text": "もうすぐ", "is_correct": false, "explanation": "時の近さを表すので、黙っていた期間を示す文には合わない。"}], "explanations": {"暫く": "「しばらく黙っていた」で、やがて笑い出すまでの時間を表し、文の流れに合う。", "滅多に": "「滅多に」は否定の文で使う副詞で、肯定の「黙っていました」には合わない。", "大いに": "程度の大きさを表すが、「黙る」という状態を修飾しないので文が成り立たない。", "もうすぐ": "時の近さを表すので、黙っていた期間を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "暫く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い試合の末、暫く勝負が決まった。", "explanation": "〈暫く〉は少しの時間を表すので、長い試合の末に決まった勝負の結末には合わない。"}, {"text": "この歌は暫く、千年にわたって歌い継がれてきた。", "explanation": "〈暫く〉は短い時間を表すので、千年という長い期間には使わない。"}, {"text": "祖母は暫く、六十年も同じ家に住んでいた。", "explanation": "〈暫く〉は短い時間を表すので、六十年という長い期間の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36794, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が止むまで、暫くに外で待ちましょう。", "corrected_sentence": "雨が止むまで、暫く外で待ちましょう。", "error_description": "「暫く」は副詞なので、後ろに「に」を付けない。「暫く外で待つ」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36794, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物は暫くすれ、届きます。", "corrected_sentence": "荷物は暫くしてから届きます。", "error_description": "「する」の連用形は「し」で、「すれ」は仮定形なので文が成り立たない。「暫くしてから」が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
