INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36795, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ある程度の時間が経過すること。行動や出来事の間に少し間があることを表す副詞。", "primary_collocate": null, "pronunciation": "しばらく", "ipa": "ɕibaɾakɯ", "syllable_count": 4, "sentences": [{"text": "彼とは暫く会っていないので、元気か心配だ。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "彼[かれ]とは暫[しばら]く会[あ]っていないので、元気[げんき]か心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "暫く連絡がなかったが、昨日ようやく手紙が届いた。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く連絡[れんらく]がなかったが、昨日[きのう]ようやく手紙[てがみ]が届[とど]いた。", "sentence_source": "generated"}, {"text": "仕事が忙しくて、暫く旅行には行けそうにない。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "仕事[しごと]が忙[いそが]しくて、暫[しばら]く旅行[りょこう]には行[い]けそうにない。", "sentence_source": "generated"}, {"text": "暫く見ないうちに、子どもは背が高くなった。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く見[み]ないうちに、子[こ]どもは背[せ]が高[たか]くなった。", "sentence_source": "generated"}, {"text": "風邪が治るまで、暫く運動を控えるつもりだ。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "風邪[かぜ]が治[なお]るまで、暫[しばら]く運動[うんどう]を控[ひか]えるつもりだ。", "sentence_source": "generated"}, {"text": "彼女は暫く何も言わず、窓の外を見ていた。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は暫[しばら]く何[なに]も言[い]わず、窓[まど]の外[そと]を見[み]ていた。", "sentence_source": "generated"}, {"text": "その店は改装のため、暫く閉まっている。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "その店[みせ]は改装[かいそう]のため、暫[しばら]く閉[し]まっている。", "sentence_source": "generated"}, {"text": "暫く外国で暮らしていたので、日本語を話す機会が少なかった。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]く外国[がいこく]で暮[く]らしていたので、日本語[にほんご]を話[はな]す機会[きかい]が少[すく]なかった。", "sentence_source": "generated"}, {"text": "弟は暫く悩んだあとで、留学することに決めた。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "弟[おとうと]は暫[しばら]く悩[なや]んだあとで、留学[りゅうがく]することに決[き]めた。", "sentence_source": "generated"}, {"text": "暫くは雨が続くと、天気予報で言っていた。", "target_word": "暫く", "complexity_tier": "T3", "furigana": "暫[しばら]くは雨[あめ]が続[つづ]くと、天気予報[てんきよほう]で言[い]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暫く", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "ある程度の期間が経つこと、出来事の間にあく間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d85d1c-c14e-4c8c-9d04-c6b8fb52030b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36795, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暫く", "is_correct": true, "explanation": "「しばらく会っていない」で、ある程度の期間会っていないことを表し、文の意味に合う。"}, {"text": "大いに", "is_correct": false, "explanation": "程度の大きさを表すが、「会っていない」期間を示すには合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "不意に起こる様子を表すので、継続している「会っていない」状態とは合わない。"}, {"text": "逆に", "is_correct": false, "explanation": "対照を表すので、「会っていない」ことを述べる文の中では意味が通らない。"}], "explanations": {"暫く": "「しばらく会っていない」で、ある程度の期間会っていないことを表し、文の意味に合う。", "大いに": "程度の大きさを表すが、「会っていない」期間を示すには合わない。", "ふと": "不意に起こる様子を表すので、継続している「会っていない」状態とは合わない。", "逆に": "対照を表すので、「会っていない」ことを述べる文の中では意味が通らない。"}, "sentence_index": 0, "correct_answer": "暫く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い工事の末、新しい橋が暫く完成した。", "explanation": "〈暫く〉は時間が少し経つことを表すので、長い工事の末に一度だけ完成するという結果には合わない。"}, {"text": "彼は暫く、三十年この会社で働いてきた。", "explanation": "〈暫く〉は短い期間を表すので、三十年という長い期間の話には合わない。"}, {"text": "この約束は暫く、永遠に守られるだろう。", "explanation": "〈暫く〉は期間が限られるので、期限なく続く約束とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36795, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暫く", "is_correct": true, "explanation": "改装中の期間を表し、「閉まっている」状態の長さに合う。"}, {"text": "滅多に", "is_correct": false, "explanation": "「滅多に」は否定の文で使う副詞で、「閉まっている」という状態には合わない。"}, {"text": "もうすぐ", "is_correct": false, "explanation": "近い未来を表すので、現在の状態「閉まっている」とは合わない。"}, {"text": "大幅に", "is_correct": false, "explanation": "程度を表すので、閉まっている期間を示す文には合わない。"}], "explanations": {"暫く": "改装中の期間を表し、「閉まっている」状態の長さに合う。", "滅多に": "「滅多に」は否定の文で使う副詞で、「閉まっている」という状態には合わない。", "もうすぐ": "近い未来を表すので、現在の状態「閉まっている」とは合わない。", "大幅に": "程度を表すので、閉まっている期間を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "暫く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い話し合いの末、暫く結論が出た。", "explanation": "〈暫く〉は少しの時間を表すので、長い話し合いの末に出る結論とは合わない。"}, {"text": "その家は暫く、代々この土地に暮らしてきた。", "explanation": "〈暫く〉は短い期間を表すので、何代にもわたる話には合わない。"}, {"text": "彼は暫く、七十年間同じ会社に勤めた。", "explanation": "〈暫く〉は短い期間を表すので、七十年という長さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36795, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女とは暫くに会っていないので、少し寂しい。", "corrected_sentence": "彼女とは暫く会っていないので、少し寂しい。", "error_description": "副詞の「暫く」には格助詞「に」を付けない。「暫く会っていない」と続けるのが正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36795, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事のため、暫くを休業します。", "corrected_sentence": "工事のため、暫く休業します。", "error_description": "副詞の「暫く」には格助詞「を」を付けない。「暫く休業する」と続けるのが正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0495e537-9402-4512-bea3-f80ad49c827a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪い", "is_correct": true, "explanation": "〈良い〉の対義語。天気が望ましくない状態を表す。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す語で、〈良い〉の対義関係にはない。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの反対を表す語で、天気の良し悪しの対義語ではない。"}, {"text": "速い", "is_correct": false, "explanation": "速さを表す語で、〈良い〉の対義語ではない。"}], "correct_answer": "悪い", "explanations": {"悪い": "〈良い〉の対義語。天気が望ましくない状態を表す。", "固い": "硬さを表す語で、〈良い〉の対義関係にはない。", "暗い": "明るさの反対を表す語で、天気の良し悪しの対義語ではない。", "速い": "速さを表す語で、〈良い〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪い", "is_correct": true, "explanation": "〈良い〉の対義語。望ましくない性質を表し、本を読んだ効果の評価に対応する。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度や態度を表す語で、〈良い〉の対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す語で、性質の評価の対義にはならない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す語で、〈良い〉の対義関係にはない。"}], "correct_answer": "悪い", "explanations": {"悪い": "〈良い〉の対義語。望ましくない性質を表し、本を読んだ効果の評価に対応する。", "冷たい": "温度や態度を表す語で、〈良い〉の対義語ではない。", "軽い": "重さを表す語で、性質の評価の対義にはならない。", "太い": "太さを表す語で、〈良い〉の対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "いいこと、すてきなことであることを表す。", "primary_collocate": null, "pronunciation": "よい", "ipa": "joi", "syllable_count": 2, "sentences": [{"text": "このケーキは味が良いので、すぐに売り切れた。", "target_word": "良い", "complexity_tier": "T3", "furigana": "このケーキは味(あじ)が良(よ)いので、すぐに売(う)り切(き)れた。", "sentence_source": "generated"}, {"text": "弟は頭が良く、難しい問題もすぐに解く。", "target_word": "良く", "complexity_tier": "T3", "furigana": "弟(おとうと)は頭(あたま)が良(よ)く、難(むずか)しい問題(もんだい)もすぐに解(と)く。", "sentence_source": "generated"}, {"text": "今日は気分が良いから、歌を歌いながら歩く。", "target_word": "良い", "complexity_tier": "T3", "furigana": "今日(きょう)は気分(きぶん)が良(よ)いから、歌(うた)を歌(うた)いながら歩(ある)く。", "sentence_source": "generated"}, {"text": "良い天気になったので、みんなで海へ行った。", "target_word": "良い", "complexity_tier": "T3", "furigana": "良(よ)い天気(てんき)になったので、みんなで海(うみ)へ行(い)った。", "sentence_source": "generated"}, {"text": "先生に褒められて、とても良い一日になった。", "target_word": "良い", "complexity_tier": "T3", "furigana": "先生(せんせい)に褒(ほ)められて、とても良(よ)い一日(いちにち)になった。", "sentence_source": "generated"}, {"text": "この辺りは空気が良くて、散歩が気持ちいい。", "target_word": "良くて", "complexity_tier": "T3", "furigana": "この辺(あた)りは空気(くうき)が良(よ)くて、散歩(さんぽ)が気持(きも)ちいい。", "sentence_source": "generated"}, {"text": "昨日の試合は結果が良くなかったので、悔しかった。", "target_word": "良くなかった", "complexity_tier": "T3", "furigana": "昨日(きのう)の試合(しあい)は結果(けっか)が良(よ)くなかったので、悔(くや)しかった。", "sentence_source": "generated"}, {"text": "母が作ってくれた服は、色も形も良い。", "target_word": "良い", "complexity_tier": "T3", "furigana": "母(はは)が作(つく)ってくれた服(ふく)は、色(いろ)も形(かたち)も良(よ)い。", "sentence_source": "generated"}, {"text": "仲が良い二人は、毎日いっしょに帰る。", "target_word": "良い", "complexity_tier": "T3", "furigana": "仲(なか)が良(よ)い二人(ふたり)は、毎日(まいにち)いっしょに帰(かえ)る。", "sentence_source": "generated"}, {"text": "良い本を読むと、心が豊かになる。", "target_word": "良い", "complexity_tier": "T3", "furigana": "良(よ)い本(ほん)を読(よ)むと、心(こころ)が豊(ゆた)かになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "良い", "label": "辞書形"}, {"form": "良く", "label": "連用形"}, {"form": "良くない", "label": "否定形"}, {"form": "良かった", "label": "過去形"}, {"form": "良くて", "label": "て形"}, {"form": "良ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "いいこと、すてきなことを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良い", "is_correct": true, "explanation": "終止形。味の良さを表し、「ので」で理由を続ける文に合う。"}, {"text": "悪い", "is_correct": false, "explanation": "味が悪いと売り切れる理由にならず、意味が合わない。"}, {"text": "高い", "is_correct": false, "explanation": "値段を表す語で、味の評価には合わない。"}, {"text": "早い", "is_correct": false, "explanation": "速さを表す語で、味の評価としては成り立たない。"}], "explanations": {"良い": "終止形。味の良さを表し、「ので」で理由を続ける文に合う。", "悪い": "味が悪いと売り切れる理由にならず、意味が合わない。", "高い": "値段を表す語で、味の評価には合わない。", "早い": "速さを表す語で、味の評価としては成り立たない。"}, "sentence_index": 0, "correct_answer": "良い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は身長が良くて、モデルの仕事を始めた。", "explanation": "ここは〈高い〉の意味。身長の高さは〈高い〉で言い、〈良い〉では背の高さを表せない。"}, {"text": "彼は足が良くて、短距離走では誰にも負けない。", "explanation": "ここは〈速い〉の意味。走る速さは〈速い〉で言い、〈良い〉では足の速さを表せない。"}, {"text": "彼は力が良くて、重い荷物も一人で運べる。", "explanation": "ここは〈強い〉の意味。力の強さは〈強い〉で表す。〈良い〉では力の強さを言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良くなかった", "is_correct": true, "explanation": "〈良い〉の否定過去。結果が望ましくなかったことを表し、「ので悔しかった」と続く。"}, {"text": "長かった", "is_correct": false, "explanation": "長さを表す語で、試合の結果の評価には合わない。"}, {"text": "遅かった", "is_correct": false, "explanation": "速さを表す語で、結果の評価としては不自然。"}, {"text": "高かった", "is_correct": false, "explanation": "高さや値段を表す語で、結果の評価には合わない。"}], "explanations": {"良くなかった": "〈良い〉の否定過去。結果が望ましくなかったことを表し、「ので悔しかった」と続く。", "長かった": "長さを表す語で、試合の結果の評価には合わない。", "遅かった": "速さを表す語で、結果の評価としては不自然。", "高かった": "高さや値段を表す語で、結果の評価には合わない。"}, "sentence_index": 6, "correct_answer": "良くなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は時間が良く、一度も遅れたことがない。", "explanation": "ここは〈正確〉の意味。時計の時刻の正しさは〈正確〉で言う。〈良い〉は性質の評価で、時刻の正確さは表せない。"}, {"text": "彼は手先が良く、細かい細工もきれいに仕上げる。", "explanation": "ここは〈器用〉の意味。手先の巧みさは〈器用〉で言う。〈良い〉では細工の技術を表せない。"}, {"text": "この包丁は刃先が良く、野菜を一瞬で切れる。", "explanation": "ここは〈鋭い〉の意味。刃の鋭さは〈鋭い〉で言い、〈良い〉では切れ味を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このケーキは味が良いく、すぐに売り切れた。", "corrected_sentence": "このケーキは味が良くて、すぐに売り切れた。", "error_description": "〈良い〉の連用形は「良く」、て形は「良くて」。「良いく」は活用形が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "良く", "is_correct": true, "explanation": "連用形。「頭が良く、」と続けて中止する形で、文を成す。"}, {"text": "良いく", "is_correct": false, "explanation": "「良いく」は活用しない形で、文として成立しない。"}, {"text": "良いて", "is_correct": false, "explanation": "「良いて」は活用しない形で、文として成立しない。"}, {"text": "良いかった", "is_correct": false, "explanation": "「良いかった」は活用しない形で、文として成立しない。"}], "correct_form": "良く", "base_form": "良い", "form_label": "連用形（中止）", "sentence_index": 1, "explanations": {"良く": "連用形。「頭が良く、」と続けて中止する形で、文を成す。", "良いく": "「良いく」は活用しない形で、文として成立しない。", "良いて": "「良いて」は活用しない形で、文として成立しない。", "良いかった": "「良いかった」は活用しない形で、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36796, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女とは仲が良いを、毎日いっしょに帰る。", "corrected_sentence": "彼女とは仲が良いので、毎日いっしょに帰る。", "error_description": "「良い」の後に「を」は続かない。理由を表す「ので」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "良い", "is_correct": true, "explanation": "終止形。文末で服の性質を評価する形で、文の意味に合う。"}, {"text": "良いだ", "is_correct": false, "explanation": "「良いだ」は標準的な活用形ではなく、文末でも成立しない。"}, {"text": "良くて", "is_correct": false, "explanation": "て形。文末に置くと文が途切れ、言い切れない。"}, {"text": "良く", "is_correct": false, "explanation": "連用形。文末で言い切れず、文が成り立たない。"}], "correct_form": "良い", "base_form": "良い", "form_label": "終止形（文末）", "sentence_index": 7, "explanations": {"良い": "終止形。文末で服の性質を評価する形で、文の意味に合う。", "良いだ": "「良いだ」は標準的な活用形ではなく、文末でも成立しない。", "良くて": "て形。文末に置くと文が途切れ、言い切れない。", "良く": "連用形。文末で言い切れず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪い", "is_correct": true, "explanation": "〈良い〉の対義語。望ましくない状態や性質を表す。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、望ましさの評価の対義にはならない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、〈良い〉の対義関係にはない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す語で、〈良い〉の対義語ではない。"}], "correct_answer": "悪い", "explanations": {"悪い": "〈良い〉の対義語。望ましくない状態や性質を表す。", "大きい": "大きさを表す語で、望ましさの評価の対義にはならない。", "重い": "重さを表す語で、〈良い〉の対義関係にはない。", "遅い": "速さを表す語で、〈良い〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪い", "is_correct": true, "explanation": "〈良い〉の対義語。望ましくない性質を表し、発音の評価に対応する。"}, {"text": "近い", "is_correct": false, "explanation": "距離を表す語で、〈良い〉の対義語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す語で、性質の評価の対義にはならない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す語で、〈良い〉の対義関係にはない。"}], "correct_answer": "悪い", "explanations": {"悪い": "〈良い〉の対義語。望ましくない性質を表し、発音の評価に対応する。", "近い": "距離を表す語で、〈良い〉の対義語ではない。", "深い": "深さを表す語で、性質の評価の対義にはならない。", "硬い": "硬さを表す語で、〈良い〉の対義関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "状態や性質が望ましいこと。肯定的に評価できること。", "primary_collocate": null, "pronunciation": "よい", "ipa": "joi", "syllable_count": 2, "sentences": [{"text": "この部屋は日当たりが良く、冬でも暖かい。", "target_word": "良く", "complexity_tier": "T3", "furigana": "この部屋(へや)は日当(ひあ)たりが良(よ)く、冬(ふゆ)でも暖(あたた)かい。", "sentence_source": "generated"}, {"text": "今日は天気が良い。", "target_word": "良い", "complexity_tier": "T3", "furigana": "今日(きょう)は天気(てんき)が良(よ)い。", "sentence_source": "generated"}, {"text": "この店の料理は味が良く、いつも客でいっぱいだ。", "target_word": "良く", "complexity_tier": "T3", "furigana": "この店(みせ)の料理(りょうり)は味(あじ)が良(よ)く、いつも客(きゃく)でいっぱいだ。", "sentence_source": "generated"}, {"text": "姉は成績が良いだけでなく、性格も明るい。", "target_word": "良い", "complexity_tier": "T3", "furigana": "姉(あね)は成績(せいせき)が良(よ)いだけでなく、性格(せいかく)も明(あか)るい。", "sentence_source": "generated"}, {"text": "昨日よりも体調が良くなったので、会社に行った。", "target_word": "良く", "complexity_tier": "T3", "furigana": "昨日(きのう)よりも体調(たいちょう)が良(よ)くなったので、会社(かいしゃ)に行(い)った。", "sentence_source": "generated"}, {"text": "良い友達に恵まれたおかげで、留学生活は楽しかった。", "target_word": "良い", "complexity_tier": "T3", "furigana": "良(よ)い友達(ともだち)に恵(めぐ)まれたおかげで、留学生活(りゅうがくせいかつ)は楽(たの)しかった。", "sentence_source": "generated"}, {"text": "試験の結果が良かったので、母はとても喜んだ。", "target_word": "良かった", "complexity_tier": "T3", "furigana": "試験(しけん)の結果(けっか)が良(よ)かったので、母(はは)はとても喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "この椅子は座り心地が良く、長時間でも疲れない。", "target_word": "良く", "complexity_tier": "T3", "furigana": "この椅子(いす)は座(すわ)り心地(ごこち)が良(よ)く、長時間(ちょうじかん)でも疲(つか)れない。", "sentence_source": "generated"}, {"text": "天気が良ければ、明日は山に登るつもりだ。", "target_word": "良ければ", "complexity_tier": "T3", "furigana": "天気(てんき)が良(よ)ければ、明日(あした)は山(やま)に登(のぼ)るつもりだ。", "sentence_source": "generated"}, {"text": "彼の発音は、日本人と同じくらい良い。", "target_word": "良い", "complexity_tier": "T3", "furigana": "彼(かれ)の発音(はつおん)は、日本人(にほんじん)と同(おな)じくらい良(よ)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "良い", "label": "辞書形"}, {"form": "良く", "label": "連用形"}, {"form": "良くない", "label": "否定形"}, {"form": "良かった", "label": "過去形"}, {"form": "良くて", "label": "て形"}, {"form": "良ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "状態や性質が望ましく、肯定的に評価できる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "良く", "is_correct": true, "explanation": "「日当たりが良く」の連用形で、「暖かい」と続けて部屋の状態を表す。"}, {"text": "早く", "is_correct": false, "explanation": "「日当たりが早く」は意味が通らない。"}, {"text": "重く", "is_correct": false, "explanation": "「日当たりが重く」は意味が通らない。"}, {"text": "遠く", "is_correct": false, "explanation": "「日当たりが遠く」は意味が通らない。"}], "explanations": {"良く": "「日当たりが良く」の連用形で、「暖かい」と続けて部屋の状態を表す。", "早く": "「日当たりが早く」は意味が通らない。", "重く": "「日当たりが重く」は意味が通らない。", "遠く": "「日当たりが遠く」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "良く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は身長が良くて、バスケットボール部でも活躍している。", "explanation": "ここは〈高い〉（背が高い）の意味。身長の高さは〈高い〉で言い、〈良い〉では背の高さを表せない。"}, {"text": "彼は足が良くて、短距離走では誰にも負けない。", "explanation": "ここは〈速い〉の意味。走る速さは〈速い〉で言い、〈良い〉では足の速さを表せない。"}, {"text": "彼は腕力が良いので、重い荷物も一人で運べる。", "explanation": "ここは〈強い〉の意味。力の強さは〈強い〉で表す。〈良い〉は望ましい性質の評価で、腕力の強さを指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "良かった", "is_correct": true, "explanation": "過去形。試験の結果が望ましかったことを表し、「ので」の前に合う。"}, {"text": "悪かった", "is_correct": false, "explanation": "対義の過去形。結果が悪ければ母が喜ぶ文脈になり、文が成り立たない。"}, {"text": "多かった", "is_correct": false, "explanation": "数量を表す語で、試験の結果の評価には合わない。"}, {"text": "難しかった", "is_correct": false, "explanation": "難易度を表す語で、結果の評価としては不自然。"}], "explanations": {"良かった": "過去形。試験の結果が望ましかったことを表し、「ので」の前に合う。", "悪かった": "対義の過去形。結果が悪ければ母が喜ぶ文脈になり、文が成り立たない。", "多かった": "数量を表す語で、試験の結果の評価には合わない。", "難しかった": "難易度を表す語で、結果の評価としては不自然。"}, "sentence_index": 6, "correct_answer": "良かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は時間が良いので、一度も遅れたことがない。", "explanation": "ここは〈正確〉の意味。時計の精度は〈正確〉で言う。〈良い〉は性質の評価で、正確さを表せない。"}, {"text": "彼は手先が良く、細かい細工もきれいに仕上げる。", "explanation": "ここは〈器用〉の意味。手先の巧みさは〈器用〉で言う。〈良い〉では細工の技術を表せない。"}, {"text": "このナイフは刃先が良く、野菜を一瞬で切れる。", "explanation": "ここは〈鋭い〉の意味。刃の鋭さは〈鋭い〉で言い、〈良い〉では切れ味を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の海は天気が良いで、人がたくさん集まった。", "corrected_sentence": "夏の海は天気が良くて、人がたくさん集まった。", "error_description": "正しい形は連用形・て形の「良くて」。「良いで」は〈良い〉の活用形が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "良い", "is_correct": true, "explanation": "終止形。文末で言い切る形で、文の意味に合う。"}, {"text": "良く", "is_correct": false, "explanation": "連用形。文末で言い切れず、文が成り立たない。"}, {"text": "良くて", "is_correct": false, "explanation": "て形。文末に置くと文が途切れ、言い切れない。"}, {"text": "良ければ", "is_correct": false, "explanation": "仮定形。文末では条件の文が途切れ、文が成り立たない。"}], "correct_form": "良い", "base_form": "良い", "form_label": "終止形（文末）", "sentence_index": 1, "explanations": {"良い": "終止形。文末で言い切る形で、文の意味に合う。", "良く": "連用形。文末で言い切れず、文が成り立たない。", "良くて": "て形。文末に置くと文が途切れ、言い切れない。", "良ければ": "仮定形。文末では条件の文が途切れ、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36797, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日の空は天気が良いを、洗濯物がよく乾く。", "corrected_sentence": "今日の空は天気が良いので、洗濯物がよく乾く。", "error_description": "「良い」の後に「を」は続かない。理由を表す「ので」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "良く", "is_correct": true, "explanation": "連用形。「座り心地が良く、」と続けて中止する形で、文を成す。"}, {"text": "良いく", "is_correct": false, "explanation": "「良いく」は活用しない形で、文として成立しない。"}, {"text": "良いて", "is_correct": false, "explanation": "「良いて」は活用しない形で、文として成立しない。"}, {"text": "良いかった", "is_correct": false, "explanation": "「良いかった」は活用しない形で、文として成立しない。"}], "correct_form": "良く", "base_form": "良い", "form_label": "連用形（中止）", "sentence_index": 7, "explanations": {"良く": "連用形。「座り心地が良く、」と続けて中止する形で、文を成す。", "良いく": "「良いく」は活用しない形で、文として成立しない。", "良いて": "「良いて」は活用しない形で、文として成立しない。", "良いかった": "「良いかった」は活用しない形で、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『畑に出て』の『に』。出かける先・行き先を表す。"}, {"text": "が", "is_correct": false, "explanation": "『畑が出て』では畑が主語になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『畑で出て』は『出る』が場所の『で』を取らないため不自然。"}, {"text": "の", "is_correct": false, "explanation": "『畑の出て』では畑が名詞修飾になり、続く動詞と結びつかず不自然。"}], "correct_answer": "に", "explanations": {"に": "『畑に出て』の『に』。出かける先・行き先を表す。", "が": "『畑が出て』では畑が主語になり、文が成り立たない。", "で": "『畑で出て』は『出る』が場所の『で』を取らないため不自然。", "の": "『畑の出て』では畑が名詞修飾になり、続く動詞と結びつかず不自然。"}, "error_tags": {"が": "subject_marker", "で": "action_location", "の": "modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『畑の草』の『の』。畑に生えている草を表す修飾の助詞。"}, {"text": "が", "is_correct": false, "explanation": "『畑が草を抜く』では畑が動作主になり、意味が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『畑を草を抜く』は目的語が二つ並び、不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "『畑と草を抜く』は同伴や並列の意味になり、畑の草を抜く文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "『畑の草』の『の』。畑に生えている草を表す修飾の助詞。", "が": "『畑が草を抜く』では畑が動作主になり、意味が成り立たない。", "を": "『畑を草を抜く』は目的語が二つ並び、不自然になる。", "と": "『畑と草を抜く』は同伴や並列の意味になり、畑の草を抜く文脈に合わない。"}, "error_tags": {"が": "subject_marker", "を": "object_marker", "と": "companion_or_and"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や花などを育てるために耕した土地。", "primary_collocate": null, "pronunciation": "はたけ", "ipa": "hatake", "syllable_count": 3, "sentences": [{"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "畑", "complexity_tier": "T4", "furigana": "経験[けいけん]豊富[ほうふ]な農家[のうか]は、広大[こうだい]な畑[はたけ]の土壌[どじょう]を丁寧[ていねい]に耕[たがや]し、野菜[やさい]の種[たね]を植[う]える。", "sentence_source": "mined"}, {"text": "祖父は毎朝、畑に出てトマトの世話をしている。", "target_word": "畑", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、畑[はたけ]に出[で]てトマトの世話[せわ]をしている。", "sentence_source": "generated"}, {"text": "雨が続いたので、畑の土がぬかるんで歩きにくい。", "target_word": "畑", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたので、畑[はたけ]の土[つち]がぬかるんで歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "畑でとれたばかりのキュウリは、とても甘くておいしい。", "target_word": "畑", "complexity_tier": "T3", "furigana": "畑[はたけ]でとれたばかりのキュウリは、とても甘[あま]くておいしい。", "sentence_source": "generated"}, {"text": "猿が畑に入って、せっかく育てた野菜を食べてしまった。", "target_word": "畑", "complexity_tier": "T3", "furigana": "猿[さる]が畑[はたけ]に入[はい]って、せっかく育[そだ]てた野菜[やさい]を食[た]べてしまった。", "sentence_source": "generated"}, {"text": "春になると、畑一面に菜の花が咲いて、あたりが黄色く染まる。", "target_word": "畑", "complexity_tier": "T3", "furigana": "春[はる]になると、畑[はたけ]一面[いちめん]に菜[な]の花[はな]が咲[さ]いて、あたりが黄色[きいろ]く染[そ]まる。", "sentence_source": "generated"}, {"text": "母は家の裏の小さな畑で、ネギやナスを作っている。", "target_word": "畑", "complexity_tier": "T3", "furigana": "母[はは]は家[いえ]の裏[うら]の小[ちい]さな畑[はたけ]で、ネギやナスを作[つく]っている。", "sentence_source": "generated"}, {"text": "畑の草を抜いていたら、あっという間に一日が終わった。", "target_word": "畑", "complexity_tier": "T3", "furigana": "畑[はたけ]の草[くさ]を抜[ぬ]いていたら、あっという間[ま]に一日[いちにち]が終[お]わった。", "sentence_source": "generated"}, {"text": "この畑は日当たりがよいので、野菜がよく育つ。", "target_word": "畑", "complexity_tier": "T3", "furigana": "この畑[はたけ]は日当[ひあ]たりがよいので、野菜[やさい]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "冬の間、畑は雪におおわれて、何も植えられない。", "target_word": "畑", "complexity_tier": "T3", "furigana": "冬[ふゆ]の間[あいだ]、畑[はたけ]は雪[ゆき]におおわれて、何[なに]も植[う]えられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "畑", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "cultivated field for growing vegetables or flowers", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "畑", "is_correct": true, "explanation": "野菜を育てるために耕した土地のことで、ここに入る語。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業を行う部屋で、土壌を耕して種を植える場所ではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、土壌を耕す対象にはならないので合わない。"}, {"text": "海", "is_correct": false, "explanation": "海は水域で、耕して野菜の種を植える場所ではないので合わない。"}], "explanations": {"畑": "野菜を育てるために耕した土地のことで、ここに入る語。", "教室": "教室は授業を行う部屋で、土壌を耕して種を植える場所ではないので合わない。", "窓": "窓は建物の開口部で、土壌を耕す対象にはならないので合わない。", "海": "海は水域で、耕して野菜の種を植える場所ではないので合わない。"}, "sentence_index": 0, "correct_answer": "畑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の午後、畑で魚を釣って過ごした。", "explanation": "ここは〈水辺〉の意味。魚を釣るのは川や池などの水辺で、耕した土地の畑とは合わない。"}, {"text": "田植えが終わると、畑に水を張ってしばらく待つ。", "explanation": "ここは〈田〉の意味。水を張って苗を植えるのは田で、畑は水を張らない土地なので合わない。"}, {"text": "縁側から見える畑には、池と石灯籠が置かれている。", "explanation": "ここは〈庭〉の意味。池や石灯籠は庭の設えで、野菜や花を育てる畑には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "畑", "is_correct": true, "explanation": "野菜や草花を育てる土地のことで、家の裏の小さな土地でネギやナスを作る文脈に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院は治療を行う施設で、ネギやナスを作る場所ではないので合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業を行う部屋で、野菜を作る場所ではないので合わない。"}, {"text": "駅", "is_correct": false, "explanation": "駅は乗降の場所で、野菜を作る場所ではないので合わない。"}], "explanations": {"畑": "野菜や草花を育てる土地のことで、家の裏の小さな土地でネギやナスを作る文脈に合う。", "病院": "病院は治療を行う施設で、ネギやナスを作る場所ではないので合わない。", "教室": "教室は授業を行う部屋で、野菜を作る場所ではないので合わない。", "駅": "駅は乗降の場所で、野菜を作る場所ではないので合わない。"}, "sentence_index": 6, "correct_answer": "畑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、海辺の畑で貝拾いをして遊んだ。", "explanation": "ここは〈浜〉の意味。貝拾いをする場所は浜辺で、耕した土地の畑とは合わない。"}, {"text": "日曜日の午後、畑の遊具で子どもたちが元気に遊んでいた。", "explanation": "ここは〈公園〉の意味。遊具がある場所は公園で、耕した土地の畑とは合わない。"}, {"text": "父は週末、畑の机で論文を書いている。", "explanation": "ここは〈書斎〉の意味。机で論文を書く場所は部屋で、畑とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は畑が草を抜いている。", "corrected_sentence": "父は畑で草を抜いている。", "error_description": "誤りは『畑が』。『が』だと畑が主語になり、草を抜く人がいなくなる。正しくは『畑で』で、動作が行われる場所を表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36799, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は毎朝、畑を水をまいている。", "corrected_sentence": "兄は毎朝、畑に水をまいている。", "error_description": "誤りは『畑を』。『水を』が既に目的語なので、畑には『を』を重ねられない。正しくは『畑に』で、水をまく先の場所を表す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "撒く対象のパンくずを示す格助詞で、他動詞「撒く」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "「撒く」は他動詞なので、パンくずを主語にすると「パンくずが撒く」となり文意が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「鳥に」の後にさらに「に」が続くと二重になり不自然で、撒く対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、撒く対象（パンくず）を示す格助詞としては使えない。"}], "correct_answer": "を", "explanations": {"を": "撒く対象のパンくずを示す格助詞で、他動詞「撒く」の目的語を表す。", "が": "「撒く」は他動詞なので、パンくずを主語にすると「パンくずが撒く」となり文意が通らない。", "に": "「鳥に」の後にさらに「に」が続くと二重になり不自然で、撒く対象を示せない。", "へ": "方向を表すが、撒く対象（パンくず）を示す格助詞としては使えない。"}, "error_tags": {"が": "主格（他動詞の目的語に不適）", "に": "二重の格（与え先の後に続かない）", "へ": "方向（撒く対象に不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "撒く対象のえさを示す格助詞で、他動詞「撒く」の目的語を表す。"}, {"text": "の", "is_correct": false, "explanation": "「えさの」と続けると名詞修飾になり、撒く動作の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、撒く対象を示すことはできない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、えさを撒く対象として示す格助詞にはならない。"}], "correct_answer": "を", "explanations": {"を": "撒く対象のえさを示す格助詞で、他動詞「撒く」の目的語を表す。", "の": "「えさの」と続けると名詞修飾になり、撒く動作の目的語にならない。", "より": "比較を表す助詞で、撒く対象を示すことはできない。", "から": "起点を表すが、えさを撒く対象として示す格助詞にはならない。"}, "error_tags": {"の": "連体修飾（名詞を修飾し目的語にならない）", "より": "比較（撒く対象に不適）", "から": "起点（撒く対象に不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ちいさなつぶを、ぱらぱらとちのうえにちらすことです。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "春になったので、庭に花の種を撒きました。", "target_word": "撒きました", "complexity_tier": "T3", "furigana": "春[はる]になったので、庭[にわ]に花[はな]の種[たね]を撒[ま]きました。", "sentence_source": "generated"}, {"text": "公園で、鳥にパンくずを撒くと、すぐに集まってきた。", "target_word": "撒く", "complexity_tier": "T3", "furigana": "公園[こうえん]で、鳥[とり]にパンくずを撒[ま]くと、すぐに集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "農家の人は、畑に小さな種をぱらぱらと撒いている。", "target_word": "撒いている", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、畑[はたけ]に小[ちい]さな種[たね]をぱらぱらと撒[ま]いている。", "sentence_source": "generated"}, {"text": "祖母は朝早く、にわとりのために庭にえさを撒く。", "target_word": "撒く", "complexity_tier": "T3", "furigana": "祖母[そぼ]は朝早[あさはや]く、にわとりのために庭[にわ]にえさを撒[ま]く。", "sentence_source": "generated"}, {"text": "雪の日は、道が滑らないように砂を撒いた。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、道[みち]が滑[すべ]らないように砂[すな]を撒[ま]いた。", "sentence_source": "generated"}, {"text": "節分の日に、家の外へ豆を撒いた。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "節分[せつぶん]の日[ひ]に、家[いえ]の外[そと]へ豆[まめ]を撒[ま]いた。", "sentence_source": "generated"}, {"text": "芝生が生えるように、土の上に草の種を撒かなければならない。", "target_word": "撒かなければ", "complexity_tier": "T3", "furigana": "芝生[しばふ]が生[は]えるように、土[つち]の上[うえ]に草[くさ]の種[たね]を撒[ま]かなければならない。", "sentence_source": "generated"}, {"text": "子どもたちは、池のコイにえさを撒いて遊んだ。", "target_word": "撒いて", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、池[いけ]のコイにえさを撒[ま]いて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "雨が降る前に、畑に肥料を撒いておきました。", "target_word": "撒いて", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]に、畑[はたけ]に肥料[ひりょう]を撒[ま]いておきました。", "sentence_source": "generated"}, {"text": "種を撒いたあとは、土を軽くかけてください。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "種[たね]を撒[ま]いたあとは、土[つち]を軽[かる]くかけてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "撒く", "label": "辞書形"}, {"form": "撒きます", "label": "丁寧形"}, {"form": "撒いた", "label": "過去形"}, {"form": "撒いて", "label": "て形"}, {"form": "撒かない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "種や豆などの小さな粒を地面にぱらぱらと散らす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撒きました", "is_correct": true, "explanation": "「まく（撒く）」の丁寧過去形で、庭に種を散らしたことを表し、文脈に合う。"}, {"text": "刈りました", "is_correct": false, "explanation": "「刈る」は草や稲を根元から切る動作で、種を庭に散らす文脈には合わない。"}, {"text": "折りました", "is_correct": false, "explanation": "「折る」は棒や紙を曲げて割る動作で、種を庭に散らす文には使えない。"}, {"text": "磨きました", "is_correct": false, "explanation": "「磨く」は表面をこすって光らせる動作で、花の種を庭に散らす場面には合わない。"}], "explanations": {"撒きました": "「まく（撒く）」の丁寧過去形で、庭に種を散らしたことを表し、文脈に合う。", "刈りました": "「刈る」は草や稲を根元から切る動作で、種を庭に散らす文脈には合わない。", "折りました": "「折る」は棒や紙を曲げて割る動作で、種を庭に散らす文には使えない。", "磨きました": "「磨く」は表面をこすって光らせる動作で、花の種を庭に散らす場面には合わない。"}, "sentence_index": 0, "correct_answer": "撒きました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末に、庭に苗木を撒いた。", "explanation": "ここは〈植える〉の意味。撒くは種を広く散らす動作で、根のついた苗木を一本ずつ植える場面には使わない。"}, {"text": "コップに牛乳を撒いた。", "explanation": "ここは〈注ぐ〉の意味。撒くは粒や粉を広く散らす動作で、容器に液体を入れる場面では使わない。"}, {"text": "糸を撒いて、ボビンにまとめた。", "explanation": "ここは〈巻く〉の意味。撒くは広く散らす動作で、糸を回して一か所にまとめる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撒かなければ", "is_correct": true, "explanation": "「撒く」の未然形に「なければ」が付き、草の種を土の上に散らす必要があるという文脈に合う。"}, {"text": "脱がなければ", "is_correct": false, "explanation": "「脱ぐ」は衣服を体から外す動作で、種を土の上に散らす文脈には合わない。"}, {"text": "叫ばなければ", "is_correct": false, "explanation": "「叫ぶ」は大声を出す動作で、種を土の上に置く場面では文が成り立たない。"}, {"text": "眠らなければ", "is_correct": false, "explanation": "「眠る」は体を休める動作で、種を土の上に散らす文脈には使えない。"}], "explanations": {"撒かなければ": "「撒く」の未然形に「なければ」が付き、草の種を土の上に散らす必要があるという文脈に合う。", "脱がなければ": "「脱ぐ」は衣服を体から外す動作で、種を土の上に散らす文脈には合わない。", "叫ばなければ": "「叫ぶ」は大声を出す動作で、種を土の上に置く場面では文が成り立たない。", "眠らなければ": "「眠る」は体を休める動作で、種を土の上に散らす文脈には使えない。"}, "sentence_index": 6, "correct_answer": "撒かなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "贈り物を新聞紙で撒いて、リボンをかけた。", "explanation": "ここは〈包む〉の意味。撒くは粒を散らす動作で、紙で覆って包む場面には使わない。"}, {"text": "壁に白いペンキを撒いた。", "explanation": "ここは〈塗る〉の意味。撒くは粒を散らす動作で、面に広げて塗る場面には使わない。"}, {"text": "靴ひもを撒いて、きちんと固定した。", "explanation": "ここは〈結ぶ〉の意味。撒くは散らす動作で、ひもを締めて留める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、畑に小さな種を撒きます。", "corrected_sentence": "昨日、畑に小さな種を撒きました。", "error_description": "時制の誤り。「昨日」は過去の出来事を表すので、過去形の「撒きました」が正しい。現在形の「撒きます」は「昨日」と合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "撒く", "is_correct": true, "explanation": "辞書形で「撒くと」の形になり、条件を表す節として文に合う。"}, {"text": "撒きたかった", "is_correct": false, "explanation": "希望の形になり、撒いた結果として鳥が集まったという文の内容と合わない。"}, {"text": "撒いて", "is_correct": false, "explanation": "て形は「と」の前に続けられず、文が成り立たない。"}, {"text": "撒かない", "is_correct": false, "explanation": "否定形の「撒かないと」は「撒かなければ」の意味になり、撒いたから集まったという文脈と逆になる。"}], "correct_form": "撒く", "base_form": "撒く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"撒く": "辞書形で「撒くと」の形になり、条件を表す節として文に合う。", "撒きたかった": "希望の形になり、撒いた結果として鳥が集まったという文の内容と合わない。", "撒いて": "て形は「と」の前に続けられず、文が成り立たない。", "撒かない": "否定形の「撒かないと」は「撒かなければ」の意味になり、撒いたから集まったという文脈と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36800, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑に肥料が撒きます。", "corrected_sentence": "畑に肥料を撒きます。", "error_description": "助詞の誤り。他動詞「撒く」の目的語「肥料」には「を」を使う。「が」にすると肥料が主語になり、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "撒いて", "is_correct": true, "explanation": "て形で、えさを撒いてから遊んだという動作の続きを表し、文に合う。"}, {"text": "撒きます", "is_correct": false, "explanation": "丁寧形は「撒きます遊んだ」と続けられず、文が成り立たない。"}, {"text": "撒きました", "is_correct": false, "explanation": "丁寧過去形は後ろの「遊んだ」に続かず、て形が必要になる。"}, {"text": "撒かなかった", "is_correct": false, "explanation": "否定過去形は「撒かなかった遊んだ」と続かず、えさを撒いたという文の意味とも逆になる。"}], "correct_form": "撒いて", "base_form": "撒く", "form_label": "て形", "sentence_index": 7, "explanations": {"撒いて": "て形で、えさを撒いてから遊んだという動作の続きを表し、文に合う。", "撒きます": "丁寧形は「撒きます遊んだ」と続けられず、文が成り立たない。", "撒きました": "丁寧過去形は後ろの「遊んだ」に続かず、て形が必要になる。", "撒かなかった": "否定過去形は「撒かなかった遊んだ」と続かず、えさを撒いたという文の意味とも逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
