INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "撒く対象のコーヒーのかすを示す格助詞で、他動詞「撒く」の目的語を表す。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、撒く対象を示す格助詞としては合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、かすを撒く対象として示すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す助詞で、撒く対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "撒く対象のコーヒーのかすを示す格助詞で、他動詞「撒く」の目的語を表す。", "と": "並列や相手を表すが、撒く対象を示す格助詞としては合わない。", "から": "起点を表すが、かすを撒く対象として示すことはできない。", "より": "比較を表す助詞で、撒く対象を示すことはできない。"}, "error_tags": {"と": "並列・相手（撒く対象に不適）", "から": "起点（撒く対象に不適）", "より": "比較（撒く対象に不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "粉や粒状のものを、広く散らすようにして置くこと。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "道が凍ったので、塩を撒いた。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "道[みち]が凍[こお]ったので、塩[しお]を撒[ま]いた。", "sentence_source": "generated"}, {"text": "庭の雑草を防ぐために、除草剤の粒を撒いた。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "庭[にわ]の雑草[ざっそう]を防[ふせ]ぐために、除草剤[じょそうざい]の粒[つぶ]を撒[ま]いた。", "sentence_source": "generated"}, {"text": "台所の床に小麦粉を撒いてしまい、掃除が大変だった。", "target_word": "撒いて", "complexity_tier": "T3", "furigana": "台所[だいどころ]の床[ゆか]に小麦粉[こむぎこ]を撒[ま]いてしまい、掃除[そうじ]が大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "冬は、駐車場に融雪剤を撒く人が多い。", "target_word": "撒く", "complexity_tier": "T3", "furigana": "冬[ふゆ]は、駐車場[ちゅうしゃじょう]に融雪剤[ゆうせつざい]を撒[ま]く人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "家の前に清めの塩を撒く人もいる。", "target_word": "撒く", "complexity_tier": "T3", "furigana": "家[いえ]の前[まえ]に清[きよ]めの塩[しお]を撒[ま]く人[ひと]もいる。", "sentence_source": "generated"}, {"text": "虫が来ないように、庭に木の灰を撒きます。", "target_word": "撒きます", "complexity_tier": "T3", "furigana": "虫[むし]が来[こ]ないように、庭[にわ]に木[き]の灰[はい]を撒[ま]きます。", "sentence_source": "generated"}, {"text": "運動会の前に、グラウンドに白い石灰を撒いて線を引いた。", "target_word": "撒いて", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前[まえ]に、グラウンドに白[しろ]い石灰[せっかい]を撒[ま]いて線[せん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "猫が入らないように、花壇にコーヒーのかすを撒いた。", "target_word": "撒いた", "complexity_tier": "T3", "furigana": "猫[ねこ]が入[はい]らないように、花壇[かだん]にコーヒーのかすを撒[ま]いた。", "sentence_source": "generated"}, {"text": "稲の根が育つように、田んぼに化学肥料の粒を撒く。", "target_word": "撒く", "complexity_tier": "T3", "furigana": "稲[いね]の根[ね]が育[そだ]つように、田[た]んぼに化学肥料[かがくひりょう]の粒[つぶ]を撒[ま]く。", "sentence_source": "generated"}, {"text": "砂利を道に撒いて、ぬかるみを歩きやすくした。", "target_word": "撒いて", "complexity_tier": "T3", "furigana": "砂利[じゃり]を道[みち]に撒[ま]いて、ぬかるみを歩[ある]きやすくした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "撒く", "label": "辞書形"}, {"form": "撒きます", "label": "丁寧形"}, {"form": "撒いた", "label": "過去形"}, {"form": "撒いて", "label": "て形"}, {"form": "撒かない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "塩・石灰・灰などの粉や粒を広い範囲に散らして置く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撒いた", "is_correct": true, "explanation": "「撒く」の過去形で、塩を道に散らしたという文脈に合う。"}, {"text": "割った", "is_correct": false, "explanation": "「割る」は物を二つ以上に分ける動作で、塩を道に散らす文脈には合わない。"}, {"text": "折った", "is_correct": false, "explanation": "「折る」は棒や紙を曲げて切る動作で、塩には使わない。"}, {"text": "刈った", "is_correct": false, "explanation": "「刈る」は草や稲を根元から切る動作で、塩を道に散らす文脈には合わない。"}], "explanations": {"撒いた": "「撒く」の過去形で、塩を道に散らしたという文脈に合う。", "割った": "「割る」は物を二つ以上に分ける動作で、塩を道に散らす文脈には合わない。", "折った": "「折る」は棒や紙を曲げて切る動作で、塩には使わない。", "刈った": "「刈る」は草や稲を根元から切る動作で、塩を道に散らす文脈には合わない。"}, "sentence_index": 0, "correct_answer": "撒いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の床に、新しいじゅうたんを撒いた。", "explanation": "ここは〈敷く〉の意味。撒くは粉や粒を散らす動作で、布を一面に広げて置く場面には使わない。"}, {"text": "グラスに水を撒いた。", "explanation": "ここは〈注ぐ〉の意味。撒くは粉や粒を広く散らす動作で、グラスに液体を入れる場面では使わない。"}, {"text": "靴ひもを撒いて、きちんと締めた。", "explanation": "ここは〈結ぶ〉の意味。撒くは散らす動作で、ひもを締めて留める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撒いて", "is_correct": true, "explanation": "て形で、石灰を撒いてから線を引くという動作の順序に合う。"}, {"text": "煮て", "is_correct": false, "explanation": "「煮る」は食材を水で加熱する動作で、石灰を地面に散らす文脈には合わない。"}, {"text": "脱いで", "is_correct": false, "explanation": "「脱ぐ」は衣服を体から外す動作で、石灰には使わない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は表面をこすって光らせる動作で、石灰を地面に散らす文脈には合わない。"}], "explanations": {"撒いて": "て形で、石灰を撒いてから線を引くという動作の順序に合う。", "煮て": "「煮る」は食材を水で加熱する動作で、石灰を地面に散らす文脈には合わない。", "脱いで": "「脱ぐ」は衣服を体から外す動作で、石灰には使わない。", "磨いて": "「磨く」は表面をこすって光らせる動作で、石灰を地面に散らす文脈には合わない。"}, "sentence_index": 6, "correct_answer": "撒いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お菓子を薄い紙で撒いて、袋に入れた。", "explanation": "ここは〈包む〉の意味。撒くは粉や粒を散らす動作で、紙で覆って包む場面には使わない。"}, {"text": "壁に白いペンキを撒いた。", "explanation": "ここは〈塗る〉の意味。撒くは粒や粉を散らす動作で、面に伸ばして塗る場面には使わない。"}, {"text": "糸を撒いて、ボビンにまとめた。", "explanation": "ここは〈巻く〉の意味。撒くは広く散らす動作で、糸を回して一つにまとめる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は、庭に石灰を撒く。", "corrected_sentence": "昨日は、庭に石灰を撒いた。", "error_description": "時制の誤り。「昨日」は過去の出来事を表すので、過去形の「撒いた」が正しい。辞書形の「撒く」は「昨日」と合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "撒いた", "is_correct": true, "explanation": "過去形で、粒を撒いたという動作を文末で表す。"}, {"text": "撒いて", "is_correct": false, "explanation": "て形は文末に置けず、「撒いて。」では文が終わらない。"}, {"text": "撒いたら", "is_correct": false, "explanation": "たら形は続く節が必要で、文末に置くと文が成り立たない。"}, {"text": "撒かない", "is_correct": false, "explanation": "否定形にすると粒を撒かないことになり、雑草を防ぐために撒いたという文の意味と逆になる。"}], "correct_form": "撒いた", "base_form": "撒く", "form_label": "過去形", "sentence_index": 1, "explanations": {"撒いた": "過去形で、粒を撒いたという動作を文末で表す。", "撒いて": "て形は文末に置けず、「撒いて。」では文が終わらない。", "撒いたら": "たら形は続く節が必要で、文末に置くと文が成り立たない。", "撒かない": "否定形にすると粒を撒かないことになり、雑草を防ぐために撒いたという文の意味と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36801, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭に石灰が撒きます。", "corrected_sentence": "庭に石灰を撒きます。", "error_description": "助詞の誤り。他動詞「撒く」の目的語「石灰」には「を」を使う。「が」にすると石灰が主語になり、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "撒いた", "is_correct": true, "explanation": "過去形で、花壇にコーヒーのかすを撒いたという動作を表す。"}, {"text": "撒かなかった", "is_correct": false, "explanation": "否定過去形で、撒かなかったことになり、猫を防ぐために撒いたという文の意味と逆になる。"}, {"text": "撒けなかった", "is_correct": false, "explanation": "可能の否定過去形で、撒けなかったことになり、猫を防ぐために撒いたという文の意味と逆になる。"}, {"text": "撒きたかった", "is_correct": false, "explanation": "希望の形で、撒きたかったという気持ちを表し、実際に撒いた事実を述べる文には合わない。"}], "correct_form": "撒いた", "base_form": "撒く", "form_label": "過去形", "sentence_index": 7, "explanations": {"撒いた": "過去形で、花壇にコーヒーのかすを撒いたという動作を表す。", "撒かなかった": "否定過去形で、撒かなかったことになり、猫を防ぐために撒いたという文の意味と逆になる。", "撒けなかった": "可能の否定過去形で、撒けなかったことになり、猫を防ぐために撒いたという文の意味と逆になる。", "撒きたかった": "希望の形で、撒きたかったという気持ちを表し、実際に撒いた事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "作る対象の新鮮な野菜を示す格助詞で、他動詞「作る」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "「作る」は他動詞なので、野菜を主語にすると「野菜が作っている」となり不自然。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を表すが、作る対象（野菜）を示す格助詞にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、野菜を作る対象として示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "作る対象の新鮮な野菜を示す格助詞で、他動詞「作る」の目的語を表す。", "が": "「作る」は他動詞なので、野菜を主語にすると「野菜が作っている」となり不自然。", "に": "相手や場所を表すが、作る対象（野菜）を示す格助詞にはならない。", "へ": "方向を表すが、野菜を作る対象として示すことはできない。"}, "error_tags": {"が": "主格（他動詞の目的語に不適）", "に": "相手・場所（作る対象に不適）", "へ": "方向（作る対象に不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「野菜の値段」の所有関係を示す連体助詞で、後ろの名詞を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "目的格の「を」は自動詞「上がる」には使えず、「野菜を値段が上がる」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、値段が上がるという関係を示すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、野菜と値段の所有関係を示すことはできない。"}], "correct_answer": "の", "explanations": {"の": "「野菜の値段」の所有関係を示す連体助詞で、後ろの名詞を修飾する。", "を": "目的格の「を」は自動詞「上がる」には使えず、「野菜を値段が上がる」は成り立たない。", "と": "並列や相手を表すが、値段が上がるという関係を示すことはできない。", "より": "比較を表すが、野菜と値段の所有関係を示すことはできない。"}, "error_tags": {"を": "目的格（自動詞「上がる」に不適）", "と": "並列（所有関係に不適）", "より": "比較（所有関係に不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべもののなかま。はたけでそだつもの。", "primary_collocate": null, "pronunciation": "やさい", "ipa": "jasai", "syllable_count": 3, "sentences": [{"text": "毎日、野菜をたくさん食べるようにしています。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "毎日[まいにち]、野菜[やさい]をたくさん食[た]べるようにしています。", "sentence_source": "generated"}, {"text": "祖父は畑で、新鮮な野菜を作っている。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "祖父[そふ]は畑[はたけ]で、新鮮[しんせん]な野菜[やさい]を作[つく]っている。", "sentence_source": "generated"}, {"text": "野菜が高いので、今週はもやしばかり買った。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "野菜[やさい]が高[たか]いので、今週[こんしゅう]はもやしばかり買[か]った。", "sentence_source": "generated"}, {"text": "この店の野菜は朝とれたばかりで、とてもおいしい。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "この店[みせ]の野菜[やさい]は朝[あさ]とれたばかりで、とてもおいしい。", "sentence_source": "generated"}, {"text": "子どもは野菜が苦手で、にんじんを残してしまう。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "子[こ]どもは野菜[やさい]が苦手[にがて]で、にんじんを残[のこ]してしまう。", "sentence_source": "generated"}, {"text": "スーパーで肉と野菜を買って、カレーを作った。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "スーパーで肉[にく]と野菜[やさい]を買[か]って、カレーを作[つく]った。", "sentence_source": "generated"}, {"text": "冬は寒さに強い野菜を畑に植える。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]さに強[つよ]い野菜[やさい]を畑[はたけ]に植[う]える。", "sentence_source": "generated"}, {"text": "雨が少なかった年は、野菜の値段が上がる。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なかった年[とし]は、野菜[やさい]の値段[ねだん]が上[あ]がる。", "sentence_source": "generated"}, {"text": "野菜は洗ってから、小さく切ってください。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "野菜[やさい]は洗[あら]ってから、小[ちい]さく切[き]ってください。", "sentence_source": "generated"}, {"text": "野菜が足りないと、体の調子が悪くなりやすい。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "野菜[やさい]が足[た]りないと、体[からだ]の調子[ちょうし]が悪[わる]くなりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "野菜", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "畑で育てて食べるにんじんやキャベツなどの食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野菜", "is_correct": true, "explanation": "食べ物として毎日たくさん食べるという文脈に自然に入る。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗剤は食べられないもので、たくさん食べるという動作の対象にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は食べ物ではなく、食べるという動作に合わない。"}, {"text": "新聞", "is_correct": false, "explanation": "新聞は食べられないもので、食べるという動作の対象にならない。"}], "explanations": {"野菜": "食べ物として毎日たくさん食べるという文脈に自然に入る。", "洗剤": "洗剤は食べられないもので、たくさん食べるという動作の対象にならない。", "教科書": "教科書は食べ物ではなく、食べるという動作に合わない。", "新聞": "新聞は食べられないもので、食べるという動作の対象にならない。"}, "sentence_index": 0, "correct_answer": "野菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "芝生の野菜を刈って、きれいに整えた。", "explanation": "ここは〈草〉の意味。野菜は食用に育てる植物で、芝生を刈る対象にはならない。"}, {"text": "彼は大きな野菜に勤めている。", "explanation": "ここは〈会社〉の意味。勤めるのは会社などの組織で、野菜を勤め先とする文は成り立たない。"}, {"text": "花瓶に野菜を生けた。", "explanation": "ここは〈花〉の意味。生けるのは花で、野菜を花瓶に生ける場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野菜", "is_correct": true, "explanation": "寒さに強い作物として畑に植えるという文脈に合う。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は畑に植えるものではないので、文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は植えられないもので、畑に植える対象にならない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は畑に植えるものではなく、文脈に合わない。"}], "explanations": {"野菜": "寒さに強い作物として畑に植えるという文脈に合う。", "雑誌": "雑誌は畑に植えるものではないので、文が成り立たない。", "石鹸": "石鹸は植えられないもので、畑に植える対象にならない。", "辞書": "辞書は畑に植えるものではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "野菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボウルで野菜をよくこねて、パンを焼いた。", "explanation": "ここは〈生地〉の意味。こねるのは生地で、野菜は練って形を作る材料にはならない。"}, {"text": "手紙の野菜を三つに折って、封筒に入れた。", "explanation": "ここは〈紙〉の意味。折るのは紙で、野菜は三つに折れるものではない。"}, {"text": "スカートの裾に野菜を縫いつけた。", "explanation": "ここは〈布〉の意味。縫うのは布や糸で、野菜を縫いつける場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、毎朝畑で野菜が収穫している。", "corrected_sentence": "祖母は、毎朝畑で野菜を収穫している。", "error_description": "助詞の誤り。他動詞「収穫する」の目的語「野菜」には「を」を使う。「が」にすると野菜が主語になり、「収穫している」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36802, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬は、暖房のない家で野菜に育てる人が多い。", "corrected_sentence": "冬は、暖房のない家で野菜を育てる人が多い。", "error_description": "助詞の誤り。目的語の「野菜」には「を」を使う。「に」にすると目的語が示せず、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
