INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36804, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "赤ちゃんや子どもが、元気に大きくなるようす。", "primary_collocate": null, "pronunciation": "すくすく", "ipa": "sɯkɯsɯkɯ", "syllable_count": 4, "sentences": [{"text": "赤ちゃんはミルクをよく飲んで、すくすく育っている。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはミルクをよく飲[の]んで、すくすく育[そだ]っている。", "sentence_source": "generated"}, {"text": "娘はすくすくと大きくなり、もう小学生だ。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "娘[むすめ]はすくすくと大[おお]きくなり、もう小学生[しょうがくせい]だ。", "sentence_source": "generated"}, {"text": "毎日よく食べるので、息子はすくすく育つ。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "毎日[まいにち]よく食[た]べるので、息子[むすこ]はすくすく育[そだ]つ。", "sentence_source": "generated"}, {"text": "孫がすくすく成長する姿を見るのが楽しみだ。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "孫[まご]がすくすく成長[せいちょう]する姿[すがた]を見[み]るのが楽[たの]しみだ。", "sentence_source": "generated"}, {"text": "弟は早寝早起きで、すくすくと育った。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "弟[おとうと]は早寝早起[はやねはやお]きで、すくすくと育[そだ]った。", "sentence_source": "generated"}, {"text": "保育園の子どもたちは、すくすく大きくなっている。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "保育園[ほいくえん]の子[こ]どもたちは、すくすく大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "田舎の空気のおかげで、子どもがすくすく育った。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "田舎[いなか]の空気[くうき]のおかげで、子[こ]どもがすくすく育[そだ]った。", "sentence_source": "generated"}, {"text": "双子の赤ちゃんは、すくすくと健康に育っています。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "双子[ふたご]の赤[あか]ちゃんは、すくすくと健康[けんこう]に育[そだ]っています。", "sentence_source": "generated"}, {"text": "去年生まれた姪も、すくすく育っているようだ。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "去年[きょねん]生[う]まれた姪[めい]も、すくすく育[そだ]っているようだ。", "sentence_source": "generated"}, {"text": "母は、子どもがすくすく育つことだけを願っている。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "母[はは]は、子[こ]どもがすくすく育[そだ]つことだけを願[ねが]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "すくすく", "label": "基本形"}, {"form": "すくすくと", "label": "と付き"}], "register": "neutral", "sense_fingerprint": "赤ちゃん・子どもが元気に順調に育つ様子を表す擬態語。『すくすく育つ』", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36804, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すくすく", "is_correct": true, "explanation": "赤ちゃんや子どもが元気に大きくなる様子を表す副詞。ミルクを飲んで順調に育つ文脈に合う。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す。育つ様子には合わない。"}, {"text": "ふらふら", "is_correct": false, "explanation": "足元や体が不安定に揺れるさまを表す。成長の様子には合わない。"}, {"text": "ぎらぎら", "is_correct": false, "explanation": "強い光がまぶしく照り返すさまを表す。育つ様子には合わない。"}], "explanations": {"すくすく": "赤ちゃんや子どもが元気に大きくなる様子を表す副詞。ミルクを飲んで順調に育つ文脈に合う。", "きらきら": "光が輝くさまを表す。育つ様子には合わない。", "ふらふら": "足元や体が不安定に揺れるさまを表す。成長の様子には合わない。", "ぎらぎら": "強い光がまぶしく照り返すさまを表す。育つ様子には合わない。"}, "sentence_index": 0, "correct_answer": "すくすく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は外国語をすくすく話した。", "explanation": "ここは〈すらすら〉の意味。すくすくは赤ちゃんや子どもが元気に育つ様子を表すので、話し方の滑らかさには使わない。"}, {"text": "株価がすくすく上がった。", "explanation": "ここは〈ぐんぐん〉の意味。すくすくは生き物が順調に育つ様子を表し、株価や数字の上昇には使わない。"}, {"text": "子どもがすくすくと遊んでいる。", "explanation": "ここは〈のびのび〉の意味。すくすくは成長の様子を表すので、遊ぶ様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36804, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "すくすく", "is_correct": true, "explanation": "子どもが元気に大きくなる様子を表す副詞。田舎の空気で育つ文脈に合う。"}, {"text": "しとしと", "is_correct": false, "explanation": "雨が静かに降るさまを表す。育つ様子には合わない。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す。育つ様子には合わない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "柔らかく軽いさまを表す。育つ様子には合わない。"}], "explanations": {"すくすく": "子どもが元気に大きくなる様子を表す副詞。田舎の空気で育つ文脈に合う。", "しとしと": "雨が静かに降るさまを表す。育つ様子には合わない。", "きらきら": "光が輝くさまを表す。育つ様子には合わない。", "ふわふわ": "柔らかく軽いさまを表す。育つ様子には合わない。"}, "sentence_index": 6, "correct_answer": "すくすく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな杉の木が、すくすくと立っている。", "explanation": "ここは〈すっくと〉の意味。すくすくは赤ちゃんや子どもが元気に育つ様子を表すので、木がまっすぐ立つ様子には使わない。"}, {"text": "赤ちゃんがすくすく眠っている。", "explanation": "ここは〈ぐっすり〉の意味。すくすくは成長の様子を表すので、眠りの深さには使わない。"}, {"text": "宿題をすくすく終えた。", "explanation": "ここは〈きちんと〉の意味。すくすくは成長の様子を表すので、仕事や宿題の仕上がりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36804, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "娘は毎日すくすくで大きくなっている。", "corrected_sentence": "娘は毎日すくすくと大きくなっている。", "error_description": "『すくすく』の後に『で』は続かない。副詞として直接動詞にかけるか、『すくすくと』とする。正しくは『すくすくと大きくなっている』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36804, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟はよく眠って、すくすくに育っている。", "corrected_sentence": "弟はよく眠って、すくすくと育っている。", "error_description": "『すくすく』の後に『に』は続かない。副詞として直接動詞にかけるか、『すくすくと』とする。正しくは『すくすくと育っている』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
