INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36805, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "成長するさまが順調で、勢いよく、またたく間に大きくなる様子。", "primary_collocate": null, "pronunciation": "すくすく", "ipa": "sɯkɯsɯkɯ", "syllable_count": 4, "sentences": [{"text": "雨のあと、庭の草がすくすく伸びた。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、庭[にわ]の草[くさ]がすくすく伸[の]びた。", "sentence_source": "generated"}, {"text": "苗は日光を浴びて、すくすくと育った。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "苗[なえ]は日光[にっこう]を浴[あ]びて、すくすくと育[そだ]った。", "sentence_source": "generated"}, {"text": "竹は春になると、すくすく伸びる。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "竹[たけ]は春[はる]になると、すくすく伸[の]びる。", "sentence_source": "generated"}, {"text": "肥料をやったら、トマトがすくすく育った。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "肥料[ひりょう]をやったら、トマトがすくすく育[そだ]った。", "sentence_source": "generated"}, {"text": "稲がすくすくと伸びて、田んぼが緑になった。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "稲[いね]がすくすくと伸[の]びて、田[た]んぼが緑[みどり]になった。", "sentence_source": "generated"}, {"text": "暖かい部屋で、豆の芽がすくすく大きくなった。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "暖[あたた]かい部屋[へや]で、豆[まめ]の芽[め]がすくすく大[おお]きくなった。", "sentence_source": "generated"}, {"text": "彼の会社は、すくすくと成長して大企業になった。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "彼[かれ]の会社[かいしゃ]は、すくすくと成長[せいちょう]して大企業[だいきぎょう]になった。", "sentence_source": "generated"}, {"text": "水をやるたびに、ひまわりがすくすく育った。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "水[みず]をやるたびに、ひまわりがすくすく育[そだ]った。", "sentence_source": "generated"}, {"text": "新しい木は、数年ですくすく伸びて、もう私の背を超えた。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "新[あたら]しい木[き]は、数年ですくすく伸[の]びて、もう私[わたし]の背[せ]を超[こ]えた。", "sentence_source": "generated"}, {"text": "野菜はすくすく育ち、すぐに収穫できた。", "target_word": "すくすく", "complexity_tier": "T3", "furigana": "野菜[やさい]はすくすく育[そだ]ち、すぐに収穫[しゅうかく]できた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "すくすく", "label": "基本形"}, {"form": "すくすくと", "label": "と付き"}], "register": "neutral", "sense_fingerprint": "植物や会社など、成長が順調で勢いよく伸びる様子を表す擬態語。『すくすく伸びる』", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36805, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "すくすく", "is_correct": true, "explanation": "植物の成長が順調で勢いよく伸びる様子を表す副詞。雨のあと草が伸びる文脈に合う。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す。草が伸びる様子には合わない。"}, {"text": "ふらふら", "is_correct": false, "explanation": "不安定に揺れるさまを表す。伸びる勢いには合わない。"}, {"text": "ぎらぎら", "is_correct": false, "explanation": "強い光がまぶしく照り返すさまを表す。草が伸びる様子には合わない。"}], "explanations": {"すくすく": "植物の成長が順調で勢いよく伸びる様子を表す副詞。雨のあと草が伸びる文脈に合う。", "きらきら": "光が輝くさまを表す。草が伸びる様子には合わない。", "ふらふら": "不安定に揺れるさまを表す。伸びる勢いには合わない。", "ぎらぎら": "強い光がまぶしく照り返すさまを表す。草が伸びる様子には合わない。"}, "sentence_index": 0, "correct_answer": "すくすく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校庭の旗が、すくすくと立っている。", "explanation": "ここは〈すっくと〉の意味。すくすくは成長が順調で勢いよく大きくなる様子を表すので、旗がまっすぐ立つ様子には使わない。"}, {"text": "野菜をすくすく煮込んだ。", "explanation": "ここは〈じっくり〉の意味。すくすくは成長の勢いを表すので、煮込む様子には使わない。"}, {"text": "手をすくすく握った。", "explanation": "ここは〈ぎゅっと〉の意味。すくすくは成長が順調な様子を表すので、握る力の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36805, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "すくすく", "is_correct": true, "explanation": "会社が順調に勢いよく大きくなる様子を表す副詞。『と』を伴い『成長して』に続く。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す。会社の成長には合わない。"}, {"text": "しとしと", "is_correct": false, "explanation": "雨が静かに降るさまを表す。成長の勢いには合わない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "柔らかく軽いさまを表す。成長の勢いには合わない。"}], "explanations": {"すくすく": "会社が順調に勢いよく大きくなる様子を表す副詞。『と』を伴い『成長して』に続く。", "きらきら": "光が輝くさまを表す。会社の成長には合わない。", "しとしと": "雨が静かに降るさまを表す。成長の勢いには合わない。", "ふわふわ": "柔らかく軽いさまを表す。成長の勢いには合わない。"}, "sentence_index": 6, "correct_answer": "すくすく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "背筋をすくすくと伸ばして座った。", "explanation": "ここは〈すっと〉の意味。すくすくは成長の勢いを表す語で、背筋を姿勢よく伸ばす場面には使わない。"}, {"text": "宿題をすくすく仕上げた。", "explanation": "ここは〈しっかり〉の意味。すくすくは成長が順調な様子を表すので、仕事や宿題の仕上げには使わない。"}, {"text": "部屋がすくすくと暖かい。", "explanation": "ここは〈ぽかぽか〉の意味。すくすくは成長の勢いを表すので、温度や暖かさの様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36805, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨のあと、苗はすくすくに伸びた。", "corrected_sentence": "雨のあと、苗はすくすくと伸びた。", "error_description": "『すくすく』の後に『に』は続かない。副詞として直接動詞にかけるか、『すくすくと』とする。正しくは『すくすくと伸びた』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36805, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の間、ゴーヤのツルがすくすく伸ばした。", "corrected_sentence": "夏の間、ゴーヤのツルがすくすく伸びた。", "error_description": "『すくすく』が修飾する動詞は自動詞『伸びる』。他動詞『伸ばす』は誤り。正しくは『すくすく伸びた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「育つ」の主語である花を示す格助詞で、花が育たなかったという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "自動詞「育つ」は目的語を取らないので、「花を育たなかった」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「花に育たなかった」は場所や相手を示すが、育つ主語を表せず不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、育つ主語を示せず、「花へ育たなかった」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「育つ」の主語である花を示す格助詞で、花が育たなかったという文に合う。", "を": "自動詞「育つ」は目的語を取らないので、「花を育たなかった」は成り立たない。", "に": "「花に育たなかった」は場所や相手を示すが、育つ主語を表せず不自然になる。", "へ": "方向を表すが、育つ主語を示せず、「花へ育たなかった」は文が成り立たない。"}, "error_tags": {"を": "目的格（自動詞に不適）", "に": "位置・相手（主語に不適）", "へ": "方向（主語に不適）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を表す格助詞で、鉢の中という場所で苗が育ったことを示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、育つ場所を示す格助詞としては合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、苗が育った場所の説明にはならない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「鉢の中が育った」となり、場所を示す働きにはならない。"}], "correct_answer": "で", "explanations": {"で": "場所を表す格助詞で、鉢の中という場所で苗が育ったことを示す。", "と": "並列や相手を表すが、育つ場所を示す格助詞としては合わない。", "より": "比較を表すが、苗が育った場所の説明にはならない。", "が": "主語を示すが、「鉢の中が育った」となり、場所を示す働きにはならない。"}, "error_tags": {"と": "並列（場所に不適）", "より": "比較（場所に不適）", "が": "主格（場所に不適）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生き物や植物が大きくなる。", "primary_collocate": null, "pronunciation": "そだつ", "ipa": "sodatsɯ", "syllable_count": 3, "sentences": [{"text": "この木は、日当たりのいい場所でよく育つ。", "target_word": "育つ", "complexity_tier": "T3", "furigana": "この木[き]は、日当[ひあ]たりのいい場所[ばしょ]でよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "水をやらなかったので、花がうまく育たなかった。", "target_word": "育たなかった", "complexity_tier": "T3", "furigana": "水[みず]をやらなかったので、花[はな]がうまく育[そだ]たなかった。", "sentence_source": "generated"}, {"text": "庭のトマトが、夏の間に大きく育った。", "target_word": "育った", "complexity_tier": "T3", "furigana": "庭[にわ]のトマトが、夏[なつ]の間[あいだ]に大[おお]きく育[そだ]った。", "sentence_source": "generated"}, {"text": "子犬は、家族に愛されて元気に育っている。", "target_word": "育っている", "complexity_tier": "T3", "furigana": "子犬[こいぬ]は、家族[かぞく]に愛[あい]されて元気[げんき]に育[そだ]っている。", "sentence_source": "generated"}, {"text": "稲は、暖かくて水の多い土地で育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "稲[いね]は、暖[あたた]かくて水[みず]の多[おお]い土地[とち]で育[そだ]ちます。", "sentence_source": "generated"}, {"text": "北の寒い地方では、この野菜は育ちにくい。", "target_word": "育ちにくい", "complexity_tier": "T3", "furigana": "北[きた]の寒[さむ]い地方[ちほう]では、この野菜[やさい]は育[そだ]ちにくい。", "sentence_source": "generated"}, {"text": "雨が続けば、草は一週間でぐんぐん育つ。", "target_word": "育つ", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]けば、草[くさ]は一週間[いっしゅうかん]でぐんぐん育[そだ]つ。", "sentence_source": "generated"}, {"text": "鉢の中で育った苗を、春に畑へ移した。", "target_word": "育った", "complexity_tier": "T3", "furigana": "鉢[はち]の中[なか]で育[そだ]った苗[なえ]を、春[はる]に畑[はたけ]へ移[うつ]した。", "sentence_source": "generated"}, {"text": "ひなは親鳥が運ぶえさを食べて、育っていく。", "target_word": "育っていく", "complexity_tier": "T3", "furigana": "ひなは親鳥[おやどり]が運[はこ]ぶえさを食[た]べて、育[そだ]っていく。", "sentence_source": "generated"}, {"text": "日陰では、この草はほとんど育たない。", "target_word": "育たない", "complexity_tier": "T3", "furigana": "日陰[ひかげ]では、この草[くさ]はほとんど育[そだ]たない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育つ", "label": "辞書形"}, {"form": "育ちます", "label": "丁寧形"}, {"form": "育った", "label": "過去形"}, {"form": "育って", "label": "て形"}, {"form": "育たない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "動物や植物が時間とともに大きくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "育つ", "is_correct": true, "explanation": "生き物や植物が大きくなる意味で、日当たりのいい場所でよく大きくなるという文脈に合う。"}, {"text": "驚く", "is_correct": false, "explanation": "「驚く」は心が動く意味で、木に使うと文が成り立たず、大きくなる意味にならない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "「叫ぶ」は大声を出す動作で、木が大きくなるという文脈には合わない。"}, {"text": "笑う", "is_correct": false, "explanation": "「笑う」は表情や声を出す動作で、木の成長を表す文脈には合わない。"}], "explanations": {"育つ": "生き物や植物が大きくなる意味で、日当たりのいい場所でよく大きくなるという文脈に合う。", "驚く": "「驚く」は心が動く意味で、木に使うと文が成り立たず、大きくなる意味にならない。", "叫ぶ": "「叫ぶ」は大声を出す動作で、木が大きくなるという文脈には合わない。", "笑う": "「笑う」は表情や声を出す動作で、木の成長を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "育つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は人口が育っている。", "explanation": "ここは〈増える〉の意味。育つは生き物や植物が大きくなることで、人口の増加には使わない。"}, {"text": "部屋が育ってきた。", "explanation": "ここは〈冷える〉の意味。育つは生き物や植物の成長を表し、室温の変化には使わない。"}, {"text": "値段が育った。", "explanation": "ここは〈上がる〉の意味。育つは生き物や植物の成長を表し、値段の上昇には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "育つ", "is_correct": true, "explanation": "生き物や植物が大きくなる意味で、草が一週間で成長するという文脈に合う。"}, {"text": "泣く", "is_correct": false, "explanation": "「泣く」は涙を流す動作で、草が一週間で大きくなるという文脈には合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は体を休める動作で、草の成長を表す文脈には合わない。"}, {"text": "吠える", "is_correct": false, "explanation": "「吠える」は大きな声を出す動作で、草の成長には使わない。"}], "explanations": {"育つ": "生き物や植物が大きくなる意味で、草が一週間で成長するという文脈に合う。", "泣く": "「泣く」は涙を流す動作で、草が一週間で大きくなるという文脈には合わない。", "眠る": "「眠る」は体を休める動作で、草の成長を表す文脈には合わない。", "吠える": "「吠える」は大きな声を出す動作で、草の成長には使わない。"}, "sentence_index": 6, "correct_answer": "育つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "倉庫の在庫が少しずつ育っている。", "explanation": "〈減る〉の場面で言う文。育つは生き物や植物の成長を表し、在庫の減少には使わない。"}, {"text": "春の日差しで、庭の雪が育っていく。", "explanation": "〈消える〉の場面で言う文。育つは生き物や植物の成長を表し、雪が消えていく場面には使わない。"}, {"text": "ガラスが育った。", "explanation": "〈割れる〉の場面で言う文。育つは生き物や植物が大きくなる意味で、物が割れる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春になると、庭の草がぐんぐん育ちた。", "corrected_sentence": "春になると、庭の草がぐんぐん育つ。", "error_description": "活用の誤り。「育つ」は五段活用の動詞で、「育ちた」という形は成り立たない。正しい辞書形は「育つ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "育たなかった", "is_correct": true, "explanation": "否定過去形で、水をやらなかった結果として花がうまく育たなかったという文脈に合う。"}, {"text": "育った", "is_correct": false, "explanation": "過去形にすると、水をやらなかったのに花が育ったことになり、文の意味が逆になる。"}, {"text": "育って", "is_correct": false, "explanation": "て形は文末の否定過去を作れず、この文の述語として成り立たない。"}, {"text": "育ちます", "is_correct": false, "explanation": "丁寧な現在形になり、過去の否定の意味を表せないため、水をやらなかった結果という文脈と合わない。"}], "correct_form": "育たなかった", "base_form": "育つ", "form_label": "否定過去形", "sentence_index": 1, "explanations": {"育たなかった": "否定過去形で、水をやらなかった結果として花がうまく育たなかったという文脈に合う。", "育った": "過去形にすると、水をやらなかったのに花が育ったことになり、文の意味が逆になる。", "育って": "て形は文末の否定過去を作れず、この文の述語として成り立たない。", "育ちます": "丁寧な現在形になり、過去の否定の意味を表せないため、水をやらなかった結果という文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36806, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この畑では、雑草を一週間で育つ。", "corrected_sentence": "この畑では、雑草が一週間で育つ。", "error_description": "助詞の誤り。自動詞「育つ」は主語を「が」で示す。「を」を使うと目的語扱いになり、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "育った", "is_correct": true, "explanation": "過去形で、鉢の中で成長した苗という状態を名詞の前で修飾し、文に合う。"}, {"text": "育ちません", "is_correct": false, "explanation": "丁寧否定形は名詞を修飾できず、「育ちません苗」は成り立たない。"}, {"text": "育ったら", "is_correct": false, "explanation": "たら形は名詞を修飾できず、「育ったら苗」は文の中で成り立たない。"}, {"text": "育とう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、「育とう苗」は成り立たない。"}], "correct_form": "育った", "base_form": "育つ", "form_label": "過去形", "sentence_index": 7, "explanations": {"育った": "過去形で、鉢の中で成長した苗という状態を名詞の前で修飾し、文に合う。", "育ちません": "丁寧否定形は名詞を修飾できず、「育ちません苗」は成り立たない。", "育ったら": "たら形は名詞を修飾できず、「育ったら苗」は文の中で成り立たない。", "育とう": "意向形は名詞を修飾できず、「育とう苗」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。場所を表す格助詞で、森の中という場所で育ったことを示す。"}, {"text": "を", "is_correct": false, "explanation": "育つは自動詞なので、目的語のを は取れない。"}, {"text": "が", "is_correct": false, "explanation": "ここは主語の位置ではないので、が は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、場所で育つ意味にはならない。"}], "correct_answer": "で", "explanations": {"で": "正解。場所を表す格助詞で、森の中という場所で育ったことを示す。", "を": "育つは自動詞なので、目的語のを は取れない。", "が": "ここは主語の位置ではないので、が は合わない。", "へ": "方向を表すが、場所で育つ意味にはならない。"}, "error_tags": {"を": "目的語; 育つは自動詞", "が": "主語; ここは主語の位置ではない", "へ": "方向; 場所を表さない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "生物が成長して大きくなる。", "primary_collocate": null, "pronunciation": "そだつ", "ipa": "sodatsɯ", "syllable_count": 3, "sentences": [{"text": "小さかった赤ちゃんも、三年たてば立派に育つ。", "target_word": "育つ", "complexity_tier": "T3", "furigana": "小[ちい]さかった赤[あか]ちゃんも、三年[さんねん]たてば立派[りっぱ]に育[そだ]つ。", "sentence_source": "generated"}, {"text": "森の中で育ったので、彼は鳥の声にくわしい。", "target_word": "育った", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]で育[そだ]ったので、彼[かれ]は鳥[とり]の声[こえ]にくわしい。", "sentence_source": "generated"}, {"text": "魚の稚魚は、川で半年育ってから海へ向かう。", "target_word": "育って", "complexity_tier": "T3", "furigana": "魚[さかな]の稚魚[ちぎょ]は、川[かわ]で半年[はんとし]育[そだ]ってから海[うみ]へ向[む]かう。", "sentence_source": "generated"}, {"text": "子牛は牧場の草を食べて、丈夫に育った。", "target_word": "育った", "complexity_tier": "T3", "furigana": "子牛[こうし]は牧場[ぼくじょう]の草[くさ]を食[た]べて、丈夫[じょうぶ]に育[そだ]った。", "sentence_source": "generated"}, {"text": "田舎で育った母は、虫が少しも怖くないそうだ。", "target_word": "育った", "complexity_tier": "T3", "furigana": "田舎[いなか]で育[そだ]った母[はは]は、虫[むし]が少[すこ]しも怖[こわ]くないそうだ。", "sentence_source": "generated"}, {"text": "温室の中なら、バナナも日本で育ちます。", "target_word": "育ちます", "complexity_tier": "T3", "furigana": "温室[おんしつ]の中[なか]なら、バナナも日本[にほん]で育[そだ]ちます。", "sentence_source": "generated"}, {"text": "子猫は思ったより早く育って、もう抱けないほど重い。", "target_word": "育って", "complexity_tier": "T3", "furigana": "子猫[こねこ]は思[おも]ったより早[はや]く育[そだ]って、もう抱[だ]けないほど重[おも]い。", "sentence_source": "generated"}, {"text": "このカブトムシの幼虫は、土の中で一年かけて育つ。", "target_word": "育つ", "complexity_tier": "T3", "furigana": "このカブトムシの幼虫[ようちゅう]は、土[つち]の中[なか]で一年[いちねん]かけて育[そだ]つ。", "sentence_source": "generated"}, {"text": "弟は食べるのが好きで、背も高く育った。", "target_word": "育った", "complexity_tier": "T3", "furigana": "弟[おとうと]は食[た]べるのが好[す]きで、背[せ]も高[たか]く育[そだ]った。", "sentence_source": "generated"}, {"text": "毎日日が当たる窓辺で、ひまわりが太く育っている。", "target_word": "育っている", "complexity_tier": "T3", "furigana": "毎日[まいにち]日[ひ]が当[あ]たる窓辺[まどべ]で、ひまわりが太[ふと]く育[そだ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育つ", "label": "辞書形"}, {"form": "育ちます", "label": "丁寧形"}, {"form": "育った", "label": "過去形"}, {"form": "育って", "label": "て形"}, {"form": "育たない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "人や動物などの生物が成長して大人に近づく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "育つ", "is_correct": true, "explanation": "正解。赤ちゃんが成長して大人に近づく意味で、三年たてば立派になる文に合う。"}, {"text": "生える", "is_correct": false, "explanation": "草や歯などが新しく出てくる意味で、人が立派になる文には合わない。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "空中を移動する意味で、成長の文脈とは無関係。"}, {"text": "眠る", "is_correct": false, "explanation": "寝ている状態を表し、立派になるという変化とは合わない。"}], "explanations": {"育つ": "正解。赤ちゃんが成長して大人に近づく意味で、三年たてば立派になる文に合う。", "生える": "草や歯などが新しく出てくる意味で、人が立派になる文には合わない。", "飛ぶ": "空中を移動する意味で、成長の文脈とは無関係。", "眠る": "寝ている状態を表し、立派になるという変化とは合わない。"}, "sentence_index": 0, "correct_answer": "育つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に熱が育って、子どもが苦しそうだった。", "explanation": "ここは〈上がる〉の意味。体温が高くなることは〈上がる〉で、〈育つ〉は生物が大人に近づく意味なので合わない。"}, {"text": "鍋のお湯がぐらぐら育ってきた。", "explanation": "ここは〈沸く〉の意味。お湯が熱くなって泡立つことは〈沸く〉で、〈育つ〉は合わない。"}, {"text": "風船に息を入れると、どんどん育った。", "explanation": "ここは〈膨らむ〉の意味。空気を入れて体積が増えることは〈膨らむ〉で、〈育つ〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "育って", "is_correct": true, "explanation": "正解。て形で、早く育って、もう抱けないほど重いと続く。"}, {"text": "育てて", "is_correct": false, "explanation": "他動詞で、目的語がないので子猫が主語の文に合わない。"}, {"text": "枯れて", "is_correct": false, "explanation": "植物が衰える意味で、子猫の成長の文脈には合わない。"}, {"text": "光って", "is_correct": false, "explanation": "光る意味で、成長の文脈とは無関係。"}], "explanations": {"育って": "正解。て形で、早く育って、もう抱けないほど重いと続く。", "育てて": "他動詞で、目的語がないので子猫が主語の文に合わない。", "枯れて": "植物が衰える意味で、子猫の成長の文脈には合わない。", "光って": "光る意味で、成長の文脈とは無関係。"}, "sentence_index": 6, "correct_answer": "育って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前のビルが三年で育った。", "explanation": "ここは〈建つ〉の意味。建物ができあがることは〈建つ〉で、〈育つ〉は生物が大人に近づく意味なので合わない。"}, {"text": "この靴は使い込むほど足に育った。", "explanation": "ここは〈なじむ〉の意味。靴が足に合っていくことは〈なじむ〉で、〈育つ〉は合わない。"}, {"text": "貯金が三か月で育った。", "explanation": "ここは〈増える〉の意味。金額が多くなることは〈増える〉で、〈育つ〉は生物の成長に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "南の島では、バナナが一年で大きく育てる。", "corrected_sentence": "南の島では、バナナが一年で大きく育つ。", "error_description": "育てるは他動詞で、〜を育てるの形で使う。ここは主語がバナナ（が）で、自分から大きくなる意味なので、自動詞の育つが正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "育った", "is_correct": true, "explanation": "正解。過去形で、森で育った経験を表し、文の内容に合う。"}, {"text": "育つ", "is_correct": false, "explanation": "辞書形で、過去の経験を述べる文には時制が合わない。"}, {"text": "育って", "is_correct": false, "explanation": "て形は文を終えられず、ので に続く形として不自然になる。"}, {"text": "育ちます", "is_correct": false, "explanation": "丁寧形は、普通体の文の中では合わない。"}], "correct_form": "育った", "base_form": "育つ", "form_label": "過去形", "sentence_index": 1, "explanations": {"育った": "正解。過去形で、森で育った経験を表し、文の内容に合う。", "育つ": "辞書形で、過去の経験を述べる文には時制が合わない。", "育って": "て形は文を終えられず、ので に続く形として不自然になる。", "育ちます": "丁寧形は、普通体の文の中では合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36807, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の終わりには、ひまわりがずいぶん育たった。", "corrected_sentence": "夏の終わりには、ひまわりがずいぶん育った。", "error_description": "育つの過去形は育った。育たったは活用の形として存在しないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "育つ", "is_correct": true, "explanation": "正解。辞書形で、一年かけて育つという習性を述べる文に合う。"}, {"text": "育たない", "is_correct": false, "explanation": "否定形で、育つという内容と反対になり文と合わない。"}, {"text": "育ちました", "is_correct": false, "explanation": "丁寧過去形で、普通体の文と合わない。"}, {"text": "育ったら", "is_correct": false, "explanation": "たら形で仮定の流れになり、事実を述べる文と合わない。"}], "correct_form": "育つ", "base_form": "育つ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"育つ": "正解。辞書形で、一年かけて育つという習性を述べる文に合う。", "育たない": "否定形で、育つという内容と反対になり文と合わない。", "育ちました": "丁寧過去形で、普通体の文と合わない。", "育ったら": "たら形で仮定の流れになり、事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。主語を表す格助詞で、人が減るの主語になる。"}, {"text": "を", "is_correct": false, "explanation": "減るは自動詞なので、目的語のを は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、減る変化の主語の位置ではない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すが、減るの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。主語を表す格助詞で、人が減るの主語になる。", "を": "減るは自動詞なので、目的語のを は取れない。", "へ": "方向を表すが、減る変化の主語の位置ではない。", "で": "場所や手段を表すが、減るの主語にはならない。"}, "error_tags": {"を": "目的語; 減るは自動詞", "へ": "方向; 変化の主語の位置ではない", "で": "手段・場所; 主語にならない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増える", "is_correct": true, "explanation": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。"}, {"text": "歩く", "is_correct": false, "explanation": "足で進む動作で、数量の反対にはならない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝ている状態を表し、数量の増減とは関係しない。"}, {"text": "届く", "is_correct": false, "explanation": "物や知らせが着く意味で、対義語ではない。"}], "correct_answer": "増える", "explanations": {"増える": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。", "歩く": "足で進む動作で、数量の反対にはならない。", "眠る": "寝ている状態を表し、数量の増減とは関係しない。", "届く": "物や知らせが着く意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。主語を表す格助詞で、ケーキが減っていないの主語になる。"}, {"text": "と", "is_correct": false, "explanation": "相手を表すが、減るの主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、比べる対象がない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、ケーキの量の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。主語を表す格助詞で、ケーキが減っていないの主語になる。", "と": "相手を表すが、減るの主語にはならない。", "より": "比較を表すが、比べる対象がない。", "から": "起点を表すが、ケーキの量の主語にはならない。"}, "error_tags": {"と": "相手; 減るの主語にならない", "より": "比較; 比べる要素がない", "から": "起点; 主語を表さない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増える", "is_correct": true, "explanation": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "空を移動する意味で、数量の反対にはならない。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く意味で、数量の対義語ではない。"}, {"text": "光る", "is_correct": false, "explanation": "光を出す意味で、数量の反対にはならない。"}], "correct_answer": "増える", "explanations": {"増える": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。", "飛ぶ": "空を移動する意味で、数量の反対にはならない。", "咲く": "花が開く意味で、数量の対義語ではない。", "光る": "光を出す意味で、数量の反対にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが少なくなることです。", "primary_collocate": null, "pronunciation": "へる", "ipa": "heɾɯ", "syllable_count": 2, "sentences": [{"text": "毎日歩いているのに、体重がなかなか減らない。", "target_word": "減らない", "complexity_tier": "T3", "furigana": "毎日[まいにち]歩[ある]いているのに、体重[たいじゅう]がなかなか減[へ]らない。", "sentence_source": "generated"}, {"text": "冬になると、公園を訪れる人が減る。", "target_word": "減る", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、公園[こうえん]を訪[おとず]れる人[ひと]が減[へ]る。", "sentence_source": "generated"}, {"text": "財布のお金が、買い物のたびに減っていく。", "target_word": "減っていく", "complexity_tier": "T3", "furigana": "財布[さいふ]のお金[かね]が、買[か]い物[もの]のたびに減[へ]っていく。", "sentence_source": "generated"}, {"text": "最近は、駅前の本屋が減ってしまった。", "target_word": "減って", "complexity_tier": "T3", "furigana": "最近[さいきん]は、駅前[えきまえ]の本屋[ほんや]が減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "雨が降らず、ダムの水が少しずつ減っている。", "target_word": "減っている", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らず、ダムの水[みず]が少[すこ]しずつ減[へ]っている。", "sentence_source": "generated"}, {"text": "夜ふかしをやめてから、疲れて休む日が減りました。", "target_word": "減りました", "complexity_tier": "T3", "furigana": "夜[よる]ふかしをやめてから、疲[つか]れて休[やす]む日[ひ]が減[へ]りました。", "sentence_source": "generated"}, {"text": "子どもが減ったので、この小学校は来年なくなる。", "target_word": "減った", "complexity_tier": "T3", "furigana": "子[こ]どもが減[へ]ったので、この小学校[しょうがっこう]は来年[らいねん]なくなる。", "sentence_source": "generated"}, {"text": "皆でさっき食べたのに、皿のケーキが全然減っていない。", "target_word": "減っていない", "complexity_tier": "T3", "furigana": "皆[みな]でさっき食[た]べたのに、皿[さら]のケーキが全然[ぜんぜん]減[へ]っていない。", "sentence_source": "generated"}, {"text": "車を使う人が減れば、町の空気はきれいになる。", "target_word": "減れば", "complexity_tier": "T3", "furigana": "車[くるま]を使[つか]う人[ひと]が減[へ]れば、町[まち]の空気[くうき]はきれいになる。", "sentence_source": "generated"}, {"text": "ガソリンが減ってきたので、スタンドに寄った。", "target_word": "減ってきた", "complexity_tier": "T3", "furigana": "ガソリンが減[へ]ってきたので、スタンドに寄[よ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "減る", "label": "辞書形"}, {"form": "減ります", "label": "丁寧形"}, {"form": "減った", "label": "過去形"}, {"form": "減って", "label": "て形"}, {"form": "減らない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "数や量が前より少なくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "減らない", "is_correct": true, "explanation": "正解。否定形で、歩いているのに体重がなかなか変わらないという文脈に合う。"}, {"text": "減らす", "is_correct": false, "explanation": "他動詞で、目的語を取るので体重が主語の文では続かない。"}, {"text": "減って", "is_correct": false, "explanation": "て形は文を終えられず、この文の述語にならない。"}, {"text": "減らず", "is_correct": false, "explanation": "連用中止の形で、文を終えられず述語にならない。"}], "explanations": {"減らない": "正解。否定形で、歩いているのに体重がなかなか変わらないという文脈に合う。", "減らす": "他動詞で、目的語を取るので体重が主語の文では続かない。", "減って": "て形は文を終えられず、この文の述語にならない。", "減らず": "連用中止の形で、文を終えられず述語にならない。"}, "sentence_index": 0, "correct_answer": "減らない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガソリンの値段が減った。", "explanation": "ここは〈下がる〉の意味。値段が低くなることは〈下がる〉で、〈減る〉は個数や量に使うので合わない。"}, {"text": "セーターを洗ったら、袖が減った。", "explanation": "ここは〈縮む〉の意味。洗って大きさが小さくなることは〈縮む〉で、〈減る〉は合わない。"}, {"text": "期末試験のあと、成績が減ってしまった。", "explanation": "ここは〈落ちる〉の意味。評価が下がることは〈落ちる〉で、〈減る〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "減った", "is_correct": true, "explanation": "正解。過去形で、子どもが少なくなった結果を述べる文に合う。"}, {"text": "増えた", "is_correct": false, "explanation": "増える意味で、子どもが減って小学校がなくなるという流れと反対になる。"}, {"text": "増えて", "is_correct": false, "explanation": "て形は文を完成させず、内容も合わない。"}, {"text": "増やした", "is_correct": false, "explanation": "他動詞で、子どもを増やす意味になり、文の流れと合わない。"}], "explanations": {"減った": "正解。過去形で、子どもが少なくなった結果を述べる文に合う。", "増えた": "増える意味で、子どもが減って小学校がなくなるという流れと反対になる。", "増えて": "て形は文を完成させず、内容も合わない。", "増やした": "他動詞で、子どもを増やす意味になり、文の流れと合わない。"}, "sentence_index": 6, "correct_answer": "減った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒さで、手の感覚が減ってきた。", "explanation": "ここは〈鈍る〉の意味。感覚が弱くなることは〈鈍る〉で、〈減る〉は数や量を表すので合わない。"}, {"text": "ろうそくの炎が減って、部屋が暗くなった。", "explanation": "ここは〈弱まる〉の意味。炎が小さく弱くなることは〈弱まる〉で、〈減る〉は数や量を表すので合わない。"}, {"text": "健康が減ってきたので、病院に行った。", "explanation": "ここは〈損なう〉の意味。体の調子が悪くなることは〈損なう〉で、〈減る〉は数や量に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は、若い人を年々減っている。", "corrected_sentence": "この町は、若い人が年々減っている。", "error_description": "減るは自動詞で、目的語を取らない。主語の若い人には が を使うので、を は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "減る", "is_correct": true, "explanation": "正解。辞書形で、冬になると起こる習慣的な変化を表す。"}, {"text": "減って", "is_correct": false, "explanation": "て形は文を終えられず、この文の述語にならない。"}, {"text": "減らず", "is_correct": false, "explanation": "連用中止の形で、文を終えられず述語にならない。"}, {"text": "減らない", "is_correct": false, "explanation": "否定形で、人が減るという内容と反対になる。"}], "correct_form": "減る", "base_form": "減る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"減る": "正解。辞書形で、冬になると起こる習慣的な変化を表す。", "減って": "て形は文を終えられず、この文の述語にならない。", "減らず": "連用中止の形で、文を終えられず述語にならない。", "減らない": "否定形で、人が減るという内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36808, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダイエットを続けて、体重がかなり減らした。", "corrected_sentence": "ダイエットを続けて、体重がかなり減った。", "error_description": "減らすは他動詞で、〜を減らすの形で使う。体重が主語の文なので、自動詞の減るの過去形が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "減っていない", "is_correct": true, "explanation": "正解。〜ていない形で、ケーキが全然減っていない状況を正しく表す。"}, {"text": "減った", "is_correct": false, "explanation": "全然は否定と組むので、肯定の過去形の減ったは文として不自然になる。"}, {"text": "減れば", "is_correct": false, "explanation": "仮定形で、文の述語にならない。"}, {"text": "減りました", "is_correct": false, "explanation": "丁寧過去形で、普通体の文と合わない。"}], "correct_form": "減っていない", "base_form": "減る", "form_label": "〜ていない形", "sentence_index": 7, "explanations": {"減っていない": "正解。〜ていない形で、ケーキが全然減っていない状況を正しく表す。", "減った": "全然は否定と組むので、肯定の過去形の減ったは文として不自然になる。", "減れば": "仮定形で、文の述語にならない。", "減りました": "丁寧過去形で、普通体の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増える", "is_correct": true, "explanation": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水の中を進む動作で、数量の反対にはならない。"}, {"text": "届く", "is_correct": false, "explanation": "物や知らせが着く意味で、対義語ではない。"}, {"text": "光る", "is_correct": false, "explanation": "光を出す意味で、数量の対義語ではない。"}], "correct_answer": "増える", "explanations": {"増える": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。", "泳ぐ": "水の中を進む動作で、数量の反対にはならない。", "届く": "物や知らせが着く意味で、対義語ではない。", "光る": "光を出す意味で、数量の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。主語を表す格助詞で、痛みが減りましたの主語になる。"}, {"text": "と", "is_correct": false, "explanation": "相手を表すが、痛みの主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、比べる対象がない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、痛みが減る主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "正解。主語を表す格助詞で、痛みが減りましたの主語になる。", "と": "相手を表すが、痛みの主語にはならない。", "より": "比較を表すが、比べる対象がない。", "から": "起点を表すが、痛みが減る主語にはならない。"}, "error_tags": {"と": "相手; 痛みの主語にならない", "より": "比較; 比べる要素がない", "から": "起点; 主語を表さない"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増える", "is_correct": true, "explanation": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。"}, {"text": "歩く", "is_correct": false, "explanation": "足で進む動作で、数量の反対にはならない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝ている状態を表し、数量の増減とは関係しない。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "空を移動する意味で、数量の反対ではない。"}], "correct_answer": "増える", "explanations": {"増える": "正解。対義語。数や量が多くなる意味で、減る（少なくなる）と反対。", "歩く": "足で進む動作で、数量の反対にはならない。", "眠る": "寝ている状態を表し、数量の増減とは関係しない。", "飛ぶ": "空を移動する意味で、数量の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "数量や程度が少なくなる。", "primary_collocate": null, "pronunciation": "へる", "ipa": "heɾɯ", "syllable_count": 2, "sentences": [{"text": "最近、駅前の店のお客さんが減っています。", "target_word": "減っています", "complexity_tier": "T3", "furigana": "最近[さいきん]、駅前[えきまえ]の店[みせ]のお客[きゃく]さんが減[へ]っています。", "sentence_source": "generated"}, {"text": "運動を始めてから、体重が少しずつ減ってきた。", "target_word": "減ってきた", "complexity_tier": "T3", "furigana": "運動[うんどう]を始[はじ]めてから、体重[たいじゅう]が少[すこ]しずつ減[へ]ってきた。", "sentence_source": "generated"}, {"text": "雨が降らないので、川の水が減ってしまった。", "target_word": "減ってしまった", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らないので、川[かわ]の水[みず]が減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "子どもが減って、この町の小学校は閉まることになった。", "target_word": "減って", "complexity_tier": "T3", "furigana": "子[こ]どもが減[へ]って、この町[まち]の小学校[しょうがっこう]は閉[し]まることになった。", "sentence_source": "generated"}, {"text": "毎日飲んでいたら、冷蔵庫のジュースがすぐに減った。", "target_word": "減った", "complexity_tier": "T3", "furigana": "毎日[まいにち]飲[の]んでいたら、冷蔵庫[れいぞうこ]のジュースがすぐに減[へ]った。", "sentence_source": "generated"}, {"text": "去年より雨の量が減ったので、畑の水やりが少なくなった。", "target_word": "減った", "complexity_tier": "T3", "furigana": "去年[きょねん]より雨[あめ]の量[りょう]が減[へ]ったので、畑[はたけ]の水[みず]やりが少[すく]なくなった。", "sentence_source": "generated"}, {"text": "給料が減ったので、旅行には行けなくなった。", "target_word": "減った", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が減[へ]ったので、旅行[りょこう]には行[い]けなくなった。", "sentence_source": "generated"}, {"text": "薬を飲み続けたら、痛みが減りました。", "target_word": "減りました", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]み続[つづ]けたら、痛[いた]みが減[へ]りました。", "sentence_source": "generated"}, {"text": "車が減れば、この道ももっと静かになるだろう。", "target_word": "減れば", "complexity_tier": "T3", "furigana": "車[くるま]が減[へ]れば、この道[みち]ももっと静[しず]かになるだろう。", "sentence_source": "generated"}, {"text": "夏休みが終わると、公園で遊ぶ子どもが減る。", "target_word": "減る", "complexity_tier": "T3", "furigana": "夏休[なつやす]みが終[お]わると、公園[こうえん]で遊[あそ]ぶ子[こ]どもが減[へ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "減る", "label": "終止形"}, {"form": "減った", "label": "過去形"}, {"form": "減って", "label": "て形"}, {"form": "減らない", "label": "否定形"}, {"form": "減れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "数や量、程度が少なくなる変化を表す自動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "減っています", "is_correct": true, "explanation": "正解。〜ています形で、お客さんが少なくなっている現在の様子を表す。"}, {"text": "減らしています", "is_correct": false, "explanation": "他動詞で、目的語を取るのでお客さんが主語の文では続かない。"}, {"text": "歩いています", "is_correct": false, "explanation": "歩く意味で、店の客数の変化とは無関係。"}, {"text": "飛んでいます", "is_correct": false, "explanation": "飛ぶ意味で、客数の変化の文脈に合わない。"}], "explanations": {"減っています": "正解。〜ています形で、お客さんが少なくなっている現在の様子を表す。", "減らしています": "他動詞で、目的語を取るのでお客さんが主語の文では続かない。", "歩いています": "歩く意味で、店の客数の変化とは無関係。", "飛んでいます": "飛ぶ意味で、客数の変化の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "減っています"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の日差しで、カーテンの色が減っていった。", "explanation": "ここは〈褪せる〉の意味。色が薄くなることは〈褪せる〉で、〈減る〉は数や量に使うので合わない。"}, {"text": "無理な運動で、健康が減ってしまった。", "explanation": "ここは〈損なう〉の意味。体の状態が悪くなることは〈損なう〉で、〈減る〉は合わない。"}, {"text": "洗濯したら、セーターの袖が減ってしまった。", "explanation": "ここは〈縮む〉の意味。洗って小さくなることは〈縮む〉で、〈減る〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "減った", "is_correct": true, "explanation": "正解。過去形で、給料が少なくなった結果を述べる文に合う。"}, {"text": "増やした", "is_correct": false, "explanation": "他動詞で、給料を増やす意味になり、旅行に行けない理由と合わない。"}, {"text": "増えた", "is_correct": false, "explanation": "増える意味で、旅行に行けなくなる理由と反対になる。"}, {"text": "増やして", "is_correct": false, "explanation": "て形は文を終えられず、この文の述語にならない。"}], "explanations": {"減った": "正解。過去形で、給料が少なくなった結果を述べる文に合う。", "増やした": "他動詞で、給料を増やす意味になり、旅行に行けない理由と合わない。", "増えた": "増える意味で、旅行に行けなくなる理由と反対になる。", "増やして": "て形は文を終えられず、この文の述語にならない。"}, "sentence_index": 6, "correct_answer": "減った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みが終わると、子どもの夢が減る。", "explanation": "ここは〈しぼむ〉の意味。夢が小さくなることは〈しぼむ〉で、〈減る〉は数や量を表すので合わない。"}, {"text": "この言葉は、使うほど意味が減っていく。", "explanation": "ここは〈薄れる〉の意味。意味が弱くなっていくことは〈薄れる〉で、〈減る〉は合わない。"}, {"text": "舞台の幕が、ゆっくりと減っていった。", "explanation": "ここは〈上がる〉の意味。幕が上がって開くことは〈上がる〉で、〈減る〉は数や量を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日使っていたら、電池にすぐに減った。", "corrected_sentence": "毎日使っていたら、電池がすぐに減った。", "error_description": "減るは自動詞で、主語の電池には が を使う。に は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "減ってきた", "is_correct": true, "explanation": "正解。〜てきた形で、体重が少しずつ変わってきた経過を表す。"}, {"text": "減らして", "is_correct": false, "explanation": "他動詞のて形で、体重が主語の文では目的語が必要になり合わない。"}, {"text": "減れば", "is_correct": false, "explanation": "仮定形で、文の述語にならない。"}, {"text": "減らない", "is_correct": false, "explanation": "否定形で、体重が減ったという内容と反対になる。"}], "correct_form": "減ってきた", "base_form": "減る", "form_label": "〜てきた形", "sentence_index": 1, "explanations": {"減ってきた": "正解。〜てきた形で、体重が少しずつ変わってきた経過を表す。", "減らして": "他動詞のて形で、体重が主語の文では目的語が必要になり合わない。", "減れば": "仮定形で、文の述語にならない。", "減らない": "否定形で、体重が減ったという内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36809, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が続いて、川の水をずいぶん減った。", "corrected_sentence": "雨が続いて、川の水がずいぶん減った。", "error_description": "減るは自動詞で、主語の川の水には が を使う。を は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "減りました", "is_correct": true, "explanation": "正解。丁寧過去形で、薬を飲んで痛みが少なくなった事実を述べる文に合う。"}, {"text": "減って", "is_correct": false, "explanation": "て形は文を終えられず、ここでは述語にならない。"}, {"text": "減らず", "is_correct": false, "explanation": "連用中止の形で、文を終えられず述語にならない。"}, {"text": "減っていない", "is_correct": false, "explanation": "否定形で、痛みが減ったという内容と反対になる。"}], "correct_form": "減りました", "base_form": "減る", "form_label": "丁寧過去形", "sentence_index": 7, "explanations": {"減りました": "正解。丁寧過去形で、薬を飲んで痛みが少なくなった事実を述べる文に合う。", "減って": "て形は文を終えられず、ここでは述語にならない。", "減らず": "連用中止の形で、文を終えられず述語にならない。", "減っていない": "否定形で、痛みが減ったという内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
