INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36810, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "じぶんで ものをつくる ことです。", "primary_collocate": null, "pronunciation": "でぃーあいわい", "ipa": "diːaiwai", "syllable_count": 6, "sentences": [{"text": "休日は、棚を作る DIY に夢中になっている。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は、棚[たな]を作[つく]る DIY に夢中[むちゅう]になっている。", "sentence_source": "generated"}, {"text": "父は DIY が好きで、庭に小さな小屋を建てた。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "父[ちち]は DIY が好[す]きで、庭[にわ]に小[ちい]さな小屋[こや]を建[た]てた。", "sentence_source": "generated"}, {"text": "DIY を始めるなら、まずは簡単な本棚から作るといい。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "DIY を始[はじ]めるなら、まずは簡単[かんたん]な本棚[ほんだな]から作[つく]るといい。", "sentence_source": "generated"}, {"text": "買うと高いので、机は DIY で作ることにした。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "買[か]うと高[たか]いので、机[つくえ]は DIY で作[つく]ることにした。", "sentence_source": "generated"}, {"text": "この店には、DIY に使う木材や工具がそろっている。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "この店[みせ]には、DIY に使[つか]う木材[もくざい]や工具[こうぐ]がそろっている。", "sentence_source": "generated"}, {"text": "初めての DIY だったが、思ったよりきれいに仕上がった。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "初[はじ]めての DIY だったが、思[おも]ったよりきれいに仕上[しあ]がった。", "sentence_source": "generated"}, {"text": "妻と DIY で壁を白く塗って、部屋の雰囲気を変えた。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "妻[つま]と DIY で壁[かべ]を白[しろ]く塗[ぬ]って、部屋[へや]の雰囲気[ふんいき]を変[か]えた。", "sentence_source": "generated"}, {"text": "DIY の動画を見ながら、小さな椅子を作った。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "DIY の動画[どうが]を見[み]ながら、小[ちい]さな椅子[いす]を作[つく]った。", "sentence_source": "generated"}, {"text": "最近は DIY が人気で、道具をそろえる人が増えている。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "最近[さいきん]は DIY が人気[にんき]で、道具[どうぐ]をそろえる人[ひと]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "週末の DIY で、ベランダに木の床を敷いた。", "target_word": "DIY", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]の DIY で、ベランダに木[き]の床[ゆか]を敷[し]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "DIY", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "業者に頼まず、自分で物を作ったり直したりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36810, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "DIY", "is_correct": true, "explanation": "自分で棚などを作る活動を指し、「棚を作るDIYに夢中」と文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩く活動で、「棚を作る散歩」とはならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "休む行為で、棚を作ることとつながらないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "部屋などをきれいにすることで、「棚を作る掃除」とは言わない。"}], "explanations": {"DIY": "自分で棚などを作る活動を指し、「棚を作るDIYに夢中」と文脈に合う。", "散歩": "歩く活動で、「棚を作る散歩」とはならない。", "昼寝": "休む行為で、棚を作ることとつながらないので合わない。", "掃除": "部屋などをきれいにすることで、「棚を作る掃除」とは言わない。"}, "sentence_index": 0, "correct_answer": "DIY"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母が DIY のケーキを焼いてくれた。", "explanation": "ここは〈手作り〉（自分で作った料理や品）の意味。DIY は家具や家を自分で作る・直すことで、食べ物には使わない。"}, {"text": "壊れた蛇口を DIY してもらった。", "explanation": "DIY は自分で作る・直す行為なので、「してもらった」（人に頼んだ）と矛盾する。"}, {"text": "パーティーで DIY を務めた。", "explanation": "ここは〈DJ〉（音楽を流す人）の意味。DIY は自分で作る活動で、役割や職業を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36810, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "DIY", "is_correct": true, "explanation": "自分で物を作って部屋の雰囲気を変える活動を指し、「妻とDIYで壁を塗る」と合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う家事で、壁を白く塗る手段にはならない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為で、壁を塗る方法としては成り立たない。"}, {"text": "散髪", "is_correct": false, "explanation": "髪を切ることで、壁を塗る手段として合わない。"}], "explanations": {"DIY": "自分で物を作って部屋の雰囲気を変える活動を指し、「妻とDIYで壁を塗る」と合う。", "洗濯": "衣類を洗う家事で、壁を白く塗る手段にはならない。", "読書": "本を読む行為で、壁を塗る方法としては成り立たない。", "散髪": "髪を切ることで、壁を塗る手段として合わない。"}, "sentence_index": 6, "correct_answer": "DIY"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は DIY で、公園のごみ拾いをした。", "explanation": "ここは〈ボランティア〉（無償で社会のために活動すること）の意味。DIY は自分で物を作ることで、社会活動の意味では使わない。"}, {"text": "毎朝、DIY で公園を走った。", "explanation": "ここは〈ジョギング〉（健康のために走ること）の意味。DIY は自分で物を作ることで、走る運動の意味では使わない。"}, {"text": "DIY に頼んで、家の床を張り替えた。", "explanation": "ここは〈大工〉（職人）の意味。DIY は人を指す語ではなく、頼む相手にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36810, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、DIY を本棚を作るつもりだ。", "corrected_sentence": "週末は、DIY で本棚を作るつもりだ。", "error_description": "正しくは「DIY で」（手段）。「を」にすると目的語が二つ重なり不自然になる。誤りは「で」を「を」にした一か所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36810, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の手入れは、DIY に行うことにした。", "corrected_sentence": "庭の手入れは、DIY で行うことにした。", "error_description": "正しくは「DIY で行う」（手段）。「に」では「行う」の手段が示せず不自然になる。誤りは「で」を「に」にした一か所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
