INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「決まっている」の主語を示す「が」で、「体裁が細かく決まっている」と自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞なので、「体裁の細かく決まっている」では動詞に続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は「一緒に」を表すので、「体裁と細かく決まっている」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「体裁へ細かく決まっている」では主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「決まっている」の主語を示す「が」で、「体裁が細かく決まっている」と自然。", "の": "「の」は名詞をつなぐ助詞なので、「体裁の細かく決まっている」では動詞に続かない。", "と": "「と」は「一緒に」を表すので、「体裁と細かく決まっている」では意味が通らない。", "へ": "「へ」は方向を表すので、「体裁へ細かく決まっている」では主語にならない。"}, "error_tags": {"の": "possessive", "と": "companion", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの、みた目やかたちのこと。", "primary_collocate": null, "pronunciation": "ていさい", "ipa": "teisai", "syllable_count": 4, "sentences": [{"text": "資料の体裁を整えてから、先生に提出した。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "資料[しりょう]の体裁[ていさい]を整[ととの]えてから、先生[せんせい]に提出[ていしゅつ]した。", "sentence_source": "generated"}, {"text": "この本は、内容はよいが体裁が古くて読みにくい。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "この本[ほん]は、内容[ないよう]はよいが体裁[ていさい]が古[ふる]くて読[よ]みにくい。", "sentence_source": "generated"}, {"text": "手紙は体裁よりも、気持ちが伝わることが大切だ。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "手紙[てがみ]は体裁[ていさい]よりも、気持[きも]ちが伝[つた]わることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "同じ体裁にそろえるため、全部の表の文字の大きさを直した。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "同[おな]じ体裁[ていさい]にそろえるため、全部[ぜんぶ]の表[ひょう]の文字[もじ]の大[おお]きさを直[なお]した。", "sentence_source": "generated"}, {"text": "報告書の体裁は、会社が決めた形に合わせる決まりだ。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の体裁[ていさい]は、会社[かいしゃ]が決[き]めた形[かたち]に合[あ]わせる決[き]まりだ。", "sentence_source": "generated"}, {"text": "見出しを太くして、文書の体裁をよくした。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "見出[みだ]しを太[ふと]くして、文書[ぶんしょ]の体裁[ていさい]をよくした。", "sentence_source": "generated"}, {"text": "体裁のよい箱に入れたので、贈り物らしく見える。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "体裁[ていさい]のよい箱[はこ]に入[い]れたので、贈[おく]り物[もの]らしく見[み]える。", "sentence_source": "generated"}, {"text": "論文は、題名や見出しの置き方など、体裁が細かく決まっている。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "論文[ろんぶん]は、題名[だいめい]や見出[みだ]しの置[お]き方[かた]など、体裁[ていさい]が細[こま]かく決[き]まっている。", "sentence_source": "generated"}, {"text": "急いで作ったため、パンフレットは体裁が乱れていた。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "急[いそ]いで作[つく]ったため、パンフレットは体裁[ていさい]が乱[みだ]れていた。", "sentence_source": "generated"}, {"text": "内容は同じでも、体裁が変わると別の本のように見える。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "内容[ないよう]は同[おな]じでも、体裁[ていさい]が変[か]わると別[べつ]の本[ほん]のように見[み]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体裁", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "文書・本・物の見た目や形式上の整い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体裁", "is_correct": true, "explanation": "文書の見た目や形式を表し、「資料の体裁を整える」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、資料を整える対象にはならない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝ている時の呼吸音で、資料とは結びつかないので合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "身につける装飾品で、資料を整える対象にはならない。"}], "explanations": {"体裁": "文書の見た目や形式を表し、「資料の体裁を整える」と自然に続く。", "天気": "空模様のことで、資料を整える対象にはならない。", "寝息": "寝ている時の呼吸音で、資料とは結びつかないので合わない。", "指輪": "身につける装飾品で、資料を整える対象にはならない。"}, "sentence_index": 0, "correct_answer": "体裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は体裁が明るくて、いつも周りを笑わせる。", "explanation": "ここは〈性格〉の意味。体裁は見た目やかたちのことで、人の性質は表さないので合わない。"}, {"text": "夏に向けて、体裁を引き締めている。", "explanation": "ここは〈体型〉（体の形）の意味。体裁は物や文書の見た目を指し、人の体つきには使わない。"}, {"text": "熱が出て、体裁が三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。体裁は数値で測れる体の状態ではなく、見た目や形式を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体裁", "is_correct": true, "explanation": "見た目の整い方を表し、「体裁のよい箱」と自然に続く。"}, {"text": "重さ", "is_correct": false, "explanation": "重さはよい・悪いで形容する語ではなく、「重さのよい箱」とは言わない。"}, {"text": "深さ", "is_correct": false, "explanation": "深さを表す語で、「深さのよい箱」は不自然で合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさで、箱の見た目を表す語として合わない。"}], "explanations": {"体裁": "見た目の整い方を表し、「体裁のよい箱」と自然に続く。", "重さ": "重さはよい・悪いで形容する語ではなく、「重さのよい箱」とは言わない。", "深さ": "深さを表す語で、「深さのよい箱」は不自然で合わない。", "音量": "音の大きさで、箱の見た目を表す語として合わない。"}, "sentence_index": 6, "correct_answer": "体裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝走って、体裁を上げた。", "explanation": "ここは〈体力〉（運動に耐える力）の意味。体裁は見た目やかたちのことで、力や持久力を表さないので合わない。"}, {"text": "初めての体裁で、少し緊張した。", "explanation": "ここは〈体験〉の意味。体裁は見た目や形式を表し、出来事を指さない。"}, {"text": "毎朝、体裁を量って記録している。", "explanation": "ここは〈体重〉の意味。体裁は数値で量れるものではなく、見た目や形式を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい雑誌の体裁が変えることにした。", "corrected_sentence": "新しい雑誌の体裁を変えることにした。", "error_description": "正しくは「体裁を変える」。「が」にすると「変える」の目的語がなくなり、文が成り立たない。誤りは「を」を「が」にした一か所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36812, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表紙の体裁を地味なので、本屋で目立たない。", "corrected_sentence": "表紙の体裁が地味なので、本屋で目立たない。", "error_description": "正しくは「体裁が地味」の「が」。「を」にすると「地味」の主語がなくなり、文が成り立たない。誤りは「が」を「を」にした一か所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「体裁より中身」の比較の形で、体裁と中身を比べる文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、比べる文脈にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「体裁を中身を」と目的語が重なり不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、中身を大切にする比較の意味にはならない。"}], "correct_answer": "より", "explanations": {"より": "「体裁より中身」の比較の形で、体裁と中身を比べる文になる。", "へ": "方向を表す助詞で、比べる文脈にならない。", "を": "「を」は目的語を示すが、「体裁を中身を」と目的語が重なり不自然。", "から": "起点を表し、中身を大切にする比較の意味にはならない。"}, "error_tags": {"へ": "方向の誤り", "から": "起点の誤り", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の外見や形式。また、世間に対する体面や見栄。", "primary_collocate": null, "pronunciation": "ていさい", "ipa": "teisai", "syllable_count": 4, "sentences": [{"text": "体裁ばかり気にして、本当に言いたいことを言えなかった。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "体裁[ていさい]ばかり気[き]にして、本当[ほんとう]に言[い]いたいことを言[い]えなかった。", "sentence_source": "generated"}, {"text": "近所の目があるので、体裁が悪くて助けを頼めない。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "近所[きんじょ]の目[め]があるので、体裁[ていさい]が悪[わる]くて助[たす]けを頼[たの]めない。", "sentence_source": "generated"}, {"text": "彼は体裁を取りつくろうために、高い時計を買った。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "彼[かれ]は体裁[ていさい]を取[と]りつくろうために、高[たか]い時計[とけい]を買[か]った。", "sentence_source": "generated"}, {"text": "会議に遅れて入るのは体裁が悪いので、早めに家を出た。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "会議[かいぎ]に遅[おく]れて入[はい]るのは体裁[ていさい]が悪[わる]いので、早[はや]めに家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "体裁を気にしないで、困ったときは人に頼ればいい。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "体裁[ていさい]を気[き]にしないで、困[こま]ったときは人[ひと]に頼[たよ]ればいい。", "sentence_source": "generated"}, {"text": "友人の前で転んで、体裁が悪かった。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の前[まえ]で転[ころ]んで、体裁[ていさい]が悪[わる]かった。", "sentence_source": "generated"}, {"text": "見舞いに行くのに手ぶらでは体裁が悪いので、花を買った。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "見舞[みま]いに行[い]くのに手[て]ぶらでは体裁[ていさい]が悪[わる]いので、花[はな]を買[か]った。", "sentence_source": "generated"}, {"text": "彼女は体裁より中身を大切にする人だ。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は体裁[ていさい]より中身[なかみ]を大切[たいせつ]にする人[ひと]だ。", "sentence_source": "generated"}, {"text": "体裁だけ立派でも、中身がなければ意味がない。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "体裁[ていさい]だけ立派[りっぱ]でも、中身[なかみ]がなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "父は世間への体裁を考えて、派手な結婚式を開いた。", "target_word": "体裁", "complexity_tier": "T3", "furigana": "父[ちち]は世間[せけん]への体裁[ていさい]を考[かんが]えて、派手[はで]な結婚式[けっこんしき]を開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体裁", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "世間に対する体面・見栄、人からどう見られるか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e61b9b9-2b71-463a-b7c3-934bb8c70858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体裁", "is_correct": true, "explanation": "世間からの体面の意味で、「体裁ばかり気にして」と自然につながる。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱を気にする話は成り立たず、体面の文脈に合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団ばかり気にする話は不自然で、体面の文脈に合わない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムばかり気にする話は不自然で、体面の文脈に合わない。"}], "explanations": {"体裁": "世間からの体面の意味で、「体裁ばかり気にして」と自然につながる。", "電柱": "電柱を気にする話は成り立たず、体面の文脈に合わない。", "座布団": "座布団ばかり気にする話は不自然で、体面の文脈に合わない。", "消しゴム": "消しゴムばかり気にする話は不自然で、体面の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "体裁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先月の不祥事で、会社の体裁が町じゅうに広まった。", "explanation": "ここは〈評判〉の意味。体裁は体面や見栄を表すので、噂が広まるという内容には使わない。"}, {"text": "彼は体裁が強く、誰にも負けない。", "explanation": "ここは〈体力〉の意味。体裁は体面を表すので、体力の有無を言う場面では使わない。"}, {"text": "この部屋は体裁が広く、家具を置いても余裕がある。", "explanation": "ここは〈面積〉の意味。体裁は体面を表すので、部屋の大きさを言うのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体裁", "is_correct": true, "explanation": "体面の意味で、手ぶらでは体面が保てないという文脈に合う。"}, {"text": "寿命", "is_correct": false, "explanation": "生き続ける期間の意味で、手土産の文脈には合わない。"}, {"text": "祝日", "is_correct": false, "explanation": "国が定めた休日の意味で、見舞いの体面とは関係しない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度の意味で、世間体を表さない。"}], "explanations": {"体裁": "体面の意味で、手ぶらでは体面が保てないという文脈に合う。", "寿命": "生き続ける期間の意味で、手土産の文脈には合わない。", "祝日": "国が定めた休日の意味で、見舞いの体面とは関係しない。", "体温": "体の温度の意味で、世間体を表さない。"}, "sentence_index": 6, "correct_answer": "体裁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このカメラは体裁が高く、写真がきれいに撮れる。", "explanation": "ここは〈性能〉の意味。体裁は体面や外見を表すので、機器の性能には使わない。"}, {"text": "箱の体裁が多くて、重すぎて運べない。", "explanation": "ここは〈数量〉の意味。体裁は量を表さないので、物の数には使わない。"}, {"text": "祖父は体裁が高く、今年で九十になる。", "explanation": "ここは〈年齢〉の意味。体裁は年齢を表さないので、年を重ねた度合いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人の前で体裁が取りつくろうのは、かえって疲れる。", "corrected_sentence": "友人の前で体裁を取りつくろうのは、かえって疲れる。", "error_description": "「取りつくろう」の目的語を示す助詞は「を」。「が」を使うと体裁が主語になり不自然になる。正しくは「体裁を取りつくろう」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36813, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は体裁が悪いで、みんなの前で謝れなかった。", "corrected_sentence": "彼は体裁が悪くて、みんなの前で謝れなかった。", "error_description": "「悪い」を後ろに続ける形は「悪くて」。「悪いで」は誤った活用形で、体裁が悪いという述語として続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '817937e2-27ce-4719-8037-c882041de9c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つまらない", "is_correct": true, "explanation": "〈楽しい〉の対義語。活動中に心が満たされない、おもしろくない様子を表す"}, {"text": "暗い", "is_correct": false, "explanation": "明るさを表す形容詞で、楽しさの反対ではない"}, {"text": "寒い", "is_correct": false, "explanation": "気温を表す形容詞で、感情の対義語ではない"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す形容詞で、楽しさとは関係しない"}], "correct_answer": "つまらない", "explanations": {"つまらない": "〈楽しい〉の対義語。活動中に心が満たされない、おもしろくない様子を表す", "暗い": "明るさを表す形容詞で、楽しさの反対ではない", "寒い": "気温を表す形容詞で、感情の対義語ではない", "硬い": "硬さを表す形容詞で、楽しさとは関係しない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
