INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何かをするとき、心がうきうきする気持ちのことです。", "primary_collocate": null, "pronunciation": "たのしい", "ipa": "tanoɕiː", "syllable_count": 4, "sentences": [{"text": "週末に海へ行くと思うと、朝から楽しい。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に海[うみ]へ行[い]くと思[おも]うと、朝[あさ]から楽[たの]しい。", "sentence_source": "generated"}, {"text": "初めての一人旅は不安もあったが、楽しい思い出になった。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "初[はじ]めての一人旅[ひとりたび]は不安[ふあん]もあったが、楽[たの]しい思[おも]い出[で]になった。", "sentence_source": "generated"}, {"text": "子どもたちは公園で楽しく遊んでいる。", "target_word": "楽しく", "complexity_tier": "T3", "furigana": "子[こ]どもたちは公園[こうえん]で楽[たの]しく遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "友達と歌うのは、とても楽しい。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "友達[ともだち]と歌[うた]うのは、とても楽[たの]しい。", "sentence_source": "generated"}, {"text": "毎日の日記は、書いてみると意外に楽しかった。", "target_word": "楽しかった", "complexity_tier": "T3", "furigana": "毎日[まいにち]の日記[にっき]は、書[か]いてみると意外[いがい]に楽[たの]しかった。", "sentence_source": "generated"}, {"text": "仲間と練習する時間が楽しくて、毎日部活に通っている。", "target_word": "楽しくて", "complexity_tier": "T3", "furigana": "仲間[なかま]と練習[れんしゅう]する時間[じかん]が楽[たの]しくて、毎日[まいにち]部活[ぶかつ]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "楽しいことがあると、一日があっという間に終わる。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "楽[たの]しいことがあると、一日[いちにち]があっという間[ま]に終[お]わる。", "sentence_source": "generated"}, {"text": "先生のクイズ授業は楽しくて、みんな笑顔になる。", "target_word": "楽しくて", "complexity_tier": "T3", "furigana": "先生[せんせい]のクイズ授業[じゅぎょう]は楽[たの]しくて、みんな笑顔[えがお]になる。", "sentence_source": "generated"}, {"text": "今日の遠足は天気もよく、一日中楽しかった。", "target_word": "楽しかった", "complexity_tier": "T3", "furigana": "今日[きょう]の遠足[えんそく]は天気[てんき]もよく、一日中[いちにちじゅう]楽[たの]しかった。", "sentence_source": "generated"}, {"text": "勉強が楽しくなれば、自然に成績も上がるだろう。", "target_word": "楽しく", "complexity_tier": "T3", "furigana": "勉強[べんきょう]が楽[たの]しくなれば、自然[しぜん]に成績[せいせき]も上[あ]がるだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しい", "label": "終止形・連体形"}, {"form": "楽しく", "label": "連用形"}, {"form": "楽しかった", "label": "過去形"}, {"form": "楽しくない", "label": "否定形"}, {"form": "楽しければ", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "何かをするときに心がうきうきする気持ちを表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しい", "is_correct": true, "explanation": "「週末に海へ行くと思うと、朝から楽しい」は、予定への期待の気持ちを表すので文脈に合う"}, {"text": "悲しい", "is_correct": false, "explanation": "海へ行く予定への期待と合わず、前後の文脈に反する"}, {"text": "寂しい", "is_correct": false, "explanation": "海へ行く予定を思う場面とは合わず、期待の気持ちを表せない"}, {"text": "怖い", "is_correct": false, "explanation": "楽しみにしている予定の気持ちと合わず、文脈に反する"}], "explanations": {"楽しい": "「週末に海へ行くと思うと、朝から楽しい」は、予定への期待の気持ちを表すので文脈に合う", "悲しい": "海へ行く予定への期待と合わず、前後の文脈に反する", "寂しい": "海へ行く予定を思う場面とは合わず、期待の気持ちを表せない", "怖い": "楽しみにしている予定の気持ちと合わず、文脈に反する"}, "sentence_index": 0, "correct_answer": "楽しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "満員電車は楽しくて、吐き気がした。", "explanation": "ここは〈不快〉の意味。吐き気を催す状況には楽しいは合わず、文の中で矛盾が生じる"}, {"text": "明日の健康診断が楽しくて、一晩中眠れなかった。", "explanation": "ここは〈不安〉の意味。心配な予定には楽しいは使わず、文の中で矛盾が生じる"}, {"text": "雨の日は楽しくて、何もすることがない。", "explanation": "ここは〈退屈〉の意味。何もせず時間をもてあます様子に楽しいは使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しい", "is_correct": true, "explanation": "「楽しいことがあると、一日があっという間に終わる」は、充実した出来事を表す連体形で文脈に合う"}, {"text": "厳しく", "is_correct": false, "explanation": "連用形で「ことがある」の前に置けず、文が成り立たない"}, {"text": "冷たく", "is_correct": false, "explanation": "連用形で「ことがある」の前に置けず、出来事を表せない"}, {"text": "忙しく", "is_correct": false, "explanation": "連用形で「ことがある」の前に置けず、文が成り立たない"}], "explanations": {"楽しい": "「楽しいことがあると、一日があっという間に終わる」は、充実した出来事を表す連体形で文脈に合う", "厳しく": "連用形で「ことがある」の前に置けず、文が成り立たない", "冷たく": "連用形で「ことがある」の前に置けず、出来事を表せない", "忙しく": "連用形で「ことがある」の前に置けず、文が成り立たない"}, "sentence_index": 6, "correct_answer": "楽しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大切な犬が死んで、楽しくて涙が止まらない。", "explanation": "ここは〈悲しい〉の意味。悲しみの場面に楽しいは使わず、文の中で矛盾が生じる"}, {"text": "山道の登りが楽しくて、帰りたくてたまらなかった。", "explanation": "ここは〈嫌〉の意味。いやでたまらない場面に楽しいは合わず、文の中で矛盾が生じる"}, {"text": "試合に負けて、楽しくて悔しかった。", "explanation": "ここは〈残念〉の意味。負けた悔しさには楽しいを使わず、文の中で矛盾が生じる"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい趣味を始めるのは、とても楽しかい。", "corrected_sentence": "新しい趣味を始めるのは、とても楽しい。", "error_description": "「楽しい」は終止形。「楽しかい」は活用として誤り（過去は「楽しかった」、否定は「楽しくない」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "楽しい", "is_correct": true, "explanation": "「思い出」を直接修飾する連体形"}, {"text": "楽しく", "is_correct": false, "explanation": "連用形で、名詞「思い出」を修飾できない"}, {"text": "楽しかろう", "is_correct": false, "explanation": "推量形で、名詞「思い出」を修飾できない"}, {"text": "楽しければ", "is_correct": false, "explanation": "仮定形で、名詞を修飾する形ではない"}], "correct_form": "楽しい", "base_form": "楽しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"楽しい": "「思い出」を直接修飾する連体形", "楽しく": "連用形で、名詞「思い出」を修飾できない", "楽しかろう": "推量形で、名詞「思い出」を修飾できない", "楽しければ": "仮定形で、名詞を修飾する形ではない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36814, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楽しいときを、時間はあっという間に過ぎる。", "corrected_sentence": "楽しいときに、時間はあっという間に過ぎる。", "error_description": "「過ぎる」の時点を示すには「に」が必要。「を」は目的語を示すので、「とき」に続けるのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "楽しくて", "is_correct": true, "explanation": "て形で「授業は楽しくて」と文を続け、後ろの「みんな笑顔になる」につなぐ連用形"}, {"text": "楽しかった", "is_correct": false, "explanation": "過去形で、現在の習慣を述べる文の「なる」とは時制が合わない"}, {"text": "楽しくなかった", "is_correct": false, "explanation": "過去の否定形で、楽しい授業の様子と逆の意味になる"}, {"text": "楽しかろう", "is_correct": false, "explanation": "推量形で、実際の授業の様子を述べる文には合わない"}], "correct_form": "楽しくて", "base_form": "楽しい", "form_label": "連用形（て形）", "sentence_index": 7, "explanations": {"楽しくて": "て形で「授業は楽しくて」と文を続け、後ろの「みんな笑顔になる」につなぐ連用形", "楽しかった": "過去形で、現在の習慣を述べる文の「なる」とは時制が合わない", "楽しくなかった": "過去の否定形で、楽しい授業の様子と逆の意味になる", "楽しかろう": "推量形で、実際の授業の様子を述べる文には合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つまらない", "is_correct": true, "explanation": "〈楽しい〉の対義語。活動中に心が満たされない、おもしろくない様子を表す"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞で、楽しさの反対ではない"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す形容詞で、感情の対義語ではない"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す形容詞で、楽しさとは関係しない"}], "correct_answer": "つまらない", "explanations": {"つまらない": "〈楽しい〉の対義語。活動中に心が満たされない、おもしろくない様子を表す", "重い": "重さを表す形容詞で、楽しさの反対ではない", "遅い": "速さを表す形容詞で、感情の対義語ではない", "固い": "硬さを表す形容詞で、楽しさとは関係しない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
