INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何かをしているときに、心が満たされて、うれしい気持ちになること。", "primary_collocate": null, "pronunciation": "たのしい", "ipa": "tanoɕiː", "syllable_count": 4, "sentences": [{"text": "ローマの子供は、木の馬のおもちゃで楽しい遊びをします。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "ローマの子供[こども]は、木[き]の馬[うま]のおもちゃで楽[たの]しい遊[あそ]びをします。", "sentence_source": "mined"}, {"text": "友達と旅行に行って、とても楽しい一日だった。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "友達[ともだち]と旅行[りょこう]に行[い]って、とても楽[たの]しい一日[いちにち]だった。", "sentence_source": "generated"}, {"text": "昨日のパーティーは楽しかったので、また行きたい。", "target_word": "楽しかった", "complexity_tier": "T3", "furigana": "昨日[きのう]のパーティーは楽[たの]しかったので、また行[い]きたい。", "sentence_source": "generated"}, {"text": "授業が楽しくて、あっという間に時間が過ぎた。", "target_word": "楽しくて", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が楽[たの]しくて、あっという間[ま]に時間[じかん]が過[す]ぎた。", "sentence_source": "generated"}, {"text": "彼の話は面白くて、聞いていると楽しい気持ちになる。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は面白[おもしろ]くて、聞[き]いていると楽[たの]しい気持[きも]ちになる。", "sentence_source": "generated"}, {"text": "家族で料理を作る時間は、いつも楽しい。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "家族[かぞく]で料理[りょうり]を作[つく]る時間[じかん]は、いつも楽[たの]しい。", "sentence_source": "generated"}, {"text": "雨の日は外で遊べないが、家の中でも楽しく過ごせる。", "target_word": "楽しく", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]で遊[あそ]べないが、家[いえ]の中[なか]でも楽[たの]しく過[す]ごせる。", "sentence_source": "generated"}, {"text": "運動会の準備は大変だったが、みんなで話しながら進めるのは楽しかった。", "target_word": "楽しかった", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の準備[じゅんび]は大変[たいへん]だったが、みんなで話[はな]しながら進[すす]めるのは楽[たの]しかった。", "sentence_source": "generated"}, {"text": "楽しい音楽を聞くと、自然に体が動いてしまう。", "target_word": "楽しい", "complexity_tier": "T3", "furigana": "楽[たの]しい音楽[おんがく]を聞[き]くと、自然[しぜん]に体[からだ]が動[うご]いてしまう。", "sentence_source": "generated"}, {"text": "この仕事は楽しくないので、続ける自信がない。", "target_word": "楽しくない", "complexity_tier": "T3", "furigana": "この仕事[しごと]は楽[たの]しくないので、続[つづ]ける自信[じしん]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "楽しい", "label": "終止形・連体形"}, {"form": "楽しく", "label": "連用形"}, {"form": "楽しかった", "label": "過去形"}, {"form": "楽しくない", "label": "否定形"}, {"form": "楽しければ", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "活動中に心が満たされてうれしい気持ちになる様子を表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楽しい", "is_correct": true, "explanation": "「木の馬のおもちゃで楽しい遊び」は、遊びの充足感を表すので文脈に合う"}, {"text": "寂しい", "is_correct": false, "explanation": "「寂しい遊び」は、おもちゃで遊ぶ場面の様子としてつながらない"}, {"text": "厳しい", "is_correct": false, "explanation": "「厳しい遊び」は、子どもの遊びの様子として文脈に合わない"}, {"text": "狭い", "is_correct": false, "explanation": "「狭い遊び」は、遊びの性質を表す語として意味が合わない"}], "explanations": {"楽しい": "「木の馬のおもちゃで楽しい遊び」は、遊びの充足感を表すので文脈に合う", "寂しい": "「寂しい遊び」は、おもちゃで遊ぶ場面の様子としてつながらない", "厳しい": "「厳しい遊び」は、子どもの遊びの様子として文脈に合わない", "狭い": "「狭い遊び」は、遊びの性質を表す語として意味が合わない"}, "sentence_index": 0, "correct_answer": "楽しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合が中止になり、楽しくて肩を落とした。", "explanation": "ここは〈がっかり〉の意味。残念な出来事で肩を落とす場面に楽しいは合わず、文の中で矛盾が生じる"}, {"text": "明日の試験が楽しくて、今から緊張している。", "explanation": "ここは〈楽しみ（期待）〉の意味。試験のように不安を伴う予定には、楽しいは使わない"}, {"text": "入院中の日々は楽しくて、毎日が苦しかった。", "explanation": "ここは〈つらい〉の意味。苦痛の状態には楽しいを使わず、文の中で矛盾が生じる"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "楽しく", "is_correct": true, "explanation": "「家の中でも楽しく過ごせる」は、過ごし方を表す連用形で文脈に合う"}, {"text": "冷たい", "is_correct": false, "explanation": "終止形のままでは「過ごせる」に続かず、意味も合わない"}, {"text": "忙しい", "is_correct": false, "explanation": "終止形のままでは「過ごせる」に続かず、家の中の過ごし方にも合わない"}, {"text": "悲しい", "is_correct": false, "explanation": "終止形のままでは「過ごせる」に続かず、前後の肯定的な文脈とも合わない"}], "explanations": {"楽しく": "「家の中でも楽しく過ごせる」は、過ごし方を表す連用形で文脈に合う", "冷たい": "終止形のままでは「過ごせる」に続かず、意味も合わない", "忙しい": "終止形のままでは「過ごせる」に続かず、家の中の過ごし方にも合わない", "悲しい": "終止形のままでは「過ごせる」に続かず、前後の肯定的な文脈とも合わない"}, "sentence_index": 6, "correct_answer": "楽しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合に負けて、楽しくて悔し泣きした。", "explanation": "ここは〈残念〉の意味。負けた悔しさで泣く場面に楽しいは合わず、文の中で矛盾が生じる"}, {"text": "長い練習で息が切れて、楽しくてやめたくなった。", "explanation": "ここは〈苦しい〉の意味。きつさを表す場面に楽しいは合わず、やめたくなる理由とも矛盾する"}, {"text": "仲のよかった友達が転校して、とても楽しい。", "explanation": "ここは〈寂しい〉の意味。別れの場面は楽しいではなく寂しいで表す"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連休は楽しくい思い出がたくさんある。", "corrected_sentence": "連休は楽しい思い出がたくさんある。", "error_description": "「楽しい」は形容詞の終止形・連体形。「楽しくい」は活用として誤り（「く」を余計に付けている）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "楽しい", "is_correct": true, "explanation": "「一日」を直接修飾する連体形"}, {"text": "楽しく", "is_correct": false, "explanation": "連用形で、名詞「一日」を修飾できない"}, {"text": "楽しかろう", "is_correct": false, "explanation": "推量形で、名詞「一日」を修飾できない"}, {"text": "楽しければ", "is_correct": false, "explanation": "仮定形で、名詞を修飾する形ではない"}], "correct_form": "楽しい", "base_form": "楽しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"楽しい": "「一日」を直接修飾する連体形", "楽しく": "連用形で、名詞「一日」を修飾できない", "楽しかろう": "推量形で、名詞「一日」を修飾できない", "楽しければ": "仮定形で、名詞を修飾する形ではない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36815, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今週は楽しいことに多かった。", "corrected_sentence": "今週は楽しいことが多かった。", "error_description": "「多い」の主語には「が」を使う。「に」は場所や相手を示すので、「楽しいこと」に付けると格が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "楽しかった", "is_correct": true, "explanation": "文末で過去の出来事を述べる過去形"}, {"text": "楽しくて", "is_correct": false, "explanation": "て形で文を続ける形で、ここでは文末の過去を示せない"}, {"text": "楽しさ", "is_correct": false, "explanation": "名詞で、活用形ではないので述語として「進めるのは」の文末には入らない"}, {"text": "楽しがった", "is_correct": false, "explanation": "別の動詞「楽しがる」の過去形で、「楽しい」の形ではなく文に合わない"}], "correct_form": "楽しかった", "base_form": "楽しい", "form_label": "過去形", "sentence_index": 7, "explanations": {"楽しかった": "文末で過去の出来事を述べる過去形", "楽しくて": "て形で文を続ける形で、ここでは文末の過去を示せない", "楽しさ": "名詞で、活用形ではないので述語として「進めるのは」の文末には入らない", "楽しがった": "別の動詞「楽しがる」の過去形で、「楽しい」の形ではなく文に合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。場所を表す格助詞で、外で遊ぶの場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "遊ぶは目的語を取らないので、を は合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手を表すが、外は場所なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、ここには主語の位置がない。"}], "correct_answer": "で", "explanations": {"で": "正解。場所を表す格助詞で、外で遊ぶの場所を示す。", "を": "遊ぶは目的語を取らないので、を は合わない。", "と": "相手を表すが、外は場所なので合わない。", "が": "主語を表すが、ここには主語の位置がない。"}, "error_tags": {"を": "目的語; 遊ぶは目的語を取らない", "と": "相手; 外は場所", "が": "主語; 主語の位置ではない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。せずにの形で、勉強せずに遊んでいるという様子を結ぶ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、ここは様子を結ぶ位置ではない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、比べる対象がない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、遊んでいる様子を結ぶことはできない。"}], "correct_answer": "に", "explanations": {"に": "正解。せずにの形で、勉強せずに遊んでいるという様子を結ぶ。", "へ": "方向を表すが、ここは様子を結ぶ位置ではない。", "より": "比較を表すが、比べる対象がない。", "から": "起点を表すが、遊んでいる様子を結ぶことはできない。"}, "error_tags": {"へ": "方向; 様子を結ばない", "より": "比較; 比べる要素がない", "から": "起点; 様子の表現に合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たのしいことをする。", "primary_collocate": null, "pronunciation": "あそぶ", "ipa": "asobɯ", "syllable_count": 3, "sentences": [{"text": "日曜日は、公園で友達と遊びました。", "target_word": "遊びました", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は、公園[こうえん]で友達[ともだち]と遊[あそ]びました。", "sentence_source": "generated"}, {"text": "宿題が終わったら、外で遊んでもいいですよ。", "target_word": "遊んでも", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が終[お]わったら、外[そと]で遊[あそ]んでもいいですよ。", "sentence_source": "generated"}, {"text": "子どもたちは雨の日でも家の中で楽しそうに遊んでいる。", "target_word": "遊んでいる", "complexity_tier": "T3", "furigana": "子[こ]どもたちは雨[あめ]の日[ひ]でも家[いえ]の中[なか]で楽[たの]しそうに遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "父は仕事が忙しくて、あまり私と遊べない。", "target_word": "遊べない", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]が忙[いそが]しくて、あまり私[わたし]と遊[あそ]べない。", "sentence_source": "generated"}, {"text": "今日は遊ぶ時間がないので、先に帰ります。", "target_word": "遊ぶ", "complexity_tier": "T3", "furigana": "今日[きょう]は遊[あそ]ぶ時間[じかん]がないので、先[さき]に帰[かえ]ります。", "sentence_source": "generated"}, {"text": "夏休みに、いとこの家へ遊びに行く予定だ。", "target_word": "遊びに", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、いとこの家[いえ]へ遊[あそ]びに行[い]く予定[よてい]だ。", "sentence_source": "generated"}, {"text": "猫がボールで遊んでいたので、写真をとった。", "target_word": "遊んでいた", "complexity_tier": "T3", "furigana": "猫[ねこ]がボールで遊[あそ]んでいたので、写真[しゃしん]をとった。", "sentence_source": "generated"}, {"text": "弟は毎日ゲームばかりして、ぜんぜん勉強せずに遊んでいる。", "target_word": "遊んでいる", "complexity_tier": "T3", "furigana": "弟[おとうと]は毎日[まいにち]ゲームばかりして、ぜんぜん勉強[べんきょう]せずに遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "この町には子どもが安全に遊ぶ場所が少ない。", "target_word": "遊ぶ", "complexity_tier": "T3", "furigana": "この町[まち]には子[こ]どもが安全[あんぜん]に遊[あそ]ぶ場所[ばしょ]が少[すく]ない。", "sentence_source": "generated"}, {"text": "昨日は一日中遊んだので、今日はとてもつかれた。", "target_word": "遊んだ", "complexity_tier": "T3", "furigana": "昨日[きのう]は一日中[いちにちじゅう]遊[あそ]んだので、今日[きょう]はとてもつかれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊ぶ", "label": "終止形"}, {"form": "遊んだ", "label": "過去形"}, {"form": "遊んで", "label": "て形"}, {"form": "遊ばない", "label": "否定形"}, {"form": "遊べば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "勉強や仕事ではなく、楽しいことをして過ごす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遊びました", "is_correct": true, "explanation": "正解。過去形で、日曜日に友達と公園で過ごした出来事を表す。"}, {"text": "消えました", "is_correct": false, "explanation": "消える意味で、友達と公園で過ごすという文とは合わない。"}, {"text": "働きました", "is_correct": false, "explanation": "働く意味で、休日に友達と過ごす文脈と反対になる。"}, {"text": "倒れました", "is_correct": false, "explanation": "倒れる意味で、友達と過ごす出来事とは合わない。"}], "explanations": {"遊びました": "正解。過去形で、日曜日に友達と公園で過ごした出来事を表す。", "消えました": "消える意味で、友達と公園で過ごすという文とは合わない。", "働きました": "働く意味で、休日に友達と過ごす文脈と反対になる。", "倒れました": "倒れる意味で、友達と過ごす出来事とは合わない。"}, "sentence_index": 0, "correct_answer": "遊びました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキの生地を遊んで焼いた。", "explanation": "ここは〈作る〉の意味。生地を作ることは〈作る〉で、〈遊ぶ〉は楽しいことをする意味なので合わない。"}, {"text": "明日の試験の宿題を、昨日一日中遊んだ。", "explanation": "ここは〈取り組む・こなす〉の意味。宿題は楽しいことではないので、〈遊ぶ〉は合わない。"}, {"text": "旅行の計画を遊んで、予定通りに実行した。", "explanation": "ここは〈立てる〉の意味。計画を立てることは〈立てる〉で、〈遊ぶ〉は楽しいことをする意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遊んでいた", "is_correct": true, "explanation": "正解。〜ていた形で、猫がボールで遊んでいた様子を表す。"}, {"text": "食べていた", "is_correct": false, "explanation": "食べる意味で、ボールと合わない。"}, {"text": "咲いていた", "is_correct": false, "explanation": "花が咲く意味で、猫の様子に合わない。"}, {"text": "寝込んでいた", "is_correct": false, "explanation": "病気で寝込む意味で、ボールで遊ぶ場面と合わない。"}], "explanations": {"遊んでいた": "正解。〜ていた形で、猫がボールで遊んでいた様子を表す。", "食べていた": "食べる意味で、ボールと合わない。", "咲いていた": "花が咲く意味で、猫の様子に合わない。", "寝込んでいた": "病気で寝込む意味で、ボールで遊ぶ場面と合わない。"}, "sentence_index": 6, "correct_answer": "遊んでいた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "締め切りの報告書を遊んでいる。", "explanation": "ここは〈取り組む〉の意味。仕事の作業は楽しいことではないので、〈遊ぶ〉は合わない。"}, {"text": "彼は祖母の介護を遊んだ。", "explanation": "ここは〈世話をする〉の意味。大切な介護は楽しいことではないので、〈遊ぶ〉は合わない。"}, {"text": "彼は会議の資料を遊んで仕上げた。", "explanation": "ここは〈仕上げる〉の意味。会議の資料作りは楽しいことではないので、〈遊ぶ〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、友達と家を遊ぶことが多い。", "corrected_sentence": "週末は、友達と家で遊ぶことが多い。", "error_description": "遊ぶは場所を「で」で示す。ここは場所の「家」に「で」を使うべきところで、「を」は目的語用なので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遊んでも", "is_correct": true, "explanation": "正解。〜ても形で、外で遊んでもよいという許可を表す。"}, {"text": "遊ばない", "is_correct": false, "explanation": "否定形で、遊んでもいいという許可と反対になる。"}, {"text": "遊びます", "is_correct": false, "explanation": "丁寧形で、普通体の文と合わない。"}, {"text": "遊んだ", "is_correct": false, "explanation": "過去形で、許可を表す文の時制と合わない。"}], "correct_form": "遊んでも", "base_form": "遊ぶ", "form_label": "〜ても形", "sentence_index": 1, "explanations": {"遊んでも": "正解。〜ても形で、外で遊んでもよいという許可を表す。", "遊ばない": "否定形で、遊んでもいいという許可と反対になる。", "遊びます": "丁寧形で、普通体の文と合わない。", "遊んだ": "過去形で、許可を表す文の時制と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みには、毎日近所の公園で遊ぶていた。", "corrected_sentence": "夏休みには、毎日近所の公園で遊んでいた。", "error_description": "遊ぶのて形は遊んで、〜ていたの形は遊んでいたなので、遊ぶていたは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遊んでいる", "is_correct": true, "explanation": "正解。〜ている形で、弟が勉強せずに遊んでいる現在の様子を表す。"}, {"text": "遊べない", "is_correct": false, "explanation": "可能の否定形で、遊んでいるという様子を表す文と合わない。"}, {"text": "遊ばせる", "is_correct": false, "explanation": "使役形で、誰かを遊ばせる意味になり、主語の弟と合わない。"}, {"text": "遊んでいない", "is_correct": false, "explanation": "否定形で、遊んでいるという文の内容と反対になる。"}], "correct_form": "遊んでいる", "base_form": "遊ぶ", "form_label": "〜ている形", "sentence_index": 7, "explanations": {"遊んでいる": "正解。〜ている形で、弟が勉強せずに遊んでいる現在の様子を表す。", "遊べない": "可能の否定形で、遊んでいるという様子を表す文と合わない。", "遊ばせる": "使役形で、誰かを遊ばせる意味になり、主語の弟と合わない。", "遊んでいない": "否定形で、遊んでいるという文の内容と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「雨がやんでから」で、雨がやんだ後に返したという時間の順序を示す。"}, {"text": "の", "is_correct": false, "explanation": "「やんでの返した」は成り立たず、時間の順序も示せない。"}, {"text": "で", "is_correct": false, "explanation": "「やんでで返した」は接続として成り立たず、ここで使う助詞ではない。"}, {"text": "へ", "is_correct": false, "explanation": "「やんでへ返した」は成り立たず、方向を表す語も合わない。"}], "correct_answer": "から", "explanations": {"から": "「雨がやんでから」で、雨がやんだ後に返したという時間の順序を示す。", "の": "「やんでの返した」は成り立たず、時間の順序も示せない。", "で": "「やんでで返した」は接続として成り立たず、ここで使う助詞ではない。", "へ": "「やんでへ返した」は成り立たず、方向を表す語も合わない。"}, "error_tags": {"の": "連体", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「図書館に返す」で、返す先（場所・相手）を示す。"}, {"text": "の", "is_correct": false, "explanation": "「図書館の返す」は名詞に続かず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「図書館と返す」は成り立たず、ここでは使えない。"}, {"text": "や", "is_correct": false, "explanation": "「図書館や返す」は並列の形にならず、成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「図書館に返す」で、返す先（場所・相手）を示す。", "の": "「図書館の返す」は名詞に続かず、成り立たない。", "と": "「図書館と返す」は成り立たず、ここでは使えない。", "や": "「図書館や返す」は並列の形にならず、成り立たない。"}, "error_tags": {"の": "連体", "と": "並列", "や": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いらないものを、もとのものに もどすこと。", "primary_collocate": null, "pronunciation": "かえす", "ipa": "kaesɯ", "syllable_count": 3, "sentences": [{"text": "図書館で借りた本を、明日返します。", "target_word": "返します", "complexity_tier": "T3", "furigana": "図書館[としょかん]で借[か]りた本[ほん]を、明日[あした]返[かえ]します。", "sentence_source": "generated"}, {"text": "友達に借りた傘を、雨がやんでから返した。", "target_word": "返した", "complexity_tier": "T3", "furigana": "友達[ともだち]に借[か]りた傘[かさ]を、雨[あめ]がやんでから返[かえ]した。", "sentence_source": "generated"}, {"text": "借りたお金は、来月までに必ず返す。", "target_word": "返す", "complexity_tier": "T3", "furigana": "借[か]りたお金[かね]は、来月[らいげつ]までに必[かなら]ず返[かえ]す。", "sentence_source": "generated"}, {"text": "読み終わったら、すぐ私に返してください。", "target_word": "返して", "complexity_tier": "T3", "furigana": "読[よ]み終[お]わったら、すぐ私[わたし]に返[かえ]してください。", "sentence_source": "generated"}, {"text": "兄に貸したゲームを返してもらった。", "target_word": "返してもらった", "complexity_tier": "T3", "furigana": "兄[あに]に貸[か]したゲームを返[かえ]してもらった。", "sentence_source": "generated"}, {"text": "古い服は、使い終えたら元の箱に返しておきます。", "target_word": "返しておきます", "complexity_tier": "T3", "furigana": "古[ふる]い服[ふく]は、使[つか]い終[お]えたら元[もと]の箱[はこ]に返[かえ]しておきます。", "sentence_source": "generated"}, {"text": "借りた辞書を返さないまま、引っ越してしまった。", "target_word": "返さない", "complexity_tier": "T3", "furigana": "借[か]りた辞書[じしょ]を返[かえ]さないまま、引[ひ]っ越[こ]してしまった。", "sentence_source": "generated"}, {"text": "この本は図書館に返すので、机の上に置かないでください。", "target_word": "返す", "complexity_tier": "T3", "furigana": "この本[ほん]は図書館[としょかん]に返[かえ]すので、机[つくえ]の上[うえ]に置[お]かないでください。", "sentence_source": "generated"}, {"text": "先生は採点したテストを、授業のあとで学生に返した。", "target_word": "返した", "complexity_tier": "T3", "furigana": "先生[せんせい]は採点[さいてん]したテストを、授業[じゅぎょう]のあとで学生[がくせい]に返[かえ]した。", "sentence_source": "generated"}, {"text": "借りた自転車を返しに、友達の家へ行った。", "target_word": "返しに", "complexity_tier": "T3", "furigana": "借[か]りた自転車[じてんしゃ]を返[かえ]しに、友達[ともだち]の家[いえ]へ行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "返す", "label": "終止形"}, {"form": "返した", "label": "過去形"}, {"form": "返して", "label": "て形"}, {"form": "返さない", "label": "否定形"}, {"form": "返せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "借りたものや使い終えたものを持ち主や元の場所に戻す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "返します", "is_correct": true, "explanation": "丁寧形（未来の予定）。「明日」と合い、丁寧に言い切る形なので空欄に入る。"}, {"text": "返した", "is_correct": false, "explanation": "過去形。「明日」という未来の時点と合わないので入らない。"}, {"text": "返さ", "is_correct": false, "explanation": "未然形。語幹の形のままでは文を言い切れず、空欄に入らない。"}, {"text": "返して", "is_correct": false, "explanation": "て形。文末に置くと言い切れず、丁寧に結ぶ形も取れない。"}], "explanations": {"返します": "丁寧形（未来の予定）。「明日」と合い、丁寧に言い切る形なので空欄に入る。", "返した": "過去形。「明日」という未来の時点と合わないので入らない。", "返さ": "未然形。語幹の形のままでは文を言い切れず、空欄に入らない。", "返して": "て形。文末に置くと言い切れず、丁寧に結ぶ形も取れない。"}, "sentence_index": 0, "correct_answer": "返します"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母の家の古い畳を、新しい畳に返した。", "explanation": "ここは〈取り替える〉の意味。返すは持ち主のもとへ戻すことで、新品と替える用法には使えない。"}, {"text": "初めて会った取引先に、名刺を返した。", "explanation": "ここは〈渡す〉の意味。返すは元々相手の物だったものを戻す語なので、初対面の相手には使えない。"}, {"text": "いらなくなった傘を、ゴミ箱に返した。", "explanation": "ここは〈捨てる〉の意味。返すは元の持ち主へ戻す語なので、ゴミとして捨てる行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "返さない", "is_correct": true, "explanation": "否定形。「〜ないまま」で、返さずに引っ越したという意味になり、文が成り立つ。"}, {"text": "返し", "is_correct": false, "explanation": "連用形。「まま」の前に置くと文が成り立たず、ここでは使えない。"}, {"text": "返せ", "is_correct": false, "explanation": "命令形。「まま」と続かず、文の意味が通らない。"}, {"text": "返そう", "is_correct": false, "explanation": "意向形（〜しよう）。「まま」に続かず、事実を述べる文には合わない。"}], "explanations": {"返さない": "否定形。「〜ないまま」で、返さずに引っ越したという意味になり、文が成り立つ。", "返し": "連用形。「まま」の前に置くと文が成り立たず、ここでは使えない。", "返せ": "命令形。「まま」と続かず、文の意味が通らない。", "返そう": "意向形（〜しよう）。「まま」に続かず、事実を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "返さない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "借りた本を、ページごと破って返した。", "explanation": "ここは〈破る〉の意味。返すは元の持ち主へ戻す語で、破損させる行為は指さないので合わない。"}, {"text": "買ったばかりの新品の鉛筆を、隣の席の子に返した。", "explanation": "ここは〈譲る〉の意味。返すは相手の元の持ち物を戻す語なので、新品の物には使えない。"}, {"text": "後で電話を返しますので、少し待ってください。", "explanation": "ここは〈かけ直す〉の意味。返すは物に使う語で、電話をかけ直す意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "借りたノートを、明日友達を返そうと思う。", "corrected_sentence": "借りたノートを、明日友達に返そうと思う。", "error_description": "返す相手は助詞『に』で示す。『友達を』は誤りで、正しくは『友達に』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "返した", "is_correct": true, "explanation": "過去形。「やんでから」の後に起きた過去の動作なので、過去形が合う。"}, {"text": "返さ", "is_correct": false, "explanation": "未然形。単独では文を終えられないので、ここでは使えない。"}, {"text": "返して", "is_correct": false, "explanation": "て形。文を言い切れず、過去の動作を述べられない。"}, {"text": "返せば", "is_correct": false, "explanation": "仮定形。「〜ば」が続かないと文が成り立たず、過去の出来事の述べ方にも合わない。"}], "correct_form": "返した", "base_form": "返す", "form_label": "過去形", "sentence_index": 1, "explanations": {"返した": "過去形。「やんでから」の後に起きた過去の動作なので、過去形が合う。", "返さ": "未然形。単独では文を終えられないので、ここでは使えない。", "返して": "て形。文を言い切れず、過去の動作を述べられない。", "返せば": "仮定形。「〜ば」が続かないと文が成り立たず、過去の出来事の述べ方にも合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36818, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "借りたCDを、明日店に返さつもりだ。", "corrected_sentence": "借りたCDを、明日店に返すつもりだ。", "error_description": "「返す」の終止形に「つもり」が続くのが正しい。「返さ」は未然形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "返す", "is_correct": true, "explanation": "終止形。「図書館に返すので」と理由を続ける形で、返却の予定を述べる。"}, {"text": "返して", "is_correct": false, "explanation": "て形。「ので」が続かず、文が成り立たない。"}, {"text": "返せ", "is_correct": false, "explanation": "命令形。「ので」と続かず、文が成り立たない。"}, {"text": "返そう", "is_correct": false, "explanation": "意向形。「ので」に続かず、理由を述べる文に合わない。"}], "correct_form": "返す", "base_form": "返す", "form_label": "終止形", "sentence_index": 7, "explanations": {"返す": "終止形。「図書館に返すので」と理由を続ける形で、返却の予定を述べる。", "返して": "て形。「ので」が続かず、文が成り立たない。", "返せ": "命令形。「ので」と続かず、文が成り立たない。", "返そう": "意向形。「ので」に続かず、理由を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「元の状態に返す」で、戻す先（状態）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「状態が返します」では状態が主語になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「状態と返します」は成り立たず、ここでは使えない。"}, {"text": "の", "is_correct": false, "explanation": "「状態の返します」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「元の状態に返す」で、戻す先（状態）を示す。", "が": "「状態が返します」では状態が主語になり、意味が通らない。", "と": "「状態と返します」は成り立たず、ここでは使えない。", "の": "「状態の返します」は文として成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沼地に返した」で、戻す先（元の場所）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「沼地を返した」では沼地が返される物になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「沼地と返した」は名詞の並列にならず、成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「沼地の返した」は名詞に続かず、成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「沼地に返した」で、戻す先（元の場所）を示す。", "を": "「沼地を返した」では沼地が返される物になり、意味が通らない。", "と": "「沼地と返した」は名詞の並列にならず、成り立たない。", "の": "「沼地の返した」は名詞に続かず、成り立たない。"}, "error_tags": {"を": "目的語", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "今まで使ったものを、元の状態に戻したり、別のものに変えたりすること。", "primary_collocate": null, "pronunciation": "かえす", "ipa": "kaesɯ", "syllable_count": 3, "sentences": [{"text": "この計画は問題が多いので、いったん白紙に返そう。", "target_word": "返そう", "complexity_tier": "T3", "furigana": "この計画[けいかく]は問題[もんだい]が多[おお]いので、いったん白紙[はくし]に返[かえ]そう。", "sentence_source": "generated"}, {"text": "展示が終わったら、会場を元の状態に返します。", "target_word": "返します", "complexity_tier": "T3", "furigana": "展示[てんじ]が終[お]わったら、会場[かいじょう]を元[もと]の状態[じょうたい]に返[かえ]します。", "sentence_source": "generated"}, {"text": "庭の落ち葉を集めて、土に返している。", "target_word": "返している", "complexity_tier": "T3", "furigana": "庭[にわ]の落[お]ち葉[ば]を集[あつ]めて、土[つち]に返[かえ]している。", "sentence_source": "generated"}, {"text": "公園の池を埋めて、元の草地に返す工事が始まった。", "target_word": "返す", "complexity_tier": "T3", "furigana": "公園[こうえん]の池[いけ]を埋[う]めて、元[もと]の草地[くさち]に返[かえ]す工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "契約が取り消され、すべてが白紙に返された。", "target_word": "返された", "complexity_tier": "T3", "furigana": "契約[けいやく]が取[と]り消[け]され、すべてが白紙[はくし]に返[かえ]された。", "sentence_source": "generated"}, {"text": "研究所は、山を切り開いた土地を森に返す計画だ。", "target_word": "返す", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]は、山[やま]を切[き]り開[ひら]いた土地[とち]を森[もり]に返[かえ]す計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "生ごみをたい肥にして土に返すと、畑がよくなる。", "target_word": "返す", "complexity_tier": "T3", "furigana": "生[なま]ごみをたい肥[ひ]にして土[つち]に返[かえ]すと、畑[はたけ]がよくなる。", "sentence_source": "generated"}, {"text": "水田を元の沼地に返したところ、鳥が戻ってきた。", "target_word": "返した", "complexity_tier": "T3", "furigana": "水田[すいでん]を元[もと]の沼地[ぬまち]に返[かえ]したところ、鳥[とり]が戻[もど]ってきた。", "sentence_source": "generated"}, {"text": "使ったテーブルは、並べ方を元の形に返しておいてください。", "target_word": "返しておいて", "complexity_tier": "T3", "furigana": "使[つか]ったテーブルは、並[なら]べ方[かた]を元[もと]の形[かたち]に返[かえ]しておいてください。", "sentence_source": "generated"}, {"text": "社長の一言で、決まっていた話を白紙に返すことになった。", "target_word": "返す", "complexity_tier": "T3", "furigana": "社長[しゃちょう]の一言[ひとこと]で、決[き]まっていた話[はなし]を白紙[はくし]に返[かえ]すことになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "返す", "label": "終止形"}, {"form": "返した", "label": "過去形"}, {"form": "返して", "label": "て形"}, {"form": "返さない", "label": "否定形"}, {"form": "返された", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "物事や場所を白紙・土・元の形など、もとの状態に戻す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: たい肥 (Zipf 1.61)']::text[], '5b06df7d-40b2-4106-9fa6-1559c7381280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "返そう", "is_correct": true, "explanation": "意向形（〜しよう）。「いったん白紙に」と合い、提案・決意を表す。"}, {"text": "返さ", "is_correct": false, "explanation": "未然形。単独では文を言い切れず、ここには入らない。"}, {"text": "返して", "is_correct": false, "explanation": "て形。文末に置くと言い切れず、文が成り立たない。"}, {"text": "返せば", "is_correct": false, "explanation": "仮定形。「〜ば」が続かず、この文の骨組みに合わない。"}], "explanations": {"返そう": "意向形（〜しよう）。「いったん白紙に」と合い、提案・決意を表す。", "返さ": "未然形。単独では文を言い切れず、ここには入らない。", "返して": "て形。文末に置くと言い切れず、文が成り立たない。", "返せば": "仮定形。「〜ば」が続かず、この文の骨組みに合わない。"}, "sentence_index": 0, "correct_answer": "返そう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝不足で、体を布団に返した。", "explanation": "ここは〈戻る〉の意味（自分が移動する）。返すは他の人や物を元の状態にする語なので、自分の体には使えない。"}, {"text": "約束の時間を、一時間早く返した。", "explanation": "ここは〈繰り上げる〉の意味。返すは元の状態に戻す語で、時間を早める用法とは違う。"}, {"text": "花瓶を窓辺から机の上に返した。", "explanation": "ここは〈移す〉の意味。返すは元の位置や状態に戻すことで、新しい場所へ動かす用法には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "返す", "is_correct": true, "explanation": "終止形。「〜と」に続けて、『土に返すと畑がよくなる』という条件を表す。"}, {"text": "返そう", "is_correct": false, "explanation": "意向形。「〜と」に続けても、条件の意味が成り立たない。"}, {"text": "返し", "is_correct": false, "explanation": "連用形。「〜と」に続かず、文が成り立たない。"}, {"text": "返しました", "is_correct": false, "explanation": "丁寧形の過去。「〜と」に続けると文が成り立たない。"}], "explanations": {"返す": "終止形。「〜と」に続けて、『土に返すと畑がよくなる』という条件を表す。", "返そう": "意向形。「〜と」に続けても、条件の意味が成り立たない。", "返し": "連用形。「〜と」に続かず、文が成り立たない。", "返しました": "丁寧形の過去。「〜と」に続けると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "返す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車のハンドルを右に返した。", "explanation": "ここは〈回す・切る〉の意味。返すは元の状態に戻す語で、向きを変える動作には使えない。"}, {"text": "一晩考えた結果、会議を来週に返すことにした。", "explanation": "ここは〈延期する〉の意味。元の状態に戻す語なので、日程を先に送る意味には使えない。"}, {"text": "一度言った発言を、すぐに返した。", "explanation": "ここは〈撤回する〉の意味。返すは元の状態に戻す語で、発言を取り消す意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使わなくなった畑を、元の森に返した予定だ。", "corrected_sentence": "使わなくなった畑を、元の森に返す予定だ。", "error_description": "予定は未来の動作を表すので『返す』が正しい。『返した』は過去形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "返します", "is_correct": true, "explanation": "丁寧形。「展示が終わったら」に続けて、丁寧な口調で説明する形。"}, {"text": "返せば", "is_correct": false, "explanation": "仮定形。「〜ば」が続かず、文が完結しない。"}, {"text": "返し", "is_correct": false, "explanation": "連用形。文末に置くと言い切れず、文が完結しない。"}, {"text": "返さ", "is_correct": false, "explanation": "未然形。単独で文を終えられず、ここでは使えない。"}], "correct_form": "返します", "base_form": "返す", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"返します": "丁寧形。「展示が終わったら」に続けて、丁寧な口調で説明する形。", "返せば": "仮定形。「〜ば」が続かず、文が完結しない。", "返し": "連用形。文末に置くと言い切れず、文が完結しない。", "返さ": "未然形。単独で文を終えられず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36819, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、埋め立てた川を、元の流れを返す計画だ。", "corrected_sentence": "市は、埋め立てた川を、元の流れに返す計画だ。", "error_description": "『返す』の到達点は助詞『に』で示す。『流れを』は誤りで、正しくは『流れに』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "返した", "is_correct": true, "explanation": "過去形。「〜たところ」で、返したという既に起きた動作を述べる。"}, {"text": "返そう", "is_correct": false, "explanation": "意向形。「〜たところ」の前に入らず、事実を述べる文に合わない。"}, {"text": "返します", "is_correct": false, "explanation": "丁寧形。「〜たところ」の前に丁寧形は続かず、文が不自然になる。"}, {"text": "返さ", "is_correct": false, "explanation": "未然形。「たところ」に続かず、文が成り立たない。"}], "correct_form": "返した", "base_form": "返す", "form_label": "過去形", "sentence_index": 7, "explanations": {"返した": "過去形。「〜たところ」で、返したという既に起きた動作を述べる。", "返そう": "意向形。「〜たところ」の前に入らず、事実を述べる文に合わない。", "返します": "丁寧形。「〜たところ」の前に丁寧形は続かず、文が不自然になる。", "返さ": "未然形。「たところ」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '089aadbc-b49d-4ac0-84fc-186d282a9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を教えてくれた」で、教える対象（目的語）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「時間に教えてくれた」は成り立たない。に は相手を示し、教える内容の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「時間で教えてくれた」は不自然。で は手段や場所を示し、目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「時間へ教えてくれた」は方向の意味になり、教える内容を示せない。"}], "correct_answer": "を", "explanations": {"を": "「時間を教えてくれた」で、教える対象（目的語）を示す。", "に": "「時間に教えてくれた」は成り立たない。に は相手を示し、教える内容の位置には合わない。", "で": "「時間で教えてくれた」は不自然。で は手段や場所を示し、目的語にはならない。", "へ": "「時間へ教えてくれた」は方向の意味になり、教える内容を示せない。"}, "error_tags": {"に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「住所を教えてもらった」で、教えてもらう対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「住所が教えてもらった」は不自然。が は主語を示し、教えられる内容の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「住所と教えてもらった」は並列の意味になり、目的語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「住所の教えてもらった」は成り立たない。の は名詞同士をつなぐ助詞で、動詞の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「住所を教えてもらった」で、教えてもらう対象（目的語）を示す。", "が": "「住所が教えてもらった」は不自然。が は主語を示し、教えられる内容の位置には合わない。", "と": "「住所と教えてもらった」は並列の意味になり、目的語を示せない。", "の": "「住所の教えてもらった」は成り立たない。の は名詞同士をつなぐ助詞で、動詞の目的語にはならない。"}, "error_tags": {"が": "主語", "と": "並列", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「教える」は、だれかに何かをわかるように話すことです。", "primary_collocate": null, "pronunciation": "おしえる", "ipa": "oɕieɾɯ", "syllable_count": 4, "sentences": [{"text": "駅への道がわからなくて、通りの人に教えてもらった。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "駅[えき]への道[みち]がわからなくて、通[とお]りの人[ひと]に教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "友達が明日の集合時間を教えてくれた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "友達[ともだち]が明日[あした]の集合[しゅうごう]時間[じかん]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "知らない人には電話番号を教えない。", "target_word": "教えない", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]には電話[でんわ]番号[ばんごう]を教[おし]えない。", "sentence_source": "generated"}, {"text": "店員は私が探していた本の場所を教えてくれた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "店員[てんいん]は私[わたし]が探[さが]していた本[ほん]の場所[ばしょ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "弟に答えを教えたら、母に叱られた。", "target_word": "教えた", "complexity_tier": "T3", "furigana": "弟[おとうと]に答[こた]えを教[おし]えたら、母[はは]に叱[しか]られた。", "sentence_source": "generated"}, {"text": "私は旅行者に駅までの行き方を教えた。", "target_word": "教えた", "complexity_tier": "T3", "furigana": "私[わたし]は旅行者[りょこうしゃ]に駅[えき]までの行[い]き方[かた]を教[おし]えた。", "sentence_source": "generated"}, {"text": "秘密の場所を教えると、友達は喜んで走っていった。", "target_word": "教える", "complexity_tier": "T3", "furigana": "秘密[ひみつ]の場所[ばしょ]を教[おし]えると、友達[ともだち]は喜[よろこ]んで走[はし]っていった。", "sentence_source": "generated"}, {"text": "彼の住所を教えてもらったので、手紙を書いた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "彼[かれ]の住所[じゅうしょ]を教[おし]えてもらったので、手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "道に迷った外国人に、近くの店を教えてあげた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]った外国人[がいこくじん]に、近[ちか]くの店[みせ]を教[おし]えてあげた。", "sentence_source": "generated"}, {"text": "教えてくれた天気予報のおかげで、傘を持って出かけた。", "target_word": "教えて", "complexity_tier": "T3", "furigana": "教[おし]えてくれた天気[てんき]予報[よほう]のおかげで、傘[かさ]を持[も]って出[で]かけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教えて", "label": "て形"}, {"form": "教えた", "label": "過去形"}, {"form": "教えない", "label": "否定形"}, {"form": "教えてもらう", "label": "授受表現"}], "register": "neutral（普通体）", "sense_fingerprint": "道や時間などの情報を相手に話して知らせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52abfa19-f32b-4331-8603-e7d9dc026dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教えて", "is_correct": true, "explanation": "「通りの人に教えてもらった」で、道を話して知らせてもらったという意味に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「通りの人に洗ってもらった」は不自然。洗うは汚れを落とす動作で、道の情報とは関係しない。"}, {"text": "運んで", "is_correct": false, "explanation": "「通りの人に運んでもらった」は道を尋ねた文脈に合わない。運ぶは物の移動を表す。"}, {"text": "預けて", "is_correct": false, "explanation": "「通りの人に預けてもらった」は不自然。預けるは物を保管させる意味で、道の文脈に合わない。"}], "explanations": {"教えて": "「通りの人に教えてもらった」で、道を話して知らせてもらったという意味に合う。", "洗って": "「通りの人に洗ってもらった」は不自然。洗うは汚れを落とす動作で、道の情報とは関係しない。", "運んで": "「通りの人に運んでもらった」は道を尋ねた文脈に合わない。運ぶは物の移動を表す。", "預けて": "「通りの人に預けてもらった」は不自然。預けるは物を保管させる意味で、道の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "教えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "受付の人は来客を応接室まで教えた。", "explanation": "〈案内〉は人を目的の場所まで連れて行くこと。教えるは言葉で情報を伝えることで、人を連れていく場面には合わない。"}, {"text": "社員は会社の書類を教えた。", "explanation": "〈提出〉は書類などを決まった先へ出すこと。教えるは情報を言葉で伝える語で、書類を出す場面には合わない。"}, {"text": "先生は週三回、学生に花束を教えている。", "explanation": "〈贈る〉は品物を相手に渡すこと。教えるは情報を伝える語で、花束を渡す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36820, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教える", "is_correct": true, "explanation": "「秘密の場所を教えると」で、場所を話して知らせるという意味に合う。"}, {"text": "壊す", "is_correct": false, "explanation": "「秘密の場所を壊すと」は文の流れに合わない。壊すは物を破損させる動作。"}, {"text": "撮る", "is_correct": false, "explanation": "「秘密の場所を撮ると」は不自然。撮るは写真を撮る動作で、話して知らせる文脈に合わない。"}, {"text": "叩く", "is_correct": false, "explanation": "「秘密の場所を叩くと」は成り立たない。叩くは打つ動作で、場所の情報には使わない。"}], "explanations": {"教える": "「秘密の場所を教えると」で、場所を話して知らせるという意味に合う。", "壊す": "「秘密の場所を壊すと」は文の流れに合わない。壊すは物を破損させる動作。", "撮る": "「秘密の場所を撮ると」は不自然。撮るは写真を撮る動作で、話して知らせる文脈に合わない。", "叩く": "「秘密の場所を叩くと」は成り立たない。叩くは打つ動作で、場所の情報には使わない。"}, "sentence_index": 6, "correct_answer": "教える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は迷子を交番まで教えた。", "explanation": "〈送る〉は人を連れて行くこと。教えるは言葉で伝えることなので、人を連れていく場面には合わない。"}, {"text": "彼女は手紙を教えた。", "explanation": "〈書く〉は文字で文章を作ること。教えるは言葉で情報を伝える語で、手紙を書く場面には使わない。"}, {"text": "彼は大会の参加者に賞を教えた。", "explanation": "〈授与〉は賞状などを渡すこと。教えるは情報を伝える語で、賞を渡す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8eeee0a-b395-49e2-8ef3-ee192c5cde70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
